-- ==== DevLet Lua 5.1/LuaJIT compatibility shim (auto-generated) ====
-- 32-bit bitwise helpers implemented with plain arithmetic so the payload
-- runs on Lua 5.1 / LuaJIT (which have no native & | ~ << >> operators).
-- Installed as GLOBALS on purpose: keeps the main chunk under LuaJIT's
-- 200-local-variable limit.
__owb_band = function(a, b)
  local r, p = 0, 1
  a = a % 4294967296
  b = b % 4294967296
  for _ = 1, 32 do
    local x = a % 2
    local y = b % 2
    if x == 1 and y == 1 then
      r = r + p
    end
    a = (a - x) / 2
    b = (b - y) / 2
    p = p * 2
  end
  return r
end
__owb_bxor = function(a, b)
  local r, p = 0, 1
  a = a % 4294967296
  b = b % 4294967296
  for _ = 1, 32 do
    local x = a % 2
    local y = b % 2
    if x ~= y then
      r = r + p
    end
    a = (a - x) / 2
    b = (b - y) / 2
    p = p * 2
  end
  return r
end
__owb_lshift = function(a, n)
  return (a * (2 ^ n)) % 4294967296
end
__owb_rshift = function(a, n)
  return math.floor(a / (2 ^ n))
end -- ================================================================
