      end)
      if # origins == 0 then
        origins[1] = FVector(camLoc.X, camLoc.Y, camLoc.Z)
      end
      for _, bd in ipairs(MB_BonePrio) do
        local bp = nil pcall(function()
          bp = enemy:GetBonePos(bd[1], MB_Sel.zero)
        end)
        if bp and not (bp.X == 0 and bp.Y == 0 and bp.Z == 0) then
          local clear = false
          for _, oV in ipairs(origins) do
            pcall(function()
              local bHit = KSL.LineTraceSingle(world, oV, FVector(bp.X, bp.Y, bp.Z), 0, false, Ign, EDD.None, HR, true)
              if bHit == false or bHit == 0 then
                clear = true
              end
            end)
            if clear then
              break
            end
          end
          if clear then
            if bd[2] then
              return { X = bp.X, Y = bp.Y, Z = bp.Z - (_G.AimNeckDownZ or 0) }
            end
            return { X = bp.X, Y = bp.Y, Z = bp.Z }
          end
        end
      end
      return nil
    end
    local mbVisibleBone = _G.MWLoS.Trace
    _G.MWLoS._clT = - 1
    function _G.MWLoS.FrameCamLoc(pc)
      local now = _G.RealNow()
      if _G.MWLoS._clT == now and _G.MWLoS._clPC == pc then
        return _G.MWLoS._cl
      end
      local cl = nil pcall(function()
        local UG = import("GameplayStatics")
        local cm = UG and UG.GetPlayerCameraManager(pc, 0)
        if cm and slua.isValid(cm) then
          cl = cm:GetCameraLocation()
        end
      end)
      _G.MWLoS._clPC = pc
      _G.MWLoS._clT = now
      _G.MWLoS._cl = cl
      return cl
    end
    function _G.MWLoS.PointVisible(pc, targetActor, selfChar, camLoc, wp)
      if not (wp and camLoc) then
        return false
      end
      local clear = false pcall(function()
        local KSL = import("KismetSystemLibrary")
        local Ign = slua.Array(UEnums.EPropertyClass.Object, import("/Script/Engine.Actor"))
        if slua.isValid(selfChar) then
          Ign:Add(selfChar)
        end
        if slua.isValid(targetActor) then
          Ign:Add(targetActor)
        end
        pcall(function()
          local veh = selfChar and ((type(selfChar.GetCurrentVehicle) == "function" and selfChar:GetCurrentVehicle()) or selfChar.CurrentVehicle)
          if veh and slua.isValid(veh) then
            Ign:Add(veh)
          end
        end)
        local HR = import("/Script/Engine.HitResult")()
        local EDD = import("EDrawDebugTrace")
        local world = slua.getWorld()
        if KSL and world then
          local bHit = KSL.LineTraceSingle(world, FVector(camLoc.X, camLoc.Y, camLoc.Z), FVector(wp.X, wp.Y, wp.Z), 0, false, Ign, EDD.None, HR, true)
          if bHit == false or bHit == 0 then
            clear = true
          end
        end
      end)
      return clear
    end
    _G.MWLoS.vcache = _G.MWLoS.vcache or {} _G.MWLoS.vinterval = 0.1
    function _G.MWLoS.CachedVisible(enemy, pc, selfChar, camLoc)
      if not (enemy and slua.isValid(enemy)) then
        return false
      end
      local now = _G.RealNow()
      local key = nil pcall(function()
        key = (type(enemy.GetUniqueID) == "function" and enemy:GetUniqueID()) or nil
      end)
      if not key then
        key = tostring(enemy)
      end
      local c = _G.MWLoS.vcache[key]
      if c and c.Actor == enemy and c.PC == pc and c.Self == selfChar and now >= c.t and (now - c.t) < _G.MWLoS.vinterval then
        return c.vis
      end
      if not camLoc then
        camLoc = _G.MWLoS.FrameCamLoc(pc)
      end
      local vis = _G.MWLoS.Trace(pc, camLoc, enemy, selfChar) ~= nil
      if not c then
        c = { t = 0, vis = true };
        _G.MWLoS.vcache[key] = c
      end
      c.Actor, c.PC, c.Self = enemy, pc, selfChar
      c.t = now
      c.vis = vis
      return vis
    end
    function _G.MWLoS.PurgeStale(now)
      now = now or _G.RealNow()
      for k, c in pairs(_G.MWLoS.vcache) do
        if (now - c.t) > 2.0 then
          _G.MWLoS.vcache[k] = nil
        end
      end
    end
    local function mbInVehicle(t)
      local veh = nil pcall(function()
        if t.GetCurrentVehicle then
          veh = t:GetCurrentVehicle()
        end
      end)
      if not mbValid(veh) then
        pcall(function()
          veh = t.CurrentVehicle
        end)
      end
      return mbValid(veh)
    end
    local function mbInsideDisplayedBox(enemy)
      local P = _G.PlayerMapMarker;
      local cfg = _G.MWConfig
      if not mbValid(enemy) or not P or not cfg or (cfg.EspPlayerBox ~= true and cfg.EspPlayerBox ~= 1) or cfg.EspPlayer == false or cfg.EspPlayer == 0 then
        return false
      end
      if type(P.GetMyPlayerController) ~= 'function' or type(P._ScreenCenterCanvas) ~= 'function' then
        return false
      end
      local pc = P.GetMyPlayerController();
      if not mbValid(pc) then
        return false
      end
      local b = P.DisplayedBoxes and P.DisplayedBoxes[enemy]
      if not b or b.Character ~= enemy or b.PC ~= pc or b.Visible ~= true then
        return false
      end
      local function finite(v)
        return type(v) == 'number' and v == v and v ~= math.huge and v ~= - math.huge
      end
      local now = _G.RealNow()
      if not finite(now) or not finite(b.Time) or now < b.Time or now - b.Time > .2 then
        return false
      end
      if not finite(b.X1) or not finite(b.X2) or not finite(b.Y1) or not finite(b.Y2) or b.X2 <= b.X1 or b.Y2 <= b.Y1 then
        return false
      end
      local cx, cy = P._ScreenCenterCanvas(pc)
      if b.Canvas ~= P.ESPCanvas or b.Width ~= P._VpPxW or b.Height ~= P._VpPxH then
        return false
      end
      return finite(cx) and finite(cy) and cx >= b.X1 and cx <= b.X2 and cy >= b.Y1 and cy <= b.Y2
    end
    _G.OwenMagicBulletInsideBox = mbInsideDisplayedBox
    local function mbCurrentTarget()
      if not _G.Mod_BulletTrack then
        return nil, nil
      end
      local now = _G.RealNow()
      if now - MB_Sel.t < 0.025 and mbValid(MB_Sel.enemy) and MB_Sel.pos and mbInsideDisplayedBox(MB_Sel.enemy) then
        return MB_Sel.enemy, MB_Sel.pos
      end
      MB_Sel.t = now MB_Sel.enemy, MB_Sel.pos = nil, nil
      local player = mbLocalChar()
      if not player then
        return nil, nil
      end
      if not mbInVehicle(player) then
        local wid = nil pcall(function()
          local PMM = _G.PlayerMapMarker
          if PMM and PMM.GetCharacterWeaponInfo then
            local info = PMM.GetCharacterWeaponInfo(player)
            wid = info and tonumber(info.WeaponID) or nil
          end
        end)
        if not wid or wid <= 0 then
          return nil, nil
        end
      end
      local pc = nil pcall(function()
        pc = player:GetPlayerControllerSafety()
      end)
      local camLoc, fwd = nil, nil pcall(function()
        local GS = import("GameplayStatics")
        local cam = GS.GetPlayerCameraManager(pc, 0)
        if cam and slua.isValid(cam) then
          camLoc = cam:GetCameraLocation()
          fwd = import("KismetMathLibrary").GetForwardVector(cam:GetCameraRotation())
        end
      end)
      MB_Sel.vis = MB_Sel.vis or {}
      local best, bestScore = nil, 1e12
      local vpCx, vpCy = nil, nil pcall(function()
        local vs = require("client.common.ui_util").GetViewportSize()
        if vs then
          vpCx, vpCy = vs.X * 0.5, vs.Y * 0.5
        end
      end)
      if not MB_Sel.screen then
        pcall(function()
          MB_Sel.screen = import("Vector2D")()
        end)
      end
      local mbScreen = MB_Sel.screen
      local bestPos, bestIsVeh = nil, nil
      local ok, list = pcall(_G.GetEnemyTargetsFromActors, 1e9)
      if ok and list then
        for _, t in ipairs(list) do
          if t.HealthStatus ~= 1 and mbInsideDisplayedBox(t) then
            local inVeh = mbInVehicle(t)
            local aimActor = t
            local d = nil pcall(function()
              d = player:GetDistanceTo(t)
            end)
            if d then
              local key = tostring(t)
              local v = MB_Sel.vis[key]
              if not v or (now - v.t) > 0.2 then
                local seen, pos = false, nil
                if inVeh then
                  pos = mbHeadPos(t)
                  if pos then
                    seen = true
                  end
                else
                  pos = mbVisibleBone(pc, camLoc, t, player)
                  if pos then
                    seen = true
                  end
                end
                v = { t = now, seen = seen, pos = pos, inVeh = inVeh }
                MB_Sel.vis[key] = v
              end
              if v.seen and v.pos and mbInsideDisplayedBox(t) then
                local aimPoint = v.pos
                local isFront = true
                if camLoc and fwd then
                  local dx, dy, dz = aimPoint.X - camLoc.X, aimPoint.Y - camLoc.Y, aimPoint.Z - camLoc.Z
                  if (dx * fwd.X + dy * fwd.Y + dz * fwd.Z) < 0 then
                    isFront = false
                  end
                end
                local score
                local sd = nil
                if vpCx and mbScreen and pc and slua.isValid(pc) then
                  pcall(function()
                    mbScreen.X = 0;
                    mbScreen.Y = 0
                    local okp = pc:ProjectWorldLocationToScreen(aimPoint, mbScreen, false)
                    if okp and mbScreen.X > 0 and mbScreen.Y > 0 then
                      local ddx, ddy = mbScreen.X - vpCx, mbScreen.Y - vpCy
                      sd = math.sqrt(ddx * ddx + ddy * ddy)
                    end
                  end)
                end
                if isFront and sd then
                  score = sd
                elseif isFront then
                  score = 1000000 + (d or 0) * 0.001
                else
                  score = 10000000 + (d or 0) * 0.001
                end
                if score < bestScore then
                  best, bestScore, bestPos, bestIsVeh = aimActor, score, aimPoint, (v.inVeh and true or false)
                end
              end
            end
          end
        end
      end
      if not best or not bestPos then
        MB_Sel.isVehicle = false
        if mbValid(MB_Sel.lastEnemy) and mbInsideDisplayedBox(MB_Sel.lastEnemy) and (now - (MB_Sel.lastT or 0)) < 0.25 then
          local lp = mbHeadPos(MB_Sel.lastEnemy) or MB_Sel.lastPos
          if lp then
            MB_Sel.enemy, MB_Sel.pos = MB_Sel.lastEnemy, lp
            return MB_Sel.lastEnemy, lp
          end
        end
        return nil, nil
      end
      MB_Sel.enemy, MB_Sel.pos, MB_Sel.isVehicle = best, bestPos, (bestIsVeh and true or false)
      MB_Sel.lastEnemy, MB_Sel.lastPos, MB_Sel.lastT = best, bestPos, now
      return best, bestPos
    end
    local function mbResteerFromSelf(Bullet, aimPos)
      if not mbValid(Bullet) or not aimPos then
        return
      end
      local from = nil pcall(function()
        from = Bullet:K2_GetActorLocation()
      end)
      if not from then
        return
      end
      local dir = (FVector(aimPos.X, aimPos.Y, aimPos.Z) - FVector(from.X, from.Y, from.Z)):GetSafeNormal(0.0001)
      local speed = _G.BulletTrack_Speed pcall(function()
        Bullet.ShootDir = dir
      end)
      pcall(function()
        Bullet:K2_SetActorRotation(dir:ToOrientationRotator(), false)
      end)
      local pm = Bullet.PMComp
      if mbValid(pm) then
        pcall(function()
          pm.ProjectileGravityScale = 0
        end)
        pcall(function()
          pm.Velocity = dir * speed
        end)
      end
    end
    function _G.BulletTrack_TickActive()
      if not _G.Mod_BulletTrack then
        for key, rec in pairs(MB_Active) do
          mbNeutralize(rec.bullet);
          MB_Active[key] = nil
        end;
        return
      end
      local now = _G.RealNow()
      for k, rec in pairs(MB_Active) do
        if not mbValid(rec.bullet) or (now - rec.born) > 0.15 then
          if mbValid(rec.bullet) then
            mbNeutralize(rec.bullet)
          end
          MB_Active[k] = nil
        elseif not rec.pending and not mbInsideDisplayedBox(rec.enemy) then
          mbNeutralize(rec.bullet)
          MB_Active[k] = nil
        elseif rec.pending then
          mbNeutralize(rec.bullet);
          MB_Active[k] = nil
        else
          if mbValid(rec.enemy) then
            mbEnsureTargetCollision(rec.enemy)
            local live = mbHeadPos(rec.enemy)
            if live then
              rec.aimPos = live
            end
          end
          mbResteerFromSelf(rec.bullet, rec.aimPos)
        end
      end
    end
    local function mbHandleBullet(Bullet, Weapon)
      if not _G.Mod_BulletTrack then
        return
      end
      if not mbValid(Bullet) then
        return
      end
      mbCacheBulletOrig(Bullet)
      local enemy, aimPos = mbCurrentTarget()
      if enemy then
        mbSteerBullet(Bullet, enemy, aimPos, Weapon)
      else
        local record = MB_Active[mbKey(Bullet)]
        if record then
          mbNeutralize(Bullet);
          MB_Active[mbKey(Bullet)] = nil
        end
      end
    end
    local MB_BulletClass = nil
    local function mbOnLaunch(Bullet)
      if not _G.Mod_BulletTrack then
        return
      end
      pcall(function()
        local lp = mbLocalChar()
        if not lp or not mbValid(Bullet) then
          return
        end
        local owner = nil pcall(function()
          owner = Bullet.WeaponOwnerPawn
        end)
        if owner ~= nil and mbValid(owner) and owner ~= lp then
          return
        end
        local w = mbSt(Bullet).weapon
        if not mbValid(w) then
          pcall(function()
            w = Bullet.OwningShootWeapon
          end)
        end
        mbHandleBullet(Bullet, w)
      end)
    end
    local function mbBindLaunch(Bullet)
      if not mbValid(Bullet) then
        return
      end
      local st = mbSt(Bullet)
      if st.bound then
        return
      end
      st.bound = true mbCacheBulletOrig(Bullet)
      pcall(function()
        Bullet.OnLaunchBullet:Add(function()
          mbOnLaunch(Bullet)
        end)
      end)
      pcall(function()
        Bullet.OnResetBullet:Add(function()
          mbOnLaunch(Bullet)
        end)
      end)
    end
    function _G.BulletTrack_ScanPool()
      if not _G.Mod_BulletTrack then
        return
      end
      pcall(function()
        if not MB_BulletClass then
          pcall(function()
            MB_BulletClass = import("STExtraShootWeaponBulletBase")
          end)
        end
        if not MB_BulletClass then
          return
        end
        local lp = mbLocalChar()
        if not lp then
