    function _G.EnableBulletTrackHook()
      if not Client then
        return false
      end
      local lp = mbLocalChar()
      if not lp then
        return false
      end
      if lp._BulletTrackHooked then
        return true
      end
      local ok, err = pcall(function()
        lp.OnCharacterShootBulletDelegate:Add(function(Weapon, Bullet)
          if not _G.Mod_BulletTrack then
            return
          end
          local handledOK = pcall(function()
            if mbValid(Bullet) and mbValid(Weapon) then
              mbSt(Bullet).weapon = Weapon
            end
            mbBindLaunch(Bullet)
            mbHandleBullet(Bullet, Weapon)
          end)
        end)
      end)
      if ok then
        lp._BulletTrackHooked = true
      end
      return ok, err
    end
    local MB_WeaponOrig = {}
    local function mbWeaponEntities(player)
      local char = player
      if char and char.Object then
        char = char.Object
      end
      if not mbValid(char) then
        return {}
      end
      local weapon = nil pcall(function()
        local wm = char.WeaponManagerComponent
        if mbValid(wm) then
          weapon = wm:GetCurrentWeapon()
        end
      end)
      if not mbValid(weapon) and type(char.GetCurrentWeapon) == "function" then
        weapon = char:GetCurrentWeapon()
      end
      if not mbValid(weapon) then
        return {}
      end
      local ents = {}
      for _, key in ipairs( { "ShootWeaponEntity_GEN_VARIABLE", "ShootWeaponEntity", "ShootWeaponEntityComp" }) do
        local e = nil pcall(function()
          e = weapon[key]
        end)
        if mbValid(e) then
          table.insert(ents, e)
        end
      end
      return ents
    end
    local function mbRestoreAllWeapons()
      for k, o in pairs(MB_WeaponOrig) do
        if mbValid(o.ent) then
          pcall(function()
            o.ent.BulletFireSpeed = o.speed
          end)
        end
        MB_WeaponOrig[k] = nil
      end
    end
    function _G.ApplyBulletTrackWeapon(player)
      if not Client then
        return
      end
      pcall(function()
        local enemy = mbCurrentTarget()
        if not enemy then
          if next(MB_WeaponOrig) then
            mbRestoreAllWeapons()
          end
          return
        end
        local speed = _G.BulletTrack_Speed
        for _, ent in ipairs(mbWeaponEntities(player)) do
          local k = mbKey(ent)
          if not MB_WeaponOrig[k] then
            local cur = nil pcall(function()
              cur = ent.BulletFireSpeed
            end)
            if cur and cur < speed then
              MB_WeaponOrig[k] = { ent = ent, speed = cur }
            end
          end
          if MB_WeaponOrig[k] then
            pcall(function()
              if ent.BulletFireSpeed ~= speed then
                ent.BulletFireSpeed = speed
              end
            end)
          end
        end
      end)
    end
    function _G.OwenNeonResetMagicTarget()
      pcall(mbRestoreAllWeapons)
      for key in pairs(MB_Active) do
        MB_Active[key] = nil
      end
      MB_Sel.enemy, MB_Sel.pos, MB_Sel.lastEnemy, MB_Sel.lastPos = nil, nil, nil, nil MB_Sel.t, MB_Sel.lastT = - 1, 0
      for key in pairs(MB_Sel.vis or {}) do
        MB_Sel.vis[key] = nil
      end
    end
    function _G.RestoreBulletTrackWeapon(player)
      pcall(mbRestoreAllWeapons)
    end
    function _G.BulletTrack_HasTarget()
