    function _G.BulletTrack_TargetPos()
      if not _G.Mod_BulletTrack then
        return nil
      end
      if not (mbValid(MB_Sel.enemy) and MB_Sel.pos) then
        return nil
      end
      local live = mbHeadPos(MB_Sel.enemy)
