    A.Fields = { SkinAttachment = true, WeaponInventoryIcons = true, AttachmentInventoryIcons = true,
    ProfileCustomization = true, CollectionHallUnlock = true, UCSpend = true, EspShowState = true, EspNationFlag = true,
    EspPlayerTeam = true, EspPlayerHP = true, RemoveFog = true, FullGrip = true, EspMinimap = true, FakeDisplayName = true,
    FakeDisplayUID = true, GraphicsCustomize = true, EspAimArrow = true }
    A.FreeDefaults = { EspRefreshRate = 0, FragFxScale = 100 }
    A.FreeHiddenRows = { ModMenu_EspShowState = true, ModMenu_EspNationFlag = true, ModMenu_EspPlayer_Team = true,
    ModMenu_EspPlayer_HP = true, ModMenu_RemoveFog = true, ModMenu_FullGrip = true, ModMenu_EspMinimap = true,
    ModMenu_EspRefreshRate = true, ModMenu_FragFxScale = true, ModMenu_SkinAttachment = true, ModMenu_CollectionHallUnlock = true,
    ModMenu_ProfileCustomization = true, ModMenu_NadeemVehicleVoice = true, ModMenu_NadeemCollection = true,
    ModMenu_NadeemDrawPersist = true, ModMenu_WeaponInventoryIcons = true, ModMenu_AttachmentInventoryIcons = true,
    ModMenu_UCSpend = true, ModMenu_NadeemPet = true, ModMenu_FakeDisplayName = true, ModMenu_FakeDisplayUID = true,
    ModMenu_GraphicsCustomize = true, ModMenu_EspAimArrow = true, ModMenu_ArrowOffscreenOnly = true,
    ModMenu_ArrowRadius = true, ModMenu_ArrowSize = true }
    function A.HiddenRow(key)
      return type(key) == 'string' and (A.FreeHiddenRows[key] == true or key:match('^ModMenu_Graphics') ~= nil)
    end
    function A.EnforceConfig()
      if A.Level() == 'vip' or type(_G.MWConfig) ~= 'table' then
        return
      end
      local free = A.Level() == 'free'
      local noAccess = { ModSkin = true, ModEmote = true, SkinDeadBox = true, KillMessage = true, KillCountUI = true,
      SkinOptionOpen = true, SkinOpenLink = true, SpecialGarageEdit = true }
      for key in pairs(_G.MWConfig) do
        if A.Fields[key] or ( not free and (noAccess[key] or (type(key) == 'string' and key:match('^SkinEnable_')))) then
          _G.MWConfig[key] = false
        end
      end
      for key, value in pairs(A.FreeDefaults) do
        _G.MWConfig[key] = value
      end
      local voice = rawget(_G, 'OwenVehicleVoice');
      if voice then
        voice.ENABLED = false
      end
      local extras = rawget(_G, 'OwenNadeemExtras')
      if extras then
        for _, key in ipairs( { 'Collection', 'Draw', 'Pet' }) do
          if type(extras[key]) == 'table' then
            extras[key].Enabled = false
          end
        end
      end
    end
    function A.GuardRow(row, skinCategory)
      if type(row) ~= 'table' or type(row.SetFunc) ~= 'function' or not (skinCategory or A.HiddenRow(row.Key)) then
        return
      end
      local record = A.Rows[row]
      if record and row.SetFunc == record.Wrapper then
        return
      end
      local original = row.SetFunc
      local wrapper = function( ...)
        if A.HiddenRow(row.Key) then
          if not A.Vip() then
            return false
          end
        elseif _G.OwenLicenseValidated ~= true or (A.Level() ~= 'free' and A.Level() ~= 'vip') then
          return false
        end
        return original( ...)
      end
      row.SetFunc = wrapper;
      A.Rows[row] = { Original = original, Wrapper = wrapper }
    end
    function A.GuardRows(def)
      for _, cat in ipairs((def or {}).Category or {}) do
        for _, row in ipairs(cat.Stack or {}) do
          A.GuardRow(row, cat.Key == 'Cat_Skin')
        end
      end
    end
  end
  local function OwenNeonAuthorized()
