    local function InstallSharedTLog(owner)
      if not owner then
        return true
      end
      local lifecycle = _G.OwenBypassLifecycle
      if not lifecycle then
        return false, 'lifecycle_unavailable'
      end
      for _, key in ipairs( { 'Info', 'Warning', 'Error', 'Debug', 'Report', 'Send', 'Flush' }) do
        if type(owner[key]) == 'function' then
          local ok, reason = lifecycle.InstallOnce(owner, key, function()
            return function()
              return nil
            end
          end)
          if not ok then
            return false, reason
          end
        end
      end
      return true
    end
