    local function patchMethod(owner, key, replacement)
      if type(owner) ~= 'table' or type(key) ~= 'string' then
        return false
      end
      local impl = rawget(owner, '__inner_impl')
      if type(impl) == 'table' then
        if type(rawget(impl, key)) ~= 'function' then
          return false
        end
        rawset(impl, key, replacement)
        return true
      end
      return (pcall(function()
        owner[key] = replacement
      end))
    end
