          evidence = 'AIController'
        end
      end
    end
    local conflict = negative and (positive or secondaryPositive)
    if not conflict then
      isAI = positive or secondaryPositive
      known = isAI or (negative and stateValid(state))
    end
    if known then
      if markData.AK_BOT_ACTOR ~= pawn or markData.AK_BOT_CANDIDATE ~= isAI then
        markData.AK_BOT_CANDIDATE = isAI
        markData.AK_BOT_SAMPLES = 1
