      return
    end
    local ok = pcall(function()
      local WeaponManager = PlayerCharacter:GetWeaponManager()
      if not slua.isValid(WeaponManager) then
        return
      end
      local isGlowEnabled = enabled
      local LinearColorClass = import("LinearColor") or _G.FLinearColor
      local glowIntensity = 80.0
      local thickness = _G.MWState.CustomTextData.WeaponGlowThickness or 3
      local colorMode = _G.MWState.CustomTextData.WeaponGlowColor or 5
      local r, g, b = 1.0, 1.0, 0.0
      if colorMode == 1 then
        r, g, b = 1.0, 0.0, 0.0
      elseif colorMode == 2 then
        r, g, b = 0.0, 1.0, 0.0
      elseif colorMode == 3 then
        r, g, b = 0.0, 0.0, 1.0
      elseif colorMode == 4 then
        r, g, b = 1.0, 1.0, 0.0
      elseif colorMode == 5 then
        local time = _G.RealNow() * 2.0
        r = (math.sin(time) + 1) / 2
        g = (math.sin(time + 2) + 1) / 2
        b = (math.sin(time + 4) + 1) / 2
      end
      local finalColor = LinearColorClass and LinearColorClass(r * glowIntensity, g * glowIntensity, b * glowIntensity, 1.0) or { R = r * 255 * glowIntensity,
      G = g * 255 * glowIntensity, B = b * 255 * glowIntensity, A = 255 }
      for slot = 1, 3 do
        local Weapon = WeaponManager:GetInventoryWeaponByPropSlot(slot)
        if slua.isValid(Weapon) then
          local ok, meshComponent = pcall(function()
            return import("/Script/Engine.MeshComponent")
          end)
          if ok then
            local ok2, components = pcall(function()
              return Weapon:GetComponentsByClass(meshComponent)
            end)
            if ok2 and components then
              local count = type(components.Num) == "function" and components:Num() or # components
              for i = 1, count do
                local comp = type(components.Get) == "function" and components:Get(i - 1) or components[i]
                if slua.isValid(comp) then
                  if isGlowEnabled then
                    pcall(function()
                      comp.UseScopeDistanceCulling = false
                      comp.PrimitiveShadingStrategy = 1
                      comp.ShadingRate = 6
                      if comp.SetDrawIdeaOutline then
                        comp:SetDrawIdeaOutline( true)
                        if comp.OverrideIdeaOutlineColor then
                          comp:OverrideIdeaOutlineColor( true, finalColor)
                        end
                        if comp.OverrideIdeaOutlineThickness then
                          comp:OverrideIdeaOutlineThickness( true, thickness)
                        end
                      elseif comp.SetRenderCustomDepth then
                        comp:SetRenderCustomDepth( true)
                      end
                    end)
                  else
                    pcall(function()
                      if comp.SetDrawIdeaOutline then
                        comp:SetDrawIdeaOutline( false)
                      elseif comp.SetRenderCustomDepth then
                        comp:SetRenderCustomDepth( false)
                      end
                    end)
                  end
                end
              end
            end
          end
        end
      end
      _G.OwenWeaponGlowWasEnabled = enabled
    end)
    if enabled and not ok then
      _G.OwenWeaponGlowWasEnabled = true
    end
  end
