        pcall(os.remove, A.Path);
        A.Path = nil
      end
      if A.EnginePath then
        pcall(os.remove, A.EnginePath);
        A.EnginePath = nil
      end
      for _, path in ipairs(A.ExportPaths or {}) do
        pcall(os.remove, path)
      end
      A.ExportPaths = nil
    end
    function A.Cancel()
      if A.Busy then
        A.Log('pipeline_closed')
      end
      A.Generation = A.Generation + 1;
      A.Busy = false;
      cleanup()
    end
    local function finish(text)
      A.Cancel();
      status(text, true)
    end
    local function timer(delay, fn)
      local ticker = module('common.time_ticker')
      if not ticker or type(ticker.AddTimerOnce) ~= 'function' then
        return false
      end
      local generation = A.Generation
      local ok, handle = pcall(ticker.AddTimerOnce, delay, function()
        if generation ~= A.Generation or _G.OwenAutoFeedback ~= A then
          return
        end
        if not enabled() then
          A.Cancel();
          return
        end
        local success = pcall(fn)
        if not success then
          finish('Lỗi xử lý ảnh; chưa xác nhận gửi')
        end
      end)
      return ok and handle ~= false
    end
    local function encodeURL(value)
      return (tostring(value):gsub('([^%w%-_%.~])', function(c)
        return string.format('%%%02X', string.byte(c))
      end))
    end
    local function base64(data)
      local alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'
      local result, chunk = {}, {}
      for i = 1, # data, 3 do
        local a, b, c = data:byte(i, i + 2)
        local value = a * 65536 + (b or 0) * 256 + (c or 0)
        chunk[ # chunk + 1] = alphabet:sub(math.floor(value / 262144) % 64 + 1, math.floor(value / 262144) % 64 + 1) .. alphabet:sub(math.floor(value / 4096) % 64 + 1, math.floor(value / 4096) % 64 + 1) .. (b and alphabet:sub(math.floor(value / 64) % 64 + 1, math.floor(value / 64) % 64 + 1) or '=') .. (c and alphabet:sub(value % 64 + 1, value % 64 + 1) or '=')
        if # chunk == 1024 then
          result[ # result + 1] = table.concat(chunk);
          chunk = {}
        end
      end
      if # chunk > 0 then
        result[ # result + 1] = table.concat(chunk)
      end
      return table.concat(result)
    end
    local function imageCandidates(enginePath)
      local paths, seen = {}, {}
      local function add(path)
        if type(path) == 'string' and path ~= '' and not seen[path] then
          seen[path] = true;
          paths[ # paths + 1] = path
        end
      end
      local captureName = enginePath:match('([^/\\]+)$')
      if captureName then
        pcall(add, Client.ProjectSavedDir() .. 'Screenshots/IOS/' .. captureName)
        pcall(function()
          local home = os.getenv('HOME')
          if home and home ~= '' then
            add(home .. '/Documents/ShadowTrackerExtra/Saved/Screenshots/IOS/' .. captureName)
          end
        end)
        for _, config in ipairs(GetConfigPaths(captureName)) do
          add(config:gsub('Paks/' .. captureName .. '$', 'Screenshots/IOS/' .. captureName))
        end
        add('Documents/ShadowTrackerExtra/Saved/Screenshots/IOS/' .. captureName)
        add('../../../ShadowTrackerExtra/Saved/Screenshots/IOS/' .. captureName)
        add('../../ShadowTrackerExtra/Saved/Screenshots/IOS/' .. captureName)
        add('ShadowTrackerExtra/Saved/Screenshots/IOS/' .. captureName)
      end
      add(enginePath)
      if enginePath:sub(1, 13) == '/private/var/' then
        add(enginePath:sub(9))
      end
      local relative = enginePath:match('/Documents/(.+)$')
      if relative then
        add(relative);
        add('Documents/' .. relative)
      end
      if enginePath:sub(1, 1) ~= '/' then
        pcall(add, import('BusinessHelper').GetMobileBasePath(enginePath))
      end
      pcall(add, import('ScriptHelperClient').ConvertRelativePathToFull(enginePath))
      local name = enginePath:match('([^/\\]+)$')
      if name then
        for _, pkg in ipairs( { 'com.vng.pubgmobile', 'com.tencent.ig', 'com.pubg.krmobile', 'com.rekoo.pubgm',
        'com.pubg.imobile' }) do
          add('/storage/emulated/0/Android/data/' .. pkg .. '/files/UE4Game/ShadowTrackerExtra/ShadowTrackerExtra/Saved/Paks/' .. name)
        end
        pcall(function()
          local home = os.getenv('HOME')
          if home and home ~= '' then
            add(home .. '/Documents/ShadowTrackerExtra/Saved/Paks/' .. name)
          end
        end)
        for _, prefix in ipairs( { 'Documents/ShadowTrackerExtra/Saved/Paks/', '../../ShadowTrackerExtra/Saved/Paks/',
        '../../../ShadowTrackerExtra/Saved/Paks/', 'ShadowTrackerExtra/Saved/Paks/', '' }) do
          add(prefix .. name)
        end
      end
      if name and name:match('^owen_feedback_') then
        local roots = {} pcall(function()
          roots[ # roots + 1] = os.getenv('HOME') .. '/Documents/ShadowTrackerExtra/Saved/'
        end)
        pcall(function()
          roots[ # roots + 1] = Client.ProjectSavedDir()
        end)
        for _, config in ipairs(GetConfigPaths(name)) do
          roots[ # roots + 1] = config:gsub('Paks/' .. name .. '$', '')
        end
        for _, root in ipairs(roots) do
          root = root:gsub('[/\\]+$', '') .. '/'
          for _, suffix in ipairs( { 'Screenshots/IOS/', 'Screenshots/iOS/', 'Screenshots/Android/',
          'Screenshots/', '' }) do
            add(root .. suffix .. name)
          end
        end
      end
      return paths
    end
    local function readImageIO(path)
      local file = io.open(path, 'rb')
      if not file then
        return nil, 'file_not_readable', 0
      end
      local measured, length = pcall(function()
        return file:seek('end')
      end)
      if measured and type(length) == 'number' then
        if length > 4500000 then
          pcall(file.close, file);
          return nil, 'over_4500000_bytes', length
        end
      end
      pcall(file.close, file);
      file = io.open(path, 'rb')
      if not file then
        return nil, 'file_not_readable', 0
      end
      local ok, data = pcall(file.read, file, '*a')
      pcall(file.close, file)
      if not ok then
        return nil, 'read_exception', 0
      end
      if type(data) ~= 'string' then
        return nil, 'read_returned_' .. type(data), 0
      end
      if # data == 0 then
        return nil, 'empty_file', 0
      end
      if # data > 4500000 then
        return nil, 'over_4500000_bytes', # data
      end
      if data:sub(1, 3) ~= string.char(255, 216, 255) then
        return nil, data:sub(1, 8) == string.char(137) .. 'PNG' .. string.char(13, 10, 26, 10) and 'png_instead_of_jpeg' or 'not_jpeg', # data
      end
      if data:sub( - 2) ~= string.char(255, 217) then
        return nil, 'jpeg_incomplete', # data
      end
      return data
    end
    local function readImage(path)
      local data, reason, size = readImageIO(path)
      if data then
        return data
      end
      if Client and type(Client.LoadFileToString) == 'function' then
        local loaded, bytes = pcall(Client.LoadFileToString, path)
        if loaded and type(bytes) == 'string' and # bytes > 0 and # bytes <= 4500000 and bytes:sub(1, 3) == string.char(255, 216, 255) and bytes:sub( - 2) == string.char(255, 217) then
          A.Log('image_reader', 'backend=Client.LoadFileToString')
          return bytes
        end
      end
      A.IOReadLogged = A.IOReadLogged or {}
      if not A.IOReadLogged[path] then
        A.IOReadLogged[path] = true A.Log('io_image_read', 'path=' .. tostring(path) .. ';reason=' .. tostring(reason) .. ';bytes=' .. tostring(size or 0))
      end
      return nil, reason, size
    end
    local function ready()
      local cfg = _G.OwenAutoFeedbackConfig
      if type(cfg) ~= 'table' or type(cfg.UploadKey) ~= 'string' or # cfg.UploadKey < 16 then
        status('Chưa cấu hình UPLOAD_KEY (ít nhất 16 ký tự)', true);
        return false
      end
      if type(cfg.ServerURL) ~= 'string' or not cfg.ServerURL:match('^https://[^/%s]+') then
        status('Worker URL cần dùng HTTPS', true);
        return false
      end
      return true
    end
    function A.LocalizeRankName(value)
      if type(value) ~= 'string' then
        return nil
      end
      local text = value:match('^%s*(.-)%s*$')
      local lower = text:lower()
      local names = {
{ 'ace dominator', 'Người Thống Trị Siêu Việt' },
{ 'ace master', 'Bậc Thầy Siêu Việt' },
{ 'conqueror', 'Chí Tôn' },
{ 'platinum', 'Bạch Kim' },
{ 'diamond', 'Kim Cương' },
{ 'bronze', 'Đồng' },
{ 'silver', 'Bạc' },
{ 'crown', 'Cao Thủ' },
{ 'gold', 'Vàng' },
{ 'ace', 'Quán Quân' },
      }
      for _, entry in ipairs(names) do
        local prefix = entry[1]
        if lower:sub(1, # prefix) == prefix then
          local suffix = text:sub( # prefix + 1)
          if suffix == '' or suffix:match('^[%s%-%(%*]') then
            return entry[2] .. suffix
          end
        end
      end
      return text
    end
    local function rankCaption()
      local name, points pcall(function()
        local result = _G.BP_STRUCT_BattleResultData
        local logic = module('GameLua.Mod.BRMod.Client.BattleResult.BattleResultData.BattleResultDataLogic')
        if not logic then
          logic = module('GameLua.Mod.BaseMod.Client.BattleResult.BattleResultData.BattleResultDataLogic')
        end
        if logic and type(logic.GetBattleResultData) == 'function' then
          local ok, current = pcall(logic.GetBattleResultData, logic)
          if ok and current and (current.rating or current.BP_STRUCT_BTRating) then
            result = current
          end
        end
        local rating = result and (result.rating or result.BP_STRUCT_BTRating)
        if rating then
          local score = tonumber(rating.rank_rating)
          if score and score == score and score > 0 and score < 1000000 then
            points = math.floor(score)
          end
          local segment = tonumber(rating.new_segment)
          local util = module('common.func_util')
          if segment and segment > 0 and util and type(util.GetRankTableData) == 'function' then
            local row = util.GetRankTableData(segment, tonumber(result.seasonNumber) or 0)
            if row then
              local value = row.Name
              if type(value) ~= 'string' or value == '' then
                value = row.IntegralTypeName
              end
              if type(value) == 'string' and value ~= '' then
                name = A.LocalizeRankName(value)
              end
            end
          end
        end
      end)
      local text = name or 'Chưa xác định'
      if points then
        text = text .. ' (' .. tostring(points) .. ' điểm)'
      end
      return (text:gsub('&', '&amp;'):gsub('<', '&lt;'):gsub('>', '&gt;'))
    end
    local function upload(data, kills, snapshot)
      if not ready() then
        A.Cancel();
        return
      end
      local http
      local manager = _G.ModuleManager
      local config = manager and manager.CommonModuleConfig and manager.CommonModuleConfig.http_manager
      if config and type(manager.GetModule) == 'function' then
        local ok, instance = pcall(manager.GetModule, config)
        if ok then
          http = instance
        end
      else
        http = module('client.slua.logic.http.http_manager')
      end
      if not http or type(http.Post) ~= 'function' then
        finish('Không có HTTP manager');
        return
      end
      local cfg = _G.OwenAutoFeedbackConfig A.Log('jpeg_ready', 'bytes=' .. tostring( # data))
      local body = 'base64_image=' .. encodeURL(base64(data)) .. '&caption=' .. encodeURL('<b>OWEN VIP — WIN FEEDBACK</b>\n<blockquote>Kills: ' ..
           tostring(kills) .. '\nRank: ' .. snapshot.rank .. '\nUID: ' .. snapshot.uid .. '\nMap: ' ..
           tostring(snapshot.map) .. '\nMode: ' .. tostring(snapshot.mode) .. '\nVN (UTC+7): ' .. snapshot.time ..
           '</blockquote>') .. '&bot_token=' .. encodeURL(cfg.UploadKey)
      A.Log('upload_payload', 'bytes=' .. tostring( # body))
      cleanup()
      local generation = A.Generation status('Đang gửi ảnh kết quả trận…', true)
      local send
      send = function(attempt)
        if generation ~= A.Generation or not enabled() then
          return
        end
        local ok, index = pcall(http.Post, http, cfg.ServerURL, { ['Content-Type'] = 'application/x-www-form-urlencoded' }, body, nil, function(success, data, response, httpStatus)
          if generation ~= A.Generation or _G.OwenAutoFeedback ~= A then
            return
          end
          if not enabled() then
            A.Cancel();
            return
          end
          local body = type(response) == 'string' and response or (type(data) == 'string' and data or '')
          local confirmed = body:find('"status"%s*:%s*true') or (type(response) == 'table' and response.status == true)
          if success and confirmed then
            finish('Đã gửi ảnh vào Telegram')
          else
            local reason = 'Worker/Telegram chưa xác nhận'
            for _, known in ipairs( { 'Invalid upload key', 'Worker configuration incomplete', 'JPEG required',
            'Image too large', 'chat not found', 'bot is not a member', 'not enough rights', 'message thread not found',
            'Unauthorized', 'Forbidden' }) do
              if body:find(known, 1, true) then
                reason = known;
                break
              end
            end
            A.Log('http_response', 'success=' .. tostring(success) .. ';code=' .. tostring(tonumber(httpStatus) or 'unknown'))
            local code = tonumber(httpStatus)
            finish('Gửi thất bại: ' .. reason .. (code and ('; HTTP ' .. tostring(code)) or ''))
          end
        end, 60)
        if generation ~= A.Generation then
          return
        end
        if not ok then
          finish('Không gửi được yêu cầu; không tự thử lại');
          return
        end
        if index == 0 then
          status('HTTP manager chưa sẵn sàng; đang đợi khởi tạo', true)
          if attempt < 3 and timer(2, function()
            send(attempt + 1)
          end) then
            return
          end
          finish('HTTP manager không tạo được yêu cầu (index 0)');
          return
        end
        A.Log('request_started', 'attempt=' .. tostring(attempt))
        A.RequestIndex = index
        if not timer(65, function()
          finish('Hết thời gian chờ; chưa xác nhận gửi, không tự gửi lại')
        end) then
          finish('Không tạo được bộ hẹn giờ')
        end
      end
      send(1)
    end
    local function captureOnEngineTick(kills, snapshot)
      status('Đang chụp ảnh kết quả trận', true)
      local ok, maker = pcall(import, 'ScreenshotMaker')
      if not ok or not maker or type(maker.MakePictureByName) ~= 'function' or type(maker.HasCaptured) ~= 'function' then
        finish('Không có API chụp ảnh');
        return
      end
      local name = 'owen_feedback_' .. tostring(os.time()) .. '_' .. tostring(A.Generation) .. '.jpg'
      local made, actual = pcall(maker.MakePictureByName, name, true)
      if not made or type(actual) ~= 'string' or actual == '' then
        finish('Engine không trả đường dẫn ảnh chụp hợp lệ');
        return
      end
      A.Log('capture_path', 'actual=' .. tostring(actual))
      A.Path = actual;
      A.EnginePath = actual
      local attempts = 0
      local check
      check = function()
        attempts = attempts + 1
        local success, captured = pcall(maker.HasCaptured, A.Path)
        if success and captured then
          A.Log('capture_complete', 'reader=v4;resize_before_read')
          if type(maker.ResizePicture) == 'function' then
            local resized = pcall(maker.ResizePicture, A.Path, 0.45, A.Path)
            A.Log('capture_resize', 'invoked=' .. tostring(resized) .. ';scale=0.45')
          end
          A.ExportPaths = {}
          local function exportJPEG()
            if type(maker.ResizePicture) == 'function' then
              local source = A.EnginePath or A.Path
              local target = source:gsub('%.[^./\\]+$', '') .. '_upload.jpg'
              A.ExportPaths[ # A.ExportPaths + 1] = target
              local ok, result = pcall(maker.ResizePicture, source, 0.6, target)
              A.Log('jpeg_export', 'invoked=' .. tostring(ok) .. ';result_type=' .. type(result))
              local candidates = imageCandidates(target)
              for _, dest in ipairs(candidates) do
                if dest:sub(1, 1) == '/' and dest ~= target then
                  local probe = io.open(dest, 'wb')
                  if probe then
                    probe:close();
                    pcall(os.remove, dest)
                    A.ExportPaths[ # A.ExportPaths + 1] = dest
                    local exported, value = pcall(maker.ResizePicture, source, 0.6, dest)
                    A.Log('jpeg_export_absolute', 'invoked=' .. tostring(exported) .. ';result_type=' .. type(value))
                    break
                  end
                end
              end
            end
          end
          local reads, lastSize = 0, nil
          local waitForImage
          waitForImage = function()
            reads = reads + 1
            local data, reason, size = readImage(A.Path)
            if not data and reads == 2 then
              exportJPEG()
            end
            if not data then
              local candidates = imageCandidates(A.EnginePath or A.Path)
              for _, export in ipairs(A.ExportPaths or {}) do
                for _, path in ipairs(imageCandidates(export)) do
                  candidates[ # candidates + 1] = path
                end
              end
              local bestSize = size or 0
              for index, path in ipairs(candidates) do
                local candidate, why, count = readImage(path)
                if candidate then
                  A.Path = path;
                  data, reason, size = candidate, why, count A.Log('image_path_resolved', 'candidate=' .. tostring(index) .. ';total=' .. tostring( # candidates))
                  break
                elseif (count or 0) > bestSize or (reason == 'file_not_readable' and why ~= 'file_not_readable') then
                  reason, size = why, count;
                  bestSize = count or 0
                end
              end
            end
            if reads == 1 or reads == 12 or reason ~= A.LastReadReason then
              A.Log('image_read', 'attempt=' .. tostring(reads) .. ';reason=' .. tostring(reason or 'jpeg_complete') .. ';bytes=' .. tostring(size or (data and # data) or 0))
            end
            A.LastReadReason = reason
            if data and lastSize == # data then
              upload(data, kills, snapshot);
              return
            end
            lastSize = data and # data or nil
            if reads < 12 then
              if not timer(1, waitForImage) then
                finish('Cannot schedule image read')
              end
            else
              finish('JPEG not ready after capture; upload cancelled')
            end
          end
          if not timer(1, waitForImage) then
            finish('Cannot schedule image read')
          end
        elseif attempts < 15 then
          if not timer(1, check) then
            finish('Không tạo được bộ hẹn giờ')
          end
        else
          finish('Hết thời gian chờ chụp ảnh')
        end
      end
      if not timer(1, check) then
        finish('Không tạo được bộ hẹn giờ')
      end
    end
    local function killsNow()
      local kills = 0 pcall(function()
        local util = module('GameLua.Mod.BaseMod.Client.Like.IngameLikeUtilClient')
        local state = util and util.GetMyPlayerState and util.GetMyPlayerState()
        kills = state and tonumber(state.Kills) or 0
        if kills == 0 then
          local logic = module('GameLua.Mod.BaseMod.Client.BattleResult.BattleResultData.BattleResultDataLogic')
          local result = logic and logic.GetBattleResultData and logic:GetBattleResultData()
          kills = result and tonumber(result.BP_mykill) or 0
        end
      end)
      return math.max(0, math.floor(kills))
    end
    local function capture(kills, snapshot)
      local generation = A.Generation
      local ok, delegate = pcall(function()
        local util = module('client.common.ui_util')
        local instance = util and util.GetGameInstance and util.GetGameInstance()
        return instance and instance.EnginePreTick
      end)
      if not ok or not delegate or type(delegate.Add) ~= 'function' then
        finish('EnginePreTick unavailable; capture cancelled');
        return
      end
      local fired = false
      _G.OwenFeedbackTickDispatchers = _G.OwenFeedbackTickDispatchers or setmetatable( {}, { __mode = 'k' })
      local dispatchers = _G.OwenFeedbackTickDispatchers
      local dispatcher = dispatchers[delegate]
      if not dispatcher then
        dispatcher = {}
        local registered, err = pcall(function()
          delegate:Add(function()
            local job = dispatcher.Job
            if not job then
              return
            end
            dispatcher.Job = nil job()
          end)
        end)
        if not registered then
          A.Log('capture_schedule_failed', tostring(err));
          finish('Cannot register capture');
          return
        end
        dispatchers[delegate] = dispatcher
      end
      local job = function()
        if fired then
          return
        end
        fired = true
        if generation ~= A.Generation or not A.Busy or _G.OwenAutoFeedback ~= A then
          return
        end
        A.Log('capture_engine_tick', 'entered=true')
        local captured, reason = pcall(captureOnEngineTick, kills, snapshot)
        if not captured then
          A.Log('capture_exception', tostring(reason));
          finish('Screenshot capture failed')
        end
      end
      dispatcher.Job = job A.Log('capture_engine_tick', 'scheduled=true')
      timer(5, function()
        if not fired and generation == A.Generation then
          fired = true;
          if dispatcher.Job == job then
            dispatcher.Job = nil
          end
          finish('EnginePreTick did not run')
        end
      end)
    end
    function A.OnWin(params)
      if not enabled() or A.Busy then
        return false
      end
      local now = os.time()
      local seen = type(params) == 'table' and A.Seen[params]
      if (seen and now - seen < 90) or (A.LastWinAt and now - A.LastWinAt < 90) then
        return false
      end
      if not ready() then
        return false
      end
      A.LastWinAt = now
      if type(params) == 'table' then
        A.Seen[params] = now
      end
      A.Generation = A.Generation + 1;
      A.Busy = true status('Đã nhận sự kiện thắng; đợi chụp ảnh', true)
      local function locStr(id)
        id = tonumber(id)
        if not id or id <= 0 then
          return ''
        end
        local loc = rawget(_G, 'LocUtil')
        if not loc then
          return ''
        end
        for _, key in ipairs( { 'TryGetLocalizeResStr', 'GetLocalizeResStr' }) do
          local fn = loc[key]
          if type(fn) == 'function' then
            local ok, v = pcall(fn, id)
            if ok and type(v) == 'string' and v ~= '' and not v:match('^%[?%d+%]?$') then
              return v
            end
          end
        end
        return ''
      end
      local function rowName(row)
        if row == nil then
          return ''
        end
        local keys = {}
        local okScan = pcall(function()
          for k in pairs(row) do
            if type(k) == 'string' then
              keys[ # keys + 1] = k
            end
          end
        end)
        if not okScan then
          return ''
        end
        table.sort(keys)
        local i
        for i = 1, # keys do
          if keys[i]:find('WordsToShow') then
            local okV, v = pcall(function()
              return row[keys[i]]
            end)
            if okV then
              local s = locStr(v)
              if s ~= '' then
                return s
              end
            end
          end
        end
        for i = 1, # keys do
          if keys[i]:find('Name') then
            local okV, v = pcall(function()
              return row[keys[i]]
            end)
            if okV and type(v) == 'string' and v ~= '' and not v:match('^%[?%d+%]?$') then
              return v
            end
          end
        end
        return ''
      end
      local function subModeOwner(cdt, subMode)
        local okTeam, tbl = pcall(cdt.GetTable, 'ModeTeamTable')
        if not okTeam or type(tbl) ~= 'table' then
          return 0
        end
        local ldf = rawget(_G, 'load')
        if type(ldf) ~= 'function' then
          return 0
        end
        local found = 0 pcall(function()
          local k, v
          for k, v in pairs(tbl) do
            local idlist = v and v.SubModeIds
            if type(idlist) == 'string' and idlist ~= '' then
              local okL, loader = pcall(ldf, 'return ' .. idlist)
              if okL and type(loader) == 'function' then
                local okA, list = pcall(loader)
                if okA and type(list) == 'table' then
                  local n, sid
                  for n = 1, # list do
                    sid = tonumber(list[n])
                    if sid == subMode then
                      found = tonumber(k) or 0
                      return
                    end
                  end
                end
              end
            end
          end
        end)
        return found
      end
      local MODE_FAMILY = { TDM = 'TDM', BRTDM = 'TDM', TDCard = 'TD Card', BRCard = 'BR Card', TPlan = 'TPlan',
      TPlanE = 'TPlan', TPlanEBR = 'TPlan', TPlanPVE = 'TPlan PVE', TPlanTDM = 'TPlan TDM', Escape = 'Escape',
      WarGame = 'War Game', SlayTheBot = 'Slay The Bot', SocialIsland = 'Social Island', CreativeBase = 'Creative',
      CreativeDemo = 'Creative', CreativeWoW = 'Creative', }
      local RANKED_CLASSIC = { [101] = true, [102] = true, [103] = true, [401] = true, [402] = true,
      [403] = true, [723] = true, [733] = true }
      local NORMAL_CLASSIC = { [111] = true, [112] = true, [113] = true, [411] = true, [412] = true,
      [413] = true }
      local RANK_WORDS = { 'rank', 'xếp hạng', '排位', 'ランク', '랭크' }
      local NORMAL_WORDS = { 'sinh tồn', 'đấu thường', 'classic', 'battle royale', '经典', '普通', 'ノーマル',
      '일반' }
      local function hasWord(low, list)
        local i
        for i = 1, # list do
          if low:find(list[i], 1, true) then
            return true
          end
        end
        return false
      end
      local function modeLabel(subMode, mainMode, selMode, cfg, localName)
        local rankKnown = false
        local ranked = false
        if RANKED_CLASSIC[mainMode] or RANKED_CLASSIC[selMode] then
          rankKnown = true;
          ranked = true
        end
        if NORMAL_CLASSIC[mainMode] or NORMAL_CLASSIC[selMode] then
          rankKnown = true
        end
        if localName ~= '' then
          local low = localName:lower()
          if hasWord(low, RANK_WORDS) then
            rankKnown = true;
            ranked = true
          elseif hasWord(low, NORMAL_WORDS) then
            rankKnown = true
          end
        end
        local family = ''
        if cfg then
          local okMt, mtv = pcall(function()
            return cfg.ModType
          end)
          if okMt and type(mtv) == 'string' then
            local rawTok
            for rawTok in mtv:gmatch('[^;]+') do
              local tok = rawTok:gsub('^%s+', ''):gsub('%s+$', '')
              if tok:lower():find('rank') then
                rankKnown = true;
                ranked = true
              elseif MODE_FAMILY[tok] then
                family = MODE_FAMILY[tok]
              end
            end
          end
        end
        local key = tonumber(subMode) or 0
        local okTdm, tdm = pcall(require, 'GameLua.Mod.TDM.GamePlay.Config.TDMConfig')
        if okTdm and type(tdm) == 'table' then
          if type(tdm.RankTDMModeConfig) == 'table' and tdm.RankTDMModeConfig[key] then
            rankKnown = true;
            ranked = true;
            family = 'TDM'
          elseif family == '' and type(tdm.ThemeTDMModeConfig) == 'table' and tdm.ThemeTDMModeConfig[key] then
            family = 'TDM'
          end
        end
        if not ranked then
          local okCl, tcl = pcall(require, 'client.slua.logic.loading.logic_teamcomp_loading')
          if okCl and type(tcl) == 'table' and type(tcl.IsRank) == 'function' then
            local okR, rv = pcall(tcl.IsRank, subMode)
            if okR and rv then
              rankKnown = true;
              ranked = true
            end
          end
        end
        if family ~= '' then
          return (ranked and 'Xếp Hạng ' or '') .. family
        end
        if rankKnown then
          if ranked then
            return 'Xếp Hạng'
          end
          return 'Đấu Thường'
        end
        if cfg or mainMode > 0 then
          return 'BattleRoyale'
        end
        return ''
      end
      local function matchInfo()
        local mapName, modeName, source = '', '', ''
        local function read(obj, key)
          local ok, v = pcall(function()
            return obj and obj[key]
          end)
          if ok then
            return v
          end
        end
        local function invoke(obj, key, ...)
          local fn = read(obj, key)
          if type(fn) ~= 'function' then
            return nil
          end
          local ok, value = pcall(fn, ...)
          if ok then
            return value
          end
        end
        local function clean(value)
          if type(value) == 'number' then
            value = locStr(value)
          end
          if type(value) ~= 'string' then
            return ''
          end
          return value:gsub('^%s+', ''):gsub('%s+$', '')
        end
        local aliases = {
{ 'fourmaps', 'Livik' },
{ 'summerland_mian', 'Karakin' },
{ 'baltic', 'Erangel' },
{ 'dihorotok', 'Vikendi' },
{ 'savagemain', 'Sanhok' },
{ 'savage_main', 'Sanhok' },
{ 'pubg_desert', 'Miramar' },
{ 'map_desert', 'Miramar' },
{ 'pubg_neon_main', 'Rondo' }
        }
        local function terrain(value)
          local name = clean(value):lower()
          for _, public in ipairs( { 'Erangel', 'Livik', 'Rondo', 'Miramar', 'Sanhok', 'Vikendi', 'Karakin',
          'Nusa' }) do
            if name:find(public:lower(), 1, true) then
              return public
            end
          end
          for _, entry in ipairs(aliases) do
            if name:find(entry[1], 1, true) then
              return entry[2]
            end
          end
          return ''
        end
        local function use(value, where)
          local name = terrain(value)
          if name ~= '' then
            mapName = name;
            source = where;
            return true
          end
          return false
        end
        local current = rawget(_G, 'OwenAutoFeedback')
        local context = current and current.ResultMapContext
        local subMode = 0
        if context and os.time() - (context.At or 0) >= 0 and os.time() - (context.At or 0) < 30 then
          subMode = tonumber(context.SubMode) or 0
        end
        local mgr = module('client.slua.logic.match.logic_mode_mgr')
        if subMode <= 0 then
          subMode = tonumber(read(mgr, 'nInGameModeID')) or 0
        end
        local native = module('GameLua.GameCore.Main.GameMainConfig')
        if subMode <= 0 then
          subMode = tonumber(invoke(native, 'GetModeID')) or 0
        end
        if subMode <= 0 then
          local instance = invoke(slua, 'getGameInstance')
          subMode = tonumber(invoke(instance, 'GetModeID', instance)) or 0
        end
        if subMode <= 0 then
          subMode = tonumber(read(rawget(_G, 'CGameState'), 'GameModeID')) or 0
