        local cdt = rawget(_G, 'CDataTable')
        local cfg = invoke(cdt, 'GetTableData', 'BTMode', subMode)
        local mapID = tonumber(read(cfg, 'MapID')) or 0
        if mapID <= 0 then
          mapID = tonumber(rawget(_G, 'MapID')) or 0
        end
        local map = mapID > 0 and invoke(cdt, 'GetTableData', 'Map', mapID) or nil
        local game = rawget(_G, 'CGame')
        use(invoke(game, 'GetMapName', game), 'CGame.GetMapName')
        if mapName == '' then
          for _, field in ipairs( { 'MapPath', 'MapNameInternal', 'MapKey', 'ShowName', 'MapName' }) do
            if use(read(map, field), 'Map.' .. field) then
              break
            end
          end
        end
        if mapName == '' then
          use(invoke(native, 'GetMapNameInternal'), 'GameMainConfig.GetMapNameInternal')
        end
        if mapName == '' then
          use(invoke(native, 'GetMapType', subMode), 'GameMainConfig.GetMapType')
        end
        if mapName == '' then
          local ui = module('client.common.ui_util')
          local instance = invoke(ui, 'GetGameInstance')
          local ok, statics = pcall(import, 'GameplayStatics')
          if ok and instance then
            use(invoke(statics, 'GetCurrentLevelName', instance, true), 'GameplayStatics.GetCurrentLevelName')
          end
        end
        if mapName == '' then
          use(invoke(mgr, 'GetMapKeyBySubMode', subMode), 'match.GetMapKeyBySubMode')
        end
        if mapName == '' then
          use(invoke(mgr, 'GetMapNameBySubMode', subMode), 'match.GetMapNameBySubMode')
        end
        local mainMode = tonumber(read(mgr, 'nSelectMatchID')) or 0
        if mainMode <= 0 and cdt and type(cdt.GetTable) == 'function' and subMode > 0 then
          local ok, value = pcall(subModeOwner, cdt, subMode)
          if ok then
            mainMode = tonumber(value) or 0
          end
        end
        local localName = clean(invoke(mgr, 'GetClassicModeWord', mainMode, subMode))
        if localName == '' then
          localName = rowName(invoke(cdt, 'GetTableData', 'MatchModeTable', mainMode))
        end
        if localName == '' then
          localName = rowName(cfg)
        end
        local ok, label = pcall(modeLabel, subMode, mainMode, tonumber(read(mgr, 'nSelectMatchID')) or 0, cfg, localName)
        modeName = ok and clean(label) or localName
        if modeName == '' then
          modeName = localName
        end
        if modeName == '' then
          modeName = '?'
        end
        local fpp = read(cfg, 'IsFpp')
        if fpp and fpp ~= 0 and fpp ~= false then
          modeName = modeName .. ' [FPP]'
        end
        if mapName == '' then
          mapName = 'Chưa xác định'
        end
        if current then
          current.MatchInfo = { Map = mapName, Source = source, SubMode = subMode, MapID = mapID }
        end
        local function esc(v)
          return (tostring(v):gsub('&', '&amp;'):gsub('<', '&lt;'):gsub('>', '&gt;'))
        end
        return esc(mapName), esc(modeName)
      end
      local metroKills = type(params) == 'table' and params.MetroExtraction and tonumber(params.MetroKills)
      local kills = metroKills and metroKills == metroKills and metroKills >= 0 and metroKills < 100000 and math.floor(metroKills) or killsNow()
      local uid = '***' pcall(function()
        local value = tostring(_G.DataMgr.roleData.uid or '')
        if # value >= 8 then
          uid = value:sub(1, 3) .. '****' .. value:sub(8)
        elseif # value >= 5 then
          uid = value:sub(1, 3) .. '****'
        elseif # value > 0 then
          uid = '****'
        end
      end)
      local snapMap, snapMode = matchInfo()
      local snapshot = { map = snapMap, mode = snapMode, rank = rankCaption(), uid = uid, time = os.date('!%Y-%m-%d %H:%M:%S', os.time() + 7 * 60 * 60) }
      A.Snapshot = snapshot
      if not timer(4, function()
        capture(kills, snapshot)
      end) then
        finish('Không có bộ hẹn giờ');
        return false
      end
      return true
    end
    function A.OnMetroResult(data)
      if type(data) ~= 'table' or type(data.metro) ~= 'table' or data.Reason ~= 'win' or data.is_team_result == true or data.is_team_result == 1 then
        return false
      end
      A.MetroSeen = A.MetroSeen or setmetatable( {}, { __mode = 'k' })
      if A.MetroSeen[data] then
        return false
      end
      A.ResultMapContext = { SubMode = data.sub_mode, At = os.time() }
      A.LastTrigger = 'MetroExtraction'
      local uid = _G.DataMgr and _G.DataMgr.roleData and _G.DataMgr.roleData.uid
      local kills
      if uid ~= nil and type(data.TeammateList) == 'table' then
        for _, role in pairs(data.TeammateList) do
          if type(role) == 'table' and tostring(role.UID) == tostring(uid) then
            kills = tonumber(role.Kill);
            break
          end
        end
      end
      local accepted = A.OnWin( { MetroExtraction = true, MetroKills = kills, Reason = 'win' })
      if accepted then
        A.MetroSeen[data] = true
      end
      return accepted
    end
    function A.InstallResultHook()
      local result = module('GameLua.Mod.BRMod.Client.BattleResult.GameOverTips.BattleResultCountDownLogic')
      if not result or type(result.OnResultProcessStart) ~= 'function' then
        return false
      end
      _G.OwenAutoFeedbackResultHooks = _G.OwenAutoFeedbackResultHooks or setmetatable( {}, { __mode = 'k' })
      if _G.OwenAutoFeedbackResultHooks[result] == result.OnResultProcessStart then
        A.ResultHooked = true;
        return true
      end
      local original = result.OnResultProcessStart
      result.OnResultProcessStart = function(self, ...)
        local active = _G.OwenAutoFeedback
        if active and self then
          active.ResultMapContext = { SubMode = self.sub_mode, At = os.time() }
        end
        local values = table.pack(original(self, ...))
        pcall(function()
          local current = _G.OwenAutoFeedback
          if current and self and self.BattleReason == 'win' and tonumber(self.Rank) == 1 then
            current.LastTrigger = 'BattleResultCountDownLogic' current.OnWin( { Reason = 'win', ShowedWinLogo = true })
          end
        end)
        return unpackValues(values, 1, values.n)
      end
      _G.OwenAutoFeedbackResultHooks[result] = result.OnResultProcessStart
      A.ResultHooked = true;
      return true
    end
    function A.ProbeImageIO()
    end
    function A.StatusText()
      local text = 'Auto Feedback: ' .. (enabled() and 'BẬT' or 'TẮT') .. '\nHook UI: ' .. (A.Hooked and 'Đã gắn' or 'Chưa gắn') .. '\nHook kết quả trận: ' .. (A.ResultHooked and 'Đã gắn' or 'Chưa gắn') .. '\nSự kiện thắng: ' .. (A.LastWinAt and 'Đã nhận' or 'Chưa nhận') .. '\nĐang xử lý: ' .. (A.Busy and 'Có' or 'Không') .. '\nTrạng thái: ' .. tostring(A.Status)
      return text
    end
    function A.ShowStatus()
      A.ProbeImageIO()
      local text = A.StatusText()
      local box = module('client.slua.logic.common.logic_common_msg_box')
      if box and type(box.Show) == 'function' then
        pcall(box.Show, 1, 'Trạng thái Feedback', text, function()
        end, nil, 'Đóng')
      else
        status(text, true)
      end
      return text
    end
    _G.OwenAutoFeedbackHooks = _G.OwenAutoFeedbackHooks or setmetatable( {}, { __mode = 'k' })
    function A.Install()
      if not enabled() then
        return false
      end
      local resultHook = A.InstallResultHook()
      local ui = _G.UIManager or module('client.slua_ui_framework.manager')
      if not ui or type(ui.ShowUI) ~= 'function' then
        return resultHook
      end
      if _G.OwenAutoFeedbackHooks[ui] == ui.ShowUI then
        A.Hooked = true;
        return true
      end
      local original = ui.ShowUI
      local function pack( ...)
        return { n = select('#', ...), ... }
      end
      ui.ShowUI = function(config, params, ...)
        local result = pack(original(config, params, ...))
        pcall(function()
          local current = _G.OwenAutoFeedback
          local configs = ui.UI_Config_InGame
          local winner = configs and configs.GameOverCountDown_UIBP
          if current and winner and config == winner and type(params) == 'table' and (params.Reason == 'win' or params.ShowedWinLogo == true) then
            current.LastTrigger = 'UIManager.ShowUI';
            current.OnWin(params)
          elseif current and configs and configs.XTBattleResultAll and config == configs.XTBattleResultAll then
            local data = type(params) == 'table' and params.Data or nil
            if not data then
              local legacy = package.loaded['GameLua.Mod.TPlan.Client.logicXtBattleResult']
              data = legacy and legacy.Data
            end
            if current.OnMetroResult then
              current.OnMetroResult(data)
            end
          end
        end)
        return unpackValues(result, 1, result.n)
      end
      _G.OwenAutoFeedbackHooks[ui] = ui.ShowUI
      A.Hooked = true
      return true
    end
    function A.SetEnabled(value)
      local on = value == true or value == 1
      if on and not ready() then
        return false
      end
      _G.MWConfig.AutoFeedbackEnabled = on
      if on then
        local installed = A.Install()
        status(installed and 'Đã bật; đang đợi trận thắng (không gửi khi /start Telegram)' or 'Đã bật; đang chờ UIManager để gắn sự kiện thắng', true)
      else
        A.Cancel();
        status('Đã tắt; yêu cầu đã gửi trước đó có thể vẫn hoàn tất', true)
      end
      return true
    end
    if _G.OwenRuntimeGuard and _G.OwenRuntimeGuard.Start then
      _G.OwenRuntimeGuard.Start('OwenAutoFeedbackInstall', 3, function()
        if enabled() then
          A.Install()
        elseif A.Busy then
          A.Cancel()
        end
      end, 2)
    end
  end
  local ConfigFileName = "Owen.dat"
  _G.MWSaveSys = { VERSION = 2, MAGIC = "LXSV", unpack = table.unpack or unpack }
  _G.MWSaveSys.KEY = { 76, 101, 120, 117, 115, 77, 87, 33, 55, 145, 163, 94, 12, 107, 210, 31, 88, 201,
  5, 66, 139, 250, 42, 173 }
  _G.LastConfigSaveStr = ""
  _G.MWSaveOutfit = _G.MWSaveOutfit
  function _G.MWSaveSys.Codec(str, enc)
    local LS = _G.MWSaveSys
    local n, kn = # str, # LS.KEY
    local out, chunk, ci = {}, {}, 0
    for i = 1, n do
      local b = string.byte(str, i)
      local k = (LS.KEY[(i - 1) % kn + 1] + i * 7) % 256
      if enc then
        b = (b + k) % 256
      else
        b = (b - k) % 256
      end
      ci = ci + 1
      chunk[ci] = b
      if ci == 200 then
        out[ # out + 1] = string.char(LS.unpack(chunk, 1, ci))
        ci = 0
      end
    end
    if ci > 0 then
      out[ # out + 1] = string.char(LS.unpack(chunk, 1, ci))
    end
    return table.concat(out)
  end
  function _G.MWSaveSys.SortedKeys(t)
    local keys = {}
    for k in pairs(t) do
      keys[ # keys + 1] = k
    end
    table.sort(keys, function(a, b)
      return tostring(a) < tostring(b)
    end)
    return keys
  end
  function _G.MWSaveSys.KeyText(k)
    if type(k) == "number" then
      return "[" .. tostring(k) .. "]"
    end
    return "[" .. string.format("%q", tostring(k)) .. "]"
  end
  function _G.MWSaveSys.ValueText(v)
    local tv = type(v)
    if tv == "string" then
      return string.format("%q", v)
    end
    if tv == "boolean" or tv == "number" then
      return tostring(v)
    end
    return nil
  end
  _G.OwenSaveSnapshot = {
    Config = {},
    Text = {},
    Valid = false
  }
  function _G.OwenSaveSnapshot.Same(source, snapshot)
    for key, value in pairs(source or {}) do
      if snapshot[key] ~= value then
        return false
      end
    end
    for key in pairs(snapshot) do
      if (source or {})[key] == nil then
        return false
      end
    end
    return true
  end
  function _G.OwenSaveSnapshot.Copy(source, snapshot)
    for key in pairs(snapshot) do
      snapshot[key] = nil
    end
    for key, value in pairs(source or {}) do
      snapshot[key] = value
    end
  end
  _G.SaveModSettings = function()
    _G.OwenTrialAccess.EnforceConfig()
    local quick = _G.OwenSaveSnapshot
    local config = _G.MWConfig or {};
    local text = (_G.MWState or {}).CustomTextData or {}
    if quick.Valid and quick.Outfit == _G.MWSaveOutfit and quick.Same(config, quick.Config) and quick.Same(text, quick.Text) then
      return true
    end
    local saved = false
    local ok = pcall(function()
      local LS = _G.MWSaveSys
      local parts = { "return {\nV = " .. LS.VERSION .. ",\nMWConfig = {\n" }
      local cfg = _G.MWConfig or {}
      for _, k in ipairs(LS.SortedKeys(cfg)) do
        local vt = LS.ValueText(cfg[k])
        if vt then
          parts[ # parts + 1] = "  " .. LS.KeyText(k) .. " = " .. vt .. ",\n"
        end
      end
      parts[ # parts + 1] = "},\nCustomTextData = {\n"
      local ctd = _G.MWState and _G.MWState.CustomTextData
      if ctd then
        for _, k in ipairs(LS.SortedKeys(ctd)) do
          local vt = LS.ValueText(ctd[k])
          if vt then
            parts[ # parts + 1] = "  " .. LS.KeyText(k) .. " = " .. vt .. ",\n"
          end
        end
      end
      parts[ # parts + 1] = "},\nOutfit = " .. (type(_G.MWSaveOutfit) == "string" and string.format("%q", _G.MWSaveOutfit) or "nil") .. ",\n}"
      local data = table.concat(parts)
      if data == _G.LastConfigSaveStr then
        saved = true;
        return
      end
      local blob = LS.Codec(LS.MAGIC .. data, true)
      for _, path in ipairs(GetConfigPaths(ConfigFileName)) do
        local file = io.open(path, "wb")
        if file then
          local writeOK, written = pcall(file.write, file, blob)
          local closeOK, closed = pcall(file.close, file)
          if writeOK and written and closeOK and closed then
            _G.LastConfigSaveStr = data;
            saved = true;
            break
          end
        end
      end
    end)
    if ok and saved then
      quick.Copy(config, quick.Config);
      quick.Copy(text, quick.Text);
      quick.Outfit = _G.MWSaveOutfit;
      quick.Valid = true
    end
    return ok and saved
  end
  _G.OwenSetMenuLanguage = function(value, persist)
    local codes = { en = 1, vi = 2, zh = 3 }
    local index = type(value) == 'string' and codes[value:lower()] or nil
    index = index or tonumber(value)
    if not index or index % 1 ~= 0 or index < 1 or index > 3 then
      return false
    end
    local code = ( { 'en', 'vi', 'zh' })[index]
    local cfg = rawget(_G, 'MWConfig')
    if type(cfg) ~= 'table' then
      _G.OwenPendingMenuLanguage = code;
      return false
    end
    cfg.MenuLanguage = index;
    _G.MWLang = ( { 'EN', 'VI', 'ZH' })[index]
    _G.OwenPendingMenuLanguage = nil
    if type(_G.RebuildMWTextMap) == 'function' then
      pcall(_G.RebuildMWTextMap)
    end
    if persist ~= false then
      if type(_G.OwenPersistMenuLanguage) == 'function' then
        pcall(_G.OwenPersistMenuLanguage, code)
      end
      if type(_G.SaveModSettings) == 'function' then
        pcall(_G.SaveModSettings)
      end
    end
    if type(_G.OwenRefreshMenuLanguage) == 'function' then
      pcall(_G.OwenRefreshMenuLanguage)
    end
    return true
  end
  _G.LoadModSettings = function()
    pcall(function()
      local LS = _G.MWSaveSys
      for _, p in ipairs(GetConfigPaths("settings.txt")) do
        pcall(os.remove, p)
      end
      local blob = nil
      for _, path in ipairs(GetConfigPaths(ConfigFileName)) do
        local file = io.open(path, "rb")
        if file then
          blob = file:read("*a")
          file:close()
          break
        end
      end
      if blob == nil then
        for _, path in ipairs(GetConfigPaths("save.dat")) do
          local file = io.open(path, "rb")
          if file then
            blob = file:read("*a")
            file:close()
            break
          end
        end
      end
      local saved = nil
      if blob and # blob > # LS.MAGIC then
        local txt = LS.Codec(blob, false)
        if txt:sub(1, # LS.MAGIC) == LS.MAGIC then
          local fn = load(txt:sub( # LS.MAGIC + 1), "owen_config", "t", {})
          if fn then
            local ok, t = pcall(fn)
            if ok and type(t) == "table" and t.V == LS.VERSION then
              saved = t
            end
          end
        end
      end
      local defs = _G.MWDefaultTextData()
      _G.MWState.CustomTextData = _G.MWState.CustomTextData or {}
      local ctd = _G.MWState.CustomTextData
      for k, v in pairs(defs) do
        if ctd[k] == nil then
          ctd[k] = v
        end
      end
      if saved then
        local extraCfg = { LessRecoil = true, VerticalRecoil = true, EmoteQuickSlots = true, EmoteWheelSlots = true }
        if type(saved.MWConfig) == "table" then
          for k, v in pairs(saved.MWConfig) do
            local group, field
            if type(k) == "string" then
              group, field = k:match("^AimProfile_(%u+)_([%a]+)$")
            end
            local profile = group and ( { AR = true, SMG = true, SR = true, SG = true, LMG = true, PISTOL = true,
            OTHER = true })[group] and (field == "FOV" or field == "Speed" or field == "Bone") and tonumber(v)
            local emoteSlots = k == "EmoteQuickSlots" or k == "EmoteWheelSlots"
            if ( not emoteSlots or (type(v) == "string" and # v <= 1024 and v:sub(1, 3) == "v1;")) and (_G.MWConfig[k] ~= nil or extraCfg[k] or profile) then
              _G.MWConfig[k] = v
            end
          end
        end
        if type(saved.MWConfig) == 'table' and saved.MWConfig.GraphicsResolutionPercent == nil then
          local old = { false, 50, 60, 70, 80, 90, 100 }
          local value = old[tonumber(saved.MWConfig.GraphicsResolution) or 1]
          _G.MWConfig.GraphicsResolutionPercent = value and value - 48 or 1
        end
        if type(saved.CustomTextData) == "table" then
          for k, v in pairs(saved.CustomTextData) do
            if defs[k] ~= nil or (type(k) == "string" and (k:match("^SkinProfile[%w_]+$") or k:match("^SkinGarage%d+Slot%d+$") or k:match("^SkinShowcase_[%w_]+$"))) then
              ctd[k] = v
            end
          end
        end
        if type(saved.Outfit) == "string" and # saved.Outfit > 0 then
          _G.MWSaveOutfit = saved.Outfit
        end
      end
      for _, key in ipairs( { "InfiniteAmmo", "FastSwapWeapon", "SuperBullet", "HitEffect", "SpeedRunV2",
      "JumpHighSingle", "LowGravity", "FlashSpeed", "FastCar", "VehicleInstantStop", "AutoHorn", "RainEffect",
      "SnowEffect" }) do
        _G.MWConfig[key] = false
      end
      for key, default in pairs(_G.MWDefaultConfig()) do
        local value = _G.MWConfig[key]
        if value == nil then
          _G.MWConfig[key] = default
        elseif type(default) == 'boolean' then
          _G.MWConfig[key] = (value == true or value == 1)
        elseif type(default) == 'number' then
          local number = tonumber(value)
          _G.MWConfig[key] = (number and number == number and number ~= math.huge and number ~= - math.huge) and number or default
        end
      end
      _G.OwenSetMenuLanguage(rawget(_G, 'OwenPendingMenuLanguage') or _G.MWConfig.MenuLanguage, false)
      _G.SaveModSettings()
    end)
  end
  _G.MWResetSettings = function()
    pcall(function()
      local defs = _G.MWDefaultConfig()
      for k, v in pairs(defs) do
        _G.MWConfig[k] = v
      end
      for k in pairs(_G.MWConfig) do
        if type(k) == "string" and k:match("^AimProfile_") then
          _G.MWConfig[k] = nil
        end
      end
      _G.MWConfig.LessRecoil = false
      _G.MWConfig.VerticalRecoil = false
      _G.MWState.CustomTextData = _G.MWState.CustomTextData or {}
      local ctd = _G.MWState.CustomTextData
      for k in pairs(ctd) do
        ctd[k] = nil
      end
      for k, v in pairs(_G.MWDefaultTextData()) do
        ctd[k] = v
      end
      for _, R in pairs(_G.MWMenuRows or {}) do
        pcall(function()
          if R.GetFunc and R.SetFunc then
            local v = R.GetFunc()
            if v ~= nil then
              R.SetFunc( nil, v)
            end
          end
        end)
      end
      _G.OwenSetMenuLanguage(_G.MWConfig.MenuLanguage)
      _G.SaveModSettings()
    end)
  end
  local function AutoSaveLoop()
    if _G.SaveModSettings then
      local saved = _G.SaveModSettings()
      if saved == false then
        error('settings_save_failed', 0)
      end
    end
  end
  if not _G.ModConfigLoaded then
    _G.LoadModSettings()
    if rawget(_G, 'OwenPendingMenuLanguage') then
      _G.OwenSetMenuLanguage(_G.OwenPendingMenuLanguage)
    end
    _G.MWConfig.HWIDGetterTrace = false _G.OwenTrialAccess.EnforceConfig()
    _G.ModConfigLoaded = true
  end
  _G.OwenRuntimeGuard.Start('AutoSave', 3.7, AutoSaveLoop)
  _G.ReadLiveConfig = function()
    if _G.SaveModSettings then
      _G.SaveModSettings()
    end
  end
