  local function ShowMWVIPMenu()
    local NM = _G.OwenNeonMenus
    if NM and not NM.Installed and _G.RealNow() >= (NM.NextProbe or 0) then
      NM.NextProbe = _G.RealNow() + 5;
      pcall(NM.Sync)
    end
    if _G.MWMenuAlreadyShown then
      return
    end
    if _G.MWState.MenuStep ~= 0 then
      return
    end
    _G.MWLang = ( { "EN", "VI", "ZH" })[_G.MWConfig.MenuLanguage or 1] or "EN"
    if not _G.InitModMenuTab() then
      return
    end
    _G.MWState.MenuStep = 99
    _G.MWMenuAlreadyShown = true pcall(function()
      if _G.SaveModSettings then
        _G.SaveModSettings()
      end
    end)
  end
  local function InitializeGraphicsUnlock()
    if not OwenNeonAuthorized() then
      return
    end
    if _G.MWState.GraphicsUnlocked then
      return
    end
    pcall(function()
      local SettingCfg = require("client.logic.setting.setting_config")
      local GraphicSettingDB = require("client.slua.umg.NewSetting.GraphicsNew.GraphicSettingDB")
      if SettingCfg then
