  local function GetAllSkeletalMeshes(enemy, markData)
    local curTime = _G.RealNow()
    if markData and markData.CachedPrimaryMesh == enemy.Mesh and markData.CachedMeshes and markData.CachedMeshTime and (curTime - markData.CachedMeshTime < 3.0) then
      local validMeshes = {}
      for _, cachedMesh in ipairs(markData.CachedMeshes) do
        if Valid(cachedMesh) then
          table.insert(validMeshes, cachedMesh)
        end
      end
      markData.CachedMeshes = validMeshes
      return validMeshes
    end
    local meshes = {}
    if Valid(enemy.Mesh) then
      table.insert(meshes, enemy.Mesh)
    end
    pcall(function()
      local SkeletalMeshClass = import("SkeletalMeshComponent")
      if SkeletalMeshClass and type(enemy.GetComponentsByClass) == "function" then
        local childs = enemy:GetComponentsByClass(SkeletalMeshClass)
        if childs then
          local count = type(childs.Num) == "function" and childs:Num() or # childs
          for i = 1, count do
            local comp = type(childs.Get) == "function" and childs:Get(i - 1) or childs[i]
            if Valid(comp) and comp ~= enemy.Mesh then
              table.insert(meshes, comp)
            end
          end
        end
      end
    end)
    if markData then
      local unique, seen = {}, {}
      for _, mesh in ipairs(meshes) do
        if Valid(mesh) and not seen[mesh] then
          seen[mesh] = true;
          unique[ # unique + 1] = mesh
        end
      end
      if _G.OwenUnDyeEnemyMesh and (markData.ColorNewApplied or markData.NeonOutlineHash) then
        for _, old in ipairs(markData.CachedMeshes or {}) do
          if not seen[old] then
            pcall(_G.OwenUnDyeEnemyMesh, old)
          end
        end
      end
      meshes = unique
      markData.CachedPrimaryMesh = enemy.Mesh
      markData.WallMeshVersion = (markData.WallMeshVersion or 0) + 1
      markData.CachedMeshes = meshes
      markData.CachedMeshTime = curTime
    end
    return meshes
  end
