  _G.GetEnemyTargetsFromActors = function(radius)
    radius = tonumber(radius) or 0
    local cacheNow = (_G.RealNow and _G.RealNow()) or os.clock()
    local cached = _G._EnemyTargetsCache
    if cached and cached.Radius == radius and (cacheNow - (cached.At or 0)) < 0.1 then
      return cached.List
    end
    local result = {}
    local player = GameplayData.GetPlayerCharacter()
    if not slua.isValid(player) then
      return result
    end
    local allCharacters = {}
    if GameplayData.GetAllPlayerCharacters then
      allCharacters = GameplayData.GetAllPlayerCharacters()
    elseif GameplayData.GameCharacters then
      for _, char in pairs(GameplayData.GameCharacters) do
        table.insert(allCharacters, char)
      end
    end
    local myTeam = player:GetTeamID()
    for _, actor in pairs(allCharacters) do
      if slua.isValid(actor) and actor ~= player then
        local hp = tonumber(actor.HealthStatus)
        local alive = (hp and hp ~= 2) or (actor.GetTeamID and actor:IsAlive())
        if alive and (tonumber(actor.TeamID) or (actor.GetTeamID and actor:GetTeamID())) ~= myTeam then
          local dist = player:GetDistanceTo(actor)
          if dist <= radius then
            table.insert(result, actor)
          end
        end
      end
    end
    _G._EnemyTargetsCache = { At = cacheNow, Radius = radius, List = result }
    return result
  end
