            return weapon.BulletFireSpeed
          end)
          if ok then
            speed = tonumber(v)
          end
        end
        if not speed or speed < 30 or speed > 300000 then
          if kind == 'SNIPER' then
            speed = 90000
          elseif kind == 'MORTAR' then
            speed = 10000
          elseif kind == 'SHOTGUN' then
            speed = 37000
          else
            speed = 88000
          end
        end
        if speed > 2000 then
          speed = speed / 100
        end
        cache[key] = speed
        return speed
      end
      function _G.OwenAimLead(target, origin, aim, predVal, weapon, kind)
        local px, py, pz = tonumber(aim.X) or 0, tonumber(aim.Y) or 0, tonumber(aim.Z) or 0
        if not Valid(target) then
          return px, py, pz
        end
        local okV, vel = pcall(target.GetVelocity, target)
        if not okV or not vel then
          return px, py, pz
        end
        local vx, vy, vz = tonumber(vel.X) or 0, tonumber(vel.Y) or 0, tonumber(vel.Z) or 0
        local moving = not (vx == 0 and vy == 0 and vz == 0)
        if not moving then
          return px, py, pz
        end
        local ox = tonumber(origin.X) or px
        local oy = tonumber(origin.Y) or py
        local oz = tonumber(origin.Z) or pz
        local speed = _G.OwenBulletSpeed(weapon, kind)
        if speed < 40 then
          speed = 40
        end
        local strength = predVal / 50.0
        if strength < 0 then
          strength = 0
        elseif strength > 2 then
          strength = 2
        end
        local ax, ay, az = px, py, pz
        for _ = 1, 3 do
          local dx, dy, dz = ax - ox, ay - oy, az - oz
          local dist = math.sqrt(dx * dx + dy * dy + dz * dz) / 100.0
          local tof = dist / speed
          if tof < 0 then
            tof = 0
          elseif tof > 3 then
            tof = 3
          end
          ax = px + vx * tof * strength
          ay = py + vy * tof * strength
          az = pz + vz * tof * strength
        end
        return ax, ay, az
      end
