          end
          if softAim then
            local state = _G.MWState.AimSoftControl
            if state then
              state.Yaw, state.Pitch = rotation.Yaw, rotation.Pitch
            end
          end
          if manualShot then
            _G.MWState.AimLastShotStatus = "rotated"
          end
          local canFireNow = true
          if isSG and sgAutoFire then
            local boneDist pcall(function()
              local point = AIM_VECTOR2D and AIM_VECTOR2D(0, 0) or { X = 0, Y = 0 }
              if AimProject(pc, fb, point) then
                boneDist = math.sqrt((point.X - cX) ^ 2 + (point.Y - cY) ^ 2)
              end
            end)
            if not boneDist or boneDist > fireGatePx then
              canFireNow = false
            end
          end
          if isSG and sgAutoFire then
            if not canFireNow then
              StopAimAutoFire(player)
            else
              local current = type(player.GetCurrentWeapon) == "function" and player:GetCurrentWeapon() or weapon
              if not Valid(current) then
                current = weapon
              end
              requestAutoFire = AimStepShotgunAutoFire(player, pc, current)
            end
          end
        end)
        if AIM_SCRATCH_USED then
          AIM_SCRATCH_USED = false
          for _, row in pairs(AIM_RANK_ROWS) do
            row.target = nil
          end
          AimClear(AIM_RANK_SCRATCH);
          AimClear(AIM_CANDIDATE_SCRATCH);
          AimClear(AIM_ROTATE_SCRATCH)
        end
        if _G.MWState then
          _G.MWState.AimLastError = not success and tostring(aimError) or nil
        end
        if manualShot and not success then
          _G.MWState.AimLastShotStatus = "error:" .. tostring(aimError)
        end
        if not manualShot and not requestAutoFire then
          StopAimAutoFire()
        end
      end
      local AIM_LOOP_TOKEN = {};
      _G.OwenNeonAimGeneration = AIM_LOOP_TOKEN
      local AIM_SHOT_BINDINGS = setmetatable( {}, { __mode = "k" })
      local AIM_SHOT_RETRY = setmetatable( {}, { __mode = "k" })
      local AIM_SHOT_STATS = { Bound = 0, Events = 0, Rotated = 0, Errors = 0 }
      _G.OwenShotgunEventStats = AIM_SHOT_STATS
      local function BindShotgunEvent(player)
        if not Valid(player) then
          return
        end
        local key = player pcall(function()
          key = player.Object or player
        end)
        if AIM_SHOT_BINDINGS[key] or _G.RealNow() < (AIM_SHOT_RETRY[key] or 0) then
          return
        end
        local delegate = nil pcall(function()
          delegate = player.OnCharacterShootBulletDelegate
        end)
        if not delegate then
          AIM_SHOT_RETRY[key] = _G.RealNow() + 2;
          return
        end
        local record = { Busy = false }
        local ok, err = pcall(function()
          local result = delegate:Add(function(weapon, bullet)
            local callbackOK, callbackError = pcall(function()
              if _G.OwenNeonAimGeneration ~= AIM_LOOP_TOKEN or record.Busy then
                return
              end
              local cfg = _G.MWConfig
              if not cfg or not AimEnabled(cfg.AimTouchEnable) or not AimEnabled(cfg.AimTouchSG) then
                return
              end
              if AimEnabled(cfg.AimTouchSGAutoFire) then
                return
              end
              local contextOK, pc, current, lobby = pcall(AimPlayerContext)
              if not contextOK or lobby or not Valid(current) or not Valid(pc) then
                return
              end
              local currentKey = current pcall(function()
                currentKey = current.Object or current
              end)
              if currentKey ~= key then
                return
              end
              local kind, held = AimWeaponKind(current)
              if kind ~= "SHOTGUN" then
                return
              end
              if Valid(weapon) and Valid(held) then
                local eventKey, heldKey = weapon, held pcall(function()
                  eventKey = weapon.Object or weapon;
                  heldKey = held.Object or held
                end)
                if eventKey ~= heldKey then
                  return
                end
              end
              record.Busy = true;
              AIM_SHOT_STATS.Events = AIM_SHOT_STATS.Events + 1
              local worked, reason = pcall(_G.AimTouch, pc, current, false, AIM_SHOT_TOKEN)
              record.Busy = false
              local status = worked and (_G.MWState.AimLastShotStatus or "no_status") or ("error:" .. tostring(reason))
              if status == "rotated" then
                AIM_SHOT_STATS.Rotated = AIM_SHOT_STATS.Rotated + 1
              end
              if not worked or status:sub(1, 6) == "error:" then
                AIM_SHOT_STATS.Errors = AIM_SHOT_STATS.Errors + 1
              end
              AIM_SHOT_STATS.LastStatus = status
            end)
            if not callbackOK then
              record.Busy = false;
              AIM_SHOT_STATS.Errors = AIM_SHOT_STATS.Errors + 1
              AIM_SHOT_STATS.LastStatus = "callback_error:" .. tostring(callbackError)
            end
          end)
          if result == false then
            error("delegate_add_rejected")
          end
        end)
        if ok then
          AIM_SHOT_BINDINGS[key] = record;
          AIM_SHOT_STATS.Bound = AIM_SHOT_STATS.Bound + 1
        else
          AIM_SHOT_RETRY[key] = _G.RealNow() + 2
        end
      end
      local AIM_WAS_ENABLED = false
      local nextPrune = 0
      _G.OwenNeonV33AimStep = function(pc, player, inLobby, dt)
        if not OwenNeonAuthorized() or not AimEnabled(_G.MWConfig.AimTouchEnable) or inLobby then
          if AIM_WAS_ENABLED then
            ClearAimRuntime();
            AIM_WAS_ENABLED = false
          end
          _G.MWState.AimLineScreenPos = nil;
          return
        end
        local cfg = _G.MWConfig
        if not (AimEnabled(cfg.AimTouchHipfire) or AimEnabled(cfg.AimTouchSG) or AimEnabled(cfg.AimTouchScopeAll) or AimEnabled(cfg.AimTouchScopeSniper) or AimEnabled(cfg.AimTouchMortar)) then
          if AIM_WAS_ENABLED then
            ClearAimRuntime();
            AIM_WAS_ENABLED = false
          end
          return
        end
        AIM_WAS_ENABLED = true
        _G.MWState.AimFrameDelta = dt
        if AimEnabled(_G.MWConfig.AimTouchSG) and not AimEnabled(_G.MWConfig.AimTouchSGAutoFire) then
          BindShotgunEvent(player)
        end
        _G.AimTouch(pc, player, inLobby)
        local now = _G.RealNow()
        if now >= nextPrune then
          nextPrune = now + 5;
          PruneAimVisCache(AIM_TARGET_CACHE.List)
        end
      end
    end
    InstallNeonV33Aim()
  end
