  _G._RN_off, _G._RN_lastRaw, _G._RN_last = 0, nil, 0
  function _G.RealNow()
    local GS = _G._RealNow_GS
    if GS == nil then
      GS = import("GameplayStatics") or false;
      _G._RealNow_GS = GS
    end
    local t = nil
    if GS then
      local w = slua.getWorld()
      if w then
        local ok, v = pcall(GS.GetRealTimeSeconds, w)
        if ok and type(v) == "number" then
          t = v
        end
      end
    end
    if not t then
      t = os.clock()
    end
    if _G._RN_lastRaw and t < _G._RN_lastRaw - 0.5 then
      _G._RN_off = _G._RN_last - t + 0.001
    end
    _G._RN_lastRaw = t
    local v = t + _G._RN_off
    if v < _G._RN_last then
      v = _G._RN_last
    end
    _G._RN_last = v
    return v
  end
  do
    local _MC = {}
    function _G.OwenImp(name)
      local v = _MC[name]
      if v ~= nil then
        return v
      end
      local ok, r = pcall(import, name)
      if not ok then
        return nil
      end
      if r ~= nil then
        _MC[name] = r
      end
      return r
    end
    function _G.OwenReq(name)
      local k = "\1" .. name
      local v = _MC[k]
      if v ~= nil then
        return v
      end
      local ok, r = pcall(require, name)
      if not ok then
        return nil
      end
      if r ~= nil then
        _MC[k] = r
      end
      return r
    end
  end
  _G.ItemESP_MaxLabels = 80
  function _G.OwenItemName(id)
    id = tonumber(id)
    if not id or id <= 0 then
      return nil
    end
    local cdt = rawget(_G, 'CDataTable')
    if not cdt or type(cdt.GetTableData) ~= 'function' then
      return nil
    end
    local ok, row = pcall(cdt.GetTableData, 'Item', id)
    if not ok or not row then
      return nil
    end
    local got, name = pcall(function()
      return row.ItemName
    end)
    if got and type(name) == 'string' and name ~= '' then
      return name
    end
    return nil
  end
  do
    local levels = { [502001] = 1, [502002] = 2, [502003] = 3, [502004] = 1, [503001] = 1, [503002] = 2,
    [503003] = 3, [501001] = 1, [501002] = 2, [501004] = 1, [501006] = 3 }
    local gearVI = { Helmet = 'Mũ', Vest = 'Giáp', Bag = 'Balo' }
    local gearEN = { Helmet = 'Helmet', Vest = 'Vest', Bag = 'Bag' }
    local compact = {
[203001] = { 'Red Dot', 'Red Dot' },
[203002] = { 'Holo', 'Holo' },
[203003] = { '2x', '2x' },
[203004] = { '4x', '4x' },
[203005] = { '8x', '8x' },
[203014] = { '3x', '3x' },
[203015] = { '6x', '6x' },
[601001] = { 'Nước tăng lực', 'Energy' },
[601002] = { 'Adrenaline', 'Adrenaline' },
[601003] = { 'Giảm đau', 'Painkillers' },
[601004] = { 'Băng', 'Bandage' },
[601005] = { 'Sơ cứu', 'First Aid' },
[601006] = { 'Túi cứu thương', 'Med Kit' },
[601020] = { 'Băng', 'Bandage' },
[601021] = { 'Sơ cứu', 'First Aid' },
[601022] = { 'Túi cứu thương', 'Med Kit' },
[602001] = { 'Bom choáng', 'Stun' },
[602002] = { 'Bom khói', 'Smoke' },
[602003] = { 'Bom lửa', 'Molotov' },
[602004] = { 'Lựu đạn', 'Frag' }
    }
    function _G.OwenItemESPName(id, itemData)
      if not itemData then
        return nil
      end
      local english = _G.MWLang == 'EN'
      id = tonumber(id)
      local category = itemData.cat
      if category == 'Helmet' or category == 'Vest' or category == 'Bag' then
        local level = levels[id]
        if level then
          local names = english and gearEN or gearVI
          return names[category] .. ' lv' .. level
        end
      end
      local short = compact[id]
      if short then
        return short[english and 2 or 1]
      end
      return itemData.label or _G.OwenItemName(id) or (english and itemData.en) or itemData.name
    end
  end
  _G.RunOptimizedItemAndVehicleESP = function(pc)
    local curTime = _G.RealNow()
    if curTime - _G.LastScanItemTime > 1.0 then
      _G.LastScanItemTime = curTime
      local player = GameplayData.GetPlayerCharacter()
      if not slua.isValid(player) then
        return
      end
      if _G._ItemGearWallPrev ~= nil and _G._ItemGearWallPrev ~= _G.MWConfig.EspItem_GearWall then
        _G.AppliedItemESP = {}
      end
      _G._ItemGearWallPrev = _G.MWConfig.EspItem_GearWall
      if _G.MWConfig.EspItem_Master then
        _G._ItemESP_PickupClass = _G._ItemESP_PickupClass or import("PickUpWrapperActor") or import("STPickupWrapperActor")
        local APickUpWrapperActor = _G._ItemESP_PickupClass
        if APickUpWrapperActor then
          local Actors = Game:GetActorsByClass(APickUpWrapperActor)
          _G.CachedItems = {}
          local candidates = {}
          local seenApplied = {}
          if Actors then
            local count = Actors:Num() or 0
            local SMClass = _G._ItemESP_SMClass or import("StaticMeshComponent");
            _G._ItemESP_SMClass = SMClass
            for i = 0, count - 1 do
              local item = Actors:Get(i)
              if slua.isValid(item) and not item.bHidden then
                seenApplied[tostring(item)] = true
                local dist = player:GetDistanceTo(item)
                do
                  local itemId = item.DefineID and item.DefineID.TypeSpecificID or item.DefineId
                  local itemData = itemId and ItemDatabase[itemId]
                  if itemData then
                    local isShow = false
                    local c = itemData.cat
                    if c == "AR" then
                      isShow = _G.MWConfig.EspItem_AR
                    elseif c == "Sniper" then
                      isShow = _G.MWConfig.EspItem_Sniper
                    elseif c == "SMG" then
                      isShow = _G.MWConfig.EspItem_SMG
                    elseif c == "Shotgun" then
                      isShow = _G.MWConfig.EspItem_Shotgun
                    elseif c == "LMG" then
                      isShow = _G.MWConfig.EspItem_LMG
                    elseif c == "Pistol" then
                      isShow = _G.MWConfig.EspItem_Pistol
                    elseif c == "Melee" then
                      isShow = _G.MWConfig.EspItem_Melee
                    elseif c == "Special" then
                      isShow = _G.MWConfig.EspItem_Special
                    elseif c == "Grenade" then
                      isShow = _G.MWConfig.EspItem_Grenade
                    elseif c == "Scope" then
                      isShow = _G.MWConfig.EspItem_Scope
                    elseif c == "Med" then
                      isShow = _G.MWConfig.EspItem_Med
                    elseif c == "Helmet" or c == "Vest" or c == "Bag" then
                      isShow = _G.MWConfig.EspItem_Gear
                    elseif c == "GasCan" then
                      isShow = _G.MWConfig.EspItem_GasCan
                    elseif c == "Ammo" then
                      isShow = _G.MWConfig.EspItem_Ammo
                    elseif c == "ShopToken" then
                      isShow = _G.MWConfig.EspItem_ShopToken
                    end
                    if isShow then
                      local espName = _G.OwenItemESPName(itemId, itemData)
                      candidates[ # candidates + 1] = { act = item, name = espName, color = itemData.color,
                      d = dist, cat = c, id = itemId, scale = itemData.scale }
                      local iId = tostring(item)
                      if not _G.AppliedItemESP[iId] then
                        local meshes = {}
                        if item.GetPickupMesh then
                          local pMesh = item:GetPickupMesh()
                          if slua.isValid(pMesh) then
                            table.insert(meshes, pMesh)
                          end
                        end
                        local childs = item:GetComponentsByClass(SMClass)
                        if childs then
                          for _, v in pairs(childs) do
                            if slua.isValid(v) and v ~= meshes[1] then
                              table.insert(meshes, v)
                            end
                          end
                        end
                        if not _G.ConsoleNewWallReady then
                          pcall(function()
                            local KSL = import("KismetSystemLibrary")
                            local w = slua.getWorld()
                            if KSL and w then
                              KSL.ExecuteConsoleCommand(w, "r.EnableDrawDyeingColor 1")
                              KSL.ExecuteConsoleCommand(w, "r.CustomDepth 3")
                              KSL.ExecuteConsoleCommand(w, "r.IdeaOutline.Enable 1")
                              KSL.ExecuteConsoleCommand(w, "r.Highlight.Enable 1")
                              _G.ConsoleNewWallReady = true
                            end
                          end)
                        end
                        local isLv3 = itemId == 502003 or itemId == 503003 or itemId == 501006
                        for _, mesh in pairs(meshes) do
                          if isLv3 then
                            pcall(function()
                              mesh:SetRenderCustomDepth( true)
                            end)
                          end
                          if isLv3 and _G.MWConfig.EspItem_GearWall then
                            pcall(function()
                              local LC = import("LinearColor") or _G.FLinearColor
                              local visColor = LC and LC(0, 22, 100, 100) or nil
                              local occColor = LC and LC(100, 0, 0, 100) or nil
                              if type(mesh.SetDrawDyeing) == "function" then
                                mesh:SetDrawDyeing( true)
                                mesh:SetDrawDyeingMode(1)
                                mesh:SetVisibleDyeingColor(visColor)
                                mesh:SetOccludedDyeingColor(occColor)
                                mesh:SetDyeingColorFadeDistance(99999.0)
                                mesh:SetDyeingColorMinMaxDistance(0.0, 99999.0)
                                mesh:SetDrawHighlight( true)
                                mesh:OverrideHighlightColor(visColor)
                                mesh:SetHighlightCanBeOccluded( false)
                                mesh:SetDrawIdeaOutline( true)
                                mesh:SetIdeaOutlineNew( true)
                                mesh:SetIdeaOutlineOcclusionHighlight( true)
                                mesh:OverrideIdeaOutlineColor(visColor)
                                mesh:SetIdeaOutlineOcclusionColor(occColor)
                                mesh:OverrideIdeaOutlineThickness(1.0)
                                mesh:SetIdeaOverrideOutlineAndOcclusion( true)
                                mesh:SetRenderCustomDepth( true)
                                mesh:SetCustomDepthStencilValue(255)
                              end
                            end)
                          elseif isLv3 and not _G.MWConfig.EspItem_GearWall then
                            pcall(function()
                              if type(mesh.SetDrawDyeing) == "function" then
                                mesh:SetDrawDyeing( false)
                                mesh:SetDrawHighlight( false)
                                mesh:SetDrawIdeaOutline( false)
                              end
                            end)
                          end
                          local numMat = 9 pcall(function()
                            if type(mesh.GetNumMaterials) == "function" then
                              numMat = mesh:GetNumMaterials() or 9
                            end
                          end)
                          if numMat > 9 then
                            numMat = 9
                          end
                          for mi = 0, numMat - 1 do
                            local mid = mesh:CreateAndSetMaterialInstanceDynamic(mi)
                            if slua.isValid(mid) then
                              local colorVisible = (isLv3 and _G.MWConfig.EspItem_GearWall) and { R = 255,
                              G = 0, B = 200, A = 10 } or { R = 50, G = 50, B = 0, A = 10 }
                              pcall(function()
                                mid:SetVectorParameterValue("LightColor", colorVisible)
                                mid:SetVectorParameterValue("ParaScaleOffset", { R = 3, G = 3, B = 0,
                                A = 0 })
                                mid:SetScalarParameterValue("RimLight", 999)
                                mid:SetScalarParameterValue("Brightness", 999)
                                mid:SetScalarParameterValue("Exposure", 999)
                              end)
                            end
                          end
                        end
                        _G.AppliedItemESP[iId] = true
                      end
                    end
                  end
                end
              end
            end
          end
          for k in pairs(_G.AppliedItemESP) do
            if not seenApplied[k] then
              _G.AppliedItemESP[k] = nil
            end
          end
          table.sort(candidates, function(a, b)
            return a.d < b.d
          end)
          local maxN = _G.ItemESP_MaxLabels or 80
          for i = 1, math.min( # candidates, maxN) do
            _G.CachedItems[ # _G.CachedItems + 1] = candidates[i]
          end
        end
        if _G.MWConfig.EspItem_DeadBox then
          pcall(function()
            local APlayerTombBox = import("PlayerTombBox")
            if APlayerTombBox then
              local deadBoxes = Game:GetActorsByClass(APlayerTombBox)
              if deadBoxes then
                local dbCount = deadBoxes:Num() or 0
                for i = 0, dbCount - 1 do
                  local box = deadBoxes:Get(i)
                  if slua.isValid(box) then
                    local bt = 0 pcall(function()
                      bt = box.BoxType or 0
                    end)
                    if bt == 1 then
                      local espName = (_G.MWLang == "EN" and "Airdrop") or "Airdrop" table.insert(_G.CachedItems, {
                        act = box,
                        name = espName,
                        color = { R = 255, G = 0, B = 0, A = 255 },
                        isBox = true,
                        kind = "airdrop",
                        off = { X = 0, Y = 0, Z = 60 }
                      })
                    else
                      local espName = (_G.MWLang == "EN" and "Dead Box") or "Dead Box" table.insert(_G.CachedItems, {
                        act = box,
                        name = espName,
                        color = { R = 255, G = 210, B = 0, A = 255 },
                        isBox = true,
                        off = { X = 0, Y = 0, Z = 60 }
                      })
                    end
                  end
                end
              end
            end
          end)
        end
      else
        _G.AppliedItemESP = {} _G.CachedItems = {}
      end
    end
  end
  local PlayerMapMarker = {}
  local RedBoxOverlay = { bActive = false, MainContainer = nil, WidgetSlot = nil, TextBlockPlayer = nil,
