  function RedBoxOverlay._MakeText(Container, str, color, size)
    local FSlateColor = RedBoxOverlay._SlateColor
    if FSlateColor == nil then
      FSlateColor = import("SlateColor") or import("/Script/SlateCore.SlateColor") or false;
      RedBoxOverlay._SlateColor = FSlateColor
    end
    local t = nil pcall(function()
      t = CGame:NewObjectFromPath("/Script/UMG.TextBlock", Container)
    end)
    if not t or not slua.isValid(t) then
      return nil
    end
    pcall(function()
      t:SetText(tostring(str))
      if FSlateColor then
        t:SetColorAndOpacity(FSlateColor(color))
      else
        t:SetColorAndOpacity(color)
      end
      if t.Font then
        local font = t.Font;
        font.Size = size;
        t.Font = font
      end
      _G.MWTextOutline(t, 1)
      pcall(function()
        t:SetShadowColorAndOpacity(FLinearColor(0.0, 0.0, 0.0, 0.8))
      end)
      pcall(function()
        t:SetShadowOffset(FVector2D(1, 1))
      end)
      t:SetWidgetVisibility(UEnums.ESlateVisibility.SelfHitTestInvisible)
    end)
    return t
  end
  function RedBoxOverlay.CreateImage()
    local ParentCanvas = PlayerMapMarker.ESPCanvas
    if not ParentCanvas or not slua.isValid(ParentCanvas) then
      if not PlayerMapMarker.InitESPCanvas() then
        return false
      end
      ParentCanvas = PlayerMapMarker.ESPCanvas
    end
    if not ParentCanvas or not slua.isValid(ParentCanvas) then
      return false
    end
    local Container = nil pcall(function()
      Container = CGame:NewObjectFromPath("/Script/UMG.CanvasPanel", ParentCanvas)
    end)
    if not Container or not slua.isValid(Container) then
      return false
    end
    local scale = .8
    local W, H = 270 * scale, 44 * scale RedBoxOverlay.ImgW, RedBoxOverlay.ImgH = W, H
    local IC = RedBoxOverlay.ImgIcon
    local iy = (H - IC) * 0.5
    local bg = _G.MWIconImageAt(Container, 0, 0, W, H, "cnt_bg", 0, 0, 0)
    local ip = _G.MWIconImageAt(Container, 12 * scale, iy, IC, IC, "ow_count_real", 0, 0, 1)
    local ib = _G.MWIconImageAt(Container, 96 * scale, iy, IC, IC, "ow_count_bot", 0, 0, 1)
    if not (bg and ip and ib) then
      pcall(function()
        Container:RemoveFromParent()
      end)
      return false
    end
    pcall(function()
      ip.w:SetColorAndOpacity(RedBoxOverlay.ColorLime)
    end)
    pcall(function()
      ib.w:SetColorAndOpacity(RedBoxOverlay.ColorYellow)
    end)
    local white = RedBoxOverlay.ColorWhite
    local numP = RedBoxOverlay._MakeText(Container, tostring(RedBoxOverlay.PlayerCount), white, RedBoxOverlay.ImgFont)
    local numB = RedBoxOverlay._MakeText(Container, tostring(RedBoxOverlay.BotCount), white, RedBoxOverlay.ImgFont)
    local function place(t, x)
      if not t then
        return
      end
      local sl = nil pcall(function()
        sl = Container:AddChildToCanvas(t)
      end)
      if sl then
        pcall(function()
          sl:SetAutoSize( true);
          sl:SetAlignment(FVector2D(0.5, 0.5));
          sl:SetPosition(FVector2D(x, H * 0.5));
          sl:SetZOrder(2)
        end)
      end
    end
    place(numP, 56 * scale);
    place(numB, 140 * scale)
    _G.MWIconImageAt(Container, 178 * scale, iy, IC, IC, "ow_count_near", 0, 0, 1)
    local near = RedBoxOverlay._MakeText(Container, tostring(RedBoxOverlay.Nearest or "-") .. "m", white, 12);
    place(near, 236 * scale);
    RedBoxOverlay.NumNearest = near
    RedBoxOverlay.TextBlockPlayer = nil;
    RedBoxOverlay.TextBlockBot = nil
    RedBoxOverlay.NumPlayer = numP;
    RedBoxOverlay.NumBot = numB
    RedBoxOverlay._NumPColor = nil;
    RedBoxOverlay._NumBColor = nil
    RedBoxOverlay._NumPColorT = nil;
    RedBoxOverlay._NumBColorT = nil
    local MainSlot = nil pcall(function()
      MainSlot = ParentCanvas:AddChildToCanvas(Container)
    end)
    if not MainSlot then
      return false
    end
    RedBoxOverlay.MainContainer = Container
    RedBoxOverlay.WidgetSlot = MainSlot pcall(function()
      MainSlot:SetAutoSize( false)
      MainSlot:SetZOrder(999)
      MainSlot:SetAlignment(FVector2D(0.5, 0.0))
      MainSlot:SetSize(FVector2D(W, H))
      local FAnchors = FAnchors or import("Anchors") or import("/Script/SlateCore.Anchors")
      if FAnchors then
        MainSlot:SetAnchors(FAnchors(0.5, 0, 0.5, 0))
      end
      MainSlot:SetPosition(FVector2D(0, 35))
    end)
    RedBoxOverlay._LastY = nil RedBoxOverlay.UpdatePosition()
    return true
  end
  function RedBoxOverlay.Create()
    return RedBoxOverlay.CreateImage()
  end
  RedBoxOverlay.ColorWhite = FLinearColor and FLinearColor(1.0, 1.0, 1.0, 1.0) or { R = 255, G = 255,
  B = 255, A = 255 }
  RedBoxOverlay.ColorLime = FLinearColor and FLinearColor(0.0, 1.0, 0.0, 1.0) or { R = 0, G = 255, B = 0,
