  RedBoxOverlay.ColorYellow = FLinearColor and FLinearColor(1.0, 0.82, 0.0, 1.0) or { R = 255, G = 210,
  B = 0, A = 255 }
  function RedBoxOverlay._SetNum(txt, value, colorKey, activeColor)
    if not txt or not slua.isValid(txt) then
      return
    end
    local str = tostring(value)
    local sKey = colorKey .. "T"
    if RedBoxOverlay[sKey] ~= str then
      RedBoxOverlay[sKey] = str;
      pcall(txt.SetText, txt, str)
    end
    local color = (value > 0) and activeColor or RedBoxOverlay.ColorWhite
    if RedBoxOverlay[colorKey] ~= color then
      RedBoxOverlay[colorKey] = color
      local FSlateColor = RedBoxOverlay._SlateColor pcall(function()
        if FSlateColor then
          txt:SetColorAndOpacity(FSlateColor(color))
        else
          txt:SetColorAndOpacity(color)
        end
      end)
    end
  end
  function RedBoxOverlay.SetCounts(players, bots, nearest)
    RedBoxOverlay.Nearest = nearest
    if RedBoxOverlay.NumNearest then
      pcall(RedBoxOverlay.NumNearest.SetText, RedBoxOverlay.NumNearest, tostring(nearest or "-") .. "m")
    end
    if RedBoxOverlay.PlayerCount == players and RedBoxOverlay.BotCount == bots then
      return
    end
    RedBoxOverlay.PlayerCount = players or 0
    RedBoxOverlay.BotCount = bots or 0 RedBoxOverlay._SetNum(RedBoxOverlay.NumPlayer, RedBoxOverlay.PlayerCount, "_NumPColor", RedBoxOverlay.ColorLime)
    RedBoxOverlay._SetNum(RedBoxOverlay.NumBot, RedBoxOverlay.BotCount, "_NumBColor", RedBoxOverlay.ColorYellow)
  end
  function RedBoxOverlay.UpdatePosition()
    local Slot = RedBoxOverlay.WidgetSlot
    if not Slot or not slua.isValid(Slot) then
      return
    end
    local PC = PlayerMapMarker.GetMyPlayerController()
    local hudY = 35
    local hh = RedBoxOverlay.ImgH
    if slua.isValid(PC) then
      local fromX, fromY = PlayerMapMarker.GetSnapLineStartPos(PC)
      if fromY and fromY > 0 then
        hudY = fromY - hh
      end
    end
    if RedBoxOverlay._LastY == hudY then
      return
    end
    RedBoxOverlay._LastY = hudY
    local FVector2D = import("Vector2D") or FVector2D pcall(function()
      Slot:SetPosition(FVector2D(0, hudY))
    end)
  end
  function RedBoxOverlay.LookAtNearest(wantBot)
    pcall(function()
      local pc = PlayerMapMarker.GetMyPlayerController()
      if not pc or not slua.isValid(pc) then
        return
      end
      local AllChars = PlayerMapMarker.GetAllCharacters()
      if not AllChars then
        return
      end
      local MyKey = PlayerMapMarker.GetMyPlayerKey()
      local MyChar = nil pcall(function()
        local GDP = PlayerMapMarker.GetGameplayData()
        if GDP and GDP.GetLocalCharacter then
          MyChar = GDP.GetLocalCharacter()
        elseif pc.GetPawn then
          MyChar = pc:GetPawn()
        end
      end)
      local MyTeamID = PlayerMapMarker.GetTeamID(MyChar)
      local camLoc = nil pcall(function()
        local GS = import("GameplayStatics")
        local cm = GS and GS.GetPlayerCameraManager(pc, 0)
        if cm then
          camLoc = cm:GetCameraLocation()
        end
      end)
      if not camLoc then
        camLoc = PlayerMapMarker.GetMyLocation()
      end
      if not camLoc then
        return
      end
      local best, bestD = nil, nil
      for PlayerKey, Character in pairs(AllChars) do
        if Character and slua.isValid(Character) and not PlayerMapMarker.IsMe(Character, PlayerKey, MyKey) and PlayerMapMarker.IsAlive(Character) then
          local isAI = PlayerMapMarker.IsAI(Character) and true or false
          if isAI == (wantBot and true or false) then
            local sameTeam = false
            if MyTeamID ~= nil then
              sameTeam = (PlayerMapMarker.GetTeamID(Character) == MyTeamID)
            end
            if not sameTeam then
              local loc = nil pcall(function()
                loc = Character:K2_GetActorLocation()
              end)
              if loc then
                local dx, dy, dz = loc.X - camLoc.X, loc.Y - camLoc.Y, loc.Z - camLoc.Z
                local d = dx * dx + dy * dy + dz * dz
                if not bestD or d < bestD then
                  best, bestD = loc, d
                end
              end
            end
          end
        end
      end
      if not best then
        return
      end
      local KML = import("KismetMathLibrary")
      local FV = _G.FVector or import("Vector")
      if not (KML and FV) then
        return
      end
      local rot = KML.FindLookAtRotation(camLoc, FV(best.X, best.Y, best.Z + 60))
      if not rot then
        return
      end
      local cur = nil pcall(function()
        cur = pc:GetControlRotation()
      end)
      pc:SetControlRotation(FRotator(rot.Pitch, rot.Yaw, (cur and cur.Roll) or 0), "AimTouch")
    end)
  end
  function RedBoxOverlay.Start()
    if RedBoxOverlay.bActive and RedBoxOverlay.MainContainer and _G.MWWidgetLive(RedBoxOverlay.MainContainer) then
      return
    end
    if RedBoxOverlay.MainContainer then
      RedBoxOverlay.Stop()
    end
    if RedBoxOverlay.Create() then
      RedBoxOverlay.bActive = true pcall(function()
        RedBoxOverlay.MainContainer:SetWidgetVisibility(UEnums.ESlateVisibility.SelfHitTestInvisible)
      end)
    end
  end
  function RedBoxOverlay.Stop()
    RedBoxOverlay.bActive = false
    if RedBoxOverlay.MainContainer and PlayerMapMarker._ProtectedWidgetStrs then
      PlayerMapMarker._ProtectedWidgetStrs[tostring(RedBoxOverlay.MainContainer)] = nil
    end
    if RedBoxOverlay.MainContainer and slua.isValid(RedBoxOverlay.MainContainer) then
      pcall(function()
        RedBoxOverlay.MainContainer:RemoveFromParent()
        RedBoxOverlay.MainContainer:ConditionalBeginDestroy()
      end)
    end
    RedBoxOverlay.MainContainer = nil
    RedBoxOverlay.WidgetSlot = nil
    RedBoxOverlay._LastY = nil
    RedBoxOverlay.TextBlockPlayer = nil
    RedBoxOverlay.TextBlockBot = nil
    RedBoxOverlay.NumNearest = nil
    RedBoxOverlay.NumPlayer = nil
    RedBoxOverlay.NumBot = nil
    RedBoxOverlay._NumPColor = nil;
    RedBoxOverlay._NumBColor = nil
    RedBoxOverlay._NumPColorT = nil;
    RedBoxOverlay._NumBColorT = nil
    RedBoxOverlay._CachedPosVec = nil
  end
  _G.RedBoxOverlay = RedBoxOverlay
