  function _G.MWIconPreload.Reset()
    local P = _G.MWIconPreload
    P.keys = nil;
    P.idx = 0;
    P.gen = nil;
    P.holders = {}
  end
  function _G.MWIconPreload.Tick()
    local P, H = _G.MWIconPreload, _G.MWHud
    if not H or not H.canvas then
      if P.gen then
        P.Reset()
      end
      return
    end
    if P.gen ~= H.gen then
      P.Reset();
      P.gen = H.gen
      P.keys = {}
      for k in pairs(_G.MWIconB64) do
        P.keys[ # P.keys + 1] = k
      end
      table.sort(P.keys)
    end
    if not P.keys or P.idx >= # P.keys then
      return
    end
    local canvas = H.canvas
    if not slua.isValid(canvas) then
      return
    end
    for _ = 1, P.PerFrame do
      P.idx = P.idx + 1
      local key = P.keys[P.idx]
      if not key then
        return
      end
      local tex = _G.MWIconTexture(key)
      if tex then
        pcall(function()
          local img = CGame:NewObjectFromPath("/Script/UMG.Image", canvas)
          if not img or not slua.isValid(img) then
            return
          end
          img:SetBrushFromTexture(tex, false)
          img:SetWidgetVisibility(UEnums.ESlateVisibility.Collapsed)
          local slot = canvas:AddChildToCanvas(img)
          if slot then
            pcall(function()
              slot:SetAutoSize( false);
              slot:SetSize(FVector2D(1, 1));
              slot:SetPosition(FVector2D( - 50, - 50))
            end)
          end
          if not PlayerMapMarker._ProtectedWidgetStrs then
            PlayerMapMarker._ProtectedWidgetStrs = {}
          end
          PlayerMapMarker._ProtectedWidgetStrs[tostring(img)] = true
          P.holders[ # P.holders + 1] = img
        end)
      end
    end
  end
  function _G.MWIconTexture(key)
    local cached = _G._MWIconTex[key]
    if cached ~= nil then
      if cached == false then
        return nil
      end
      if type(cached) == "number" then
        if _G.RealNow() < cached then
          return nil
        end
      elseif slua.isValid(cached) then
        return cached
      end
      _G._MWIconTex[key] = nil
    end
    local b64 = _G.MWIconB64[key]
    if not b64 then
      _G._MWIconTex[key] = false
      return nil
    end
    local tex = nil
    local written = {} pcall(function()
      local bytes = _G.MWB64Decode(b64)
      _G._MWIconLoadN = (_G._MWIconLoadN or 0) + 1
      local fname = "mw_icon_" .. key .. "_" .. tostring(_G._MWIconLoadN) .. ".png"
      for _, path in ipairs(GetConfigPaths(fname)) do
        local f = io.open(path, "wb")
        if f then
          local wrote = pcall(f.write, f, bytes);
          local closed = pcall(f.close, f)
          if wrote and closed then
            written[1] = path;
            break
          end
          pcall(os.remove, path)
        end
      end
      local LT = import("LoadTexture")
      local BH = import("BusinessHelper")
      if not LT then
        return
      end
      for _, path in ipairs(written) do
        local cands = { path }
        pcall(function()
          if BH and BH.GetMobileBasePath then
            local mp = BH.GetMobileBasePath(path);
            if mp and mp ~= "" then
              cands[ # cands + 1] = mp
            end
          end
        end)
        for _, cp in ipairs(cands) do
          pcall(function()
            tex = LT.GetTexture2DFromDiskFile(cp)
          end)
          if tex and slua.isValid(tex) then
            return
          end
          tex = nil
        end
      end
    end)
    for _, path in ipairs(written) do
      pcall(os.remove, path)
    end
    if tex and slua.isValid(tex) then
      _G._MWIconTex[key] = tex
      return tex
    end
    _G._MWIconTex[key] = _G.RealNow() + 3.0
    return nil
  end
