      ok = true
    end)
    if not ok then
      return nil
    end
    pcall(function()
      img:SetWidgetVisibility(UEnums.ESlateVisibility.HitTestInvisible)
    end)
    local slot = nil pcall(function()
      slot = canvas:AddChildToCanvas(img)
    end)
    if slot then
      pcall(function()
        slot:SetAutoSize( false)
      end)
      pcall(function()
        slot:SetSize(FVector2D and FVector2D(w, h) or { X = w, Y = h })
      end)
      pcall(function()
        slot:SetPosition(FVector2D and FVector2D(x, y) or { X = x, Y = y })
      end)
      pcall(function()
        slot:SetAlignment(FVector2D and FVector2D(ax or 0, ay or 0) or { X = ax or 0, Y = ay or 0 })
      end)
      pcall(function()
        slot:SetZOrder(z or 0)
      end)
    end
    if not PlayerMapMarker._ProtectedWidgetStrs then
      PlayerMapMarker._ProtectedWidgetStrs = {}
    end
    PlayerMapMarker._ProtectedWidgetStrs[tostring(img)] = true
    return { w = img, slot = slot, key = key }
  end
