    local pawn
    if IsValid(pc) then
      pcall(function()
        if pc.GetPlayerCharacterSafety then
          pawn = pc:GetPlayerCharacterSafety()
        elseif pc.GetPawn then
          pawn = pc:GetPawn()
        end
      end)
    end
    local now = _G.RealNow()
    local state = P.CharacterSnapshot
    if not state then
      state = {
        Actors = {}
      };
      P.CharacterSnapshot = state
    end
    local lowSpec = _G.OwenLowSpecEnabled()
    if ( not lowSpec or not force) and state.PC == pc and state.Pawn == pawn and state.Time and now >= state.Time and now - state.Time < (lowSpec and .30 or .10) then
      return state.Actors
    end
    state.PC, state.Pawn, state.Time = pc, pawn, now
    local actors = state.Actors;
    for key in pairs(actors) do
      actors[key] = nil
    end
    local count = 0
    local function add(key, ch)
      if not ch or not slua.isValid(ch) then
        return
      end
      local playerKey pcall(function()
        if ch.GetPlayerKey then
          playerKey = ch:GetPlayerKey()
        end;
        playerKey = playerKey or ch.PlayerKey or (ch.PlayerState and ch.PlayerState.PlayerKey)
      end)
      if playerKey == 0 or playerKey == "" then
        playerKey = nil
      end
      key = playerKey or tostring(ch)
      if not actors[key] then
        count = count + 1
      end;
      actors[key] = ch
    end
    pcall(function()
      local pawns = Game:GetAllPlayerPawns();
      if pawns then
        for key, ch in pairs(pawns) do
          add(key, ch)
        end
      end
    end)
    if count <= 1 then
      local gs = P.GetCGameState()
      if gs and gs.GetAllCharacters then
        pcall(function()
          local chars = gs:GetAllCharacters();
          if chars then
            for key, ch in pairs(chars) do
              add(key, ch)
            end
          end
        end)
      end
    end
    return actors
  end
