      local probeNow = (_G.RealNow and _G.RealNow()) or os.clock()
      local hit = probe[Character]
      if hit and probeNow < (hit.At or 0) then
        return hit.Dead == true
      end
      loadEnums()
      local dead, state = liveDead(Character)
      local key = keyOf(Character, state)
      local keys = PlayerMapMarker._DeadKeys
      if key and keys and keys[key] then
        dead = true
      end
      if dead then
        latch = latch or setmetatable( {}, { __mode = 'k' })
        PlayerMapMarker._DeadLatch = latch
        latch[Character] = true
        if key then
          keys = keys or {} PlayerMapMarker._DeadKeys = keys
          keys[key] = true
        end
        if PlayerMapMarker._AliveSince then
          PlayerMapMarker._AliveSince[Character] = nil
        end
      end
      probe[Character] = { At = probeNow + 0.1, Dead = dead }
      return dead
    end
  end
  function PlayerMapMarker.IsAlive(Character)
    if not Character then
      return false
    end
    local okDead, isDead = pcall(PlayerMapMarker.IsDeadState, Character)
    if okDead and isDead == true then
      return false
    end
    local f = Character.IsAlive
    if f then
      local ok, r = pcall(f, Character);
      if ok and r ~= nil then
        return r
      end
    end
    return true
  end
  function PlayerMapMarker.IsOurESPWidget(w)
    if not w or not slua.isValid(w) then
      return false
    end
    if PlayerMapMarker._ProtectedWidgetStrs and PlayerMapMarker._ProtectedWidgetStrs[tostring(w)] then
      return false
    end
    local bIsOurs = false pcall(function()
      local wstr = tostring(w)
      for KeyStr, ESPData in pairs(PlayerMapMarker.ESPWidgets) do
        if ESPData and ESPData.Widget and ESPData.Widget.Container then
          local cstr = tostring(ESPData.Widget.Container)
          if cstr == wstr then
            bIsOurs = true
            return
          end
        end
      end
    end)
    if bIsOurs then
      return true
    end
    pcall(function()
      if w.GetChildrenCount then
        local n = w:GetChildrenCount()
        for i = 0, n - 1 do
          local child = w:GetChildAt(i)
          if child and slua.isValid(child) then
            local cstr = tostring(child)
            if string.find(cstr, "Border") then
              bIsOurs = true
              break
            end
          end
        end
      end
    end)
    if not bIsOurs then
      pcall(function()
        local slot = w.Slot
        if slot and slot.GetPosition then
          local pos = slot:GetPosition()
          if pos and (math.abs(pos.X or 0) > 1 or math.abs(pos.Y or 0) > 1) then
            bIsOurs = true
          end
        end
      end)
    end
    return bIsOurs
  end
  function PlayerMapMarker.ApplyAnchorBasedPosition(Slot, ScreenPos, Canvas)
    if not Slot or not ScreenPos then
      return false
    end
    local sx = ScreenPos.X or 0
    local sy = ScreenPos.Y or 0
    local sz = PlayerMapMarker.ESPWidgetSize or (FVector2D and FVector2D(100, 30) or { X = 100, Y = 30 })
    local align = PlayerMapMarker.ESPWidgetAlignment or (FVector2D and FVector2D(0.5, 1.0) or { X = 0.5,
    Y = 1.0 })
    local canvasW, canvasH = 0, 0
    if PlayerMapMarker._cachedViewportW and PlayerMapMarker._cachedViewportW > 200 then
      canvasW = PlayerMapMarker._cachedViewportW
      canvasH = PlayerMapMarker._cachedViewportH
    end
    if canvasW < 200 then
      pcall(function()
        local PC = PlayerMapMarker.GetMyPlayerController()
        if IsValid(PC) and PC.GetViewportSize then
          local VS = FVector2D and FVector2D(0, 0) or { X = 0, Y = 0 }
          PC:GetViewportSize(VS)
          if VS and VS.X and VS.X > 200 then
            canvasW = VS.X;
            canvasH = VS.Y
            PlayerMapMarker._cachedViewportW = canvasW;
            PlayerMapMarker._cachedViewportH = canvasH
          end
        end
      end)
    end
    if canvasW > 200 and canvasH > 200 then
      local anchorX = (sx + (PlayerMapMarker.ESPAnchorOffsetX or 0)) / canvasW
      local anchorY = (sy + (PlayerMapMarker.ESPAnchorOffsetY or 0)) / canvasH
      anchorX = math.max(0, math.min(1, anchorX))
      anchorY = math.max(0, math.min(1, anchorY))
      local bSuccess = false pcall(function()
        local FAnchors = import("Anchors") or import("/Script/SlateCore.Anchors")
        if Slot.SetAnchors and FAnchors then
          local anchors = FAnchors(anchorX, anchorY, anchorX, anchorY)
          if anchors then
            Slot:SetAnchors(anchors)
            Slot:SetPosition(FVector2D and FVector2D(0, 0) or { X = 0, Y = 0 })
            bSuccess = true
          end
        end
      end)
      if not bSuccess then
        pcall(function()
          if Slot.SetAnchors then
            Slot:SetAnchors(anchorX, anchorY, anchorX, anchorY)
            Slot:SetPosition(FVector2D and FVector2D(0, 0) or { X = 0, Y = 0 })
            bSuccess = true
          end
        end)
      end
      if bSuccess then
        pcall(function()
          if Slot.SetOffsets and import("Margin") then
            Slot:SetOffsets(import("Margin")(0, 0, sz.X, sz.Y))
          end
        end)
        pcall(function()
          Slot:SetSize(sz)
        end)
        pcall(function()
          Slot:SetAlignment(align)
        end)
        pcall(function()
          if Slot.SetAutoSize then
            Slot:SetAutoSize(PlayerMapMarker.ESPWidgetAutoSize or true)
          end
        end)
        pcall(function()
          if Slot.SetZOrder then
            Slot:SetZOrder(PlayerMapMarker.ESPWidgetZOrder or 2)
          end
        end)
        return true
      end
    end
    pcall(function()
      Slot:SetPosition(FVector2D and FVector2D(sx, sy) or { X = sx, Y = sy })
      pcall(function()
        Slot:SetSize(sz)
      end)
      pcall(function()
        Slot:SetAlignment(align)
      end)
      pcall(function()
        if Slot.SetAutoSize then
          Slot:SetAutoSize(PlayerMapMarker.ESPWidgetAutoSize or true)
        end
      end)
      pcall(function()
        if Slot.SetZOrder then
          Slot:SetZOrder(PlayerMapMarker.ESPWidgetZOrder or 2)
        end
      end)
    end)
    return false
  end
