  function _G.MWHud.Refresh()
    local H = _G.MWHud
    local now = _G.RealNow()
    if H.chkT and (now - H.chkT) < 0.1 then
      return
    end
    H.chkT = now
    local cur = PlayerMapMarker._CurrentHudCanvas()
    if cur ~= nil then
      H.lostT = nil
      if cur ~= H.canvas then
        H.canvas = cur;
        H.gen = H.gen + 1;
        H.seenT = now H.OnChanged()
      end
    elseif H.canvas ~= nil then
      if not H.lostT then
        H.lostT = now
      end
      if (now - H.lostT) >= H.LostSec then
        H.canvas = nil;
        H.seenT = nil;
        H.gen = H.gen + 1 H.OnChanged()
      end
    end
  end
  function _G.MWHud.ForceReset()
    local H = _G.MWHud
    if H.canvas == nil then
      return
    end
    H.canvas = nil;
    H.seenT = nil;
    H.lostT = nil;
    H.gen = H.gen + 1 H.OnChanged()
  end
  function _G.MWHud.Ready()
    local H = _G.MWHud H.Refresh()
    return H.canvas ~= nil and H.seenT ~= nil and (_G.RealNow() - H.seenT) >= H.StableSec
