  PlayerMapMarker._CanvasOffsetY = 0.0
  function PlayerMapMarker.UpdateCanvasTransform(PC)
    if not PlayerMapMarker.ESPCanvas or not Game:IsValid(PlayerMapMarker.ESPCanvas) then
      return
    end
    local nowC = _G.RealNow()
    if PlayerMapMarker._CanvasXformTime and (nowC - PlayerMapMarker._CanvasXformTime) < 0.25 then
      return
    end
    PlayerMapMarker._CanvasXformTime = nowC
    local success = false pcall(function()
      local SBL = SlateBlueprintLibrary
      if SBL and SBL.AbsoluteToLocal then
        local cg = PlayerMapMarker.ESPCanvas:GetCachedGeometry()
        if cg then
          local pt0 = SBL.AbsoluteToLocal(cg, FVector2D and FVector2D(0, 0) or { X = 0, Y = 0 })
          local pt1 = SBL.AbsoluteToLocal(cg, FVector2D and FVector2D(100, 100) or { X = 100, Y = 100 })
          if pt0 and pt1 then
            PlayerMapMarker._CanvasScaleX = (pt1.X - pt0.X) / 100
            PlayerMapMarker._CanvasScaleY = (pt1.Y - pt0.Y) / 100
            PlayerMapMarker._CanvasOffsetX = pt0.X
            PlayerMapMarker._CanvasOffsetY = pt0.Y
            success = true
          end
        end
      end
    end)
    if not success then
      pcall(function()
        local WLL = WidgetLayoutLibrary
        if WLL and WLL.ScreenToWidgetLocal then
          local cg = PlayerMapMarker.ESPCanvas:GetCachedGeometry()
          if cg then
            local pt0 = FVector2D and FVector2D(0, 0) or { X = 0, Y = 0 }
            local pt1 = FVector2D and FVector2D(0, 0) or { X = 0, Y = 0 }
            WLL.ScreenToWidgetLocal(PC, cg, FVector2D and FVector2D(0, 0) or { X = 0, Y = 0 }, pt0)
            WLL.ScreenToWidgetLocal(PC, cg, FVector2D and FVector2D(100, 100) or { X = 100, Y = 100 }, pt1)
            PlayerMapMarker._CanvasScaleX = (pt1.X - pt0.X) / 100
            PlayerMapMarker._CanvasScaleY = (pt1.Y - pt0.Y) / 100
            PlayerMapMarker._CanvasOffsetX = pt0.X
            PlayerMapMarker._CanvasOffsetY = pt0.Y
            success = true
          end
        end
      end)
    end
    if not success then
      local scale = 1.0
      local WLL = WidgetLayoutLibrary
      if WLL and WLL.GetViewportScale then
        scale = WLL.GetViewportScale(PC) or 1.0
      end
      PlayerMapMarker._CanvasScaleX = 1.0 / scale
      PlayerMapMarker._CanvasScaleY = 1.0 / scale
      PlayerMapMarker._CanvasOffsetX = 0
      PlayerMapMarker._CanvasOffsetY = 0
    end
  end
  function PlayerMapMarker.ScreenPixelToCanvasLocal(PC, ScreenPixelPos)
    local out = PlayerMapMarker._CanvasTmp
    if not out then
      out = FVector2D and FVector2D(0, 0) or { X = 0, Y = 0 };
      PlayerMapMarker._CanvasTmp = out
    end
    if not ScreenPixelPos then
      out.X = 0;
      out.Y = 0;
      return out
    end
    local scaleX = PlayerMapMarker._CanvasScaleX or 1.0
    local scaleY = PlayerMapMarker._CanvasScaleY or 1.0
    local offsetX = PlayerMapMarker._CanvasOffsetX or 0
    local offsetY = PlayerMapMarker._CanvasOffsetY or 0
    out.X = ScreenPixelPos.X * scaleX + offsetX
    out.Y = ScreenPixelPos.Y * scaleY + offsetY
    return out
  end
  function PlayerMapMarker.ProjectWorldToCanvasLocal(PC, WorldLoc)
    local _ZeroPos2D = PlayerMapMarker._ZeroPos2D
    if not _ZeroPos2D then
      _ZeroPos2D = FVector2D and FVector2D(0, 0) or { X = 0, Y = 0 };
      PlayerMapMarker._ZeroPos2D = _ZeroPos2D
    end
    if not IsValid(PC) or not WorldLoc then
      return false, _ZeroPos2D
    end
    local ScreenPixelPos = PlayerMapMarker._ProjTmp
    if not ScreenPixelPos then
      ScreenPixelPos = FVector2D and FVector2D(0, 0) or { X = 0, Y = 0 };
      PlayerMapMarker._ProjTmp = ScreenPixelPos
    end
    ScreenPixelPos.X = 0;
    ScreenPixelPos.Y = 0
    local ok, res = pcall(PC.ProjectWorldLocationToScreen, PC, WorldLoc, ScreenPixelPos, true)
    local bOK = ok and res ~= false and res ~= 0 and (res == true or res == 1 or (ScreenPixelPos.X ~= 0 or ScreenPixelPos.Y ~= 0))
    if not bOK or (ScreenPixelPos.X == 0 and ScreenPixelPos.Y == 0) then
      return false, _ZeroPos2D
    end
    if not PlayerMapMarker._ProjSane(ScreenPixelPos.X, ScreenPixelPos.Y) then
      return false, _ZeroPos2D
    end
    local CanvasLocalPos = PlayerMapMarker.ScreenPixelToCanvasLocal(PC, ScreenPixelPos)
    return true, CanvasLocalPos
  end
  function PlayerMapMarker.GetDynamicViewportSize(PC)
    local width, height = 0, 0
    if PlayerMapMarker.ESPCanvas and Game:IsValid(PlayerMapMarker.ESPCanvas) then
      pcall(function()
        local cg = PlayerMapMarker.ESPCanvas:GetCachedGeometry()
        if cg and cg.GetLocalSize then
          local sz = cg:GetLocalSize()
          if sz and sz.X and sz.X > 200 then
            width = sz.X
            height = sz.Y
          end
        end
      end)
    end
    if width > 200 then
      return width, height
    end
    pcall(function()
      local WLL = WidgetLayoutLibrary
      if WLL and WLL.GetViewportSize then
        local sz = WLL.GetViewportSize(PC or PlayerMapMarker.GetMyPlayerController())
        if sz and sz.X and sz.X > 200 then
          width = sz.X
          height = sz.Y
        end
      end
    end)
    if width > 200 then
      pcall(function()
        local WLL = WidgetLayoutLibrary
        if WLL and WLL.GetViewportScale then
          local scale = WLL.GetViewportScale(PC or PlayerMapMarker.GetMyPlayerController())
          if scale and type(scale) == "number" and scale > 0 and scale ~= 1.0 then
            width = width / scale
            height = height / scale
          end
        end
      end)
      return width, height
    end
    return PlayerMapMarker._cachedViewportW or 1920, PlayerMapMarker._cachedViewportH or 1080
  end
  function PlayerMapMarker._SetContainerVis(Widget, Container, vis)
    if type(Container) ~= "userdata" then
      return
    end
    if type(Widget) == "table" then
      if Widget._VisState == vis then
        return
      end
      Widget._VisState = vis
    end
    Container:SetWidgetVisibility(vis)
  end
  function PlayerMapMarker._ScaleForDist(distCm)
    local base = PlayerMapMarker.ESPBaseScale or 0.9
    if not distCm or distCm <= 1 then
      return base
    end
    local sc = (PlayerMapMarker.ESPScaleRefDist or 2500) / distCm
    local mn, mx = PlayerMapMarker.ESPScaleMin or 0.45, PlayerMapMarker.ESPScaleMax or 1.6
    if sc < mn then
      sc = mn
    elseif sc > mx then
      sc = mx
    end
    sc = base * sc
    return math.floor(sc * 50 + 0.5) / 50
  end
  function PlayerMapMarker._Dist3D(a, b)
    if not a or not b then
      return nil
    end
    local dx, dy, dz = a.X - b.X, a.Y - b.Y, a.Z - b.Z
    return math.sqrt(dx * dx + dy * dy + dz * dz)
  end
  function PlayerMapMarker._ShowAnyUINow()
    local c = _G.MWConfig
    return (c.EspPlayerName or c.EspPlayerDistance or (c.EspPlayerHP and PlayerMapMarker.bWidgetHPBar) or c.EspPlayerTeam or c.EspPlayerWeapon or c.EspPlayerBotLabel or c.EspShowState or c.EspNationFlag) and true or false
  end
  function PlayerMapMarker._ESPPosBody(Widget, Container, CanvasPos)
    if not (PlayerMapMarker.ESPCanvas and Game:IsValid(PlayerMapMarker.ESPCanvas)) then
      return
    end
    local ptr = (type(Widget) == "table") and Widget._PtrStr or nil
    if not ptr then
      ptr = tostring(Container);
      if type(Widget) == "table" then
        Widget._PtrStr = ptr
      end
    end
    local Slot = PlayerMapMarker.ESPWidgetPtrs[ptr]
    if not Slot or not slua.isValid(Slot) or type(Slot) == "boolean" then
      local addedSlot = PlayerMapMarker.ESPCanvas:AddChildToCanvas(Container)
      if addedSlot and slua.isValid(addedSlot) then
        Slot = addedSlot
        PlayerMapMarker.ESPWidgetPtrs[ptr] = addedSlot
        if type(Widget) == "table" then
          Widget.Slot = addedSlot;
          Widget._VisState = nil
        end
        pcall(function()
          Slot:SetAutoSize( true)
        end)
        pcall(function()
          Slot.bAutoSize = true
        end)
        local align = FVector2D and FVector2D(0.5, 1.0) or { X = 0.5, Y = 1.0 }
        pcall(function()
          Slot.Alignment = align
        end)
        pcall(function()
          Slot:SetAlignment(align)
        end)
        pcall(function()
          Slot:SetAlignment(0.5, 1.0)
        end)
        pcall(function()
          Slot:SetZOrder(PlayerMapMarker.ESPWidgetZOrder or 20)
        end)
      end
    end
    local bShowAnyUI = PlayerMapMarker._ShowAnyUI
    if bShowAnyUI == nil then
      bShowAnyUI = PlayerMapMarker._ShowAnyUINow()
    end
    PlayerMapMarker._SetContainerVis(Widget, Container, bShowAnyUI and UEnums.ESlateVisibility.SelfHitTestInvisible or UEnums.ESlateVisibility.Collapsed)
    if not Widget._OffsetResetDone then
      pcall(function()
