          pcall(function()
            Widget.NameText:SetRenderTranslation(FVector2D and FVector2D(0.0, 0.0) or { X = 0, Y = 0 })
          end)
        end
        if Widget.HealthFill and slua.isValid(Widget.HealthFill) then
          pcall(function()
            Widget.HealthFill:SetRenderTranslation(FVector2D and FVector2D(0.0, 0.0) or { X = 0, Y = 0 })
          end)
        end
      end
      pcall(function()
        Container.RenderTransformPivot = FVector2D and FVector2D(0.5, 1.0) or { X = 0.5, Y = 1.0 }
      end)
      pcall(function()
        Container:SetRenderTransformPivot(FVector2D and FVector2D(0.5, 1.0) or { X = 0.5, Y = 1.0 })
      end)
      Widget._OffsetResetDone = true
    end
    if not Slot or not slua.isValid(Slot) or Slot == PlayerMapMarker.ESPCanvas then
      if Widget and type(Widget) == "table" and Widget.Slot and slua.isValid(Widget.Slot) then
        Slot = Widget.Slot
      elseif Container.Slot and slua.isValid(Container.Slot) then
        Slot = Container.Slot
      end
    end
    local sc = (type(Widget) == "table" and Widget._WantScale) or (PlayerMapMarker.ESPBaseScale or 0.9)
    if type(Widget) == "table" and Widget._AppliedScale ~= sc then
      Widget._AppliedScale = sc
      if not Widget._ScaleVec then
        Widget._ScaleVec = FVector2D and FVector2D(sc, sc) or { X = sc, Y = sc }
      else
        Widget._ScaleVec.X = sc;
        Widget._ScaleVec.Y = sc
      end
      pcall(Container.SetRenderScale, Container, Widget._ScaleVec)
    end
    if Slot and slua.isValid(Slot) and Slot ~= PlayerMapMarker.ESPCanvas then
      local finalX = CanvasPos.X + (PlayerMapMarker.ESPAnchorOffsetX or 0)
      local finalY = CanvasPos.Y + (PlayerMapMarker.ESPAnchorOffsetY or 0) * sc
      if Widget and type(Widget) == "table" then
        if Widget._LastPosX ~= finalX or Widget._LastPosY ~= finalY then
          Widget._LastPosX, Widget._LastPosY = finalX, finalY
          if not Widget._CachedPosVec then
            Widget._CachedPosVec = FVector2D and FVector2D(finalX, finalY) or { X = finalX, Y = finalY }
          else
            Widget._CachedPosVec.X = finalX
            Widget._CachedPosVec.Y = finalY
          end
          Slot:SetPosition(Widget._CachedPosVec)
        end
      else
        Slot:SetPosition(FVector2D and FVector2D(finalX, finalY) or { X = finalX, Y = finalY })
      end
    end
  end
  function PlayerMapMarker.UpdateESPPositionWithPC(Widget, WorldLoc, PC, CanvasPos)
    if not Widget or not IsValid(PC) then
      return false
    end
    if Widget.Container == false then
      return true
    end
    local Container = Widget.Container or Widget
    local bOnScreen = true
    if not CanvasPos then
      if not WorldLoc then
        return false
      end
      bOnScreen, CanvasPos = PlayerMapMarker.ProjectWorldToCanvasLocal(PC, WorldLoc)
    end
    if not bOnScreen then
      pcall(PlayerMapMarker._SetContainerVis, Widget, Container, UEnums.ESlateVisibility.Collapsed)
      return false
    end
    pcall(PlayerMapMarker._ESPPosBody, Widget, Container, CanvasPos)
    return true
  end
  function PlayerMapMarker._ESPStyleText(w, txt)
    if not w or not slua.isValid(w) then
      return
    end
    local vis = (txt == "") and UEnums.ESlateVisibility.Collapsed or UEnums.ESlateVisibility.SelfHitTestInvisible pcall(w.SetWidgetVisibility, w, vis)
    if txt == "" then
      return
    end
    pcall(w.SetText, w, txt)
    local col = PlayerMapMarker._ESPWhiteColor
    if col == nil then
      local slateColor = PlayerMapMarker._SlateColorClass
      if slateColor == nil then
        slateColor = import("SlateColor") or import("/Script/SlateCore.SlateColor") or false
        PlayerMapMarker._SlateColorClass = slateColor
      end
      local white = FLinearColor and FLinearColor(1.0, 1.0, 1.0, 1.0) or { R = 255, G = 255, B = 255,
      A = 255 }
      col = (slateColor and slateColor(white)) or white
      PlayerMapMarker._ESPWhiteColor = col
    end
    if w.SetColorAndOpacity then
      pcall(w.SetColorAndOpacity, w, col)
    end
    if w.SetJustification then
      pcall(w.SetJustification, w, 1)
    end
    local slot = w.Slot
    if slot and slot.SetHorizontalAlignment then
      pcall(slot.SetHorizontalAlignment, slot, 1)
    end
    local tr = PlayerMapMarker._ESPTextTranslation
    if tr == nil then
      local x = PlayerMapMarker.ESPTextOffsetX or 0
      local y = PlayerMapMarker.ESPTextOffsetY or 0
      tr = FVector2D and FVector2D(x, y) or { X = x, Y = y }
      PlayerMapMarker._ESPTextTranslation = tr
    end
    pcall(w.SetRenderTranslation, w, tr)
  end
  function PlayerMapMarker._CacheESPBoxChildren(Widget, W, boxName, cacheKey)
    local list = {}
    local box = PlayerMapMarker._FindNamedWidgetInTree(W, boxName, 8)
    if box and slua.isValid(box) and box.GetChildrenCount then
      local n = box:GetChildrenCount()
      for i = 0, n - 1 do
        local child = box:GetChildAt(i)
        if child and slua.isValid(child) and child.SetText then
          list[ # list + 1] = child
        end
      end
    end
    Widget[cacheKey] = list
  end
  function PlayerMapMarker.UpdateESPText(Widget, Text)
    if not Widget then
      return
    end
    if Widget._LastESPText == Text then
      return
    end
    Widget._LastESPText = Text
    local style = PlayerMapMarker._ESPStyleText
    if Widget.NameText and slua.isValid(Widget.NameText) then
      style(Widget.NameText, Text)
    end
    if Widget.IsGameWidget and Widget.Container then
      local W = Widget.Container
      if W and slua.isValid(W) then
        if W.SetPlayerName then
          local Name = Text
          local idx = string.find(Text, " %[")
          if idx then
            Name = string.sub(Text, 1, idx - 1)
          end
          pcall(W.SetPlayerName, W, Name)
        end
        style(W.TextBlock_TeamName, Text)
