        if not Widget._CachedHBChildren then
          pcall(PlayerMapMarker._CacheESPBoxChildren, Widget, W, "HorizontalBox_TeamName", "_CachedHBChildren")
        end
        local hb = Widget._CachedHBChildren
        if hb then
          for i = 1, # hb do
            style(hb[i], Text)
          end
        end
      end
    end
