  local DrawLine = {} _G.DrawLine = DrawLine
  DrawLine.IMG_K = 2.0
  function DrawLine.CreateImg(zOrder)
    if _G._LineImgFailedT and (_G.RealNow() - _G._LineImgFailedT) < 3.0 then
      return nil
    end
    if not _InitDrawCanvas() then
      return nil
    end
    local it = _G.MWIconImageAt(_DrawCanvas, 0, 0, 10, 10, "line_tex", 0.0, 0.5, zOrder or 1)
    if not it then
      _G._LineImgFailedT = _G.RealNow()
      return nil
    end
    _G._LineImgFailedT = nil pcall(function()
      it.w:SetRenderTransformPivot(FVector2D and FVector2D(0.0, 0.5) or { X = 0, Y = 0.5 })
    end)
    pcall(function()
      it.w:SetWidgetVisibility(UEnums.ESlateVisibility.Collapsed)
    end)
    return {
      Widget = it.w,
      Slot = it.slot,
      img = true,
      _posVec = FVector2D and FVector2D(0, 0) or { X = 0, Y = 0 },
      _sizeVec = FVector2D and FVector2D(0, 0) or { X = 0, Y = 0 },
      _visible = false,
    }
  end
  function DrawLine.Create(zOrder)
    return DrawLine.CreateImg(zOrder)
  end
  function DrawLine.Update(line, fromX, fromY, toX, toY, color, thickness)
    if not line or not line.Widget or not line.Slot or not slua.isValid(line.Widget) then
      return
    end
    local thick = thickness or 1
    if line._visible == true and line._x1 == fromX and line._y1 == fromY and line._x2 == toX and line._y2 == toY and line._thick == thick and line._lastColor == color then
      return
    end
    local dx = toX - fromX
    local dy = toY - fromY
    local length = math.sqrt(dx * dx + dy * dy)
    local thick = thickness or 1
    local angle = _Draw_atan2(dy, dx) * 57.29577951308232
    local h = thick * (line.img == false and 1 or DrawLine.IMG_K)
    line._posVec.X = fromX
    line._posVec.Y = fromY line.Slot:SetPosition(line._posVec)
    line._sizeVec.X = length
    line._sizeVec.Y = h line.Slot:SetSize(line._sizeVec)
    line.Widget:SetRenderAngle(angle)
    if color and line._lastColor ~= color then
      if line.img == false then
        line.Widget:SetBrushColor(color)
      else
        line.Widget:SetColorAndOpacity(color)
      end
      line._lastColor = color
    end
    if line._visible ~= true then
      line._visible = true;
      line.Widget:SetWidgetVisibility(UEnums.ESlateVisibility.SelfHitTestInvisible)
    end
    line._x1, line._y1, line._x2, line._y2, line._thick = fromX, fromY, toX, toY, thick
  end
  function DrawLine.Hide(line)
    if line and line.Widget and slua.isValid(line.Widget) then
      if line._visible ~= false then
        line._visible = false line.Widget:SetWidgetVisibility(UEnums.ESlateVisibility.Collapsed)
      end
    end
  end
  function DrawLine.Remove(line)
    _RemoveBorder(line)
  end
  function DrawLine.ResetCanvas()
    _DrawCanvas = nil
  end
  function DrawLine.GetCanvas()
    if not _InitDrawCanvas() then
      return nil
    end
    return _DrawCanvas
  end
