  function PlayerMapMarker.GetSnapLineStartPos(PC)
    local nowC = _G.RealNow()
    if PlayerMapMarker._SnapFromX and PlayerMapMarker._SnapFromTime and (nowC - PlayerMapMarker._SnapFromTime) < 0.25 then
      return PlayerMapMarker._SnapFromX, PlayerMapMarker._SnapFromY
    end
    local screenPixelW, screenPixelH = 0, 0
    local scale = 1.0 pcall(function()
      if PC and PC.GetViewportSize then
        local vs = FVector2D and FVector2D(0, 0) or { X = 0, Y = 0 }
        PC:GetViewportSize(vs)
        if vs and vs.X and vs.X > 200 then
          screenPixelW = vs.X
          screenPixelH = vs.Y
        end
      end
    end)
    if screenPixelW <= 200 then
      pcall(function()
        local WLL = WidgetLayoutLibrary
        if WLL and WLL.GetViewportSize then
          local vs = WLL.GetViewportSize(PC)
          if vs and vs.X and vs.X > 200 then
            screenPixelW = vs.X
            screenPixelH = vs.Y
          end
        end
      end)
    end
    pcall(function()
      local WLL = WidgetLayoutLibrary
      if WLL and WLL.GetViewportScale then
        local s = WLL.GetViewportScale(PC)
        if s and type(s) == "number" and s > 0 then
          scale = s
        end
      end
    end)
    if screenPixelW <= 200 then
      screenPixelW = (PlayerMapMarker._cachedViewportW or 1920) * scale
      screenPixelH = (PlayerMapMarker._cachedViewportH or 1080) * scale
    end
    PlayerMapMarker._VpPxW, PlayerMapMarker._VpPxH = screenPixelW, screenPixelH
    if not PlayerMapMarker._CachedTopCenterPixel then
      PlayerMapMarker._CachedTopCenterPixel = FVector2D and FVector2D(0, 0) or { X = 0, Y = 0 }
    end
    PlayerMapMarker._CachedTopCenterPixel.X = screenPixelW / 2.0
    PlayerMapMarker._CachedTopCenterPixel.Y = (PlayerMapMarker.SnapLineOriginY or 50) * scale
    local fromCanvasPos = PlayerMapMarker.ScreenPixelToCanvasLocal(PC, PlayerMapMarker._CachedTopCenterPixel)
    local fromX = fromCanvasPos.X + (PlayerMapMarker.SnapLineOriginOffsetX or 0)
    local fromY = fromCanvasPos.Y PlayerMapMarker._SnapFromX, PlayerMapMarker._SnapFromY, PlayerMapMarker._SnapFromTime = fromX, fromY, nowC
    return fromX, fromY
  end
  function PlayerMapMarker.GetSkeletonDisplayColor(visible, isBot, knocked)
    if knocked then
      return PlayerMapMarker.KnockColor
    end
    if not visible then
      return PlayerMapMarker.SkelColorOcc
    end
    if _G.OwenGetSnaplineColor then
      return _G.OwenGetSnaplineColor(_G.MWConfig.EspSkeletonColor or 3, 1)
    end
    return isBot and PlayerMapMarker.SkelColorBot or PlayerMapMarker.SkelColor
  end
  function PlayerMapMarker.GetSnaplineDisplayColor(visible, isBot, knocked)
    local cfg = _G.MWConfig or {} isBot = isBot == true or isBot == 1
    if (cfg.WallHackV2 == true or cfg.WallHackV2 == 1) and _G.OwenGetSnaplineColor then
      local index
      if isBot then
        index = visible and (cfg.ColorBotWHVis or 2) or (cfg.ColorBotWHOcc or 4)
      else
        index = visible and (cfg.ColorEnemyWHVis or 3) or (cfg.ColorEnemyWHOcc or 0)
      end
      return _G.OwenGetSnaplineColor(index, 1)
    end
    if cfg.EspPlayerSkeleton == true or cfg.EspPlayerSkeleton == 1 then
      return PlayerMapMarker.GetSkeletonDisplayColor(visible, isBot, knocked)
    end
    if knocked then
      return PlayerMapMarker.KnockColor
    end
    return visible and (isBot and PlayerMapMarker.SnapLineColorBot or PlayerMapMarker.SnapLineColorPlayer) or PlayerMapMarker.SnapLineColorHidden
  end
  local OwenSnap = {
    World = { X = 0, Y = 0, Z = 0 }
  }
  function OwenSnap.Cam(pc, now)
    local camera = pc.PlayerCameraManager
    if not camera or not slua.isValid(camera) then
      local GS = _G.OwenImp("GameplayStatics")
      camera = GS and GS.GetPlayerCameraManager(pc, 0)
    end
    local location = camera:GetCameraLocation();
    local rotation = camera:GetCameraRotation()
    return { PC = pc, Time = now, Location = location, Yaw = math.rad(rotation.Yaw), Pitch = math.rad(rotation.Pitch) }
  end
  function OwenSnap.Point(character, out)
    local p = character:K2_GetActorLocation()
    out.X, out.Y, out.Z = p.X, p.Y, p.Z + 80
    return out
  end
  function PlayerMapMarker.SnaplineEndpoint(pc, character, pos, onScreen)
    local cfg = _G.MWConfig or {};
    local mode = tonumber(cfg.SnaplineMode) or 1
    if mode == 1 then
      return pos, onScreen
    end
    if not pc or not character then
      return nil, false
    end
    local now = PlayerMapMarker._FrameNow or _G.RealNow();
    local c = PlayerMapMarker._SnaplineCamera
    if not c or c.PC ~= pc or now - c.Time > 0.02 then
      local ok, value = pcall(OwenSnap.Cam, pc, now)
      if not ok then
        return nil, false
      end;
      c = value;
      PlayerMapMarker._SnaplineCamera = c
    end
    local ok, world = pcall(OwenSnap.Point, character, OwenSnap.World)
    if not ok or not world then
      return nil, false
    end
    local dx, dy, dz = world.X - c.Location.X, world.Y - c.Location.Y, world.Z - c.Location.Z
    local cy, sy = math.cos(c.Yaw), math.sin(c.Yaw)
    local front = dx * cy + dy * sy;
    local side = - dx * sy + dy * cy
    if mode == 2 and front < - 0.001 then
      return nil, false
    end
    local vertical = dz * math.cos(c.Pitch) - (dx * cy + dy * sy) * math.sin(c.Pitch)
    local w, h = PlayerMapMarker._VpPxW or 1920, PlayerMapMarker._VpPxH or 1080
    local sx, syc = PlayerMapMarker._CanvasScaleX or 1, PlayerMapMarker._CanvasScaleY or 1
    local ox, oy = PlayerMapMarker._CanvasOffsetX or 0, PlayerMapMarker._CanvasOffsetY or 0
    if pos and onScreen and front >= - 0.001 then
      local x, y = (pos.X - ox) / sx, (pos.Y - oy) / syc
      if x >= 0 and x <= w and y >= 0 and y <= h then
        return pos, true
      end
    end
    local x, y = side, - vertical
    if front < - 0.001 then
      y = - front - vertical * 0.25
    end
    if math.abs(x) + math.abs(y) < 0.001 then
      y = 1
    end
    local halfW, halfH = math.max(1, w / 2 - 20), math.max(1, h / 2 - 20)
    local tx = math.abs(x) > 0.001 and halfW / math.abs(x) or math.huge
    local ty = math.abs(y) > 0.001 and halfH / math.abs(y) or math.huge
    local scale = math.min(tx, ty)
    return { X = (w / 2 + x * scale) * sx + ox, Y = (h / 2 + y * scale) * syc + oy }, true
  end
  function PlayerMapMarker.UpdateSnapLine(KeyStr, CanvasPos, bOnScreen, fromX, fromY, isBot, PC, Character)
    if not PlayerMapMarker.bUseSnapLines then
      return
    end
    local LineData = PlayerMapMarker.SnapLineWidgets[KeyStr]
    if LineData and not _G.MWWidgetLive(LineData.Widget) then
      pcall(DrawLine.Remove, LineData)
      PlayerMapMarker.SnapLineWidgets[KeyStr] = nil;
      LineData = nil
    end
    CanvasPos, bOnScreen = PlayerMapMarker.SnaplineEndpoint(PC, Character, CanvasPos, bOnScreen)
    if not CanvasPos or not bOnScreen then
      if LineData then
        DrawLine.Hide(LineData)
      end
      return
    end
    if not LineData then
      LineData = PlayerMapMarker.CreateSnapLine()
      if not LineData then
        return
      end
      PlayerMapMarker.SnapLineWidgets[KeyStr] = LineData
    end
    local toX = CanvasPos.X + (PlayerMapMarker.SnapLineHeadOffsetX or 0)
    local toY = CanvasPos.Y + (PlayerMapMarker.SnapLineHeadOffsetY or 0)
    local ed = PlayerMapMarker.ESPWidgets[KeyStr]
    local vis = true
    local ch = Character or (ed and ed.Character)
    if IsValid(PC) and ch then
      vis = PlayerMapMarker._LOS(KeyStr, PC, ch)
    end
    local knocked = ed and (ed._Knock == true or ed._Knock == 1) or false
    if ch and tonumber(ch.HealthStatus) == 1 then
      knocked = true
    end
    local snapColor = PlayerMapMarker.GetSnaplineDisplayColor(vis, isBot, knocked)
    local thickness = PlayerMapMarker.SnapLineThickness or 1.5 pcall(DrawLine.Update, LineData, fromX, fromY, toX, toY, snapColor, thickness)
  end
  function PlayerMapMarker.RemoveSnapLine(KeyStr)
    PlayerMapMarker._LosCache[KeyStr] = nil
    local LineData = PlayerMapMarker.SnapLineWidgets[KeyStr]
    if LineData then
      DrawLine.Remove(LineData)
      PlayerMapMarker.SnapLineWidgets[KeyStr] = nil
    end
  end
