  function PlayerMapMarker._NewLabelText(canvas, fontSize, color, ax, ay)
    local txt = nil pcall(function()
      txt = CGame:NewObjectFromPath("/Script/UMG.TextBlock", canvas)
    end)
    if not txt or not slua.isValid(txt) then
      return nil
    end
    local FSlateColor = PlayerMapMarker._SlateColorClass
    if FSlateColor == nil then
      FSlateColor = import("SlateColor") or import("/Script/SlateCore.SlateColor") or false;
      PlayerMapMarker._SlateColorClass = FSlateColor
    end
    pcall(function()
      txt:SetText("")
    end)
    pcall(function()
      if FSlateColor then
        txt:SetColorAndOpacity(FSlateColor(color))
      else
        txt:SetColorAndOpacity(color)
      end
    end)
    pcall(function()
      local f = txt.Font;
      f.Size = fontSize;
      txt.Font = f
    end)
    _G.MWTextOutline(txt, 1)
    pcall(function()
      txt:SetJustification(1)
    end)
    pcall(function()
      txt:SetShadowColorAndOpacity(PlayerMapMarker.LabelShadow)
    end)
    pcall(function()
      txt:SetShadowOffset(FVector2D and FVector2D(0.5, 0.5) or { X = 0.5, Y = 0.5 })
    end)
    pcall(function()
      txt:SetRenderTransformPivot(FVector2D and FVector2D(ax, ay) or { X = ax, Y = ay })
    end)
    pcall(function()
      txt:SetWidgetVisibility(UEnums.ESlateVisibility.Collapsed)
    end)
    local slot = nil pcall(function()
      slot = canvas:AddChildToCanvas(txt)
    end)
    if slot then
      pcall(function()
        slot:SetAutoSize( true)
      end)
      pcall(function()
        slot:SetAlignment(FVector2D and FVector2D(ax, ay) or { X = ax, Y = ay })
      end)
      pcall(function()
        slot:SetZOrder(4)
      end)
    end
    if not PlayerMapMarker._ProtectedWidgetStrs then
      PlayerMapMarker._ProtectedWidgetStrs = {}
    end
    PlayerMapMarker._ProtectedWidgetStrs[tostring(txt)] = true
    return {
      w = txt,
      slot = slot,
      vis = false,
      text = nil,
      sc = nil,
      pos = FVector2D and FVector2D(0, 0) or { X = 0, Y = 0 },
      scv = FVector2D and FVector2D(1, 1) or { X = 1, Y = 1 },
      x = nil,
      y = nil
    }
  end
