    if slot then
      pcall(function()
        slot:SetAutoSize( false)
      end)
      pcall(function()
        slot:SetSize(FVector2D and FVector2D(PlayerMapMarker.WpnIconW, PlayerMapMarker.WpnIconH) or { X = PlayerMapMarker.WpnIconW,
        Y = PlayerMapMarker.WpnIconH })
      end)
      pcall(function()
        slot:SetAlignment(FVector2D and FVector2D(1.0, 1.0) or { X = 1, Y = 1 })
