    end)
    pcall(function()
      b:SetWidgetVisibility(UEnums.ESlateVisibility.Collapsed)
    end)
    local slot = nil pcall(function()
      slot = canvas:AddChildToCanvas(b)
    end)
    if slot then
      pcall(function()
        slot:SetAutoSize( false)
      end)
      pcall(function()
        slot:SetSize(FVector2D and FVector2D(PlayerMapMarker.TeamDotSize, PlayerMapMarker.TeamDotSize) or { X = PlayerMapMarker.TeamDotSize,
        Y = PlayerMapMarker.TeamDotSize })
      end)
      pcall(function()
        slot:SetAlignment(FVector2D and FVector2D(1.0, 0.5) or { X = 1, Y = 0.5 })
      end)
      pcall(function()
        slot:SetZOrder(4)
      end)
    end
    if not PlayerMapMarker._ProtectedWidgetStrs then
      PlayerMapMarker._ProtectedWidgetStrs = {}
    end
    PlayerMapMarker._ProtectedWidgetStrs[tostring(b)] = true
    return {
      w = b,
      slot = slot,
      vis = false,
      color = nil,
      sc = nil,
      pos = FVector2D and FVector2D(0, 0) or { X = 0, Y = 0 },
      scv = FVector2D and FVector2D(1, 1) or { X = 1, Y = 1 },
      x = nil,
      y = nil
    }
  end
  function PlayerMapMarker._LabelSet(item, show, x, y, sc)
    if not item or not item.w or not slua.isValid(item.w) then
      return
    end
    if not show then
      if item.vis ~= false then
        item.vis = false;
        item.w:SetWidgetVisibility(UEnums.ESlateVisibility.Collapsed)
      end
      return
    end
    if item.vis ~= true then
      item.vis = true;
      item.w:SetWidgetVisibility(UEnums.ESlateVisibility.HitTestInvisible)
    end
    if item.slot and (item.x ~= x or item.y ~= y) then
      item.x, item.y = x, y item.pos.X, item.pos.Y = x, y item.slot:SetPosition(item.pos)
    end
    if sc and item.text ~= nil then
      sc = sc * math.max(0.5, math.min(2, (tonumber(_G.MWConfig.ESPTextSize) or 100) / 100))
    end
    if sc and item.sc ~= sc then
      item.sc = sc item.scv.X, item.scv.Y = sc, sc item.w:SetRenderScale(item.scv)
    end
  end
  function PlayerMapMarker._LabelText(item, text)
    if not item or not item.w or item.text == text then
      return
    end
    item.text = text pcall(item.w.SetText, item.w, text)
  end
  function PlayerMapMarker._LabelColor(item, color)
    if not item or not item.w or item.color == color then
      return
    end
    item.color = color
    local FSlateColor = PlayerMapMarker._SlateColorClass pcall(function()
      if FSlateColor then
        item.w:SetColorAndOpacity(FSlateColor(color))
      else
        item.w:SetColorAndOpacity(color)
      end
    end)
  end
  function PlayerMapMarker.GetLabels(KeyStr)
    local lb = PlayerMapMarker.Labels[KeyStr]
    if lb and lb.name and lb.name.w and slua.isValid(lb.name.w) then
      return lb
    end
    local canvas = PlayerMapMarker.ESPCanvas
    if not canvas or not Game:IsValid(canvas) then
      return nil
    end
    lb = { name = PlayerMapMarker._NewLabelText(canvas, PlayerMapMarker.LabelFontName, PlayerMapMarker.LabelColorPlayer, 0.5, 0.0),
    dist = PlayerMapMarker._NewLabelText(canvas, PlayerMapMarker.LabelFontDist, PlayerMapMarker.LabelColorDist, 0.5, 0.0),
    wpn = PlayerMapMarker._NewLabelText(canvas, PlayerMapMarker.LabelFontWpn, PlayerMapMarker.LabelColorWpn, 0.0, 1.0),
    wicon = PlayerMapMarker._NewWeaponIcon(canvas), wsh1 = PlayerMapMarker._NewWeaponIcon(canvas, 3),
    tring = PlayerMapMarker._NewTagImage(canvas, "team_dot", 3, PlayerMapMarker.TeamDotRingSize), tdot = PlayerMapMarker._NewTagImage(canvas, "team_dot", 4),
    wpnT = 0, wpnName = nil, wpnID = nil, distM = nil, teamID = nil, }
    if lb.wsh1 then
      pcall(lb.wsh1.w.SetColorAndOpacity, lb.wsh1.w, PlayerMapMarker.WpnIconOutlineColor)
    end
    if lb.tring then
      pcall(lb.tring.w.SetColorAndOpacity, lb.tring.w, PlayerMapMarker.TeamDotRingColor)
    end
    PlayerMapMarker.Labels[KeyStr] = lb
    return lb
  end
  PlayerMapMarker._LabelKeys = { "state", "nation", "bot", "name", "dist", "wpn", "wicon", "tdot", "tring",
  "wsh1" }
  function PlayerMapMarker._WpnOutlineSync(lb)
    if not lb.wicon or not lb.wicon.w or not slua.isValid(lb.wicon.w) then
      return
    end
    local iw = (lb.wicon.loadedID == 0) and PlayerMapMarker.FistIconW or PlayerMapMarker.WpnIconW
    local ih = (lb.wicon.loadedID == 0) and PlayerMapMarker.FistIconH or PlayerMapMarker.WpnIconH
    local sz = FVector2D and FVector2D(iw, ih) or { X = iw, Y = ih }
    local sh = lb.wsh1
    if sh and sh.w and slua.isValid(sh.w) then
      pcall(function()
        sh.w:SetBrush(lb.wicon.w.Brush)
        if sh.slot then
          sh.slot:SetSize(sz)
        end
        if sh.w.SetDesiredSizeOverride then
          sh.w:SetDesiredSizeOverride(sz)
        end
        sh.w:SetColorAndOpacity(PlayerMapMarker.WpnIconOutlineColor)
      end)
      sh.vis = nil
    end
  end
  function PlayerMapMarker._NewTagImage(canvas, key, z, size)
    size = size or PlayerMapMarker.TeamDotSize
    local img = _G.MWIconImageAt(canvas, 0, 0, size, size, key, 0.5, 1.0, z or 3)
    if not img then
      return nil
    end
    pcall(function()
      img.w:SetRenderTransformPivot(FVector2D and FVector2D(0.5, 1.0) or { X = 0.5, Y = 1 })
    end)
    pcall(function()
      img.w:SetWidgetVisibility(UEnums.ESlateVisibility.Collapsed)
    end)
    img.vis = false;
    img.x = nil;
    img.y = nil;
    img.sc = nil;
    img.color = nil
    img.pos = FVector2D and FVector2D(0, 0) or { X = 0, Y = 0 }
    img.scv = FVector2D and FVector2D(1, 1) or { X = 1, Y = 1 }
    return img
  end
  function PlayerMapMarker.HideLabels(KeyStr)
    if _G.OwenNativePlayerMarks then
      _G.OwenNativePlayerMarks.HideKey(KeyStr)
    end
    local lb = PlayerMapMarker.Labels[KeyStr]
    if not lb then
      return
    end
    for _, k in ipairs(PlayerMapMarker._LabelKeys) do
      PlayerMapMarker._LabelSet(lb[k], false)
    end
  end
  function PlayerMapMarker.RemoveLabels(KeyStr)
    if _G.OwenNativePlayerMarks then
      _G.OwenNativePlayerMarks.HideKey(KeyStr)
    end
    local lb = PlayerMapMarker.Labels[KeyStr]
    if not lb then
      return
    end
    for _, k in ipairs(PlayerMapMarker._LabelKeys) do
      local it = lb[k]
      if it and it.w and slua.isValid(it.w) then
        if PlayerMapMarker._ProtectedWidgetStrs then
          PlayerMapMarker._ProtectedWidgetStrs[tostring(it.w)] = nil
        end
        pcall(function()
          it.w:RemoveFromParent()
        end)
      end
    end
    PlayerMapMarker.Labels[KeyStr] = nil
  end
  function PlayerMapMarker.ClearAllLabels()
    if _G.OwenNativePlayerMarks then
      _G.OwenNativePlayerMarks.Stop()
    end
    for KeyStr in pairs(PlayerMapMarker.Labels) do
      PlayerMapMarker.RemoveLabels(KeyStr)
    end
    PlayerMapMarker.Labels = {}
  end
  function PlayerMapMarker._WeaponLabel(Character)
    local info = PlayerMapMarker.GetCharacterWeaponInfo(Character)
    if not info then
      return nil
    end
    local n = info.WeaponName
    if type(n) == "string" and n ~= "" then
      return n
    end
    local id = tonumber(info.WeaponID)
    local localised = id and id > 0 and _G.OwenItemName(id) or nil
    if localised then
      return localised
    end
    if id and id > 0 and ItemDatabase and ItemDatabase[id] then
      return ItemDatabase[id].name
    end
    return nil
  end
  do
    local labels = {
{ 'STANDING', 'CROUCHING', 'PRONE', 'KNOCKED' },
{ 'ĐỨNG', 'NGỒI', 'NẰM', 'ĐÃ GỤC' },
{ '站立', '蹲下', '趴下', '倒地' },
    }
    function PlayerMapMarker.GetStatusLabel(pose, knocked)
      local lang = tonumber((_G.MWConfig or {}).MenuLanguage) or 1
      local words = labels[lang] or labels[1]
      local index = (knocked == true or knocked == 1) and 4 or pose == 1 and 2 or pose == 2 and 3 or 1
      return words[index]
    end
  end
  function PlayerMapMarker._LabelsBody(KeyStr, Character, ESPData, cx, y1, y2, sc)
    local cfg = _G.MWConfig
    local nativeLabels = false
    if _G.OwenNativePlayerMarks then
      local ok, result = pcall(_G.OwenNativePlayerMarks.Touch, KeyStr, Character, ESPData, cx, y1, y2, math.floor(math.max(PlayerMapMarker.LabelTextMin, math.min(PlayerMapMarker.LabelTextMax, sc / (PlayerMapMarker.ESPBaseScale or 0.9))) * 50 + 0.5) / 50)
      nativeLabels = ok and result == true
      if not ok then
        _G.OwenNativePlayerMarks.Stop();
        _G.OwenNativePlayerMarks.NextSetup = (_G.RealNow and _G.RealNow() or os.clock()) + 5;
        _G.OwenNativePlayerMarks.LastError = tostring(result)
      end
    end
    local lb = PlayerMapMarker.GetLabels(KeyStr)
    if not lb then
      return
    end
    local knocked = Character.HealthStatus == 1
    if ESPData then
      ESPData._Knock = knocked
    end
    local ts = sc / (PlayerMapMarker.ESPBaseScale or 0.9)
    if ts < PlayerMapMarker.LabelTextMin then
      ts = PlayerMapMarker.LabelTextMin
    elseif ts > PlayerMapMarker.LabelTextMax then
      ts = PlayerMapMarker.LabelTextMax
    end
    ts = math.floor(ts * 50 + 0.5) / 50
    local gap = PlayerMapMarker.LabelGap
    local isBot = ESPData and (ESPData.IsBot == true or ESPData.IsBot == 1) or false
    local rowH = nativeLabels and (_G.OwenNativePlayerMarks.HeaderHeight(Character) / ts) or 0
    if cfg.EspPlayerWeapon and not nativeLabels then
      local now = PlayerMapMarker._FrameNow or _G.RealNow()
      if now - (lb.wpnT or 0) >= 0.5 then
        lb.wpnT = now
        local info = nil pcall(function()
          info = PlayerMapMarker.GetCharacterWeaponInfo(Character)
        end)
        local wid = info and tonumber(info.WeaponID) or nil
        local wname = nil
        if info then
          if type(info.WeaponName) == "string" and info.WeaponName ~= "" then
            wname = info.WeaponName
          elseif wid and wid > 0 and _G.OwenItemName(wid) then
            wname = _G.OwenItemName(wid)
          elseif wid and wid > 0 and ItemDatabase and ItemDatabase[wid] then
            wname = ItemDatabase[wid].name
          end
        end
        lb.wpnName = wname
        if wname then
          PlayerMapMarker._LabelText(lb.wpn, wname)
        end
        if lb.wicon and wid and wid > 0 then
          if lb.wicon.loadedID ~= wid then
            lb.wicon.loadedID = wid
            local ok = false pcall(function()
              ok = PlayerMapMarker.ApplyWeaponIconToImage(lb.wicon.w, info)
            end)
            lb.wicon.ok = ok and true or false pcall(function()
              local sz = FVector2D and FVector2D(PlayerMapMarker.WpnIconW, PlayerMapMarker.WpnIconH) or { X = PlayerMapMarker.WpnIconW,
              Y = PlayerMapMarker.WpnIconH }
              if lb.wicon.slot then
                lb.wicon.slot:SetSize(sz)
              end
              if lb.wicon.w.SetDesiredSizeOverride then
                lb.wicon.w:SetDesiredSizeOverride(sz)
              end
            end)
            lb.wicon.vis = nil
          end
        elseif lb.wicon then
          if lb.wicon.loadedID ~= 0 then
            lb.wicon.loadedID = 0
            local ok = false pcall(function()
              local util = require("client.slua_ui_framework.util")
              local r = util.SetTexture(lb.wicon.w, PlayerMapMarker.FistIconPath, { sync = true, bMatchSize = false })
              ok = r ~= nil
              if not ok and lb.wicon.w.SetBrushResourceFromPathSync then
                lb.wicon.w:SetBrushResourceFromPathSync(PlayerMapMarker.FistIconPath, false);
                ok = true
              end
            end)
            lb.wicon.ok = ok pcall(function()
              local sz = FVector2D and FVector2D(PlayerMapMarker.FistIconW, PlayerMapMarker.FistIconH) or { X = PlayerMapMarker.FistIconW,
              Y = PlayerMapMarker.FistIconH }
              if lb.wicon.slot then
                lb.wicon.slot:SetSize(sz)
              end
              if lb.wicon.w.SetDesiredSizeOverride then
                lb.wicon.w:SetDesiredSizeOverride(sz)
              end
              lb.wicon.w:SetColorAndOpacity(FLinearColor and FLinearColor(1.0, 1.0, 1.0, 1.0) or { R = 1,
              G = 1, B = 1, A = 1 })
            end)
            lb.wicon.vis = nil
          end
          lb.wpnName = nil
        end
      end
      local hasIcon = lb.wicon and lb.wicon.ok
      local hasName = false
      if hasIcon and lb._outlineID ~= lb.wicon.loadedID then
        lb._outlineID = lb.wicon.loadedID;
        PlayerMapMarker._WpnOutlineSync(lb)
      end
      if hasIcon then
        local iw = (lb.wicon.loadedID == 0) and PlayerMapMarker.FistIconW or PlayerMapMarker.WpnIconW
        local ih = (lb.wicon.loadedID == 0) and PlayerMapMarker.FistIconH or PlayerMapMarker.WpnIconH
        if (ih + PlayerMapMarker.WeaponHeadGap) * ts > rowH then
          rowH = (ih + PlayerMapMarker.WeaponHeadGap) * ts
        end
        local ix, iy = cx - (hasName and 2 or - iw * ts * 0.5), y1 - gap - PlayerMapMarker.WeaponHeadGap * ts PlayerMapMarker._LabelSet(lb.wicon, true, ix, iy, ts)
        local k = PlayerMapMarker.WpnIconOutlineScale PlayerMapMarker._LabelSet(lb.wsh1, true, ix + iw * ts * (k - 1) * 0.5, iy + ih * ts * (k - 1) * 0.5, ts * k)
      else
        PlayerMapMarker._LabelSet(lb.wicon, false)
        PlayerMapMarker._LabelSet(lb.wsh1, false)
      end
      if hasName then
        local th = (PlayerMapMarker.LabelFontWpn + 4) * ts
        if th > rowH then
          rowH = th
        end
        local dw = 0
        if not hasIcon then
          pcall(function()
            local ds = lb.wpn.w:GetDesiredSize();
            dw = ds and ds.X or 0
          end)
        end
        PlayerMapMarker._LabelSet(lb.wpn, true, hasIcon and (cx + 2) or (cx - dw * ts * 0.5), y1 - gap, ts)
      else
        PlayerMapMarker._LabelSet(lb.wpn, false)
      end
    else
      PlayerMapMarker._LabelSet(lb.wicon, false);
      PlayerMapMarker._LabelSet(lb.wpn, false)
      PlayerMapMarker._LabelSet(lb.wsh1, false)
    end
    local teamID = ESPData and ESPData.TeamID
    if cfg.EspPlayerTeam and teamID and lb.tdot then
      local tagY = y1 - gap - ((rowH > 0) and (rowH + PlayerMapMarker.TeamTagGap) or 0)
      if lb.teamID ~= teamID then
