        local tc = PlayerMapMarker.GetTeamColor(teamID)
        lb.tdot.color = tc;
        pcall(lb.tdot.w.SetColorAndOpacity, lb.tdot.w, tc)
        local key = PlayerMapMarker.TeamShapeKeys[(teamID % 4) + 1] or "team_dot" _G.MWIconSet(lb.tdot, key)
        if lb.tring then
          _G.MWIconSet(lb.tring, key)
