      end
      local half = (PlayerMapMarker.TeamDotRingSize - PlayerMapMarker.TeamDotSize) * 0.5 * ts PlayerMapMarker._PinSet(lb.tring, true, cx, tagY + half, ts)
      PlayerMapMarker._PinSet(lb.tdot, true, cx, tagY, ts)
    else
      PlayerMapMarker._PinSet(lb.tdot, false);
      PlayerMapMarker._PinSet(lb.tring, false)
    end
    local textScale = math.max(0.5, math.min(2, (tonumber(cfg.ESPTextSize) or 100) / 100))
    local nextY = y2 + gap
    if nativeLabels then
      nextY = nextY + (_G.OwenNativePlayerMarks.GetFooterHeight(Character) or 0)
    end
    if cfg.EspPlayerName and not nativeLabels then
      local nm = (ESPData and ESPData.Name) or "Unknown" PlayerMapMarker._LabelText(lb.name, nm)
      PlayerMapMarker._LabelColor(lb.name, knocked and PlayerMapMarker.KnockColor or (isBot and PlayerMapMarker.LabelColorBot or PlayerMapMarker.LabelColorPlayer))
      PlayerMapMarker._LabelSet(lb.name, true, cx, nextY, ts)
      nextY = nextY + (PlayerMapMarker.LabelFontName + 5) * ts * textScale
    else
      PlayerMapMarker._LabelSet(lb.name, false)
    end
    local botKnown = ESPData and ESPData.BotKnown == true
    if (cfg.EspPlayerBotLabel == true or cfg.EspPlayerBotLabel == 1) and not nativeLabels then
      isBot, botKnown = PlayerMapMarker.IsAI(Character)
      if ESPData then
        ESPData.IsBot, ESPData.BotKnown = isBot, botKnown
      end
    end
    if (cfg.EspPlayerBotLabel == true or cfg.EspPlayerBotLabel == 1) and botKnown and not nativeLabels then
      if not lb.bot then
        lb.bot = PlayerMapMarker._NewLabelText(PlayerMapMarker.ESPCanvas, PlayerMapMarker.LabelFontName, PlayerMapMarker.LabelColorBot, 0.5, 0)
      end
      local lang = tonumber(cfg.MenuLanguage) or 1 PlayerMapMarker._LabelText(lb.bot, isBot and "BOT" or (lang == 2 and "NGƯỜI" or (lang == 3 and "玩家" or "PLAYER")))
      PlayerMapMarker._LabelSet(lb.bot, true, cx, nextY, ts)
      nextY = nextY + (PlayerMapMarker.LabelFontName + 5) * ts * textScale
    else
      PlayerMapMarker._LabelSet(lb.bot, false)
    end
    if cfg.EspShowState then
      if not lb.state then
        lb.state = PlayerMapMarker._NewLabelText(PlayerMapMarker.ESPCanvas, PlayerMapMarker.LabelFontName, PlayerMapMarker.LabelColorPlayer, 0.5, 0)
      end
      local pose = Character.PoseState
      if pose == nil then
        pcall(function()
          pose = Character:GetPoseState()
        end)
      end
      local state = PlayerMapMarker.GetStatusLabel(pose, knocked)
      PlayerMapMarker._LabelText(lb.state, state);
      PlayerMapMarker._LabelSet(lb.state, true, cx, nextY, ts)
      nextY = nextY + (PlayerMapMarker.LabelFontName + 5) * ts * textScale
    else
      PlayerMapMarker._LabelSet(lb.state, false)
    end
    if (cfg.EspNationFlag == true or cfg.EspNationFlag == 1) and not nativeLabels then
      if not lb.nation then
        lb.nation = PlayerMapMarker._NewWeaponIcon(PlayerMapMarker.ESPCanvas, 4);
        if lb.nation and lb.nation.slot then
          lb.nation.slot:SetAlignment(FVector2D(0.5, 1));
          lb.nation.slot:SetSize(FVector2D(30, 20))
        end
      end
      if lb.nation then
        local now = PlayerMapMarker._FrameNow or _G.RealNow()
        if now >= (lb.nationT or 0) then
          lb.nationT = now + 2 pcall(function()
            local ps = Character.PlayerState or (Character.GetPlayerStateSafety and Character:GetPlayerStateSafety())
            local nation = tostring((ps and ps.Nation) or Character.Nation or "G1")
            if nation == "" or nation == "0" then
              nation = "G1"
            end
            if lb.nationKey ~= nation then
              local row = CDataTable.GetTableData("RegionConfig", nation) or CDataTable.GetTableData("RegionConfig", "G1")
              local path = (row and row.res_path) or "/Game/UMG/Texture/Atlas/NationalflagUI/Frames/T_icon_flag_iland_png.T_icon_flag_iland_png"
              if path and path ~= "" then
                local loaded
                if lb.nation.w.SetBrushFromPathAsync then
                  loaded = lb.nation.w:SetBrushFromPathAsync(path, false)
                else
                  local util = require("client.slua_ui_framework.util");
                  loaded = util.SetTexture(lb.nation.w, path, { sync = false, bMatchSize = false })
                end
                if loaded ~= false then
                  lb.nationKey = nation
                end
              end
            end
          end)
        end
        PlayerMapMarker._LabelSet(lb.nation, lb.nationKey ~= nil, cx, y1 - gap - rowH - gap - 20 * ts, ts)
      end
    else
      PlayerMapMarker._LabelSet(lb.nation, false)
    end
    if cfg.EspPlayerDistance then
      local d = ESPData and ESPData._DistCm
      if d then
        local m = d / 100
        local key = (m < 1000) and math.floor(m) or (1000000 + math.floor(m / 100))
        if lb.distM ~= key then
          lb.distM = key PlayerMapMarker._LabelText(lb.dist, (m < 1000) and string.format("%dm", math.floor(m)) or string.format("%.1fkm", m / 1000))
        end
