  function PlayerMapMarker._HeadRingSet(sk, show, cx, cy, r, color)
    local hr = sk.headImg
    if not show then
      if hr and hr.vis ~= false then
        hr.vis = false;
        pcall(hr.w.SetWidgetVisibility, hr.w, UEnums.ESlateVisibility.Collapsed)
      end
      return
    end
    if not hr then
      if _G._HeadRingFailedT and (_G.RealNow() - _G._HeadRingFailedT) < 3.0 then
        return false
      end
      local canvas = DrawLine.GetCanvas()
      if not canvas then
        return false
      end
      hr = _G.MWIconImageAt(canvas, 0, 0, 10, 10, "head_ring", 0.5, 0.5, 3)
      if not hr then
        _G._HeadRingFailedT = _G.RealNow()
        return false
      end
      _G._HeadRingFailedT = nil
      hr.vis = false;
      hr.cx = nil;
      hr.cy = nil;
      hr.d = nil;
      hr.color = nil
      hr.pos = FVector2D and FVector2D(0, 0) or { X = 0, Y = 0 }
      hr.size = FVector2D and FVector2D(10, 10) or { X = 10, Y = 10 }
      sk.headImg = hr
    end
    if not slua.isValid(hr.w) then
      sk.headImg = nil
      return false
    end
    local d = math.floor(r * 2 + 0.5)
    if d < 8 then
      d = 8
    end
    local key = (d <= 24) and "head_ring_s" or ((d <= 64) and "head_ring_m" or "head_ring")
    if hr.key ~= key then
      _G.MWIconSet(hr, key)
    end
    if hr.cx ~= cx or hr.cy ~= cy then
      hr.cx, hr.cy = cx, cy;
      hr.pos.X, hr.pos.Y = cx, cy;
      pcall(hr.slot.SetPosition, hr.slot, hr.pos)
    end
    if hr.d ~= d then
      hr.d = d;
      hr.size.X, hr.size.Y = d, d;
      pcall(hr.slot.SetSize, hr.slot, hr.size)
    end
    if hr.color ~= color then
      hr.color = color;
      pcall(hr.w.SetColorAndOpacity, hr.w, color)
    end
    if hr.vis ~= true then
      hr.vis = true;
      pcall(hr.w.SetWidgetVisibility, hr.w, UEnums.ESlateVisibility.HitTestInvisible)
    end
    return true
  end
  function PlayerMapMarker.HideSkel(KeyStr)
    local sk = PlayerMapMarker.Skel[KeyStr]
    if not sk then
      return
    end
    sk.OnScreen = false
    for _, l in pairs(sk.lines) do
      DrawLine.Hide(l)
    end
    for _, l in pairs(sk.ends or {}) do
      DrawLine.Hide(l)
    end
    for _, l in pairs(sk.under) do
      DrawLine.Hide(l)
    end
    PlayerMapMarker._HeadRingSet(sk, false)
  end
  function PlayerMapMarker.RemoveSkel(KeyStr)
    local sk = PlayerMapMarker.Skel[KeyStr]
    if not sk then
      return
    end
    for _, l in pairs(sk.lines) do
      DrawLine.Remove(l)
    end
    for _, l in pairs(sk.ends or {}) do
      DrawLine.Remove(l)
    end
    for _, l in pairs(sk.under) do
      DrawLine.Remove(l)
    end
    if sk.headImg and sk.headImg.w and slua.isValid(sk.headImg.w) then
      pcall(function()
        sk.headImg.w:RemoveFromParent()
      end)
    end
    sk.headImg = nil
    PlayerMapMarker.Skel[KeyStr] = nil
  end
  function PlayerMapMarker.ClearAllSkel()
    for KeyStr in pairs(PlayerMapMarker.Skel) do
      PlayerMapMarker.RemoveSkel(KeyStr)
    end
    PlayerMapMarker.Skel = {}
    local s = _G.OwenSkeletonBudget
    if s then
      s.TraceContext = nil;
      s.TraceKey = nil;
      s.Cursor = 0;
      s.TraceCursor = 0
      for k in pairs(s.Targets) do
        s.Targets[k] = nil
      end
      for k in pairs(s.Selected) do
        s.Selected[k] = nil
      end
    end
  end
  do
    local S = {
      Targets = {},
      Selected = {},
      Cursor = 0,
      TraceCursor = 0,
      FarBones = { [1] = true, [2] = true, [5] = true, [8] = true, [11] = true, [14] = true, [17] = true },
      FarLinks = {
{ 18, 2 },
{ 2, 5 },
{ 2, 8 },
{ 2, 11 },
{ 5, 14 },
{ 5, 17 }
      }
    }
    _G.OwenSkeletonBudget = S
    function S.Vector()
      return FVector and FVector(0, 0, 0) or { X = 0, Y = 0, Z = 0 }
    end
    function S.NewLine()
      if (S.WidgetLeft or 0) <= 0 then
        return
      end
      S.WidgetLeft = S.WidgetLeft - 1
      local canvas = PlayerMapMarker.ESPCanvas
      if not canvas then
        return
      end
      local w = CGame:NewObjectFromPath('/Script/UMG.Border', canvas)
      if not w then
        return
      end
      local slot = canvas:AddChildToCanvas(w)
      if not slot then
        w:RemoveFromParent();
        return
      end
      slot:SetAutoSize( false);
      slot:SetAlignment(FVector2D(0, 0.5));
      slot:SetZOrder(3)
      w:SetRenderTransformPivot(FVector2D(0, 0.5))
      local brush = w.Background;
      brush.DrawAs = 3;
      w:SetBrush(brush)
      w:SetWidgetVisibility(UEnums.ESlateVisibility.Collapsed)
      PlayerMapMarker._ProtectedWidgetStrs = PlayerMapMarker._ProtectedWidgetStrs or {} PlayerMapMarker._ProtectedWidgetStrs[tostring(w)] = true
      return { Widget = w, Slot = slot, img = false, _posVec = FVector2D(0, 0), _sizeVec = FVector2D(0, 0),
      _visible = false }
    end
    function S.Enabled(v)
      return v == true or v == 1
    end
    function S.Plan()
      local now = _G.RealNow();
      S.Now = now;
      local lowSpec = _G.OwenLowSpecEnabled();
      S.WidgetLeft = lowSpec and 8 or 12;
      S.BoneLeft = lowSpec and 68 or 85
      for k in pairs(S.Selected) do
        S.Selected[k] = nil
      end
      local n = 0
      if not S.Enabled(_G.MWConfig.EspPlayerSkeleton) or _G.MWConfig.EspPlayer == false or _G.MWConfig.EspPlayer == 0 then
        if S.PartialActive then
          for _, sk in pairs(PlayerMapMarker.Skel) do
            sk.TraceContext = nil
          end
        end
        S.PartialActive = false;
        S.TraceLeft = 0;
        S.NextTrace = 0;
        S.TraceKey = nil;
        S.TraceContext = nil;
        return
      end
      for key, sk in pairs(PlayerMapMarker.Skel) do
        if sk.OnScreen and now - (sk.DrawAt or 0) < .2 then
          n = n + 1;
          S.Targets[n] = key
        end
      end
      for i = # S.Targets, n + 1, - 1 do
        S.Targets[i] = nil
      end
      local budget = lowSpec and 68 or 85
      for _ = 1, n do
        S.Cursor = S.Cursor % n + 1;
        local key = S.Targets[S.Cursor];
        local sk = PlayerMapMarker.Skel[key];
        local cost = sk.Far and 7 or 17
        if now >= (sk.NextPose or 0) then
          if budget < cost then
            S.Cursor = (S.Cursor - 2) % n + 1;
            break
          end
          S.Selected[key] = true;
          budget = budget - cost
        end
      end
      if not S.Enabled(_G.MWConfig.EspSkeletonSegmentColor) then
        if S.PartialActive then
          for _, sk in pairs(PlayerMapMarker.Skel) do
            sk.TraceContext = nil;
            sk.SegmentVis = nil;
            sk.Boundaries = nil
          end
        end
        S.PartialActive = false;
        S.TraceLeft = 0;
        S.NextTrace = 0;
        S.TraceKey = nil;
        S.TraceContext = nil;
        return
      end
      S.PartialActive = true
      if lowSpec then
        table.sort(S.Targets, function(a, b)
          local ea, eb = PlayerMapMarker.ESPWidgets[a], PlayerMapMarker.ESPWidgets[b]
          local da, db = ea and ea._DistCm or math.huge, eb and eb._DistCm or math.huge
          if da == db then
            return tostring(a) < tostring(b)
          end
          return da < db
        end)
      end
      local traceCount = lowSpec and math.min(n, 6) or n
      if now >= (S.NextTrace or 0) then
        S.NextTrace = now + (lowSpec and 1 / 30 or 1 / 60);
        S.TraceLeft = lowSpec and 12 or 25;
        S.TraceKey = nil
        if traceCount > 0 then
          S.TraceCursor = S.TraceCursor % traceCount + 1;
          S.TraceKey = S.Targets[S.TraceCursor]
        end
      end
    end
    function S.Sample(key, sk, pawn, pc)
      local now = S.Now or _G.RealNow();
      local ed = PlayerMapMarker.ESPWidgets[key]
      local far = ((ed and ed._DistCm) or 0) > 12000
      if sk.Pawn ~= pawn or sk.Mesh ~= pawn.Mesh or sk.Far ~= far then
        sk.Pawn = pawn;
        sk.Mesh = pawn.Mesh;
        sk.Far = far;
        sk.NextPose = 0;
        sk.SegmentVis = {};
        sk.Boundaries = {};
        sk.TraceContext = nil
        for _, pt in pairs(sk.pts) do
          pt.Sample = nil
        end
      end
      sk.OnScreen = true;
      sk.DrawAt = now
      local cost = far and 7 or 17
      local read = S.Selected[key] and now >= (sk.NextPose or 0) and (S.BoneLeft or 0) >= cost
      local origin = pawn:K2_GetActorLocation()
      if read then
        S.BoneLeft = S.BoneLeft - cost
        sk.NextPose = now + (far and 1 / 15 or ((ed and ed._DistCm or 0) > 5000 and 1 / 30 or 1 / 60))
        sk.Origin = sk.Origin or {};
        sk.Origin.X, sk.Origin.Y, sk.Origin.Z = origin.X, origin.Y, origin.Z
      end
      local ox = sk.Origin;
      local dx, dy, dz = 0, 0, 0
      if ox then
        dx, dy, dz = origin.X - ox.X, origin.Y - ox.Y, origin.Z - ox.Z
      end
      for i, name in ipairs(PlayerMapMarker.SkelBones) do
        local pt = sk.pts[i] or {};
        sk.pts[i] = pt;
        pt.ok = false
        if not far or S.FarBones[i] then
          if read then
            local ok, v = pcall(pawn.GetBonePos, pawn, name, PlayerMapMarker._Zero3)
            if ( not ok or not v or (v.X == 0 and v.Y == 0 and v.Z == 0)) and pawn.Mesh and type(pawn.Mesh.GetSocketLocation) == 'function' then
              local exists = true
              if type(pawn.Mesh.DoesSocketExist) == 'function' then
                local good, value = pcall(pawn.Mesh.DoesSocketExist, pawn.Mesh, name);
                exists = good and S.Enabled(value)
              end
              if exists then
                ok, v = pcall(pawn.Mesh.GetSocketLocation, pawn.Mesh, name)
              end
            end
            if ok and v and not (v.X == 0 and v.Y == 0 and v.Z == 0) then
              pt.Sample = pt.Sample or {};
              pt.Sample.X, pt.Sample.Y, pt.Sample.Z = v.X, v.Y, v.Z
            else
              pt.Sample = nil
            end
          end
          if pt.Sample then
            local w = pt.World or S.Vector();
            pt.World = w;
            w.X, w.Y, w.Z = pt.Sample.X + dx, pt.Sample.Y + dy, pt.Sample.Z + dz
            local ok, x, y = PlayerMapMarker.ProjectWorldToCanvasLocalRaw(pc, w);
            pt.ok = ok;
            pt.x, pt.y = x, y
          end
        end
      end
      local head = sk.pts[1];
      local chin = sk.pts[18] or {};
      sk.pts[18] = chin
      chin.ok = head.ok;
      chin.x, chin.y = head.x, head.y;
      chin.World = head.World
      local topOK, tx, ty = false, 0, 0
      if head.ok then
        local w = sk.HeadWorld or S.Vector();
        sk.HeadWorld = w;
        w.X, w.Y, w.Z = head.World.X, head.World.Y, head.World.Z + 19 topOK, tx, ty = PlayerMapMarker.ProjectWorldToCanvasLocalRaw(pc, w)
        w.Z = head.World.Z + 9;
        head.ok, head.x, head.y = PlayerMapMarker.ProjectWorldToCanvasLocalRaw(pc, w)
      end
      return topOK, tx, ty
    end
    function S.Trace(pc, pawn, point)
      local sk = S.TraceKey and PlayerMapMarker.Skel[S.TraceKey]
      local own = (_G.OwenNeonOverlayContext or {}).Player
      local c = sk and sk.TraceContext or S.TraceContext
      if c and own and c.Owner ~= own then
        c = nil
      end
      if not c or c.PC ~= pc or c.Pawn ~= pawn then
        c = { PC = pc, Pawn = pawn, KSL = import('KismetSystemLibrary'), Hit = import('/Script/Engine.HitResult')() }
        c.Ignore = slua.Array(UEnums.EPropertyClass.Object, import('/Script/Engine.Actor'))
        c.Ignore:Add(pawn)
        if not own and type(pc.GetPlayerCharacterSafety) == 'function' then
          own = pc:GetPlayerCharacterSafety()
        end
        if not own and type(pc.GetPawn) == 'function' then
          own = pc:GetPawn()
        end
        if own then
          c.Ignore:Add(own)
        end
        if own then
          if type(own.GetCurrentWeapon) == 'function' then
            pcall(function()
              local weapon = own:GetCurrentWeapon();
              if weapon and slua.isValid(weapon) then
                c.Ignore:Add(weapon)
              end
            end)
          end
          if type(own.GetCurrentVehicle) == 'function' then
            pcall(function()
              local vehicle = own:GetCurrentVehicle();
              if vehicle and slua.isValid(vehicle) then
                c.Ignore:Add(vehicle)
              end
            end)
          end
        end
        c.Owner = own;
        c.Start = FVector(0, 0, 0);
        c.Finish = FVector(0, 0, 0);
        S.TraceContext = c
        if sk then
          sk.TraceContext = c
        end
      end
      local cam = pc.PlayerCameraManager:GetCameraLocation();
      c.Start.X, c.Start.Y, c.Start.Z = cam.X, cam.Y, cam.Z c.Finish.X, c.Finish.Y, c.Finish.Z = point.X, point.Y, point.Z
      c.TraceColor = c.TraceColor or FLinearColor(0, 0, 0, 0)
      local hit = c.KSL.LineTraceSingle(slua.getWorld(), c.Start, c.Finish, 0, false, c.Ignore, 0, c.Hit, true, c.TraceColor, c.TraceColor, 0)
      return hit == false or hit == 0
    end
    function S.RefreshSegments(key, sk, pc, pawn, links)
      if not S.Enabled(_G.MWConfig.EspSkeletonSegmentColor) or _G.MWConfig.EspPlayer == false or _G.MWConfig.EspPlayer == 0 or not S.Enabled(_G.MWConfig.EspPlayerSkeleton) or S.TraceKey ~= key or not sk.OnScreen then
        return
      end
      if S.Now < (S.TraceRetryAt or 0) then
        return
      end
      sk.SegmentVis = sk.SegmentVis or {};
      local now = S.Now
      local count = 17;
      local attempts = 0;
      local spent = 0;
      local budget = math.min(17, S.TraceLeft or 0)
      while attempts < count and spent < budget do
        attempts = attempts + 1;
        sk.TraceCursor = (sk.TraceCursor or 0) % count + 1;
        local i = sk.TraceCursor
        local a = sk.pts[i]
        if ( not sk.Far or S.FarBones[i]) and a and a.ok and a.World then
          S.TraceLeft = S.TraceLeft - 1
          spent = spent + 1
          local ok, value = pcall(S.Trace, pc, pawn, a.World)
          local e = sk.SegmentVis[i] or {};
          sk.SegmentVis[i] = e;
          e.At = now;
          e.Visible = ok and value == true or nil
          if ok and value == false then
            e.Visible = false
          end
          if not ok then
            S.LastTraceError = tostring(value);
            S.TraceRetryAt = now + 2;
            break
          else
            S.LastTraceError = nil
          end
        end
      end
      if S.LastTraceError or (S.TraceLeft or 0) < 2 or not links then
        return
      end
      sk.Boundaries = sk.Boundaries or {}
      local total = # links
      for _ = 1, total do
        if S.TraceLeft < 2 then
          break
        end
        sk.BoundaryCursor = (sk.BoundaryCursor or 0) % total + 1;
        local li = sk.BoundaryCursor
        local ai, bi = links[li][1], links[li][2];
        if ai == 18 then
          ai = 1
        end;
        if bi == 18 then
          bi = 1
        end
        local va, vb = sk.SegmentVis[ai], sk.SegmentVis[bi]
        local a, b = sk.pts[ai], sk.pts[bi]
        if va and vb and va.Visible ~= nil and vb.Visible ~= nil and va.Visible ~= vb.Visible and a and b and a.ok and b.ok and a.World and b.World then
          local low, high = 0, 1;
          local w = sk.BoundaryWorld or S.Vector();
          sk.BoundaryWorld = w
          local success = true
          for step = 1, 2 do
            local t = (low + high) * .5
            w.X = a.World.X + (b.World.X - a.World.X) * t;
            w.Y = a.World.Y + (b.World.Y - a.World.Y) * t;
            w.Z = a.World.Z + (b.World.Z - a.World.Z) * t
            S.TraceLeft = S.TraceLeft - 1
            local ok, value = pcall(S.Trace, pc, pawn, w)
            if not ok then
              S.LastTraceError = tostring(value);
              S.TraceRetryAt = now + 2;
              success = false;
              break
            end
            if value == va.Visible then
              low = t
            else
              high = t
            end
          end
          if success then
            local e = sk.Boundaries[li] or {};
            sk.Boundaries[li] = e;
            e.T = (low + high) * .5;
            e.A = va.Visible;
            e.B = vb.Visible
          end
          if not success then
            break
          end
        end
      end
    end
    function S.Split(sk, li)
      local e = sk.Boundaries and sk.Boundaries[li]
      local links = sk.Far and S.FarLinks or PlayerMapMarker.SkelLinks
      local link = links and links[li]
      if e and link then
        local ai, bi = link[1], link[2];
        if ai == 18 then
          ai = 1
        end;
        if bi == 18 then
          bi = 1
        end
        local a, b = sk.SegmentVis[ai], sk.SegmentVis[bi]
        if a and b and a.Visible == e.A and b.Visible == e.B then
          return e.T
        end
      end
      return .5
    end
    function S.Color(sk, i, fallback, bot, knocked)
      if not S.Enabled(_G.MWConfig.EspSkeletonSegmentColor) then
        return fallback
      end
      if i == 18 then
        i = 1
      end
      local e = sk.SegmentVis and sk.SegmentVis[i]
      if not e or e.Visible == nil then
        return fallback
      end
      local visible = e.Visible == true
      return PlayerMapMarker.GetSkeletonDisplayColor(visible, bot, knocked)
    end
  end
  function PlayerMapMarker._SkelBody(KeyStr, Character, PC)
    local sk = PlayerMapMarker.Skel[KeyStr]
    if not sk then
      sk = {
        lines = {},
        under = {},
        pts = {}
      };
      PlayerMapMarker.Skel[KeyStr] = sk
    end
    local pts = sk.pts
    local z3 = PlayerMapMarker._Zero3
    if not z3 then
      z3 = { X = 0, Y = 0, Z = 0 };
      PlayerMapMarker._Zero3 = z3
    end
    local headTopOk, headTopX, headTopY = _G.OwenSkeletonBudget.Sample(KeyStr, sk, Character, PC)
    local visible = PlayerMapMarker._LOS(KeyStr, PC, Character)
    local edB = PlayerMapMarker.ESPWidgets[KeyStr]
    local isBotS = edB and edB.IsBot or false
    local color = PlayerMapMarker.GetSkeletonDisplayColor(visible, isBotS, tonumber(Character.HealthStatus) == 1)
    local tk = tonumber(_G.MWConfig.EspSkeletonThickness) or PlayerMapMarker.SkelThickness
    local soft = PlayerMapMarker.SkelSoft
    local colorS, tkS = (visible and (isBotS and PlayerMapMarker.SkelColorBotSoft or PlayerMapMarker.SkelColorSoft) or PlayerMapMarker.SkelColorOccSoft), tk * (PlayerMapMarker.SkelSoftMul or 2.0)
    if Character.HealthStatus == 1 then
      color = PlayerMapMarker.KnockColor;
      colorS = PlayerMapMarker.KnockColor
    end
    local links = sk.Far and _G.OwenSkeletonBudget.FarLinks or PlayerMapMarker.SkelLinks _G.OwenSkeletonBudget.RefreshSegments(KeyStr, sk, PC, Character, links)
    local partial = _G.OwenSkeletonBudget.Enabled(_G.MWConfig.EspSkeletonSegmentColor)
    sk.ends = sk.ends or {}
    for li = 1, # links do
      local ai, bi = links[li][1], links[li][2]
      local a, b = pts[ai], pts[bi]
      local vis = a and b and a.ok and b.ok
      local line = sk.lines[li]
      if vis and not line then
        line = _G.OwenSkeletonBudget.NewLine();
        sk.lines[li] = line
      end
      local ca = vis and _G.OwenSkeletonBudget.Color(sk, ai, color, isBotS, tonumber(Character.HealthStatus) == 1) or color
      local cb = vis and _G.OwenSkeletonBudget.Color(sk, bi, color, isBotS, tonumber(Character.HealthStatus) == 1) or color
      local split = partial and ca ~= cb
      local tail = sk.ends[li]
      if split and vis and not tail then
        tail = _G.OwenSkeletonBudget.NewLine();
        sk.ends[li] = tail
      end
      if vis and line then
        if split and tail then
          local t = _G.OwenSkeletonBudget.Split(sk, li)
          local mx, my = a.x + (b.x - a.x) * t, a.y + (b.y - a.y) * t DrawLine.Update(line, a.x, a.y, mx, my, ca, tk)
          DrawLine.Update(tail, mx, my, b.x, b.y, cb, tk)
        else
          DrawLine.Update(line, a.x, a.y, b.x, b.y, partial and ca or color, tk)
          if tail then
            DrawLine.Hide(tail)
          end
        end
      else
        if line then
          DrawLine.Hide(line)
        end
        if tail then
          DrawLine.Hide(tail)
        end
      end
      if sk.under[li] then
        DrawLine.Hide(sk.under[li])
      end
    end
    for li, line in pairs(sk.lines) do
      if li > # links then
        DrawLine.Hide(line)
      end
    end
    for li, line in pairs(sk.ends) do
      if li > # links then
        DrawLine.Hide(line)
      end
    end
    local hp = pts[1]
    if hp and hp.ok and headTopOk then
      local dx, dy = headTopX - hp.x, headTopY - hp.y
      local r = math.sqrt(dx * dx + dy * dy)
      if r < 2 then
        r = 2
      end
      if r > (PlayerMapMarker.SkelHeadMaxR or 250) then
        PlayerMapMarker._HeadRingSet(sk, false)
      else
        PlayerMapMarker._HeadRingSet(sk, true, hp.x, hp.y, r, _G.OwenSkeletonBudget.Color(sk, 1, color, isBotS, tonumber(Character.HealthStatus) == 1))
      end
    else
      PlayerMapMarker._HeadRingSet(sk, false)
    end
  end
  function PlayerMapMarker._ScreenCenterCanvas(PC)
    local now = _G.RealNow()
    if PlayerMapMarker._CenterT and (now - PlayerMapMarker._CenterT) < 0.5 and PlayerMapMarker._CenterX then
      return PlayerMapMarker._CenterX, PlayerMapMarker._CenterY
    end
    local pw, ph = 0, 0 pcall(function()
      local vs = FVector2D and FVector2D(0, 0) or { X = 0, Y = 0 }
      PC:GetViewportSize(vs)
      if vs and vs.X and vs.X > 200 then
        pw, ph = vs.X, vs.Y
      end
    end)
    if pw <= 200 then
      pcall(function()
        local WLL = import("WidgetLayoutLibrary")
        local vs = WLL.GetViewportSize(PC)
        if vs and vs.X and vs.X > 200 then
          pw, ph = vs.X, vs.Y
        end
      end)
    end
    if pw <= 200 then
      pw, ph = 1920, 1080
    end
    PlayerMapMarker._VpPxW, PlayerMapMarker._VpPxH = pw, ph
    local cx, cy = PlayerMapMarker.ScreenPixelToCanvasLocalRaw(PC, pw * 0.5, ph * 0.5)
    PlayerMapMarker._CenterX, PlayerMapMarker._CenterY, PlayerMapMarker._CenterT = cx, cy, now
    return cx, cy
  end
  PlayerMapMarker.Pins = {} PlayerMapMarker.PinH = 28
  PlayerMapMarker.PinZOff = 45
