  local function OwenVehicleIconNameKind(value)
    local n = tostring(value or ""):lower()
    if n == "" then
      return nil
    end
    if n:find("armed", 1, true) or n:find("technical", 1, true) or n:find("guntruck", 1, true) or n:find("weaponvehicle", 1, true) or n:find("vũ trang", 1, true) then
      return "armed"
    end
    if n:find("mtlb", 1, true) or n:find("mt-lb", 1, true) or n:find("mt_lb", 1, true) then
      return "mtlb"
    end
    if n:find("sidecar", 1, true) or n:find("motorcyclecart", 1, true) or n:find("xe máy thùng", 1, true) or n:find("mô tô thùng", 1, true) then
      return "sidecar"
    end
    if n:find("rony", 1, true) then
      return "rony"
    end
    if n:find("uaz", 1, true) then
      return "uaz"
    end
    if n:find("pickup", 1, true) or n:find("pick-up", 1, true) or n:find("pick up", 1, true) or n:find("bán tải", 1, true) then
      return "pickup"
    end
    if n:find("minibus", 1, true) or n:find("mini bus", 1, true) or n == "van" or n:find("_van_", 1, true) or n == "xe tải nhỏ" then
      return "minibus"
    end
    if n:find("monster", 1, true) or n:find("bigfoot", 1, true) then
      return "offroad"
    end
    if n:find("tank", 1, true) or n:find("tracked", 1, true) or n:find("leopard", 1, true) or n:find("xe tăng", 1, true) then
      return "tank"
    end
    if n:find("helicopter", 1, true) or n:find("heli", 1, true) or n:find("chopper", 1, true) then
      return "heli"
    end
    if n:find("plane", 1, true) or n:find("aircraft", 1, true) or n:find("motor glider", 1, true) or n:find("glider", 1, true) then
      return "plane"
    end
    if n:find("snowmobile", 1, true) then
      return "snowmobile"
    end
    if n:find("scooter", 1, true) then
      return "scooter"
    end
    if n:find("tukshai", 1, true) or n:find("tuktuk", 1, true) or n:find("tuk tuk", 1, true) or n:find("rickshaw", 1, true) or n:find("auto rickshaw", 1, true) then
      return "tuktuk"
    end
    if n:find("atv", 1, true) or n:find("quad", 1, true) or n:find("rzr", 1, true) then
      return "atv"
    end
    if n:find("buggy", 1, true) then
      return "buggy"
    end
    if n:find("pg-117", 1, true) or n:find("pg117", 1, true) or n:find("aquarail", 1, true) or n:find("airboat", 1, true) or n:find("boat", 1, true) or n:find("jetski", 1, true) or n:find("jet ski", 1, true) then
      return "boat"
    end
    if n:find("brdm", 1, true) or n:find("loottruck", 1, true) or n:find("store bus", 1, true) or n:find("storebus", 1, true) or n:find("bus", 1, true) or n:find("van", 1, true) or n:find("truck", 1, true) then
      return "heavy"
    end
    if n:find("motorcycle", 1, true) or n:find("motorbike", 1, true) or n:find("snowbike", 1, true) or n:find("bike", 1, true) then
      return "moto"
    end
    if n:find("offroad", 1, true) or n:find("off-road", 1, true) then
      return "offroad"
    end
    return nil
  end
  function PlayerMapMarker.OwenVehicleIconKey(item)
