    local key = kind and ('veh_' .. kind) or ((item.kind and PlayerMapMarker.VehKindIcon[item.kind]) or ('veh_' .. (item.kind or item.group or 'car')))
    return _G.MWIconB64[key] and key or 'veh_car'
  end
