  do
    local R = {
      Owners = {}
    }
    _G.OwenNativeMarkRouter = R
    function R.Prepare(pc, id, owner)
      assert(pc and pc.GetComponentByClass, 'native_controller_component_unavailable')
      local component = pc:GetComponentByClass(import('MapUIMarkManager'))
      assert(component and slua.isValid(component), 'native_map_manager_unavailable')
      local manager = component.m_ScreenMarkManager assert(manager and slua.isValid(manager), 'native_screen_manager_unavailable')
      assert(manager.InitMarkGroupData and manager.GetWidgetByActor, 'native_screen_manager_api_unavailable')
      local groups = manager.ScreenMarkGroupMap
      local group = groups and groups.Get and groups:Get(id)
      if not group then
        manager:InitMarkGroupData(id, true)
      end
      if groups and groups.Get then
        assert(groups:Get(id), 'native_group_not_initialized')
      end
      owner.Manager = manager
    end
    function R.Resolve(owner, record)
      if record.Ready or not record.Visible or record.Failed then
        return
      end
      local now = _G.RealNow and _G.RealNow() or os.clock()
      if now < (record.NextResolve or 0) then
        return
      end
      record.NextResolve = now + 0.25
      local manager = owner.Manager
      if not manager or not slua.isValid(manager) then
        owner.LastError = 'native_screen_manager_lost';
        return
      end
      local actor = record.Actor or (record.Item and record.Item.act)
      local ok, widget = pcall(manager.GetWidgetByActor, manager, owner.TypeID, actor)
      if not ok then
        owner.LastError = 'native_widget_query:' .. tostring(widget);
        return
      end
      if widget and slua.isValid(widget) then
        owner.Recovered = (owner.Recovered or 0) + 1 owner.OnBind(widget, actor, owner.TypeID, record.ID)
      else
        owner.LastError = 'native_widget_not_bound'
      end
    end
    function R.Add(id, owner)
      if not R.Class then
        R.Class = require('GameLua.Mod.BaseMod.Client.ScreenMarkUI.CommonActorScreenMarkUI')
        R.Hooks = {}
        local function hook(key, fn)
          local original = R.Class[key];
          assert(type(original) == 'function', 'missing_native_callback:' .. key)
          local wrapped = function(self, ...)
            return fn(original, self, ...)
          end
          R.Hooks[key] = { Original = original, Wrapped = wrapped };
          R.Class[key] = wrapped
        end
        if type(R.Class.SetUpInfoInternal) == 'function' then
          hook('SetUpInfoInternal', function(original, self, id)
            local n = R.Owners[id]
            if n and n.OnNativeSetup then
              n.OnNativeSetup(self)
            end
            local result = original(self, id)
            if n and n.OnNativeSetup then
              n.OnNativeSetup(self)
            end
            return result
          end)
        end
        hook('OnActorBindUI', function(original, self, actor, typeID, instance)
          local n = R.Owners[typeID];
          if n then
            return n.OnBind(self, actor, typeID, instance)
          end
          return original(self, actor, typeID, instance)
        end)
        hook('OnActorUnbindUI', function(original, self, actor)
          local n = R.Owners[self.ID];
          if n then
            return n.OnUnbind(self, actor)
          end
          return original(self, actor)
        end)
        hook('OnUpdateState', function(original, self, ...)
          if R.Owners[self.ID] then
            return
          end
          return original(self, ...)
        end)
      end
      assert( not R.Owners[id] or R.Owners[id] == owner, 'native_route_collision')
      R.Owners[id] = owner
    end
    function R.Remove(id)
      R.Owners[id] = nil
      if next(R.Owners) then
        return
      end
      if R.Class then
        for key, h in pairs(R.Hooks or {}) do
          if R.Class[key] == h.Wrapped then
            R.Class[key] = h.Original
          end
        end
      end
      R.Class = nil;
      R.Hooks = nil
    end
  end
  do
    local N = {
      TypeID = 479901,
      Records = {},
      WidgetOwners = setmetatable( {}, { __mode = 'k' }),
      Count = 0,
      Limit = 20,
      Interval = 0.2,
      NextTick = 0,
      NextSetup = 0,
      Status = 'idle'
    }
    _G.OwenNativeVehicleMarks = N
    local distanceColor = FLinearColor and FLinearColor(1, 0, 0, 1) or { R = 255, G = 0, B = 0, A = 255 }
    local nativeChildren = { 'Image_Icon', 'Image_BG', 'ImageBG_Distance', 'Text_Distance', 'ImageBG_Time',
    'TextBlock_Time' }
    local function now()
      return _G.RealNow and _G.RealNow() or os.clock()
    end
    local function valid(v)
      return v ~= nil and slua.isValid(v)
    end
    local function visibility(w, on)
      if valid(w) then
        w:SetWidgetVisibility(on and UEnums.ESlateVisibility.SelfHitTestInvisible or UEnums.ESlateVisibility.Collapsed)
      end
    end
    function N.DetachDefaults(w)
      if not w.OwenVehicleCanvas then
        local icon = w.Image_Icon
        local parent = valid(icon) and icon.GetParent and icon:GetParent()
        for _ = 1, 8 do
          if not valid(parent) then
            break
          end
          if parent.AddChildToCanvas then
            w.OwenVehicleCanvas = parent;
            break
          end
          parent = parent.GetParent and parent:GetParent()
        end
      end
      for _, key in ipairs(nativeChildren) do
        local control = w[key]
        visibility(control, false)
        if not w.OwenVehicleDefaultsDetached and valid(control) and control.RemoveFromParent then
          control:RemoveFromParent()
        end
      end
      if w.OwenVehicleCanvas then
        w.OwenVehicleDefaultsDetached = true
      end
    end
    function N.EnsureView(w)
      local v = w.OwenVehicleView
      if v and valid(v.Icon) and valid(v.Row) and valid(v.Name) and valid(v.Distance) and valid(v.Health) then
        return v
      end
      local parent = w.OwenVehicleCanvas
      if not valid(parent) or not parent.AddChildToCanvas then
        return nil
      end
      v = {}
      local ok, err = pcall(function()
        local function create(key, path, template)
          local control = CGame:NewObjectFromPath(path, parent);
          v[key] = control;
          assert(valid(control))
          local slot = parent:AddChildToCanvas(control);
          assert(slot)
          if slot.SetAutoSize then
            slot:SetAutoSize(key ~= 'Icon')
          end
          if template then
            local font = template.Font or (template.GetFont and template:GetFont())
            if font then
              control.Font = font
            end
          end
          if control.SetRenderOpacity then
            control:SetRenderOpacity(1)
          end
          visibility(control, false)
        end
        create('Icon', '/Script/UMG.Image')
        create('Row', '/Script/UMG.HorizontalBox')
        local function rowText(key, template)
          local text = CGame:NewObjectFromPath('/Script/UMG.TextBlock', v.Row);
          v[key] = text;
          assert(valid(text))
          assert(v.Row:AddChildToHorizontalBox(text))
          local font = template and (template.Font or (template.GetFont and template:GetFont()))
          if font then
            text.Font = font
          end
          visibility(text, false)
        end
        rowText('Name', w.TextBlock_Time)
        rowText('Distance', w.Text_Distance)
        create('Health', '/Script/UMG.TextBlock', w.Text_Distance)
      end)
      if not ok then
        for _, control in pairs(v) do
          if valid(control) then
            pcall(control.RemoveFromParent, control)
          end
        end
        N.LastError = 'native_vehicle_private_content:' .. tostring(err);
        return nil
      end
      v.TextScaleVector = FVector2D(1, 1)
      if v.Row.SetRenderTransformPivot then
        v.Row:SetRenderTransformPivot(FVector2D(0.5, 0))
      end
      for _, text in ipairs( { v.Name, v.Distance, v.Health }) do
        local font = text.Font or (text.GetFont and text:GetFont())
        if font then
          font.Size = PlayerMapMarker.VehFont;
          if font.OutlineSettings then
            font.OutlineSettings.OutlineSize = 1
          end;
          text.Font = font
        end
        if text.SetRenderTransformPivot then
          text:SetRenderTransformPivot(FVector2D(0.5, 0))
        end
        PlayerMapMarker._ProtectedWidgetStrs = PlayerMapMarker._ProtectedWidgetStrs or {} PlayerMapMarker._ProtectedWidgetStrs[tostring(text)] = true
      end
      PlayerMapMarker._ProtectedWidgetStrs[tostring(v.Row)] = true
      w.OwenVehicleView = v;
      return v
    end
    local function hideView(w)
      local v = w and w.OwenVehicleView
      if v then
        visibility(v.Icon, false);
        visibility(v.Row, false);
        visibility(v.Name, false);
        visibility(v.Distance, false);
        visibility(v.Health, false)
      end
    end
    local function resetStyle(r)
      r.Ready = false;
      r.NextResolve = 0
      r.IconKey = nil;
      r.Label = nil;
      r.DistanceText = nil;
      r.Health = nil;
      r.Layout = nil;
      r.FontSize = nil;
      r.TextScale = nil;
      r.Color = nil
    end
    function N.OnNativeSetup(w)
      visibility(w, false)
      w.TextBlock_Distance = nil;
      w.bCountDownTime = false N.DetachDefaults(w);
      hideView(w)
      local r = N.WidgetOwners[w]
      if r then
        resetStyle(r)
      end
    end
    function N.ApplyTextSize(r)
      local w = r.Widget
      if not valid(w) or N.WidgetOwners[w] ~= r or w.ID ~= N.TypeID then
        return false
      end
      local view = w.OwenVehicleView
      if not view or not valid(view.Name) or not valid(view.Health) then
        return false
      end
      local pct = tonumber((_G.MWConfig or {}).ESPTextSize) or 100
      if pct ~= pct then
        pct = 100
      end
      local scale = 0.4 * math.max(0.5, math.min(2, pct / 100))
      if r.TextScale ~= scale then
        local vector = view.TextScaleVector vector.X, vector.Y = scale, scale view.Row:SetRenderScale(vector);
        view.Health:SetRenderScale(vector)
        local row = PlayerMapMarker.VehFont * scale + 4
        local slot = view.Health.Slot
        if slot and slot.SetPosition then
          slot:SetPosition(FVector2D(0, 2 + row))
        end
        r.TextScale = scale
      end
      return true
    end
    function N.RefreshTextSize()
      if not N.Active or not (_G.MWConfig or {}).EspVehicle then
        return
      end
      for _, r in pairs(N.Records) do
        if r.Wanted and r.Ready and r.Visible then
          pcall(N.ApplyTextSize, r)
        end
      end
    end
    function N.Style(r)
      local w = r.Widget;
      local c = _G.MWConfig
      if N.WidgetOwners[w] ~= r or not valid(w) or w.ID ~= N.TypeID then
        return false
      end
      local view = N.EnsureView(w);
      if not view then
        return false
      end
      local icon, nameText, healthText = view.Icon, view.Name, view.Health
      w.MaxShowDistance = N.MaxDistance
      local key = PlayerMapMarker.OwenVehicleIconKey(r.Item)
      if r.IconKey ~= key then
        local tex = _G.MWIconTexture(key);
        if not tex then
          return false
        end
        icon:SetBrushFromTexture(tex, false);
        r.IconKey = key
        if icon.SetBrushSize then
          local aspect = PlayerMapMarker.OwenVehicleIconAspect[key] or 1
          local size = FVector2D(0.5 * PlayerMapMarker.VehIconH * aspect, 0.5 * PlayerMapMarker.VehIconH)
          icon:SetBrushSize(size)
          if icon.Slot and icon.Slot.SetSize then
            icon.Slot:SetSize(size)
          end
        end
      end
      visibility(w.Image_BG, false);
      visibility(w.ImageBG_Distance, false);
      visibility(w.ImageBG_Time, false)
      w.TextBlock_Distance = nil
      local label = r.Item.name or ''
      local distanceText = ''
      if c.VehicleShowDistance ~= false and r.Distance then
        local meters = math.floor(r.Distance / 100 + 0.5)
        distanceText = meters < 1000 and meters .. 'm' or string.format('%.1fkm', meters / 1000)
      end
      local health = '';
      local vc = r.Item.act.VehicleCommon
      if not valid(vc) and r.Item.act.GetVehicleCommon then
        vc = r.Item.act:GetVehicleCommon()
      end
      if valid(vc) then
        local hp = vc.GetVehicleHP and vc:GetVehicleHP() or vc.Hp
        local mx = vc.GetVehicleHPMax and vc:GetVehicleHPMax() or vc.HPMax
        if type(hp) == 'number' and type(mx) == 'number' and hp > 0 and mx > 0 then
          health = math.floor(hp + 0.5) .. '/' .. math.floor(mx + 0.5)
        end
      end
      local displayName = label .. ((label ~= '' and distanceText ~= '') and ' ' or '')
      if r.Label ~= displayName then
        nameText:SetText(displayName);
        r.Label = displayName
      end
      if r.DistanceText ~= distanceText then
        view.Distance:SetText(distanceText);
        r.DistanceText = distanceText;
        r.TextScale = nil
      end
      if r.Health ~= health then
        healthText:SetText(health);
        r.Health = health
      end
      if not r.Layout then
        local function place(control, x, y, ax, ay)
          local slot = control.Slot
          if slot and slot.SetPosition and slot.SetAlignment then
            slot:SetAlignment(FVector2D(ax, ay));
            slot:SetPosition(FVector2D(x, y))
          end
        end
        place(icon, 0, - 2, 0.5, 1)
        place(view.Row, 0, 2, 0.5, 0)
        place(healthText, 0, PlayerMapMarker.VehFont + 6, 0.5, 0)
        r.Layout = true
      end
      local color = PlayerMapMarker.VehColors[r.Item.kind or r.Item.group or 'car'] or PlayerMapMarker.VehColors.car assert(color, 'native_vehicle_color_unavailable')
      if r.Color ~= color then
        local slate = PlayerMapMarker._SlateColorClass
        if slate == nil then
          slate = import('SlateColor');
          PlayerMapMarker._SlateColorClass = slate
        end
        local tint = slate and slate(color) or color
        if nameText.SetColorAndOpacity then
          nameText:SetColorAndOpacity(tint)
        end
        if view.Distance.SetColorAndOpacity then
          view.Distance:SetColorAndOpacity(slate and slate(distanceColor) or distanceColor)
        end
        if healthText.SetColorAndOpacity then
          healthText:SetColorAndOpacity(tint)
        end
        r.Color = color
      end
      if not N.ApplyTextSize(r) then
        return false
      end
      visibility(icon, c.VehicleShowIcon ~= false)
      visibility(view.Row, label ~= '' or distanceText ~= '')
      visibility(nameText, label ~= '')
      visibility(view.Distance, distanceText ~= '')
      visibility(healthText, health ~= '')
      return true
    end
    function N.Hide(r)
      if r.Visible and N.Tools then
        pcall(N.Tools.HideMapMark, r.ID)
      end
      if r.Widget and N.WidgetOwners[r.Widget] == r then
        if r.Widget.ID == N.TypeID then
          hideView(r.Widget);
          pcall(visibility, r.Widget, false)
        end
        N.WidgetOwners[r.Widget] = nil
      end
      r.Visible = false;
      resetStyle(r);
      r.Widget = nil
    end
    function N.Stop()
      if not N.Active then
        return
      end
      for _, r in pairs(N.Records) do
        N.Hide(r)
      end
      _G.OwenNativeMarkRouter.Remove(N.TypeID)
      N.Active = false;
      N.Manager = nil;
      N.Candidates = nil;
      N.FreeCandidates = nil;
      N.NextTick = 0;
      N.Status = 'off'
    end
    function N.Setup(pc)
      if N.Active then
        return true
      end
      if now() < N.NextSetup then
        return false
      end
      N.NextSetup = now() + 5
      local ok, err = pcall(function()
        N.Tools = require('GameLua.Mod.BaseMod.Common.InGameMarkTools')
        N.GameTools = require('GameLua.Mod.BaseMod.Common.GamePlayTools')
        N.Class = require('GameLua.Mod.BaseMod.Client.ScreenMarkUI.CommonActorScreenMarkUI')
        assert(type(N.Class.OnActorBindUI) == 'function' and type(N.Tools.ShowMapMark) == 'function')
        local cfg = N.GameTools.GetCurrentConfig('ScreenMarkConfig');
        assert(cfg)
        assert( not cfg[N.TypeID] or cfg[N.TypeID].OwenVehicleNative, 'native_type_collision')
        cfg[N.TypeID] = {
          OwenVehicleNative = true,
          UIPathName = '/Game/Mod/EvoBase/BluePrints/UI/ScreenMark/Item/CommonActorScreenMark_UIBP.CommonActorScreenMark_UIBP_C',
          MaxWidgetNum = N.Limit,
          MaxShowDistance = 100000,
          UpdateBindingInterval = 0.05,
          UpdateBindingIntervalMax = 0.1,
          bCollapseWhenFree = true,
          bBindOutScreen = false,
          bBindBlocked = true,
          bIsBindingActor = true,
          bNeedPreLoad = true,
          bNeedUpdateState = false,
          WorldPositionOffset = FVector(0, 0, PlayerMapMarker.VehZOff),
          CommonMarkConfig = { bDistance = false, bCountDownTime = false }
        }
        N.Config = cfg[N.TypeID]
        N.OnBind = function(self, actor, id)
          local r = N.Records[tostring(actor)]
          if not r or not r.Wanted or not N.Active then
            visibility(self, false);
            return
          end
          N.OnNativeSetup(self)
          local previous = N.WidgetOwners[self]
          if previous and previous ~= r then
            resetStyle(previous);
            previous.Widget = nil
          end
          if r.Widget and r.Widget ~= self and N.WidgetOwners[r.Widget] == r then
            visibility(r.Widget, false);
            N.WidgetOwners[r.Widget] = nil
          end
          r.Widget = self;
          N.WidgetOwners[self] = r;
          resetStyle(r)
          local applied, err = pcall(function()
            self:SetUpInfoInternal(id);
            assert(N.Style(r), 'native_widget_or_texture_unavailable')
          end)
          r.Ready = applied;
          r.Failed = not applied
          if applied then
            visibility(self, true);
            N.Status = 'native';
            N.LastError = nil
          end
          if not applied then
            visibility(self, false);
            N.Status = 'widget_fallback';
            N.LastError = tostring(err)
          end
        end
        N.OnUnbind = function(self, actor)
          local r = N.Records[tostring(actor)]
          if r and r.Widget == self and N.WidgetOwners[self] == r then
            N.OnNativeSetup(self);
            N.WidgetOwners[self] = nil;
            r.Widget = nil
          end
        end
        _G.OwenNativeMarkRouter.Add(N.TypeID, N)
        _G.OwenNativeMarkRouter.Prepare(pc, N.TypeID, N)
      end)
      if not ok then
        N.Active = true;
        N.Stop();
        N.Status = 'setup_fallback';
        N.LastError = tostring(err);
        return false
      end
      N.Active = true;
      N.Status = 'native';
      N.LastError = nil;
      return true
    end
    function N.Sync(pc)
      local c = _G.MWConfig
      if not c.EspVehicle then
        N.Stop();
        return
      end
      if now() < N.NextTick then
        return
      end
      if not N.Active and now() < N.NextSetup then
        return
      end
      N.NextTick = now() + N.Interval
      if not valid(pc) then
        N.Stop();
        return
      end
      local world = pc:GetWorld()
      if N.World and tostring(world) ~= N.World then
        N.Stop();
        N.Records = {};
        N.Count = 0;
        N.NextSetup = 0
      end
      N.World = tostring(world)
      if not N.Setup(pc) then
        return
      end
      N.MaxDistance = 100 * (tonumber(c.VehicleMaxDistance) or 400)
      for _, r in pairs(N.Records) do
        r.Wanted = false
      end
      local origin = PlayerMapMarker.GetMyLocation();
      local limit = N.MaxDistance
      if not origin then
        for _, r in pairs(N.Records) do
          N.Hide(r)
        end;
        return
      end
      N.Candidates = N.Candidates or {};
      N.FreeCandidates = N.FreeCandidates or {}
      local candidates, free = N.Candidates, N.FreeCandidates
      for i = # candidates, 1, - 1 do
        free[ # free + 1] = candidates[i];
        candidates[i] = nil
      end
      local width, height
      if PlayerMapMarker.ProjectWorldToCanvasLocal and PlayerMapMarker.GetDynamicViewportSize then
        width, height = PlayerMapMarker.GetDynamicViewportSize(pc)
      end
      for _, item in ipairs(_G.CachedVehicles or {}) do
        local actor = item.act;
        local group = item.group
        local selected = (group == 'car' and c.EspVeh_Car) or (group == 'moto' and c.EspVeh_Moto) or (group == 'offroad' and c.EspVeh_Offroad) or (group == 'boat' and c.EspVeh_Boat) or ((group ~= 'car' and group ~= 'moto' and group ~= 'offroad' and group ~= 'boat') and c.EspVeh_Heavy)
        if selected and valid(actor) then
          local loc = actor:K2_GetActorLocation();
          local distance = loc and PlayerMapMarker._Dist3D(origin, loc)
          local visible = true
          if width and height and width > 0 and height > 0 then
            local ok, result, pos = pcall(PlayerMapMarker.ProjectWorldToCanvasLocal, pc, loc)
            visible = ok and (result == true or result == 1) and pos and pos.X >= 0 and pos.X <= width and pos.Y >= 0 and pos.Y <= height
          end
          if distance and distance <= limit and visible and item.hasDriver ~= true and item.hasDriver ~= 1 and not actor.bHidden then
            local rank = # candidates + 1
            for i, v in ipairs(candidates) do
              if distance < v.Distance then
                rank = i;
                break
              end
            end
            if rank <= N.Limit then
              local record = table.remove(free) or {};
              record.Item = item;
              record.Location = loc;
              record.Distance = distance table.insert(candidates, rank, record)
              if # candidates > N.Limit then
                free[ # free + 1] = table.remove(candidates)
              end
            end
          end
        end
      end
      N.RecoveryBudget = 2
      for _, candidate in ipairs(candidates) do
        local item = candidate.Item
        local actor = item.act;
        local group = item.group
        local selected = (group == 'car' and c.EspVeh_Car) or (group == 'moto' and c.EspVeh_Moto) or (group == 'offroad' and c.EspVeh_Offroad) or (group == 'boat' and c.EspVeh_Boat) or ((group ~= 'car' and group ~= 'moto' and group ~= 'offroad' and group ~= 'boat') and c.EspVeh_Heavy)
        if selected and valid(actor) and not actor.bHidden and item.hasDriver ~= true and item.hasDriver ~= 1 then
          local loc = candidate.Location
          if loc and PlayerMapMarker._Dist3D(origin, loc) <= limit then
            local key = tostring(actor);
            local r = N.Records[key]
            if not r and N.Count < N.Limit then
              r = { Item = item, Wanted = true, Distance = candidate.Distance };
              N.Records[key] = r;
              N.Count = N.Count + 1
              local ok, id = pcall(N.Tools.ClientAddMapMark, N.TypeID, loc, 0, '', 4, actor)
              if ok and id and id ~= 0 and id ~= - 1 then
                r.ID = id;
                r.Visible = true;
                r.Started = now();
                if r.Failed then
                  N.Hide(r)
                end
              else
                r.Failed = true;
                N.Status = 'create_fallback'
              end
            end
            if r then
              r.Item = item;
              r.Wanted = true;
              r.Distance = candidate.Distance
              if r.ID and r.Failed and now() >= (r.NextRetry or 0) and (r.Attempts or 0) < 3 and N.RecoveryBudget > 0 then
                N.RecoveryBudget = N.RecoveryBudget - 1;
                r.Attempts = (r.Attempts or 0) + 1
                r.Failed = false;
                r.NextResolve = 0;
                r.Started = now();
                r.NextRetry = now() + 15
              end
              if r.ID and not r.Failed then
                if not r.Visible then
                  r.Visible = true;
                  r.Started = now();
                  pcall(N.Tools.ShowMapMark, r.ID)
                end
                _G.OwenNativeMarkRouter.Resolve(N, r)
                if r.Ready then
                  local ok, applied = pcall(N.Style, r)
                  if not ok or not applied then
                    r.Failed = true;
                    N.Hide(r);
                    N.Status = 'style_fallback'
                  end
                elseif now() - (r.Started or 0) > 3 then
                  r.Failed = true;
                  N.Hide(r);
                  N.Status = 'timeout_fallback';
                  N.LastError = N.LastError or 'native_bind_timeout'
                end
              end
            end
          end
        end
      end
      for _, r in pairs(N.Records) do
        if not r.Wanted then
          N.Hide(r)
        end
      end
    end
    function N.Handles(key)
      local r = N.Active and N.Records[key]
      return r and r.Wanted and r.Ready and r.Visible and not r.Failed or false
    end
  end
  do
    local N = {
      TypeID = 479902,
      Records = {},
      ByKey = {},
      Count = 0,
      Limit = 20,
      NextSetup = 0,
      Status = 'idle'
    }
    _G.OwenNativePlayerMarks = N
    local contentKeys = { 'Name', 'Bot', 'Weapon', 'Flag' }
    local botWords = { 'PLAYER', 'NGƯỜI', '玩家' }
    local nativeChildren = { 'Image_Icon', 'Image_BG', 'ImageBG_Distance', 'Text_Distance', 'ImageBG_Time',
    'TextBlock_Time' }
    local function now()
      return _G.RealNow and _G.RealNow() or os.clock()
    end
    local function valid(v)
      return v ~= nil and slua.isValid(v)
    end
    local function on(v)
      return v == true or v == 1
    end
    local function enabled()
      local c = _G.MWConfig
      return on(c.EspPlayer) and on(c.PlayerNativeMarkers) and (on(c.EspPlayerName) or on(c.EspPlayerBotLabel) or on(c.EspPlayerWeapon) or on(c.EspNationFlag))
    end
    local function hide(w)
      if valid(w) then
        w:SetWidgetVisibility(UEnums.ESlateVisibility.Collapsed)
      end
    end
    function N.ClearContent(r)
      for _, key in ipairs(contentKeys) do
        local item = r[key]
        if item then
          if item.w then
            if PlayerMapMarker._ProtectedWidgetStrs then
              PlayerMapMarker._ProtectedWidgetStrs[tostring(item.w)] = nil
            end
            if valid(item.w) then
              pcall(item.w.RemoveFromParent, item.w)
            end
          end
          r[key] = nil
        end
      end
      if valid(r.Canvas) then
        pcall(r.Canvas.RemoveFromParent, r.Canvas)
      end
      r.Canvas = nil;
      r.SharedRoot = nil;
      r.Widget = nil;
      r.Ready = false;
      r.WeaponID = nil;
      r.WeaponOK = nil;
      r.Nation = nil;
      r.NextWeapon = 0;
      r.NextFlag = 0
    end
    function N.HideContent(r)
      for _, key in ipairs(contentKeys) do
        if r[key] then
          PlayerMapMarker._LabelSet(r[key], false)
        end
      end
      r.Widget = nil;
      r.Ready = false;
      r.HeaderHeight = 0;
      r.FooterHeight = 0
    end
    function N.Hide(r)
      if r.Visible and N.Tools then
        pcall(N.Tools.HideMapMark, r.ID)
      end
      r.OnScreen = false;
      r.Visible = false;
      N.HideContent(r)
    end
    function N.HideKey(key)
      local r = N.ByKey[key]
      if r then
        N.Hide(r)
      end
    end
    function N.Stop()
      N.Running = false;
      N.Controller = nil;
      N.Manager = nil
      if not N.Active then
        return
      end
      for _, r in pairs(N.Records) do
        N.Hide(r);
        N.ClearContent(r)
      end
      _G.OwenNativeMarkRouter.Remove(N.TypeID);
      N.Active = false;
      N.Status = 'off'
    end
    function N.Style(r)
      local c = _G.MWConfig;
      local p = PlayerMapMarker;
      local ch = r.Actor;
      local data = r.Data or {}
      if r.OnScreen == false or not N.Running or not enabled() then
        N.HideContent(r);
        return false
      end
      if not valid(r.Canvas) then
        return false
      end
      local scale = math.max(0.5, math.min(2, (tonumber(c.ESPTextSize) or 100) / 100))
      local ts = r.Scale or 1;
      local x = r.X or 0;
      local top = r.Top or 0;
      local gap = p.LabelGap or 4
      local y = (r.Bottom or 0) + gap;
      local line = (p.LabelFontName + 5) * scale * ts
      local known, bot = false, (data.IsBot == true or data.IsBot == 1)
      if on(c.EspPlayerBotLabel) then
        bot, known = p.IsAI(ch)
      end
      local lang = tonumber(c.MenuLanguage) or 1
      if on(c.EspPlayerName) then
        p._LabelText(r.Name, data.Name or 'Unknown')
        p._LabelColor(r.Name, ch.HealthStatus == 1 and p.KnockColor or (bot and p.LabelColorBot or p.LabelColorPlayer))
        p._LabelSet(r.Name, true, x, y, ts);
        y = y + line
      else
        p._LabelSet(r.Name, false)
      end
      if on(c.EspPlayerBotLabel) and known then
        p._LabelText(r.Bot, bot and 'BOT' or (botWords[lang] or botWords[1]));
        p._LabelSet(r.Bot, true, x, y, ts);
        y = y + line
      else
        p._LabelSet(r.Bot, false)
      end
      r.FooterHeight = y - ((r.Bottom or 0) + gap)
      local header = 0
      if on(c.EspPlayerWeapon) then
        if now() >= (r.NextWeapon or 0) then
          r.NextWeapon = now() + 0.5
          local info = p.GetCharacterWeaponInfo(ch);
          local id = info and tonumber(info.WeaponID) or 0
          if r.WeaponID ~= id or not r.WeaponOK then
            if id > 0 then
              r.WeaponOK = p.ApplyWeaponIconToImage(r.Weapon.w, info) == true
            else
              local util = require('client.slua_ui_framework.util')
              r.WeaponOK = util.SetTexture(r.Weapon.w, p.FistIconPath, { sync = true, bMatchSize = false }) ~= nil
            end
            if r.WeaponOK then
              r.WeaponID = id
            end
          end
        end
        if r.WeaponOK then
          p._LabelSet(r.Weapon, true, x + p.WpnIconW * ts / 2, top - gap - (p.WeaponHeadGap or 12) * ts, ts);
          header = p.WpnIconH + (p.WeaponHeadGap or 12)
        else
          p._LabelSet(r.Weapon, false)
        end
      else
        p._LabelSet(r.Weapon, false)
      end
      if on(c.EspNationFlag) then
        if now() >= (r.NextFlag or 0) then
          r.NextFlag = now() + 2
          local ps = ch.PlayerState or (ch.GetPlayerStateSafety and ch:GetPlayerStateSafety())
          local nation = tostring((ps and ps.Nation) or ch.Nation or 'G1');
          if nation == '' or nation == '0' then
            nation = 'G1'
          end
          if r.Nation ~= nation then
            local row = CDataTable.GetTableData('RegionConfig', nation) or CDataTable.GetTableData('RegionConfig', 'G1')
            local path = (row and row.res_path) or '/Game/UMG/Texture/Atlas/NationalflagUI/Frames/T_icon_flag_iland_png.T_icon_flag_iland_png'
            if path and path ~= '' then
              local loaded
              if r.Flag.w.SetBrushFromPathAsync then
                loaded = r.Flag.w:SetBrushFromPathAsync(path, false)
              else
                loaded = require('client.slua_ui_framework.util').SetTexture(r.Flag.w, path, { sync = false,
                bMatchSize = false })
              end
              if loaded ~= false then
                r.Nation = nation
              end
            end
          end
        end
        if r.Nation then
          p._LabelSet(r.Flag, true, x, top - gap - header * ts - gap - 20 * ts, ts)
        else
          p._LabelSet(r.Flag, false)
        end
      else
        p._LabelSet(r.Flag, false)
      end
      if r.Widget then
        r.Widget.MaxShowDistance = 100 * (tonumber(c.EspMaxDistance) or 400)
      end
      r.HeaderHeight = header * ts
      return true
    end
    function N.HeaderHeight(actor)
      local r = N.Records[tostring(actor)]
      return r and r.HeaderHeight or 0
    end
    function N.GetFooterHeight(actor)
      local r = N.Records[tostring(actor)]
      return r and r.FooterHeight or 0
    end
    function N.OnBind(w, actor, id)
      local r = N.Records[tostring(actor)]
      if not r or r.OnScreen == false or not N.Running or not enabled() then
        hide(w);
        return
      end
      r.Widget = w;
      w.ID = id
      local ok, err = pcall(function()
        w:SetUpInfoInternal(id);
        w.TextBlock_Distance = nil
        for _, key in ipairs(nativeChildren) do
          hide(w[key])
        end
        local root = PlayerMapMarker.ESPCanvas assert(valid(root) and root.AddChildToCanvas, 'shared_esp_canvas_unavailable')
        local reusable = r.SharedRoot == root and valid(r.Canvas)
        for _, key in ipairs(contentKeys) do
          local item = r[key];
          reusable = reusable and item ~= nil and valid(item.w) and item.slot ~= nil
        end
        if not reusable then
          N.ClearContent(r);
          r.Widget = w;
          r.SharedRoot = root
          r.Canvas = CGame:NewObjectFromPath('/Script/UMG.CanvasPanel', root);
          assert(valid(r.Canvas))
          local slot = root:AddChildToCanvas(r.Canvas);
          assert(slot)
          slot:SetSize(FVector2D(0, 0));
          slot:SetAlignment(FVector2D(0, 0))
          local pos = FVector2D(0, 0)
          slot:SetPosition(pos);
          slot:SetZOrder(10)
          r.Name = PlayerMapMarker._NewLabelText(r.Canvas, PlayerMapMarker.LabelFontName, PlayerMapMarker.LabelColorPlayer, 0.5, 0)
          r.Bot = PlayerMapMarker._NewLabelText(r.Canvas, PlayerMapMarker.LabelFontName, PlayerMapMarker.LabelColorBot, 0.5, 0)
          r.Weapon = PlayerMapMarker._NewWeaponIcon(r.Canvas, 4);
          r.Flag = PlayerMapMarker._NewWeaponIcon(r.Canvas, 4)
          assert(r.Name and r.Name.slot and r.Bot and r.Bot.slot and r.Weapon and r.Weapon.slot and r.Flag and r.Flag.slot, 'native_content_missing')
          r.Flag.slot:SetSize(FVector2D(30, 20));
          r.Flag.slot:SetAlignment(FVector2D(0.5, 1))
        end
        r.NextWeapon = 0;
        r.NextFlag = 0 assert(N.Style(r))
      end)
      r.Ready = ok;
      r.Failed = not ok
      if ok then
        N.Status = 'native';
        N.LastError = nil
      end
      if not ok then
        N.ClearContent(r);
        hide(w);
        N.Status = 'widget_fallback';
        N.LastError = tostring(err)
      end
    end
    function N.OnUnbind(w, actor)
      local r = N.Records[tostring(actor)];
      if r and r.Widget == w then
        N.HideContent(r)
      end
    end
    function N.Setup(pc)
      if N.Active then
        return true
      end
      if now() < N.NextSetup then
        return false
      end
      N.NextSetup = now() + 5
      local ok, err = pcall(function()
        N.Tools = require('GameLua.Mod.BaseMod.Common.InGameMarkTools')
        local cfg = require('GameLua.Mod.BaseMod.Common.GamePlayTools').GetCurrentConfig('ScreenMarkConfig');
        assert(cfg)
        assert( not cfg[N.TypeID] or cfg[N.TypeID].OwenPlayerNative, 'native_type_collision')
        cfg[N.TypeID] = {
          OwenPlayerNative = true,
          UIPathName = '/Game/Mod/EvoBase/BluePrints/UI/ScreenMark/Item/CommonActorScreenMark_UIBP.CommonActorScreenMark_UIBP_C',
          MaxWidgetNum = N.Limit,
          MaxShowDistance = 100000,
          bBindOutScreen = false,
          bBindBlocked = true,
          bIsBindingActor = true,
          BindSocketName = 'head',
          WorldPositionOffset = FVector(0, 0, 0),
          UpdateBindingInterval = 0.05,
          UpdateBindingIntervalMax = 0.1,
          bCollapseWhenFree = true,
          bNeedPreLoad = true,
          bNeedUpdateState = false,
          CommonMarkConfig = { bDistance = false, bCountDownTime = false }
        }
        _G.OwenNativeMarkRouter.Add(N.TypeID, N)
        _G.OwenNativeMarkRouter.Prepare(pc, N.TypeID, N)
      end)
      if not ok then
        _G.OwenNativeMarkRouter.Remove(N.TypeID);
        N.Status = 'setup_fallback';
        N.LastError = tostring(err);
        return false
      end
      N.Active = true;
      N.Status = 'native';
      return true
    end
    function N.Tick(pc, inMatch)
      if not inMatch or not enabled() or not valid(pc) then
        N.Stop();
        return
      end
      N.CreateBudget = 2
      if now() < (N.NextCleanup or 0) then
        N.Running = true;
        return
      end
      local world = tostring(pc:GetWorld())
      if N.World and N.World ~= world then
        N.Stop();
        N.Records = {};
        N.ByKey = {};
        N.Count = 0;
        N.NextSetup = 0
      end
      N.World = world;
      N.Controller = pc;
      N.Running = true
      N.NextCleanup = now() + 0.2
      for _, r in pairs(N.Records) do
        if not valid(r.Actor) then
          N.Hide(r);
          N.ClearContent(r)
        elseif r.Visible and now() - (r.Seen or 0) > 0.3 then
          N.Hide(r)
        end
      end
    end
    function N.Touch(key, actor, data, x, top, bottom, scale)
      if not N.Running or not enabled() or not valid(actor) then
        return false
      end
      if not N.Setup(N.Controller) then
        return false
      end
      local actorKey = tostring(actor);
      local r = N.Records[actorKey]
      if not r then
        if N.Count >= N.Limit or (N.CreateBudget or 0) <= 0 then
          return false
        end
        N.CreateBudget = N.CreateBudget - 1
        r = { Actor = actor, Data = data, Seen = now(), X = x, Top = top, Bottom = bottom, Scale = scale,
        OnScreen = true };
        N.Records[actorKey] = r;
        N.ByKey[key] = r;
        N.Count = N.Count + 1
        local ok, id = pcall(N.Tools.ClientAddMapMark, N.TypeID, actor:K2_GetActorLocation(), 0, '', 4, actor)
        if ok and id and id ~= 0 and id ~= - 1 then
          r.ID = id;
          r.Visible = true;
          r.Started = now();
          if r.Failed then
            N.Hide(r)
          end
        else
          r.Failed = true;
          N.Status = 'create_fallback'
        end
      end
      N.ByKey[key] = r;
      r.OnScreen = true
      r.Seen = now();
      r.Data = data;
      r.X = x or r.X;
      r.Top = top or r.Top;
      r.Bottom = bottom or r.Bottom;
      r.Scale = scale or r.Scale
      if r.Failed then
        return false
      end
      if not r.Visible then
        r.Visible = true;
        r.Started = now();
        pcall(N.Tools.ShowMapMark, r.ID)
      end
      _G.OwenNativeMarkRouter.Resolve(N, r)
      if r.Ready then
        r.NextStyle = now() + 0.1;
        local ok, result = pcall(N.Style, r)
        if not ok or not result then
          r.Failed = true;
          N.LastError = tostring(result);
          N.Status = 'style_fallback';
          N.Hide(r)
        end
      elseif not r.Ready and now() - (r.Started or 0) > 3 then
        r.Failed = true;
        N.Hide(r);
        N.Status = 'timeout_fallback';
        N.LastError = N.LastError or 'native_bind_timeout'
      end
      return r.Ready and r.Visible and not r.Failed
    end
  end
  function _G.VehMark_Tick(pc)
    for key in pairs(PlayerMapMarker.VehMarks) do
      PlayerMapMarker.RemoveVehMark(key)
    end
    local native = _G.OwenNativeVehicleMarks
    if native then
      local ok, err = pcall(native.Sync, pc)
      if not ok then
        native.Stop();
        native.NextSetup = (_G.RealNow and _G.RealNow() or os.clock()) + 5;
        native.Status = "sync_failed";
        native.LastError = tostring(err)
      end
    end
  end
  function PlayerMapMarker.HideBox(KeyStr)
    local current = PlayerMapMarker.BoxLines[KeyStr];
    if current and current.Bounds then
      if PlayerMapMarker.DisplayedBoxes then
        PlayerMapMarker.DisplayedBoxes[current.Bounds.Character] = nil
      end;
      current.Bounds = nil
    end
    local box = PlayerMapMarker.BoxLines[KeyStr]
    if box then
      for i = 1, # box do
        DrawLine.Hide(box[i])
      end
    end
    PlayerMapMarker.HideLabels(KeyStr)
    PlayerMapMarker.HideSkel(KeyStr)
  end
  function PlayerMapMarker.RemoveBox(KeyStr)
    local current = PlayerMapMarker.BoxLines[KeyStr]
    if current and current.Bounds and PlayerMapMarker.DisplayedBoxes then
      PlayerMapMarker.DisplayedBoxes[current.Bounds.Character] = nil
    end
    local box = PlayerMapMarker.BoxLines[KeyStr]
    if box then
      for i = 1, # box do
        DrawLine.Remove(box[i])
      end
      PlayerMapMarker.BoxLines[KeyStr] = nil
    end
    PlayerMapMarker.RemoveSkel(KeyStr)
  end
  function PlayerMapMarker.ClearAllBoxes()
    for KeyStr, box in pairs(PlayerMapMarker.BoxLines) do
      for i = 1, # box do
        DrawLine.Remove(box[i])
      end
    end
    PlayerMapMarker.BoxLines = {} PlayerMapMarker.DisplayedBoxes = setmetatable( {}, { __mode = "k" })
    PlayerMapMarker.ClearAllSkel()
  end
  function PlayerMapMarker._BoxBody(KeyStr, Character, PC, hx, hy, sc, ESPData)
    local feet = PlayerMapMarker.GetCharacterLocation(Character)
    if not feet then
      PlayerMapMarker.HideBox(KeyStr)
      return
    end
    local hh = 90
    local cap = Character.CapsuleComponent
    if cap and slua.isValid(cap) and cap.GetScaledCapsuleHalfHeight then
      hh = cap:GetScaledCapsuleHalfHeight() or 90
    end
    feet.Z = feet.Z - hh
    local okF, fx, fy = PlayerMapMarker.ProjectWorldToCanvasLocalRaw(PC, feet)
    if not okF then
      PlayerMapMarker.HideBox(KeyStr)
      return
    end
    local h = fy - hy
    if h < 6 then
      h = 6
    end
    if h > (PlayerMapMarker._VpPxH or 1080) * 2 then
      PlayerMapMarker.HideBox(KeyStr)
      return
    end
    local ratio = PlayerMapMarker.BoxRatioStand
    if Character.IsProne and Character:IsProne() then
      ratio = PlayerMapMarker.BoxRatioProne
    elseif Character.bIsCrouched then
      ratio = PlayerMapMarker.BoxRatioCrouch
    end
    local w = h * ratio
    local cx = (hx + fx) * 0.5
    local x1, x2 = cx - w * 0.5, cx + w * 0.5
    local box = PlayerMapMarker.BoxLines[KeyStr]
    if not box then
      box = {}
      for i = 1, PlayerMapMarker.BoxSegs do
        box[i] = DrawLine.Create(3)
      end
      PlayerMapMarker.BoxLines[KeyStr] = box
    end
    local y1, y2 = hy, fy
    local bounds = box.Bounds or {};
    box.Bounds = bounds
    PlayerMapMarker.DisplayedBoxes = PlayerMapMarker.DisplayedBoxes or setmetatable( {}, { __mode = "k" })
    PlayerMapMarker.DisplayedBoxes[Character] = bounds bounds.X1, bounds.Y1, bounds.X2, bounds.Y2 = x1, y1, x2, y2;
    bounds.Character = Character;
    bounds.Time = _G.RealNow();
    bounds.PC = PC;
    bounds.Canvas = PlayerMapMarker.ESPCanvas;
    bounds.Width = PlayerMapMarker._VpPxW;
    bounds.Height = PlayerMapMarker._VpPxH;
    bounds.Visible = false
    if _G.MWConfig.EspPlayerBox then
      local c, t = PlayerMapMarker.BoxColor, PlayerMapMarker.BoxThickness
      if Character.HealthStatus == 1 then
        c = PlayerMapMarker.BoxColorKnock
      end
      local L = math.min(w, h) * (PlayerMapMarker.BoxCornerFrac or 0.3)
      if L < 3 then
        L = 3
      end
      DrawLine.Update(box[1], x1, y1, x1 + L, y1, c, t)
      DrawLine.Update(box[2], x1, y1, x1, y1 + L, c, t)
      DrawLine.Update(box[3], x2 - L, y1, x2, y1, c, t)
      DrawLine.Update(box[4], x2, y1, x2, y1 + L, c, t)
      DrawLine.Update(box[5], x1, y2, x1 + L, y2, c, t)
      DrawLine.Update(box[6], x1, y2 - L, x1, y2, c, t)
      DrawLine.Update(box[7], x2 - L, y2, x2, y2, c, t)
      DrawLine.Update(box[8], x2, y2 - L, x2, y2, c, t)
      bounds.Visible = true
    else
      for i = 1, 8 do
        DrawLine.Hide(box[i])
      end
    end
    if _G.MWConfig.EspPlayerHP and Character.HealthStatus ~= 1 then
      local pct = 1
      local hp, mhp = Character.Health, (Character.HealthMax or Character.MaxHealth)
      if type(hp) == "number" and type(mhp) == "number" and mhp > 0 then
        pct = hp / mhp
      end
      if pct < 0 then
        pct = 0
      elseif pct > 1 then
        pct = 1
      end
      local bw = h * 0.06
      if bw < PlayerMapMarker.HPBarWidthMin then
        bw = PlayerMapMarker.HPBarWidthMin
      elseif bw > PlayerMapMarker.HPBarWidthMax then
        bw = PlayerMapMarker.HPBarWidthMax
      end
      local bx = x1 - (PlayerMapMarker.HPBarGap or 3) - bw * 0.5 DrawLine.Update(box[9], bx, y2, bx, y1, PlayerMapMarker.HPBarBgColor, bw)
      local fillTop = y2 - h * pct
      local hc
      if pct > 0.7 then
        hc = PlayerMapMarker.HPBarColorHigh
      elseif pct > 0.5 then
        hc = PlayerMapMarker.HPBarColorMidHi
      elseif pct > 0.25 then
        hc = PlayerMapMarker.HPBarColorMid
      else
        hc = PlayerMapMarker.HPBarColorLow
      end
      if pct > 0.001 then
        DrawLine.Update(box[10], bx, y2, bx, fillTop, hc, bw)
      else
        DrawLine.Hide(box[10])
      end
    else
      DrawLine.Hide(box[9]);
      DrawLine.Hide(box[10])
    end
    if _G.MWConfig.EspPlayerHPHorizontal then
      local hp, maxHP = Character.Health, Character.HealthMax or Character.MaxHealth
      if Character.HealthStatus == 1 then
        hp, maxHP = Character.NearDeathBreath, Character.NearDeathBreathMax
      end
      local pct = type(hp) == 'number' and type(maxHP) == 'number' and maxHP > 0 and math.max(0, math.min(1, hp / maxHP)) or 0
      if not box[11] then
        box[11] = DrawLine.Create(3);
        box[12] = DrawLine.Create(3)
      end
      local bw = math.max(46, math.min(90, w * 1.15));
      local bx = cx - bw * .5;
      local by = y1 - 10 DrawLine.Update(box[11], bx - 1.5, by, bx + bw + 1.5, by, PlayerMapMarker.HPBarBgColor, 6)
      local color = pct > .5 and PlayerMapMarker.HPBarColorHigh or (pct > .25 and PlayerMapMarker.HPBarColorMid or PlayerMapMarker.HPBarColorLow)
      if pct > 0 then
        DrawLine.Update(box[12], bx, by, bx + bw * pct, by, color, 3.5)
      else
        DrawLine.Hide(box[12])
      end
    elseif box[11] then
      DrawLine.Hide(box[11]);
      DrawLine.Hide(box[12])
    end
    pcall(PlayerMapMarker._LabelsBody, KeyStr, Character, ESPData, cx, y1, y2, sc or (PlayerMapMarker.ESPBaseScale or 0.9))
    if _G.MWConfig.EspPlayerSkeleton then
      pcall(PlayerMapMarker._SkelBody, KeyStr, Character, PC)
    else
      PlayerMapMarker.HideSkel(KeyStr)
    end
  end
  function PlayerMapMarker.UpdateBox(KeyStr, Character, PC, CanvasPos, bOnScreen, sc, ESPData)
    local c = _G.MWConfig
    if not (c.EspPlayerBox or c.EspPlayerHP or c.EspPlayerHPHorizontal or c.EspPlayerName or c.EspPlayerDistance or c.EspPlayerWeapon or c.EspPlayerSkeleton or c.EspPlayerBotLabel or c.EspShowState or c.EspNationFlag) then
      if PlayerMapMarker.BoxLines[KeyStr] then
        PlayerMapMarker.RemoveBox(KeyStr)
      end
      PlayerMapMarker.HideLabels(KeyStr)
      return
    end
    if ESPData and ESPData._DistCm and ESPData._DistCm > 100 * (tonumber(c.EspMaxDistance) or 400) then
      PlayerMapMarker.HideBox(KeyStr);
      return
    end
    if not bOnScreen or not CanvasPos then
      PlayerMapMarker.HideBox(KeyStr)
      return
    end
    pcall(PlayerMapMarker._BoxBody, KeyStr, Character, PC, CanvasPos.X, CanvasPos.Y, sc, ESPData)
  end
  function PlayerMapMarker.ScreenPixelToCanvasLocalRaw(PC, screenX, screenY)
    local scaleX = PlayerMapMarker._CanvasScaleX or 1.0
    local scaleY = PlayerMapMarker._CanvasScaleY or 1.0
    local offsetX = PlayerMapMarker._CanvasOffsetX or 0
    local offsetY = PlayerMapMarker._CanvasOffsetY or 0
    return screenX * scaleX + offsetX, screenY * scaleY + offsetY
  end
  function PlayerMapMarker._ProjSane(x, y)
    local W = PlayerMapMarker._VpPxW or 1920
    local H = PlayerMapMarker._VpPxH or 1080
    if x ~= x or y ~= y then
      return false
    end
    if x < - W or x > W * 2 or y < - H or y > H * 2 then
      return false
    end
    return true
  end
  function PlayerMapMarker.ProjectWorldToCanvasLocalRaw(PC, WorldLoc)
    if not IsValid(PC) or not WorldLoc then
      return false, 0, 0
    end
    if not PlayerMapMarker._tempScreenPixelPos then
      PlayerMapMarker._tempScreenPixelPos = FVector2D and FVector2D(0, 0) or { X = 0, Y = 0 }
    end
    local tempPos = PlayerMapMarker._tempScreenPixelPos
    local okProj, res = pcall(PC.ProjectWorldLocationToScreen, PC, WorldLoc, tempPos, true)
    local bOK = okProj and (res == true or res == 1)
    if not bOK or (tempPos.X == 0 and tempPos.Y == 0) then
      return false, 0, 0
    end
    if not PlayerMapMarker._ProjSane(tempPos.X, tempPos.Y) then
      return false, 0, 0
    end
    local canvasX, canvasY = PlayerMapMarker.ScreenPixelToCanvasLocalRaw(PC, tempPos.X, tempPos.Y)
    return true, canvasX, canvasY
  end
  function PlayerMapMarker.ClearAllESP()
    if PlayerMapMarker.VisibilityBudget then
      PlayerMapMarker.VisibilityBudget.Reset()
    end
    PlayerMapMarker.CharacterSnapshot = nil
    PlayerMapMarker._AICache = {} PlayerMapMarker._DeadKeys = nil
    PlayerMapMarker._DeadLatch = setmetatable( {}, { __mode = 'k' })
    PlayerMapMarker._DeadProbe = setmetatable( {}, { __mode = 'k' })
    PlayerMapMarker._LatchRecheck = setmetatable( {}, { __mode = 'k' })
    PlayerMapMarker._AliveSince = setmetatable( {}, { __mode = 'k' })
    RedBoxOverlay.Stop()
    for KeyStr, Data in pairs(PlayerMapMarker.ESPWidgets) do
      PlayerMapMarker.RemoveESPWidget(Data.Widget, KeyStr)
    end
    PlayerMapMarker.ESPWidgets = {} PlayerMapMarker.ESPWidgetPtrs = {} PlayerMapMarker.ClearAllSnapLines()
    PlayerMapMarker.ClearAllBoxes()
    PlayerMapMarker.ClearAllLabels()
    PlayerMapMarker.ClearAllPins()
    PlayerMapMarker.ClearAllVehMarks()
    if _G.ItemLabels then
      pcall(_G.ItemLabels.Clear)
    end
    if PlayerMapMarker.ESPCanvas and Game:IsValid(PlayerMapMarker.ESPCanvas) then
      pcall(function()
        local n = PlayerMapMarker.ESPCanvas:GetChildrenCount()
        for i = n - 1, 0, - 1 do
          local child = PlayerMapMarker.ESPCanvas:GetChildAt(i)
          if child and slua.isValid(child) then
            if PlayerMapMarker.IsOurESPWidget(child) then
              PlayerMapMarker.ESPCanvas:RemoveChild(child)
            end
          end
        end
      end)
    end
    PlayerMapMarker.ESPCanvas = nil
    PlayerMapMarker._CanvasXformTime = nil
    PlayerMapMarker._SnapFromTime = nil
    PlayerMapMarker._OBHeadWidgetClass = nil
    PlayerMapMarker._OBHeadWidgetLoadFailed = false
    PlayerMapMarker._bDumpedWidgetChildren = false
    PlayerMapMarker._cachedViewportW = 1920
    PlayerMapMarker._cachedViewportH = 1080
  end
  function PlayerMapMarker.UpdateESP(AllPlayers, MyLoc)
    if not PlayerMapMarker.bUseScreenESP then
      return
    end
    PlayerMapMarker.bUseSnapLines = _G.MWConfig.EspPlayerLine
    if not PlayerMapMarker.InitESPCanvas() then
      return
    end
    if PlayerMapMarker._OBHeadWidgetLoadFailed then
      return
    end
    local PC = PlayerMapMarker.GetMyPlayerController()
    if IsValid(PC) then
      PlayerMapMarker.UpdateCanvasTransform(PC)
    end
    local fromX, fromY = 0, 0
    if PlayerMapMarker.bUseSnapLines and IsValid(PC) then
      fromX, fromY = PlayerMapMarker.GetSnapLineStartPos(PC)
    end
    local MyKey = PlayerMapMarker.GetMyPlayerKey()
    local SeenKeys = {}
    local MyChar = nil pcall(function()
      local GDP = PlayerMapMarker.GetGameplayData()
      if GDP and GDP.GetLocalCharacter then
        MyChar = GDP.GetLocalCharacter()
      else
        if PC and PC.GetPawn then
          MyChar = PC:GetPawn()
        end
      end
    end)
    local MyTeamID = PlayerMapMarker.GetTeamID(MyChar)
    PlayerMapMarker._ShowAnyUI = PlayerMapMarker._ShowAnyUINow()
    for PlayerKey, Character in pairs(AllPlayers) do
      if IsValid(Character) then
        local bIsMe = PlayerMapMarker.IsMe(Character, PlayerKey, MyKey)
        local bIsAI, botKnown = PlayerMapMarker.IsAI(Character, PlayerKey)
        local KeyStr = tostring(PlayerKey)
        local Name = PlayerMapMarker.GetPlayerName(Character)
        local Loc = PlayerMapMarker.GetESPLocation(Character)
        local DistStr = ""
        if MyLoc and Loc then
          DistStr = PlayerMapMarker.GetDistanceString(MyLoc, Loc)
        end
        local bSkip = false
        if bIsMe and not PlayerMapMarker.bIncludeMe then
          bSkip = true
        end
        if bIsAI and not PlayerMapMarker.bIncludeAI then
          bSkip = true
        end
        local TeamID = PlayerMapMarker.GetTeamID(Character)
        if MyTeamID ~= nil and TeamID == MyTeamID and not bIsMe then
          bSkip = true
        end
        local bIsAlive = PlayerMapMarker.IsAlive(Character)
        if not bIsAlive then
          bSkip = true
          PlayerMapMarker._DeadKeys = PlayerMapMarker._DeadKeys or {}
          if KeyStr then
            PlayerMapMarker._DeadKeys[KeyStr] = true
          end
        end
        if not bSkip and Loc and ( not MyLoc or PlayerMapMarker._Dist3D(MyLoc, Loc) <= 100 * (tonumber(_G.MWConfig.EspMaxDistance) or 400)) then
          SeenKeys[KeyStr] = true
          local ESPData = PlayerMapMarker.ESPWidgets[KeyStr]
          local Text = ""
          if _G.MWConfig.EspPlayerName then
            Text = Name
          end
          if _G.MWConfig.EspPlayerDistance and DistStr and DistStr ~= "" then
            if Text ~= "" then
              Text = string.format("%s [%s]", Text, DistStr)
            else
              Text = string.format("[%s]", DistStr)
            end
          end
          local bOnScreen, CanvasPos = PlayerMapMarker.ProjectWorldToCanvasLocal(PC, Loc)
          if not ESPData then
            local Widget = PlayerMapMarker.CreateESPWidget()
            if Widget then
              if MyLoc then
                Widget._WantScale = PlayerMapMarker._ScaleForDist(PlayerMapMarker._Dist3D(MyLoc, Loc))
              end
              PlayerMapMarker.ESPWidgets[KeyStr] = { Widget = Widget, Character = Character, Name = Name,
              LastDistStr = DistStr, TeamID = TeamID, IsBot = bIsAI, BotKnown = botKnown, }
              PlayerMapMarker.UpdateESPText(Widget, Text)
              if bIsAlive then
                PlayerMapMarker.UpdateESPPositionWithPC(Widget, Loc, PC, CanvasPos)
                PlayerMapMarker.ApplyTeamColor(Widget, TeamID)
                local HP = Character.Health or 0
                local MaxHP = Character.MaxHealth or 120
                local pct = 0
                if HP > 0 and MaxHP > 0 then
                  pct = HP / MaxHP
                  if pct > 1 then
                    pct = 1
                  end
                  if pct < 0 then
                    pct = 0
                  end
                end
                PlayerMapMarker.UpdateESPHealth(Widget, pct)
                PlayerMapMarker.AddWeaponIconToESP(Widget, Character)
                if PlayerMapMarker.bUseSnapLines then
                  PlayerMapMarker.UpdateSnapLine(KeyStr, CanvasPos, bOnScreen, fromX, fromY, bIsAI, PC, Character)
                else
                  PlayerMapMarker.RemoveSnapLine(KeyStr)
                end
              else
                local Container = Widget.Container or Widget pcall(PlayerMapMarker._SetContainerVis, Widget, Container, UEnums.ESlateVisibility.Collapsed)
                PlayerMapMarker.UpdateESPHealth(Widget, 0)
                PlayerMapMarker.RemoveSnapLine(KeyStr)
              end
            end
          else
            ESPData.Character = Character
            ESPData.Name = Name
            ESPData.LastDistStr = DistStr
            ESPData.IsBot = bIsAI
            ESPData.BotKnown = botKnown
            if bIsAlive then
              ESPData.TeamID = TeamID PlayerMapMarker.ApplyTeamColor(ESPData.Widget, TeamID)
              PlayerMapMarker.UpdateESPText(ESPData.Widget, Text)
              PlayerMapMarker.UpdateESPPositionWithPC(ESPData.Widget, Loc, PC, CanvasPos)
              local HP = Character.Health or 0
              local MaxHP = Character.MaxHealth or 120
              local pct = 0
              if HP > 0 and MaxHP > 0 then
                pct = HP / MaxHP
                if pct > 1 then
                  pct = 1
                end
                if pct < 0 then
                  pct = 0
                end
              end
              PlayerMapMarker.UpdateESPHealth(ESPData.Widget, pct)
              PlayerMapMarker.AddWeaponIconToESP(ESPData.Widget, Character)
              if PlayerMapMarker.bUseSnapLines then
                PlayerMapMarker.UpdateSnapLine(KeyStr, CanvasPos, bOnScreen, fromX, fromY, bIsAI, PC, Character)
              else
                PlayerMapMarker.RemoveSnapLine(KeyStr)
              end
            else
              local Container = ESPData.Widget.Container or ESPData.Widget pcall(PlayerMapMarker._SetContainerVis, ESPData.Widget, Container, UEnums.ESlateVisibility.Collapsed)
              PlayerMapMarker.UpdateESPHealth(ESPData.Widget, 0)
              PlayerMapMarker.RemoveSnapLine(KeyStr)
            end
          end
        end
      end
    end
    for KeyStr, Data in pairs(PlayerMapMarker.ESPWidgets) do
      if SeenKeys[KeyStr] then
        Data._OwenMissingSince = nil
      else
        local now = _G.RealNow()
        Data._OwenMissingSince = Data._OwenMissingSince or now
        local alive = IsValid(Data.Character) and PlayerMapMarker.IsAlive(Data.Character)
        if not alive or now - Data._OwenMissingSince >= 0.6 then
          PlayerMapMarker.RemoveESPWidget(Data.Widget, KeyStr)
          PlayerMapMarker.ESPWidgets[KeyStr] = nil
        end
      end
    end
  end
  PlayerMapMarker._LightStep = function(KeyStr, ESPData, PC, fromX, fromY, VIS_HIDE, MyLocL)
    local Widget = ESPData.Widget
    local Character = ESPData.Character
    local Container = Widget and Widget.Container or nil
    if type(Container) ~= "userdata" or not slua.isValid(Container) then
      Container = nil
    end
    if not (Widget and Character and IsValid(Character)) then
      PlayerMapMarker.RemoveSnapLine(KeyStr);
      PlayerMapMarker.HideBox(KeyStr)
      if Widget then
        PlayerMapMarker.RemoveESPWidget(Widget, KeyStr)
      end
      PlayerMapMarker.ESPWidgets[KeyStr] = nil
      return
    end
    if Widget and Character and IsValid(Character) then
      local gov = _G.OwenESPGov
      if gov and gov.Level > 0 then
        local d = ESPData._DistCm
        if d and d > (gov.FarCm or 6000) then
          local ph = ESPData._Ph
          if ph == nil then
            ph = # KeyStr;
            ESPData._Ph = ph
          end
          local stride = (gov.Level >= 3) and 4 or ((gov.Level >= 2) and 3 or 2)
          if (ph % stride) ~= (gov.Frames % stride) then
            return true
          end
        end
      end
      local bIsAlive = PlayerMapMarker.IsAlive(Character)
      if not bIsAlive then
        if Container then
          pcall(PlayerMapMarker._SetContainerVis, Widget, Container, VIS_HIDE)
        end
        PlayerMapMarker.RemoveSnapLine(KeyStr)
        PlayerMapMarker.HideBox(KeyStr)
      else
        if Container and not Widget._OpacitySet then
          pcall(Container.SetRenderOpacity, Container, 1.0)
          Widget._OpacitySet = true
        end
        local Loc = PlayerMapMarker.GetESPLocation(Character)
        if Loc then
          local sc = PlayerMapMarker.ESPBaseScale or 0.9
          if MyLocL then
            local dcm = PlayerMapMarker._Dist3D(MyLocL, Loc)
            ESPData._DistCm = dcm
            sc = PlayerMapMarker._ScaleForDist(dcm)
          end
          Widget._WantScale = sc
          local bOnScreen, CanvasPos = PlayerMapMarker.ProjectWorldToCanvasLocal(PC, Loc)
          local tp = PlayerMapMarker._ProjTmp
          local onScreen = bOnScreen and tp and tp.X >= 0 and tp.Y >= 0 and tp.X <= (PlayerMapMarker._VpPxW or 1920) and tp.Y <= (PlayerMapMarker._VpPxH or 1080)
          if Container then
            pcall(PlayerMapMarker.UpdateESPPositionWithPC, Widget, Loc, PC, CanvasPos)
          end
          if PlayerMapMarker.bUseSnapLines then
            pcall(PlayerMapMarker.UpdateSnapLine, KeyStr, CanvasPos, bOnScreen, fromX, fromY, ESPData.IsBot, PC, Character)
          else
            PlayerMapMarker.RemoveSnapLine(KeyStr)
          end
          pcall(PlayerMapMarker.UpdateBox, KeyStr, Character, PC, CanvasPos, bOnScreen and onScreen, sc, ESPData)
        else
          PlayerMapMarker.RemoveSnapLine(KeyStr)
          PlayerMapMarker.HideBox(KeyStr)
        end
      end
    end
  end
  function PlayerMapMarker.UpdateESPLight()
    if not PlayerMapMarker.bUseScreenESP then
      if RedBoxOverlay and RedBoxOverlay.bActive then
        RedBoxOverlay.UpdatePosition()
      end
      return
    end
    PlayerMapMarker.bUseSnapLines = _G.MWConfig.EspPlayerLine
    if not PlayerMapMarker.ESPCanvas or not Game:IsValid(PlayerMapMarker.ESPCanvas) then
      return
    end
    local PC = PlayerMapMarker.GetMyPlayerController()
    if not IsValid(PC) then
      return
    end
    PlayerMapMarker.UpdateCanvasTransform(PC)
    PlayerMapMarker._FrameNow = _G.RealNow()
    if RedBoxOverlay and RedBoxOverlay.bActive then
      RedBoxOverlay.UpdatePosition()
    end
    local fromX, fromY = 0, 0
    if PlayerMapMarker.bUseSnapLines then
      fromX, fromY = PlayerMapMarker.GetSnapLineStartPos(PC)
    end
    PlayerMapMarker._ShowAnyUI = PlayerMapMarker._ShowAnyUINow()
    local VIS_HIDE = UEnums.ESlateVisibility.Collapsed
    local MyLocL = PlayerMapMarker.GetMyLocation()
    pcall(_G.OwenSkeletonBudget.Plan)
    for KeyStr, ESPData in pairs(PlayerMapMarker.ESPWidgets) do
      local actorOK, actorError = pcall(PlayerMapMarker._LightStep, KeyStr, ESPData, PC, fromX, fromY, VIS_HIDE, MyLocL)
      if actorOK then
        ESPData._OwenErrorSince = nil
      else
        local now = _G.RealNow()
        ESPData._OwenErrorSince = ESPData._OwenErrorSince or now
        PlayerMapMarker.OwenLastESPError = { At = now, Message = tostring(actorError) }
        if now - ESPData._OwenErrorSince >= 0.2 then
          pcall(PlayerMapMarker.RemoveSnapLine, KeyStr)
          pcall(PlayerMapMarker.HideBox, KeyStr)
          if ESPData.Widget then
            pcall(PlayerMapMarker.RemoveESPWidget, ESPData.Widget, KeyStr)
          end
          PlayerMapMarker.ESPWidgets[KeyStr] = nil
        end
      end
    end
  end
  function PlayerMapMarker.UpdateESPDistances()
    if not PlayerMapMarker.bUseScreenESP then
      return
    end
    local MyLoc = PlayerMapMarker.GetMyLocation()
    if not MyLoc then
      return
    end
    local PC = PlayerMapMarker.GetMyPlayerController()
    if not IsValid(PC) then
      return
    end
    PlayerMapMarker.UpdateCanvasTransform(PC)
    for KeyStr, ESPData in pairs(PlayerMapMarker.ESPWidgets) do
      local Character = ESPData.Character
      local Widget = ESPData.Widget
      local Container = Widget and (Widget.Container or Widget)
      if Character and IsValid(Character) and type(Container) == "userdata" and slua.isValid(Container) then
        local Loc = PlayerMapMarker.GetESPLocation(Character)
        if Loc then
          local Dist = PlayerMapMarker.CalcDistance(MyLoc, Loc)
          ESPData.LastDistance = Dist
          if PlayerMapMarker.bShowDistance then
            local DistStr = ""
            local changed = false
            if Dist then
              local Meters = Dist / 100
              local mKey = (Meters < 1000) and math.floor(Meters) or (1000000 + math.floor(Meters / 100))
              if ESPData._DistKey ~= mKey then
                ESPData._DistKey = mKey
                if Meters < 1000 then
                  ESPData._DistStrC = string.format("%dm", math.floor(Meters))
                else
                  ESPData._DistStrC = string.format("%.1fkm", Meters / 1000)
                end
                changed = true
              end
              DistStr = ESPData._DistStrC
            end
            local Name = ESPData.Name or "Unknown"
            if ESPData._TextName ~= Name then
              ESPData._TextName = Name
              changed = true
            end
            if changed or ESPData._TextCache == nil or ESPData._TextShowName ~= _G.MWConfig.EspPlayerName or ESPData._TextShowDistance ~= _G.MWConfig.EspPlayerDistance then
              ESPData._TextShowName = _G.MWConfig.EspPlayerName
              ESPData._TextShowDistance = _G.MWConfig.EspPlayerDistance
              local cfg = _G.MWConfig
              local Text = ""
              if cfg.EspPlayerName then
                Text = Name
              end
              if cfg.EspPlayerDistance and DistStr and DistStr ~= "" then
                if Text ~= "" then
                  Text = Text .. " [" .. DistStr .. "]"
                else
                  Text = "[" .. DistStr .. "]"
                end
              end
              ESPData._TextCache = Text
            end
            ESPData.LastDistStr = DistStr PlayerMapMarker.UpdateESPText(Widget, ESPData._TextCache or "")
          end
        end
      end
    end
  end
  function PlayerMapMarker.ScanAndUpdate()
    local AllChars = PlayerMapMarker.GetAllCharacters()
    if not AllChars then
      PlayerMapMarker.ClearAllESP();
      RedBoxOverlay.SetCounts(0, 0);
      return 0
    end
    local MyKey = PlayerMapMarker.GetMyPlayerKey()
    local MyLoc = PlayerMapMarker.GetMyLocation()
    local MyChar = nil pcall(function()
      local GDP = PlayerMapMarker.GetGameplayData()
      if GDP and GDP.GetLocalCharacter then
        MyChar = GDP.GetLocalCharacter()
      else
        local PC = PlayerMapMarker.GetMyPlayerController()
        if PC and PC.GetPawn then
          MyChar = PC:GetPawn()
        end
      end
    end)
    local MyTeamID = PlayerMapMarker.GetTeamID(MyChar)
    local realPlayers = 0
    local nearest = nil
    local botPlayers = 0
    for PlayerKey, Character in pairs(AllChars) do
      if IsValid(Character) then
        local bIsMe = PlayerMapMarker.IsMe(Character, PlayerKey, MyKey)
        local bIsAI = PlayerMapMarker.IsAI(Character)
        local bIsAlive = PlayerMapMarker.IsAlive(Character)
        if bIsAlive and not bIsMe then
          local bIsMyTeam = false
          if MyTeamID ~= nil then
            local targetTeamID = PlayerMapMarker.GetTeamID(Character)
            if targetTeamID == MyTeamID then
              bIsMyTeam = true
            end
          end
          if not bIsMyTeam and Character.HealthStatus ~= 2 then
            local loc = PlayerMapMarker.GetCharacterLocation(Character)
            local d = loc and MyLoc and PlayerMapMarker.CalcDistance(loc, MyLoc)
            if d and ( not nearest or d < nearest) then
              nearest = d
            end
            if bIsAI then
              botPlayers = botPlayers + 1
            else
              realPlayers = realPlayers + 1
            end
          end
        end
      end
    end
    if _G.MWConfig.EspPlayerCount then
      if not RedBoxOverlay.bActive then
        RedBoxOverlay.Start()
      end
      RedBoxOverlay.SetCounts(realPlayers, botPlayers, nearest and math.floor(nearest / 100 + .5))
    else
      if RedBoxOverlay.bActive then
        RedBoxOverlay.Stop()
      end
    end
    if PlayerMapMarker.bUseScreenESP then
      PlayerMapMarker.UpdateESP(AllChars, MyLoc)
      return 0
    end
    return 0
  end
  function PlayerMapMarker._ClearTimers()
    local pc = PlayerMapMarker._ActiveTimerPC
    local hs = PlayerMapMarker._TimerHandles
    PlayerMapMarker._TimerHandles = nil
    if hs and pc and slua.isValid(pc) and pc.RemoveGameTimer then
      for _, h in ipairs(hs) do
        if h then
          pcall(pc.RemoveGameTimer, pc, h)
        end
      end
    end
  end
  do
    local V = { Level = 0, Ms = 0, Peak = 0, Frames = 0, Bad = 0, Good = 0, T0 = 0, FarCm = 6000 }
    _G.OwenESPGov = V
    function V.Enabled()
      local c = _G.MWConfig
      return not (c and (c.EspAutoQuality == false or c.EspAutoQuality == 0))
    end
    function V.Begin()
      V.T0 = os.clock()
    end
    function V.End()
      local spent = (os.clock() - V.T0) * 1000
      if spent < 0 or spent > 200 then
        spent = 0
      end
      V.Ms = V.Ms * 0.85 + spent * 0.15
      if spent > V.Peak then
        V.Peak = spent
      end
      V.Frames = V.Frames + 1
      if not V.Enabled() then
        V.Level = 0;
        return
      end
      local want = 0
      if V.Ms >= (tonumber(_G.MWConfig and _G.MWConfig.EspGovLv3Ms) or 12) then
        want = 3
      elseif V.Ms >= (tonumber(_G.MWConfig and _G.MWConfig.EspGovLv2Ms) or 8) then
        want = 2
      elseif V.Ms >= (tonumber(_G.MWConfig and _G.MWConfig.EspGovLv1Ms) or 5) then
        want = 1
      end
      if want > V.Level then
        V.Bad = V.Bad + 1
        if V.Bad >= 6 then
          V.Level = want;
          V.Bad = 0;
          V.Good = 0
        end
      elseif want < V.Level then
        V.Good = V.Good + 1
        if V.Good >= 90 then
          V.Level = V.Level - 1;
          V.Good = 0;
          V.Bad = 0
        end
      else
        V.Bad = 0;
        V.Good = 0
      end
    end
  end
  function _G.OwenNeonFrameDispatcher(first, second)
    local now = _G.RealNow()
    _G.OwenNeonLastFrameTime = now
    _G.OwenFrameSeq = (_G.OwenFrameSeq or 0) + 1
    local dt = tonumber(second) or tonumber(first)
    if dt and dt > 0 and dt <= 1 then
      _G.OwenNeonFrameDT = dt
      _G.OwenNeonAccumDT = math.min((_G.OwenNeonAccumDT or 0) + dt, 0.1)
    end
    local hz = tonumber(_G.MWConfig and _G.MWConfig.EspRefreshRate) or 0
    if hz ~= 60 and hz ~= 90 and hz ~= 120 and hz ~= 144 then
      hz = 0
    end
    local espDue = true
    if hz > 0 then
      local interval = 1 / hz
      local nextWork = _G.OwenNeonNextESPWork or now
      if _G.OwenNeonESPHz ~= hz then
        nextWork = now
      end
      espDue = now + 0.000001 >= nextWork
      if espDue then
        nextWork = nextWork + interval
        if nextWork <= now then
          nextWork = now + interval
        end
      end
      _G.OwenNeonNextESPWork = nextWork
    else
      _G.OwenNeonNextESPWork = nil
    end
    _G.OwenNeonESPHz = hz
    _G.OwenNeonAccumDT = 0
    local PMM = _G.PlayerMapMarker
    if espDue and PMM and PMM.VisibilityBudget then
      pcall(PMM.VisibilityBudget.Pump)
    end
    if PMM and PMM.bActive then
      PMM._ActiveTimerTick = os.time()
      local due = espDue
      if due and _G.OwenLowSpecEnabled and _G.OwenLowSpecEnabled() then
        local frameNow = _G.OwenNeonLastFrameTime
        due = frameNow >= (PMM._NextLowSpecLight or 0)
        if due then
          PMM._NextLowSpecLight = frameNow + 1 / 30
        end
      end
      if due then
        local gov = _G.OwenESPGov
        if gov then
          gov.Begin()
        end
        local ok, err = _G.OwenRuntimeGuard.Call('Frame.Light', PMM.UpdateESPLight)
        if gov then
          gov.End()
        end
        if ok then
          PMM._LastLightFrameTime = _G.RealNow()
        else
          PMM._LightFrameErrors = (PMM._LightFrameErrors or 0) + 1;
          PMM._LastLightFrameError = tostring(err)
        end
      end
    end
    if _G.AimFrameTick then
      local frameOK = _G.OwenRuntimeGuard.Call('Frame.Dispatch', _G.AimFrameTick, dt)
      if not frameOK and _G.OwenNeonResetOverlayContext then
        pcall(_G.OwenNeonResetOverlayContext)
      end
    end
  end
  function _G.OwenNeonEnsureFrameListener()
    local hud = require("game_frontend_hud")
    if _G.OwenNeonFrameListenerOwner == hud and _G.OwenNeonFrameListenerFunction == _G.OwenNeonFrameDispatcher then
      _G._AimFrameTickRegistered = true;
      _G._ESPFrameTickRegistered = true;
      return true
    end
    local result = hud.SetSluaTickListener(_G.OwenNeonFrameDispatcher)
    if result == false then
      return false
    end
    _G.OwenNeonFrameListenerOwner = hud;
    _G.OwenNeonFrameListenerFunction = _G.OwenNeonFrameDispatcher
    _G._AimFrameTickRegistered = true;
    _G._ESPFrameTickRegistered = true;
    return true
  end
  function PlayerMapMarker.AttachTimers()
    if not PlayerMapMarker.bActive then
      return
    end
    pcall(function()
      local pc = PlayerMapMarker.GetMyPlayerController()
      if not slua.isValid(pc) or not pc.AddGameTimer then
        local now = os.time()
        if PlayerMapMarker._AttachPending then
          if PlayerMapMarker._AttachPendingTime and (now - PlayerMapMarker._AttachPendingTime) < 2 then
            return
          end
        end
        PlayerMapMarker._AttachPending = true;
        PlayerMapMarker._AttachPendingTime = now pcall(function()
          require("timer").SetGameTimer(1.0, false, function()
            PlayerMapMarker._AttachPending = nil;
            PlayerMapMarker._AttachPendingTime = nil;
            PlayerMapMarker.AttachTimers()
          end)
        end)
        return
      end
      PlayerMapMarker._AttachPending = nil;
      PlayerMapMarker._AttachPendingTime = nil
      local now = os.time()
      local lastPC = PlayerMapMarker._ActiveTimerPC
      local lastTick = PlayerMapMarker._ActiveTimerTick
      if lastPC and slua.isValid(lastPC) and lastPC == pc then
        if lastTick and (now - lastTick) < 5 then
          return
        end
      end
      PlayerMapMarker._ClearTimers()
      PlayerMapMarker._ActiveTimerPC = pc;
      PlayerMapMarker._ActiveTimerTick = now
      local hs = {} PlayerMapMarker._TimerHandles = hs pcall(function()
        hs[ # hs + 1] = pc:AddGameTimer(PlayerMapMarker.nUpdateInterval or 0.5, true, function()
          PlayerMapMarker._ActiveTimerTick = os.time()
          if PlayerMapMarker.bActive then
            pcall(PlayerMapMarker.ScanAndUpdate)
          end
        end)
      end)
      if not _G._ESPFrameTickRegistered then
        local okReg, registered = pcall(_G.OwenNeonEnsureFrameListener)
        if okReg and registered then
          _G._ESPFrameTickRegistered = true
        end
      end
      pcall(function()
        hs[ # hs + 1] = pc:AddGameTimer(PlayerMapMarker._LightUpdateInterval or 0.02, true, function()
          if not PlayerMapMarker.bActive then
            return
          end
          local now = _G.RealNow()
          if now - (PlayerMapMarker._LastLightFrameTime or - 1) < 0.10 then
            return
          end
          PlayerMapMarker._ActiveTimerTick = os.time()
          PlayerMapMarker._LightFallbackCalls = (PlayerMapMarker._LightFallbackCalls or 0) + 1
          local ok, err = pcall(PlayerMapMarker.UpdateESPLight)
          if not ok then
            PlayerMapMarker._LightFrameErrors = (PlayerMapMarker._LightFrameErrors or 0) + 1
            PlayerMapMarker._LastLightFrameError = tostring(err)
          end
          if now - (_G.OwenNeonLastFrameTime or - 1) >= 0.10 and _G.AimFrameTick then
            local frameOK = _G.OwenRuntimeGuard.Call('Frame.Fallback', _G.AimFrameTick, PlayerMapMarker._LightUpdateInterval or 0.02)
            if not frameOK and _G.OwenNeonResetOverlayContext then
              pcall(_G.OwenNeonResetOverlayContext)
            end
          end
        end)
      end)
      pcall(function()
        hs[ # hs + 1] = pc:AddGameTimer(PlayerMapMarker._DistanceUpdateInterval or 0.1, true, function()
          PlayerMapMarker._ActiveTimerTick = os.time()
          if PlayerMapMarker.bActive and PlayerMapMarker.bUseScreenESP and PlayerMapMarker.bShowDistance then
            pcall(PlayerMapMarker.UpdateESPDistances)
          end
        end)
      end)
      pcall(require, "timer").SetGameTimer(5.0, false, PlayerMapMarker.AttachTimers)
    end)
  end
  function PlayerMapMarker.Start()
    if PlayerMapMarker.bActive then
      return
    end
    PlayerMapMarker.bActive = true
    PlayerMapMarker._DeadKeys = nil
    PlayerMapMarker._DeadLatch = setmetatable( {}, { __mode = 'k' })
    PlayerMapMarker._DeadProbe = setmetatable( {}, { __mode = 'k' })
    PlayerMapMarker._LatchRecheck = setmetatable( {}, { __mode = 'k' })
    PlayerMapMarker._AliveSince = setmetatable( {}, { __mode = 'k' })
    PlayerMapMarker._LastLightFrameTime = nil
    PlayerMapMarker._LightFrameErrors = 0;
    PlayerMapMarker._LastLightFrameError = nil;
    PlayerMapMarker._LightFallbackCalls = 0
    PlayerMapMarker._FrameCount = 0 PlayerMapMarker.ScanAndUpdate()
    PlayerMapMarker.AttachTimers()
  end
  function PlayerMapMarker.Stop()
    PlayerMapMarker.CharacterSnapshot = nil
    PlayerMapMarker.bActive = false
    PlayerMapMarker._FrameCount = 0 PlayerMapMarker.ClearAllESP()
    pcall(PlayerMapMarker._ClearTimers)
    PlayerMapMarker._ActiveTimerPC = nil;
    PlayerMapMarker._ActiveTimerTick = nil
  end
  _G.PlayerMapMarker = PlayerMapMarker
  local FOVCircle_ScaleX = 1.0
  local FOVCircle_ScaleY = 1.0
  local FOVCircle_OffsetX = 0
  local FOVCircle_OffsetY = 0
  local function UpdateFOVCanvasTransform(PC)
    local canvas = DrawLine.GetCanvas()
    if not canvas then
      return
    end
    local nowC = _G.RealNow()
    if _G._FOVCircle_XformTime and (nowC - _G._FOVCircle_XformTime) < 0.25 then
      return
    end
    _G._FOVCircle_XformTime = nowC pcall(function()
      local SlateBP = import("SlateBlueprintLibrary")
      if not SlateBP then
        return
      end
      local cg = canvas:GetCachedGeometry()
      local absP0 = FVector2D(0, 0)
      local absP1 = FVector2D(1, 0)
      local lp0 = SlateBP.AbsoluteToLocal(cg, absP0)
      local lp1 = SlateBP.AbsoluteToLocal(cg, absP1)
      local dx = lp1.X - lp0.X
      local dy = lp1.Y - lp0.Y
      local scale = math.sqrt(dx * dx + dy * dy)
      if scale < 0.0001 then
        scale = 1.0
      end
      FOVCircle_ScaleX = scale
      FOVCircle_ScaleY = scale
      FOVCircle_OffsetX = lp0.X
      FOVCircle_OffsetY = lp0.Y
    end)
  end
  function _G.CleanUpFOVCircle()
    _G._FOVCircle_XformTime = nil;
    _G._FOV_vpTime = nil
    local fi = _G._FOVImg
    for _, line in ipairs(fi and fi.lines or {}) do
      if PlayerMapMarker._ProtectedWidgetStrs then
        PlayerMapMarker._ProtectedWidgetStrs[tostring(line.Widget)] = nil
      end
      pcall(DrawLine.Remove, line)
    end
    if fi and fi.w and slua.isValid(fi.w) then
      pcall(function()
        fi.w:RemoveFromParent()
      end)
    end
    _G._FOVImg = nil
  end
  _G.FOVRingColorIdle = FLinearColor and FLinearColor(1.0, 1.0, 1.0, 0.9) or { R = 255, G = 255, B = 255,
  A = 230 }
  _G.FOVRingColorLock = FLinearColor and FLinearColor(1.0, 1.0, 1.0, 0.9) or { R = 255, G = 255, B = 255,
  A = 230 }
  local function InitFOVImage()
    local fi = _G._FOVImg
    local currentCanvas = DrawLine.GetCanvas()
    if fi and fi.canvas == currentCanvas then
      if fi.w and _G.MWWidgetLive(fi.w) then
        return fi
      end
      if fi.lines and # fi.lines == 48 then
        local live = true;
        for _, line in ipairs(fi.lines) do
          if not _G.MWWidgetLive(line.Widget) then
            live = false;
            break
          end
        end
        if live then
          return fi
        end
      end
    end
    if fi then
      _G.CleanUpFOVCircle()
    end
    local canvas = DrawLine.GetCanvas()
    if not canvas then
      return nil
    end
    if _G._FOVImgFailedT and (_G.RealNow() - _G._FOVImgFailedT) < 3.0 then
      return nil
    end
    fi = _G.MWIconImageAt(canvas, 0, 0, 100, 100, "fov_ring", 0.5, 0.5, 5)
    if not fi or not fi.slot then
      if fi and fi.w then
        pcall(function()
          fi.w:RemoveFromParent()
        end)
      end
      fi = {
        lines = {}
      }
      local ok = pcall(function()
        for i = 1, 48 do
          local widget = CGame:NewObjectFromPath("/Script/UMG.Border", canvas)
          assert(widget and slua.isValid(widget), "fov_border_creation_failed")
          local slot = canvas:AddChildToCanvas(widget)
          if not slot then
            pcall(function()
              widget:RemoveFromParent()
            end);
            error("fov_border_slot_failed")
          end
          fi.lines[ # fi.lines + 1] = { Widget = widget, Slot = slot, img = false, _posVec = FVector2D(0, 0),
          _sizeVec = FVector2D(0, 0) }
          slot:SetAutoSize( false);
          slot:SetAlignment(FVector2D(0, 0.5));
          slot:SetZOrder(5)
          widget:SetRenderTransformPivot(FVector2D(0, 0.5))
          local visibility = widget.SetVisibility or widget.SetWidgetVisibility visibility(widget, UEnums.ESlateVisibility.Collapsed)
          PlayerMapMarker._ProtectedWidgetStrs = PlayerMapMarker._ProtectedWidgetStrs or {} PlayerMapMarker._ProtectedWidgetStrs[tostring(widget)] = true
        end
      end)
      if not ok then
        for _, line in ipairs(fi.lines) do
          if PlayerMapMarker._ProtectedWidgetStrs then
            PlayerMapMarker._ProtectedWidgetStrs[tostring(line.Widget)] = nil
          end
          pcall(DrawLine.Remove, line)
        end;
        _G._FOVImgFailedT = _G.RealNow();
        return nil
      end
    end
    _G._FOVImgFailedT = nil
    if fi.w then
      pcall(function()
(fi.w.SetVisibility or fi.w.SetWidgetVisibility)(fi.w, UEnums.ESlateVisibility.Collapsed)
      end)
    end
    fi.canvas = canvas
    fi.vis = false;
    fi.cx = nil;
    fi.cy = nil;
    fi.d = nil;
    fi.lock = nil
    fi.pos = FVector2D and FVector2D(0, 0) or { X = 0, Y = 0 }
    fi.size = FVector2D and FVector2D(100, 100) or { X = 100, Y = 100 }
    _G._FOVImg = fi
    return fi
  end
  local function UpdateFOVCircle(fovVal, PC)
    local fi = InitFOVImage()
    if not fi then
      return
    end
    UpdateFOVCanvasTransform(PC)
    local vpW, vpH = 0, 0
    local nowV = _G.RealNow()
    if _G._FOV_vpTime and (nowV - _G._FOV_vpTime) < 0.25 and _G._FOV_vpW then
      vpW, vpH = _G._FOV_vpW, _G._FOV_vpH
    else
      pcall(function()
        local ui_util = require("client.common.ui_util")
        local vs = ui_util and ui_util.GetViewportSize()
        if vs and vs.X > 200 then
          vpW = vs.X
          vpH = vs.Y
        end
      end)
      if vpW >= 200 then
        _G._FOV_vpW, _G._FOV_vpH, _G._FOV_vpTime = vpW, vpH, nowV
      end
    end
    if vpW < 200 then
      return
    end
    fovVal = tonumber(fovVal) or 30
    local radiusPx = (fovVal / 100.0) * (vpW / 2.0)
    local cx = (vpW / 2) * FOVCircle_ScaleX + FOVCircle_OffsetX
    local cy = (vpH / 2) * FOVCircle_ScaleY + FOVCircle_OffsetY
    local rX = radiusPx * FOVCircle_ScaleX
    local rY = radiusPx * FOVCircle_ScaleY
    if fi.lines then
      local lock = (_G.MWState and _G.MWState.AimTouchTarget and slua.isValid(_G.MWState.AimTouchTarget)) and true or false
      if fi.cx ~= cx or fi.cy ~= cy or fi.rx ~= rX or fi.ry ~= rY or fi.lock ~= lock or not fi.vis then
        local color = lock and _G.FOVRingColorLock or _G.FOVRingColorIdle
        for i, line in ipairs(fi.lines) do
          local a = (i - 1) * math.pi * 2 / 48;
          local b = i * math.pi * 2 / 48 DrawLine.Update(line, cx + math.cos(a) * rX, cy + math.sin(a) * rY, cx + math.cos(b) * rX, cy + math.sin(b) * rY, color, 1.5)
        end
        fi.cx, fi.cy, fi.rx, fi.ry, fi.lock, fi.vis = cx, cy, rX, rY, lock, true
      end
      return
    end
    do
      local d = math.floor(rX * 2 + 0.5)
      local lock = (_G.MWState and _G.MWState.AimTouchTarget and slua.isValid(_G.MWState.AimTouchTarget)) and true or false
      if fi.cx ~= cx or fi.cy ~= cy then
        fi.cx, fi.cy = cx, cy fi.pos.X, fi.pos.Y = cx, cy pcall(fi.slot.SetPosition, fi.slot, fi.pos)
      end
      if fi.d ~= d then
        fi.d = d fi.size.X, fi.size.Y = d, d pcall(fi.slot.SetSize, fi.slot, fi.size)
      end
      if fi.lock ~= lock then
        fi.lock = lock pcall(fi.w.SetColorAndOpacity, fi.w, lock and _G.FOVRingColorLock or _G.FOVRingColorIdle)
      end
      if fi.vis ~= true then
        local fn = fi.w.SetVisibility or fi.w.SetWidgetVisibility
        local ok = type(fn) == "function" and pcall(fn, fi.w, UEnums.ESlateVisibility.HitTestInvisible)
        if ok then
          fi.vis = true
        end
      end
    end
  end
  local function HideFOVCircle()
    local fi = _G._FOVImg
    if fi and fi.lines and fi.vis ~= false then
      for _, line in ipairs(fi.lines) do
        pcall(DrawLine.Hide, line)
      end;
      fi.vis = false
    end
    if fi and fi.w and slua.isValid(fi.w) and fi.vis ~= false then
      fi.vis = false pcall(fi.w.SetWidgetVisibility, fi.w, UEnums.ESlateVisibility.Collapsed)
    end
  end
