  B = 0, A = 235 }
  function _G.MinimapESP.GetPanel(T)
    local now = _G.RealNow()
    if T.panel and slua.isValid(T.panel) and T.base and slua.isValid(T.base) and (now - T._winT) < 1.0 then
      return T.panel, T.base
    end
    T._winT = now
    local panel, base = nil, nil pcall(function()
      local UIManager = _G.UIManager
      if not UIManager or not UIManager.UI_Config_InGame then
        return
      end
      local win = UIManager.GetUI(UIManager.UI_Config_InGame[T.cfg])
      local root = win and win.UIRoot
      if not root or not slua.isValid(root) then
        return
      end
      if T.key == "big" then
        local shown = false pcall(function()
          shown = root.CurrentMapUIBP and root.CurrentMapUIBP.bIsShow == true
        end)
        if not shown then
          return
        end
      end
      local p = root.CommonFunctionAddPanel
      local b = root.MapUIBase
      if ( not b or not slua.isValid(b)) and root.CurrentMapUIBP then
        b = root.CurrentMapUIBP.CurrentMapUI
      end
      if p and slua.isValid(p) and b and slua.isValid(b) and _G.MWWidgetLive(p) then
        panel, base = p, b
      end
    end)
    if T.panel ~= panel then
      _G.MinimapESP.Clear(T)
    end
    T.panel, T.base = panel, base
    return panel, base
  end
  function _G.MinimapESP._NewImg(panel, key, size, z, color)
    local img = _G.MWIconImageAt(panel, 0, 0, size, size, key, 0.5, 0.5, z)
    if not img then
      return nil
    end
    pcall(function()
      local FAnchors = FAnchors or import("Anchors") or import("/Script/SlateCore.Anchors")
      if FAnchors and img.slot then
        img.slot:SetAnchors(FAnchors(0.5, 0.5, 0.5, 0.5))
      end
      img.w:SetRenderTransformPivot(FVector2D and FVector2D(0.5, 0.5) or { X = 0.5, Y = 0.5 })
      img.w:SetColorAndOpacity(color)
      img.w:SetWidgetVisibility(UEnums.ESlateVisibility.Collapsed)
    end)
    img.vis = false;
    img.x = nil;
    img.y = nil;
    img.sc = nil;
    img.color = color;
    img.ang = nil
    img.pos = FVector2D and FVector2D(0, 0) or { X = 0, Y = 0 }
    img.scv = FVector2D and FVector2D(1, 1) or { X = 1, Y = 1 }
    return img
  end
  function _G.MinimapESP.Remove(T, key)
    local it = T.items[key]
    if not it then
      return
    end
    for _, k in ipairs( { "img", "outline", "wedge" }) do
      local im = it[k]
      if im and im.w and slua.isValid(im.w) then
        if PlayerMapMarker._ProtectedWidgetStrs then
          PlayerMapMarker._ProtectedWidgetStrs[tostring(im.w)] = nil
        end
        pcall(function()
          im.w:RemoveFromParent()
        end)
      end
    end
    T.items[key] = nil
  end
  function _G.MinimapESP.Clear(T)
    for key in pairs(T.items) do
      _G.MinimapESP.Remove(T, key)
    end
    T.items = {}
    for _, it in ipairs(T.free or {}) do
      T.items["__f"] = it;
      _G.MinimapESP.Remove(T, "__f")
    end
    T.free = {}
  end
  function _G.MinimapESP.TickTarget(T, Lib)
    local M = _G.MinimapESP
    local panel, base = M.GetPanel(T)
    if not panel then
      return
    end
    local center, scale = nil, nil pcall(function()
      center = base.LevelLandScapeCenterC;
      scale = base:GetLevelToMapScale()
    end)
    if not center or not scale or scale == 0 then
      return
    end
    local seen = {}
    for KeyStr, ESPData in pairs(PlayerMapMarker.ESPWidgets) do
      local ch = ESPData.Character
      if ch and IsValid(ch) and PlayerMapMarker.IsAlive(ch) then
        local loc, fwd = nil, nil pcall(function()
          loc = ch:K2_GetActorLocation();
          fwd = ch:GetActorForwardVector()
        end)
        if loc then
          local it = T.items[KeyStr]
          if not it or not (it.img and _G.MWWidgetLive(it.img.w)) then
            if it then
              M.Remove(T, KeyStr)
            end
            T.free = T.free or {}
            while # T.free > 0 and not it do
              local cand = table.remove(T.free)
              if cand and cand.img and _G.MWWidgetLive(cand.img.w) then
                it = cand
              end
            end
            if not it then
              it = { wedge = M._NewImg(panel, "mm_wedge", M.ImgSize, 50, M.ColorWedge), outline = M._NewImg(panel, "mm_dot", M.ImgSize * M.OutlineScale, 51, M.ColorOutline),
              img = M._NewImg(panel, "mm_dot", M.ImgSize, 52, M.ColorEnemy) }
              if not it.img then
                it = nil
              end
            end
            if it then
              it.img.ang = nil
            end
            T.items[KeyStr] = it
          end
          if it then
            local ok, mp = pcall(Lib.MapCenterToPointVector2D, loc, center, scale)
            if ok and mp then
              seen[KeyStr] = true PlayerMapMarker._PinSet(it.img, true, mp.X, mp.Y)
              PlayerMapMarker._PinSet(it.outline, true, mp.X, mp.Y)
              PlayerMapMarker._PinSet(it.wedge, true, mp.X, mp.Y)
              if fwd then
                local ok2, mp2 = pcall(Lib.MapCenterToPointVector2D, FVector(loc.X + fwd.X * 200, loc.Y + fwd.Y * 200, loc.Z), center, scale)
                if ok2 and mp2 then
                  local dx, dy = mp2.X - mp.X, mp2.Y - mp.Y
                  if dx * dx + dy * dy > 1e-6 then
                    local ang = math.floor(math.deg(math.atan(dx, - dy)) + 0.5) % 360
                    if it.img.ang ~= ang then
                      it.img.ang = ang
                      if it.wedge then
                        pcall(it.wedge.w.SetRenderAngle, it.wedge.w, ang)
                      end
                    end
                  end
                end
              end
            end
          end
        end
      end
    end
    T.free = T.free or {}
    for key, it in pairs(T.items) do
      if not seen[key] then
        PlayerMapMarker._PinSet(it.img, false);
        PlayerMapMarker._PinSet(it.outline, false);
        PlayerMapMarker._PinSet(it.wedge, false)
        T.items[key] = nil
        if # T.free < 40 then
          T.free[ # T.free + 1] = it
        else
          T.items[key] = it;
          M.Remove(T, key)
        end
      end
    end
  end
  function _G.MinimapESP.Tick()
    local M = _G.MinimapESP
    if not _G.MWHud.Ready() then
      return
    end
    if not _G.MWConfig.EspMinimap or not _G.MWConfig.EspPlayer then
      for _, T in ipairs(M.targets) do
        if next(T.items) or # (T.free or {}) > 0 then
          M.Clear(T)
        end
      end
      return
    end
    local Lib = M._Lib
    if not Lib then
      Lib = import("STExtraMapFunctionLibrary") or import("/Script/ShadowTrackerExtra.STExtraMapFunctionLibrary");
      M._Lib = Lib
    end
    if not Lib then
      return
    end
    for _, T in ipairs(M.targets) do
      pcall(M.TickTarget, T, Lib)
    end
  end
