  function _G.ItemLabels._Col(c)
    if not c then
      return PlayerMapMarker.LabelColorName
    end
    local r, g, b, a = c.R or 255, c.G or 255, c.B or 255, c.A or 255
    if r > 1 or g > 1 or b > 1 or a > 1 then
      r, g, b, a = r / 255, g / 255, b / 255, a / 255
    end
    return FLinearColor and FLinearColor(r, g, b, a) or { R = r, G = g, B = b, A = a }
  end
  function _G.ItemLabels.Remove(key)
