    if it.w and slua.isValid(it.w) then
      if PlayerMapMarker._ProtectedWidgetStrs then
        PlayerMapMarker._ProtectedWidgetStrs[tostring(it.w)] = nil
      end
      pcall(function()
        it.w:RemoveFromParent()
      end)
    end
    if it.icon and it.icon.w and slua.isValid(it.icon.w) then
      if PlayerMapMarker._ProtectedWidgetStrs then
        PlayerMapMarker._ProtectedWidgetStrs[tostring(it.icon.w)] = nil
      end
      pcall(function()
        it.icon.w:RemoveFromParent()
      end)
    end
    _G.ItemLabels.items[key] = nil
