  function _G.ItemLabels.Tick(pc, localPlayer)
    local M = _G.ItemLabels
    if not _G.MWConfig.EspItem_Master then
      if next(M.items) or # (M.free or {}) > 0 then
        M.Clear()
      end
      return
    end
    local canvas = PlayerMapMarker.ESPCanvas
    if not canvas or not Game:IsValid(canvas) then
      if not PlayerMapMarker.InitESPCanvas() then
        return
      end
      canvas = PlayerMapMarker.ESPCanvas
    end
    local myLoc = nil pcall(function()
      myLoc = localPlayer:K2_GetActorLocation()
    end)
    local seen = {}
    local loc = M._loc
    if not loc then
      loc = FVector(0, 0, 0);
      M._loc = loc
    end
    for _, cached in ipairs(_G.CachedItems or {}) do
      local act = cached.act
      if ( not cached.isBox) and act and slua.isValid(act) and not act.bHidden then
        local key = tostring(act)
        local aloc = nil pcall(function()
          aloc = act:K2_GetActorLocation()
        end)
        if aloc then
          local dcm = myLoc and PlayerMapMarker._Dist3D(myLoc, aloc) or 2500
          if dcm > 200 and dcm <= 100 * (tonumber(_G.MWConfig.ItemMaxDistance) or 400) then
            local it = M.items[key]
            if not it or not (it.w and _G.MWWidgetLive(it.w)) then
              if it then
                M.Remove(key)
              end
              M.free = M.free or {}
              while # M.free > 0 and not it do
                local cand = table.remove(M.free)
                if cand and cand.w and _G.MWWidgetLive(cand.w) then
                  it = cand
                end
              end
              if not it then
                it = PlayerMapMarker._NewLabelText(canvas, M.Font, PlayerMapMarker.LabelColorName, 0.5, 1.0)
              end
              if it then
                it.key = key;
                it.text = nil;
                it.lastM = nil;
                it.name = nil;
                it.srcColor = nil;
                M.items[key] = it
              end
            end
            if it then
              local o = cached.off or { X = 0, Y = 0, Z = M.ZOff }
              loc.X, loc.Y, loc.Z = aloc.X + (o.X or 0), aloc.Y + (o.Y or 0), aloc.Z + (o.Z or 0)
              local bOn, cp = PlayerMapMarker.ProjectWorldToCanvasLocal(pc, loc)
              if bOn then
                seen[key] = true
                local m = math.floor(dcm / 100 + 0.5)
                local ci = (cached.id and M.ItemIcon[cached.id]) or M.CatIcon[cached.cat or ""]
                if cached.cat == "Ammo" or (tonumber(cached.id) and tonumber(cached.id) >= 300000 and tonumber(cached.id) < 400000) or cached.cat == "GasCan" then
                  ci = nil
                end
                if it.lastM ~= m or it.name ~= cached.name then
                  it.lastM = m;
                  it.name = cached.name
                  if ci and ci.text == "none" then
                    PlayerMapMarker._LabelText(it, "")
                  elseif ci and ci.text == "dist" then
                    PlayerMapMarker._LabelText(it, m .. "m")
                  else
                    PlayerMapMarker._LabelText(it, string.format("%s [%dm]", cached.name or "", m))
                  end
                end
                local ts = M.ScaleRefCm / (dcm > 1 and dcm or 1)
                if ts < M.ScaleMin then
                  ts = M.ScaleMin
                elseif ts > M.ScaleMax then
                  ts = M.ScaleMax
                end
                ts = math.floor(ts * 50 + 0.5) / 50
                if cached.scale then
                  ts = ts * cached.scale
                end
                if it.srcColor ~= cached.color then
                  it.srcColor = cached.color
                  local lc = (ci and ci.color) or M._Col(cached.color)
                  PlayerMapMarker._LabelColor(it, lc)
                  if it.icon then
                    it.icon.color = lc;
                    pcall(it.icon.w.SetColorAndOpacity, it.icon.w, lc)
                  end
                end
                if ci then
                  if not it.icon or not _G.MWWidgetLive(it.icon.w) or it.iconKey ~= ci.key then
                    if it.icon and it.icon.w and slua.isValid(it.icon.w) then
                      pcall(function()
                        it.icon.w:RemoveFromParent()
                      end)
                    end
                    it.iconKey = ci.key
                    local ic = _G.MWIconImageAt(canvas, 0, 0, ci.w or ci.size, ci.h or ci.size, ci.key, 0.5, 1.0, 4)
                    if ic then
                      pcall(function()
                        ic.w:SetRenderTransformPivot(FVector2D and FVector2D(0.5, 1.0) or { X = 0.5,
                        Y = 1 })
                      end)
                      pcall(function()
                        ic.w:SetWidgetVisibility(UEnums.ESlateVisibility.Collapsed)
                      end)
                      ic.vis = false;
                      ic.x = nil;
                      ic.y = nil;
                      ic.sc = nil
                      ic.pos = FVector2D and FVector2D(0, 0) or { X = 0, Y = 0 }
                      ic.scv = FVector2D and FVector2D(1, 1) or { X = 1, Y = 1 }
                      local lc = (ci and ci.color) or M._Col(cached.color);
                      ic.color = lc;
                      pcall(ic.w.SetColorAndOpacity, ic.w, lc)
                    end
                    it.icon = ic
                  end
                  if it.icon then
                    PlayerMapMarker._PinSet(it.icon, true, cp.X, cp.Y - 2, ts)
                  end
                  PlayerMapMarker._LabelSet(it, true, cp.X, cp.Y + (M.Font + 6) * ts + M.AmmoTextGap, ts)
                else
                  if it.icon then
                    PlayerMapMarker._PinSet(it.icon, false)
                  end
                  PlayerMapMarker._LabelSet(it, true, cp.X, cp.Y, ts)
                end
              end
            end
          end
        end
      end
    end
    M.free = M.free or {}
    for key, it in pairs(M.items) do
      if not seen[key] then
        PlayerMapMarker._LabelSet(it, false)
        if it.icon then
          PlayerMapMarker._PinSet(it.icon, false)
        end
        M.items[key] = nil
        if # M.free < M.MaxPool and it.w and slua.isValid(it.w) then
          M.free[ # M.free + 1] = it
        else
          M.items[key] = it;
          M.Remove(key)
        end
      end
    end
  end
  _G.HideWatermark = { t = 0, tBid = 0, badge = nil, logo = nil, canvas = nil, hidden = false }
  function _G.HideWatermark.Find(pc)
    local H = _G.HideWatermark
    if H.badge and _G.MWWidgetLive(H.badge) and H.logo and _G.MWWidgetLive(H.logo) then
      return true
    end
    H.badge, H.logo, H.canvas, H.hidden = nil, nil, nil, false
    local root = nil pcall(function()
      local ui = UIManager.GetUI(UIManager.UI_Config_InGame.Common_Logo_UIBP)
      root = ui and ui.UIRoot
    end)
    if not Valid(root) then
      pcall(function()
        local WBL = import("WidgetBlueprintLibrary")
        local UW = import("UserWidget")
        local arr = slua.Array(UEnums.EPropertyClass.Object, UW)
        WBL.GetAllWidgetsOfClass(pc, arr, UW, false)
        for _, uw in pairs(arr) do
          if uw and slua.isValid(uw) then
            local n = "";
            pcall(function()
              n = Game:GetPlainName(uw)
            end)
            if n and n:find("Common_Logo") then
              root = uw
              break
            end
          end
        end
      end)
    end
    if not Valid(root) then
      return false
    end
    local top = root.WidgetTree and root.WidgetTree.RootWidget
    local function walk(x, d)
      if not x or not slua.isValid(x) or d > 6 then
        return
      end
      local okc, n = pcall(function()
        return x:GetChildrenCount()
      end)
      if not okc or type(n) ~= "number" then
        return
      end
      for i = 0, n - 1 do
        local ok2, ch = pcall(function()
          return x:GetChildAt(i)
        end)
        if ok2 and ch then
          local nm = "";
          pcall(function()
            nm = Game:GetPlainName(ch)
          end)
          nm = tostring(nm or "")
          if nm == "18+" then
            H.badge = ch;
            H.canvas = x
          elseif nm == "ImageLogo" then
            H.logo = ch;
            H.canvas = x;
            H.logoParent = x
          end
          walk(ch, d + 1)
        end
      end
    end
    walk(top, 0)
    return (H.badge or H.logo) and true or false
  end
