      _G.MWConfig.MoveMenuBar = enabled
      local F = _G.FpsButton
      if F then
        if not enabled then
          F.TouchPolling = false
        end
        F.Visible = nil
        if F.Sync then
          pcall(F.Sync)
        end
      end
      return true
    end
    function D.PollLauncher(pc)
