      local cfg = _G.MWConfig or {}
      if not (cfg.MoveMenuBar == true or cfg.MoveMenuBar == 1) or not F.TouchPolling then
        return
      end
      if D.LauncherPC ~= pc then
        D.CancelLauncher();
        D.LauncherPC = pc
      end
      D.LauncherDown = D.LauncherDown or {}
      if not D.LauncherFinger and D.Active and D.Active.Kind == 'fps' and D.Active.PC == pc then
        D.LauncherFinger = { Index = D.Active.Index, Moved = D.Active.Moved == true }
