    local width = _G.OwenFPSHUD and _G.OwenFPSHUD.Width() or 120
    local w, h = width * scale, 33 * scale
    local drag = _G.OwenNeonUIDrag.Active
    if drag and drag.Kind == 'fps' then
      local x, y = _G.OwenNeonUIDrag.Clamp(_G.FpsButton.cx or drag.X, _G.FpsButton.cy or drag.Y, w, h, W, H)
      return x, y, w, h, scale
    end
    local cfg = _G.MWConfig
    local nx, ny = tonumber(cfg.FpsPosX) or - 1, tonumber(cfg.FpsPosY) or - 1
    local x = nx >= 0 and nx * math.max(0, W - w) or W * .19
    local y = ny >= 0 and ny * math.max(0, H - h) or H * .025 x, y = _G.OwenNeonUIDrag.Clamp(x, y, w, h, W, H)
    return x, y, w, h, scale
  end
  function _G.FpsButton.ReadFps(dt)
    local F = _G.FpsButton
    local fps pcall(function()
      if Client and type(Client.GetFPS) == "function" then
        fps = tonumber(Client.GetFPS())
      end
    end)
    if not fps or fps ~= fps or fps <= 0 or fps > 1000 then
      dt = tonumber(dt)
      if not dt or dt <= 0 or dt > 1 then
        pcall(function()
          local GS = import("GameplayStatics");
          local world = slua.getWorld()
          if GS and GS.GetWorldDeltaSeconds and world then
            dt = tonumber(GS.GetWorldDeltaSeconds(world))
          end
        end)
      end
      if ( not dt or dt <= 0 or dt > 1) and _G.OwenNeonFrameDT then
        dt = _G.OwenNeonFrameDT
      end
      if dt and dt > 0 and dt <= 1 then
        fps = 1 / dt
      else
        fps = F.fps
      end
    end
    F.fps = (fps and fps == fps and fps > 0 and fps <= 1000) and fps or 0
    return F.fps
  end
  function _G.FpsButton.CanOpenMenu()
    return tonumber((_G.MWConfig or {}).MenuMode) ~= 2
  end
  function _G.FpsButton.Enabled()
    return _G.FpsButton.CanOpenMenu() or (_G.OwenFPSHUD and _G.OwenFPSHUD.Enabled()) == true
  end
  function _G.FpsButton.SetVisible(enabled)
    local F = _G.FpsButton
    local drag = _G.OwenNeonUIDrag
    if not enabled and drag then
      if drag.Active and drag.Active.Kind == 'fps' then
        drag.Active = nil
      end
      if drag.Pending and drag.Pending.Kind == 'fps' then
        drag.Pending = nil
      end
      if drag.Consumed == 'fps' then
        drag.Consumed = nil
      end
    end
    if F.Visible == enabled and F.VisibilityWidget == F.txt and (_G.RealNow() - (F.VisibilityCheckAt or 0)) < 0.5 then
      return
    end
    local allOK = true
    local visibility = UEnums.ESlateVisibility
    local function show(widget, hit)
      if widget and slua.isValid(widget) then
        local fn = widget.SetVisibility or widget.SetWidgetVisibility
        local ok = type(fn) == "function" and pcall(fn, widget, enabled and (hit and visibility.Visible or visibility.HitTestInvisible) or visibility.Collapsed)
        if not ok then
          allOK = false
        end
      end
    end
    show(F.pill and F.pill.w, false);
    show(F.txt, false);
    show(F.btn, true)
    for _, out in ipairs(F.outs or {}) do
      show(out.w, false)
    end
    if not enabled and _G.OwenNeonUIDrag.CancelLauncher then
      _G.OwenNeonUIDrag.CancelLauncher()
    end
    if not enabled and F.Press then
      F.Press( false)
    end
    if allOK then
      F.Visible = enabled;
      F.VisibilityWidget = F.txt;
      F.VisibilityCheckAt = _G.RealNow()
    else
      F.Visible = nil;
      F.VisibilityWidget = nil;
      F.LastError = "fps_visibility_failed"
    end
  end
  function _G.FpsButton.Create(pc)
    local F = _G.FpsButton
    if not F.Enabled() then
      F.SetVisible( false);
      return false
    end
    if not PlayerMapMarker.InitESPCanvas() then
      F.LastError = "fps_canvas_not_ready";
      return false
    end
    local currentCanvas = PlayerMapMarker.ESPCanvas
    local function attached(widget)
      if not _G.MWWidgetLive(widget) then
        return false
      end
      local ok, parent = pcall(widget.GetParent, widget);
      return ok and parent == currentCanvas
    end
    if F.pill and attached(F.pill.w) and attached(F.txt) and attached(F.btn) then
      return true
    end
    local now = _G.RealNow()
    if F.NextCreate and now < F.NextCreate then
      return false
    end
    F.NextCreate = now + 0.5
    local function remove(widget)
      if widget then
        if PlayerMapMarker._ProtectedWidgetStrs then
          PlayerMapMarker._ProtectedWidgetStrs[tostring(widget)] = nil
        end
        pcall(function()
          widget:RemoveFromParent()
        end)
      end
    end
    local function cleanup()
      remove(F.pill and F.pill.w);
      remove(F.txt);
      remove(F.btn)
      for _, item in ipairs(F.outs or {}) do
        remove(item.w)
      end
      F.pill, F.btn, F.btnSlot, F.txt, F.txtSlot, F.outs, F.shownKey, F.lastStr = nil, nil, nil, nil, nil, nil, nil, nil
      F.Visible = nil;
      F.VisibilityWidget = nil
    end
    cleanup()
    local x0, y0, w, h, scale = F.LogoRect(pc)
    if not x0 then
      return false
    end
    if not PlayerMapMarker.InitESPCanvas() then
      return false
    end
    local canvas = PlayerMapMarker.ESPCanvas
    if not canvas or not Game:IsValid(canvas) then
      return false
    end
    F.pill = _G.MWIconImageAt(canvas, x0, y0, w, h, "fps_pill", 0, 0, 3)
    if not F.pill then
      pcall(function()
        local border = CGame:NewObjectFromPath("/Script/UMG.Border", canvas)
        assert(border and slua.isValid(border), "fps_border_creation_failed")
        local slot = canvas:AddChildToCanvas(border)
        if not slot then
          border:RemoveFromParent();
          error("fps_border_slot_failed")
        end
        F.pill = { w = border, slot = slot, key = "fps_fallback" }
        slot:SetAutoSize( false);
        slot:SetPosition(FVector2D(x0, y0));
        slot:SetSize(FVector2D(w, h));
        slot:SetAlignment(FVector2D(0, 0));
        slot:SetZOrder(3)
        border:SetBrushColor(FLinearColor(0.025, 0.04, 0.08, 0.95))
        PlayerMapMarker._ProtectedWidgetStrs = PlayerMapMarker._ProtectedWidgetStrs or {} PlayerMapMarker._ProtectedWidgetStrs[tostring(border)] = true
      end)
    end
    if not F.pill then
      F.LastError = "fps_background_creation_failed";
      cleanup();
      return false
    end
    pcall(function()
      F.pill.w:SetWidgetVisibility(UEnums.ESlateVisibility.HitTestInvisible)
    end)
    local SC = F.Scale * scale
    local tx0, ty0 = x0 + w * 0.5, y0 + h * 0.5
    local function mkText(x, y, lc, z)
      local t = nil pcall(function()
        t = CGame:NewObjectFromPath("/Script/UMG.TextBlock", canvas)
      end)
      if not (t and slua.isValid(t)) then
        return nil
      end
      local slot = nil pcall(function()
        slot = canvas:AddChildToCanvas(t)
      end)
      if not slot then
        pcall(function()
          t:RemoveFromParent()
        end);
        return nil
      end
      if slot then
        pcall(function()
          slot:SetAutoSize( true)
        end)
        pcall(function()
          slot:SetPosition(FVector2D(x, y))
        end)
        pcall(function()
          slot:SetAlignment(FVector2D(0.5, 0.5))
        end)
        pcall(function()
          slot:SetZOrder(z)
        end)
      end
      pcall(function()
        t:SetRenderTransformPivot(FVector2D(0.5, 0.5))
      end)
      pcall(function()
        t:SetRenderScale(FVector2D(SC, SC))
      end)
      F.SC = SC pcall(function()
        local FSlateColor = import("SlateColor") or import("/Script/SlateCore.SlateColor")
        if FSlateColor then
          local color = FSlateColor(lc);
          pcall(function()
            color.SpecifiedColor = lc;
            color.ColorUseRule = 0
          end);
          t:SetColorAndOpacity(color)
        else
          t:SetColorAndOpacity(lc)
        end
      end)
      pcall(function()
        t:SetWidgetVisibility(UEnums.ESlateVisibility.HitTestInvisible)
      end)
      if not PlayerMapMarker._ProtectedWidgetStrs then
        PlayerMapMarker._ProtectedWidgetStrs = {}
      end
      PlayerMapMarker._ProtectedWidgetStrs[tostring(t)] = true
      return { w = t, slot = slot }
    end
    local main = mkText(tx0, ty0, FLinearColor(1.0, 1.0, 1.0, 1.0), 5)
    if not main then
      F.LastError = "fps_text_creation_failed";
      cleanup();
      return false
    end
    _G.MWTextOutline(main.w, 1)
    pcall(function()
      main.w:SetShadowColorAndOpacity(FLinearColor(0, 0, 0, 0.8))
    end)
    pcall(function()
      main.w:SetShadowOffset(FVector2D(1, 1))
    end)
    F.txt = main.w;
    F.txtSlot = main.slot
    F.outs = {} pcall(function()
      local FLinearColor = import("LinearColor") or FLinearColor
      local FSlateColor = import("SlateColor") or import("/Script/SlateCore.SlateColor")
      local btn = CGame:NewObjectFromPath("/Script/UMG.Button", canvas)
      if not btn or not slua.isValid(btn) then
        return
      end
      local transparent = FLinearColor(0, 0, 0, 0)
      pcall(function()
        btn:SetBackgroundColor(transparent)
      end)
      pcall(function()
        btn.WidgetStyle.Normal.TintColor = FSlateColor(transparent)
      end)
      pcall(function()
        btn.WidgetStyle.Hovered.TintColor = FSlateColor(transparent)
      end)
      pcall(function()
        btn.WidgetStyle.Pressed.TintColor = FSlateColor(transparent)
      end)
      pcall(function()
        btn:SetBrushColor(transparent)
      end)
      pcall(function()
        btn.bIsFocusable = false
      end)
      pcall(function()
        btn.IsFocusable = false
      end)
      btn.OnClicked:Add(function()
        if not F.Enabled() or not F.CanOpenMenu() then
          return
        end
        if F.TouchPolling then
          _G.OwenNeonUIDrag.ClickLauncher(pc, true);
          return
        end
        if _G.OwenNeonUIDrag.Consumed == 'fps' then
          _G.OwenNeonUIDrag.Consumed = nil;
          return
        end
        pcall(function()
          if _G.OwenNeonMenus then
            _G.OwenNeonMenus.Toggle(pc)
          end
        end)
      end)
      btn.OnPressed:Add(function()
        if not F.Enabled() then
          return
        end;
        F.Press( true);
        if not (_G.MWConfig.MoveMenuBar == true or _G.MWConfig.MoveMenuBar == 1) then
          _G.OwenNeonUIDrag.Consumed = nil;
          return
        end;
        _G.OwenNeonUIDrag.Begin('fps', pc, F.cx or x0, F.cy or y0, F.cw or w, F.ch or h)
      end)
      btn.OnReleased:Add(function()
        if _G.MWConfig.MoveMenuBar == true or _G.MWConfig.MoveMenuBar == 1 then
          _G.OwenNeonUIDrag.Release('fps')
        end;
        F.Press( false)
      end)
      local slot = canvas:AddChildToCanvas(btn)
      if slot then
        pcall(function()
          slot:SetAutoSize( false)
        end)
        pcall(function()
          slot:SetPosition(FVector2D(x0 - 4 * scale, y0 - 4 * scale))
        end)
        pcall(function()
          slot:SetSize(FVector2D(w + 8 * scale, h + 8 * scale))
        end)
        pcall(function()
          slot:SetZOrder(1000)
        end)
      end
      pcall(function()
        btn:SetWidgetVisibility(UEnums.ESlateVisibility.Visible)
      end)
      F.btn, F.btnSlot = btn, slot
      if not PlayerMapMarker._ProtectedWidgetStrs then
        PlayerMapMarker._ProtectedWidgetStrs = {}
      end
      PlayerMapMarker._ProtectedWidgetStrs[tostring(btn)] = true
    end)
    F.cx, F.cy, F.cw, F.ch, F.scale = x0, y0, w, h, scale pcall(function()
      F.txt:SetText("OWEN")
    end)
    if not attached(F.btn) then
      F.LastError = "fps_button_creation_failed";
      cleanup();
      return false
    end
    F.LastError = nil;
    F.NextCreate = nil;
    F.Visible = nil;
    F.VisibilityWidget = nil
    return true
  end
  function _G.FpsButton.Sync()
    _G.FpsButton.SetVisible(_G.FpsButton.Enabled())
  end
  function _G.FpsButton.Press(p)
    local F = _G.FpsButton
    local sc = p and 1.08 or 1.0
    local function sc1(w, base, px, py)
      pcall(function()
        if w and slua.isValid(w) then
          w:SetRenderTransformPivot(FVector2D(px, py))
          w:SetRenderScale(FVector2D(base * sc, base * sc))
        end
      end)
    end
    if F.pill then
      sc1(F.pill.w, 1.0, 0.5, 0.5)
    end
    local base = F.SC or 1.0 sc1(F.txt, base, 0.5, 0.5)
    for _, o in ipairs(F.outs or {}) do
      sc1(o.w, base, 0, 0.5)
    end
  end
  function _G.FpsButton.Tick(pc, dt)
    local F = _G.FpsButton
    local movable = _G.MWConfig.MoveMenuBar == true or _G.MWConfig.MoveMenuBar == 1
    local touch = movable and type(pc.GetInputTouchState) == 'function'
    if F.TouchPolling ~= touch then
      if not touch then
        _G.OwenNeonUIDrag.CancelLauncher()
      end
      F.TouchPolling = touch;
      F.Visible = nil
    end
    if not F.Enabled() then
      F.SetVisible( false);
      return
    end
    if not F.Create(pc) then
      return
    end
    F.Sync()
    if F.TouchPolling then
      _G.OwenNeonUIDrag.PollLauncher(pc)
    end
    local now = _G.RealNow()
    if now - (F.t or 0) >= 0.5 then
      F.t = now
      local x0, y0, w, h, scale = F.LogoRect(pc)
      if x0 and (math.abs(x0 - F.cx) > 0.5 or math.abs(y0 - F.cy) > 0.5 or math.abs(w - F.cw) > 0.5 or math.abs(h - F.ch) > 0.5) then
        F.cx, F.cy, F.cw, F.ch, F.scale = x0, y0, w, h, scale pcall(function()
          F.pill.slot:SetPosition(FVector2D(x0, y0));
          F.pill.slot:SetSize(FVector2D(w, h))
        end)
        local tx0, ty0 = x0 + w * 0.5, y0 + h * 0.5 pcall(function()
          F.txtSlot:SetPosition(FVector2D(tx0, ty0))
        end)
        local SC = F.Scale * scale
        F.SC = SC pcall(function()
          F.txt:SetRenderScale(FVector2D(SC, SC))
        end)
        for _, ot in ipairs(F.outs or {}) do
          pcall(function()
            ot.w:SetRenderScale(FVector2D(SC, SC))
          end)
          ot.dx, ot.dy = (ot.dx < 0 and - 1 or (ot.dx > 0 and 1 or 0)) * SC, (ot.dy < 0 and - 1 or (ot.dy > 0 and 1 or 0)) * SC pcall(function()
            ot.slot:SetPosition(FVector2D(tx0 + ot.dx, ty0 + ot.dy))
          end)
        end
        pcall(function()
          F.btnSlot:SetPosition(FVector2D(x0 - 4 * scale, y0 - 4 * scale));
          F.btnSlot:SetSize(FVector2D(w + 8 * scale, h + 8 * scale))
        end)
      end
    end
    if now < (F.NextTextAt or 0) then
      return
    end
    F.NextTextAt = now + 0.25
    local str = _G.OwenFPSHUD.Text()
    if str ~= F.lastStr then
      local ok, result = pcall(function()
        return F.txt:SetText(str)
      end)
      if ok and result ~= false then
        F.lastStr = str
      end
      for _, ot in ipairs(F.outs or {}) do
        if slua.isValid(ot.w) then
          pcall(function()
            ot.w:SetText(str)
          end)
        end
      end
    end
  end
  _G.OwenFPSHUD = {}
  do
    local H = _G.OwenFPSHUD
    function H.Enabled()
      local cfg = _G.MWConfig or {}
      return cfg.FPSPingHUD == true or cfg.FPSPingHUD == 1
    end
    function H.Stop()
      H.Next = nil;
      H.Value = nil;
      H.LastText = nil
    end
    function H.Text()
      if not H.Enabled() then
        return 'DevLet'
      end
      return 'DevLet| FPS: ' .. (H.Value and tostring(math.floor(H.Value + 0.5)) or '--')
    end
    function H.Width()
      if not H.Enabled() then
        return 120
      end
      local F = _G.FpsButton or {}
      local width = # H.Text() * 20
      if F.lastStr == H.Text() and F.txt then
        pcall(function()
          local measured = tonumber(F.txt:GetDesiredSize().X)
          if measured and measured > 0 then
            width = measured
          end
        end)
      end
      return math.max(240, math.ceil(48 + width * (F.Scale or .55)))
    end
    function H.Tick(pc, dt)
      if not H.Enabled() then
        if H.Next or H.Value then
          H.Stop()
        end
        return
      end
      local now = _G.RealNow()
      if now < (H.Next or 0) then
        return
      end
      H.Next = now + .25
      local sample = _G.FpsButton.ReadFps(dt)
      if sample and sample == sample and sample > 0 and sample <= 1000 then
        H.Value = H.Value and H.Value * .7 + sample * .3 or sample
      end
      H.LastText = H.Text()
    end
  end
