  local function LMlin(c)
    if c <= 0.04045 then
      return c / 12.92
    end
    return ((c + 0.055) / 1.055) ^ 2.4
  end
  local function LMcol(c)
    return FLinearColor(LMlin(c[1]), LMlin(c[2]), LMlin(c[3]), c[4])
  end
  local function LMslate(c)
    local FSlateColor = import("SlateColor") or import("/Script/SlateCore.SlateColor")
    local lc = LMcol(c)
    if FSlateColor then
      return FSlateColor(lc)
    end
    return lc
  end
  function LM.OpenCollection()
    if not _G.OwenNeonLobbySceneAllowed or not _G.OwenNeonLobbySceneAllowed() then
      return false
    end
    if not _G.MWConfig.CollectionHallUnlock then
      return
    end
    _G.OwenCollectionOpenRequested = true
    if _G.OwenInstallCollectionHall then
      _G.OwenInstallCollectionHall()
    end
  end
  function LM.Rows()
    if _G.OwenNeonMenus and _G.OwenNeonMenus.InstallV33Rows then
      _G.OwenNeonMenus.InstallV33Rows()
    end
    if not _G.MWMenuRows and _G._ModMenuDef then
      _G.MWMenuRows = {}
      for _, cat in ipairs(_G._ModMenuDef.Category or {}) do
        for _, row in ipairs(cat.Stack or {}) do
          if row.Key then
            _G.MWMenuRows[row.Key] = row
          end
        end
      end
    end
    return _G.MWMenuRows
  end
  function LM.UIType(R)
    local ok, AM = pcall(require, "client.slua.umg.NewSetting.Item.AliasMap")
    if ok and AM then
      if R.UI == AM.TitleSwitcher then
        return "title"
      end
      if R.UI == AM.Slider then
        return "slider"
      end
    end
    if R.MinValue ~= nil and R.MaxValue ~= nil then
      return "slider"
    end
    if R.ExpandIndex ~= nil then
      return "title"
    end
    return "switch"
  end
