  function LM.DisplayLabel(key, fallback)
    local names = LM.DisplayNames[key]
    local lang = tonumber((_G.MWConfig or {}).MenuLanguage) or 1
    if names and lang ~= 3 then
      return lang == 2 and names[2] or names[1]
    end
    return LM.Translate(fallback)
  end
  function LM.Label(key)
    local R = LM.Rows() and LM.Rows()[key]
    if not R then
      return key
    end
    local t = R.Text
    if type(t) == "number" then
      t = (_G._FakeTextMap and _G._FakeTextMap[t]) or tostring(t)
    end
    return LM.DisplayLabel(key, t)
  end
  function LM.OptLabel(id)
    return LM.Translate(type(id) == "number" and ((_G._FakeTextMap or {})[id] or tostring(id)) or id)
  end
  function LM.Lang()
    return (_G.MWConfig or {}).MenuLanguage ~= 2
  end
