  function LM.Translate(text)
    local label = tostring(text)
    local key = LM.TranslationAliases[label] or label
    local pair = LM.Translations[key]
    local lang = tonumber((_G.MWConfig or {}).MenuLanguage) or 1
    return pair and (lang == 2 and pair[1] or lang == 3 and pair[2]) or LM.EnglishLabels[key] or label
  end
