      rs = canvas:AddChildToCanvas(root)
    end)
    local nx, ny = tonumber(_G.MWConfig.MenuPosX) or - 1, tonumber(_G.MWConfig.MenuPosY) or - 1
    local x = nx >= 0 and nx * math.max(0, W - mw) or (W - mw) * .5
    local y = ny >= 0 and ny * math.max(0, H - mh) or (H - mh) * .5 x, y = _G.OwenNeonUIDrag.Clamp(x, y, mw, mh, W, H)
    LM.X, LM.Y, LM.ViewW, LM.ViewH = x, y, W, H
    if rs then
      pcall(function()
        rs:SetAutoSize( false);
        rs:SetPosition(FVector2D(x, y));
        rs:SetSize(FVector2D(mw, mh));
        rs:SetZOrder(1200)
      end)
    end
    LM.Protect(root)
    LM.root, LM.rootSlot = root, rs LM.RoundRect(7, 7, 1090, 664, 22, LM.C.win, 1, LM.items)
    LM.Button(0, 0, 1104, 678, 3, LM.items, function()
    end)
    LM.RoundRect(18, 18, 190, 642, 17, LM.C.side, 4, LM.items, true)
    LM.Rect(208, 18, 2, 642, LM.C.line, 5, LM.items)
    LM.FrameBorder()
