    LM.Text("DevLet EDITION", 26, 598, 13, LM.C.navText, 0, 0, 6, LM.items)
    LM.Text(LM.ExpireText(), 26, 633, 12, LM.C.cyan, 0, 0, 6, LM.items)
    LM.Rect(26, 580, 156, 2, LM.C.line, 5, LM.items)
    do
      local xs = 30
      local xx, xy = 1104 - 32 - xs, (63 - xs) * 0.5 + 10
      local xi = LM.Img("ui_close", xx, xy, xs, xs, nil, 6, LM.items)
      LM.Button(xx - 8, xy - 8, xs + 16, xs + 16, 12, LM.items, function()
