  function LM.BuildNav()
    LM.Clear(LM.nav)
    for i, sec in ipairs(LM.Layout) do
      local y = 216 + (i - 1) * 72;
      local on = i == LM.sec
      if on then
        LM.RoundRect(16, y, 176, 56, 14, LM.C.navOn, 4, LM.nav);
        LM.Rect(16, y + 12, 3, 32, LM.C.cyan, 5, LM.nav)
      end
      LM.Text(string.format("%02d", i), 30, y + 28, 14, on and LM.C.cyan or LM.C.tabText, 0, 0.5, 6, LM.nav)
      LM.Text(sec.name, 72, y + 28, 20, on and LM.C.logoWhite or LM.C.navText, 0, 0.5, 6, LM.nav)
      LM.Button(16, y, 176, 56, 10, LM.nav, function()
        LM.sec = i;
        LM.tab = 1;
        LM.ViewPage = 1;
        LM.BuildNav();
        LM.BuildTabs();
        LM.BuildContent()
      end)
    end
  end
  LM.tabs = {}
  function LM.BuildTabs()
    LM.Clear(LM.tabs)
    local sec = LM.Layout[LM.sec];
    local tw = math.min(172, 826 / # sec.tabs)
    LM.Text(sec.name, 236, 29, 28, LM.C.logoWhite, 0, 0, 6, LM.tabs)
    for i, tab in ipairs(sec.tabs) do
      local x = 236 + (i - 1) * tw;
      local on = i == LM.tab LM.RoundRect(x, 101, tw - 8, 48, 4, LM.C.line, 3, LM.tabs)
      LM.RoundRect(x + 2, 103, tw - 12, 44, 3, on and LM.C.navOn or LM.C.win, 4, LM.tabs)
      if on then
        LM.Rect(x, 101, tw - 8, 46, LM.C.navOn, 4, LM.tabs);
        LM.Rect(x, 146, tw - 8, 3, LM.C.cyan, 5, LM.tabs)
      end
      LM.Text(LM.Lang() and tab.en or tab.vn, x + (tw - 8) * 0.5, 124, math.min(18, math.max(12, tw / 8)), on and LM.C.cyan or LM.C.tabText, 0.5, 0.5, 6, LM.tabs)
      LM.Button(x, 101, tw - 8, 48, 10, LM.tabs, function()
        LM.tab = i;
        LM.ViewPage = 1;
        LM.BuildTabs();
        LM.BuildContent()
      end)
    end
  end
  LM.RowH, LM.Font, LM.Check, LM.TitleH, LM.SliderH = 40, 18, 24, 34, 72
  LM.InfoLH = 26
  function LM.DeviceInfo()
    local ok, list = pcall(LM.DeviceInfoRaw)
    if ok and type(list) == "table" and # list > 0 then
      return list
    end
    local plat, model, osv = "", "", "" pcall(function()
      plat = tostring(Client.GetDevicePlatformName())
    end)
    pcall(function()
      model = tostring(Client.GetDeviceModel())
    end)
    pcall(function()
      osv = tostring(Client.GetOSVersion())
    end)
    return {
{ "Device", model },
{ "System", plat .. " " .. osv },
{ "Info", "Error: " .. tostring(list):sub(1, 28) }
    }
  end
  function LM.DeviceInfoRaw()
    local function raw(fn)
      local r = nil pcall(function()
        if Client and type(Client[fn]) == "function" then
          r = Client[fn]()
        end
      end)
      return r
    end
    local function g(fn)
      local r = raw(fn)
      if r == nil then
        return ""
      end
      r = tostring(r)
      if r == "nil" then
        return ""
      end
      return r
    end
    local function num(fn)
      return tonumber(raw(fn))
    end
    local function yn(fn)
      local r = raw(fn);
      if r == nil then
        return ""
      end
      return r and "Yes" or "No"
    end
    local function orU(v)
      if v == nil or v == "" then
        return "Unknown"
      end
      return v
    end
    local function mb(v, unit)
      if not v then
        return ""
      end
      if unit == "GB" then
        return string.format("%.1f GB", v / 1024)
      end
      return string.format("%d MB", math.floor(v))
    end
    local plat, model, name, make = g("GetDevicePlatformName"), g("GetDeviceModel"), g("GetDeviceName"), g("GetDeviceMake")
    local osv, app = g("GetOSVersion"), g("GetAppVersion")
    local dev = model ~= "" and model or name
    if plat == "Android" and make ~= "" and dev ~= "" and not dev:lower():find(make:lower(), 1, true) then
      dev = make .. " " .. dev
    end
    if dev == "" then
      dev = "Unknown"
    end
    local sysName = plat
    if plat == "IOS" then
      sysName = dev:find("^iPad") and "iPadOS" or "iOS"
    end
    if sysName == "" then
      sysName = "Unknown"
    end
    local isAndroid = (plat == "Android")
    local cores, hz = num("GetCPUCoreCount"), num("GetCPUMaxFrequency")
    local cpu = g("GetCpuType")
    local cpuLine = cpu
    if cores then
      cpuLine = (cpuLine ~= "" and (cpuLine .. " ") or "") .. math.floor(cores) .. " cores"
    end
    if hz and hz > 0 then
      cpuLine = cpuLine .. string.format(" @ %.2f GHz", hz / 1e9)
    end
    local usedMB = nil pcall(function()
      local st = raw("GetMemoryStats");
      if st and st.UsedPhysical then
        usedMB = st.UsedPhysical / 1024 / 1024
      end
    end)
    local ram = num("GetMemorySize")
    local ramLine = ram and mb(ram, "GB") or ""
    if usedMB then
      ramLine = ramLine .. (ramLine ~= "" and " / " or "") .. string.format("used %d MB", math.floor(usedMB))
    end
    local gl = g("GetGLType");
    local glv = g("GetGLVersion")
    local gfx = gl .. ((glv ~= "" and glv ~= gl) and (" " .. glv) or "")
    local notch = "" pcall(function()
      local n = raw("GetNotchSize")
      if type(n) == "table" then
        local t = {}
        for i = 1, math.min( # n, 4) do
          t[ # t + 1] = tostring(math.floor(tonumber(n[i]) or 0))
        end
        notch = table.concat(t, " / ")
      elseif n ~= nil then
        notch = tostring(n)
      end
    end)
    local carrier = g("GetTelecomSvr")
    if carrier == "" then
      carrier = g("GetOperator")
    end
    if carrier == "" then
      local cj = g("GetCarrierInfo")
      if cj ~= "" then
        carrier = cj
      end
    end
    local emu = yn("IsEmulator")
    local emuName = g("GetEmulatorName")
    if emu == "Yes" and emuName ~= "" then
      emu = "Yes (" .. emuName .. ")"
    end
    local lang = g("GetCurrentLanguage");
    local sysLang = g("GetSystemLanguage")
    local langLine = lang
    if sysLang ~= "" and sysLang ~= lang then
      langLine = langLine .. " / sys " .. sysLang
    end
    local sw, sh = num("GetScreenWidth"), num("GetScreenHight")
    local pw, ph = num("GetPhysicalScreenWidth"), num("GetPhysicalScreenHeight")
    local lvl = g("GetTCDeviceLevel");
    local exact = g("GetExactDeviceLevel")
    local lvlLine = lvl
    if exact ~= "" and exact ~= lvl then
      lvlLine = lvlLine .. " / " .. exact
    end
    local list = {
{ "Device", dev },
{ "Nick Name", orU(g("GetDeivceNickName")) },
{ "Hardware", orU(g("GetPhoneType")) },
{ "System", sysName .. (osv ~= "" and (" " .. osv) or "") },
{ "Version", orU(app) },
{ "Language", orU(langLine) },
{ "CPU", orU(cpuLine) },
{ "GPU", orU(g("GetGPUFamily")) },
{ "RAM", orU(ramLine) },
{ "Free Space", orU(mb(num("GetDeviceFreeSpace"), "GB")) },
{ "Graphics", orU(gfx) },
{ "Vulkan", orU(yn("IsSupportVulkan")) },
{ "Dev Level", orU(lvlLine) },
{ "Quality", orU(g("GetDeviceQualityLevel")) },
{ "Low Memory", orU(yn("IsLowMemoryDevice")) },
{ "Screen", (sw and sh) and (math.floor(sw) .. " x " .. math.floor(sh)) or "Unknown" },
{ "Physical", (pw and ph) and (math.floor(pw) .. " x " .. math.floor(ph)) or "Unknown" },
{ "Density", orU(g("GetScreenDensity")) },
{ "Notch", orU(notch) },
{ "Network", orU(g("GetNetWorkType")) },
{ "Local IP", orU(g("GetIpAddr")) },
{ "IP Region", orU(g("GetIPRegion")) },
{ "Region", orU(g("GetPublishRegion")) },
{ "Carrier", orU(carrier) },
{ "VPN", orU(yn("GetIsPlayerUsingVPN")) },
{ "Time Zone", orU(g("GetTimezoneName")) },
{ "Server IP", orU(g("GetDSConnectionIP")) },
{ "Emulator", orU(emu) },
{ "Gyroscope", orU(yn("IsDeviceSupportGyrSensor")) },
{ "Bluetooth", orU(yn("IsUsingBluetooth")) },
{ "Device ID", orU(g("GetPhoneDeviceID")) },
{ "Ad ID", orU(g("GetPhoneAdvertisingID")) },
{ "XID", orU(g("GetDeviceXID")) },
{ "Login", orU(g("GetLoginChannel")) },
{ "Game Mode", orU(g("GetGameModeID")) },
    }
    if isAndroid then
      list[ # list + 1] = { "Android SO", orU(g("GetAndroidSOVersion")) }
      list[ # list + 1] = { "Google Svc", orU(g("GetGoogleServiceVersionCode")) }
    end
    for _, li in ipairs(list) do
      local v = tostring(li[2])
      if # v > 24 then
        v = v:sub(1, 24)
      end
      li[2] = v
    end
    return list
  end
  function LM.BuildContent()
    LM.CloseDrop();
    LM.Clear(LM.content);
    LM.drag = nil
    local tab = LM.Layout[LM.sec].tabs[LM.tab];
    local pages = {
{}
    };
    local used = 0;
    local col = 0
    local function add(item)
      if used + item.H > 446 then
        used = 0;
        if col == 0 then
          col = 1
        else
          pages[ # pages + 1] = {};
          col = 0
        end
      end
      item.Col = col;
      item.Y = used;
      pages[ # pages][ # pages[ # pages] + 1] = item;
      used = used + item.H
    end
    local info = LM.DeviceInfo;
    local infoList
    for _, key in ipairs(tab.keys) do
      local row = LM.Rows() and LM.Rows()[key];
      local h
      if key:sub(1, 7) == '_title:' then
        h = 34
      elseif key:sub(1, 6) == '_info:' then
        infoList = infoList or info()
        for _, li in ipairs(infoList) do
          add( { Info = li, H = 36 })
        end
      elseif key:sub(1, 5) == '_btn:' then
        h = 48
      elseif row then
        h = (LM.UIType(row) == 'slider' or row.SwitcherText) and 84 or 64
      end
      if h then
        add( { Key = key, Row = row, H = h })
      end
    end
    LM.PageCount = # pages;
    LM.ViewPage = math.max(1, math.min(LM.ViewPage or 1, # pages))
    local x, y, cw = 236, 166, 410
    for _, item in ipairs(pages[LM.ViewPage]) do
      x = 236 + (item.Col or 0) * 430;
      y = 166 + (item.Y or 0)
      local key, row = item.Key, item.Row
      if item.Info then
        LM.Rect(x, y, cw, 32, LM.C.card, 3, LM.content)
        LM.Text(item.Info[1], x + 12, y + 16, 16, LM.C.tabText, 0, 0.5, 6, LM.content)
        LM.Text(tostring(item.Info[2]), x + cw - 12, y + 16, 16, LM.C.rowText, 1, 0.5, 6, LM.content)
      elseif key:sub(1, 7) == '_title:' then
        LM.Text(key:sub(8), x, y + 17, 14, LM.C.cyan, 0, 0.5, 6, LM.content)
      elseif key:sub(1, 5) == '_btn:' then
        local id, label = key:sub(6):match('^(.-)|(.*)$')
        LM.Rect(x, y, 240, 38, LM.C.navOn, 4, LM.content)
        LM.Text(label or key:sub(6), x + 120, y + 19, 17, LM.C.cyan, 0.5, 0.5, 6, LM.content)
        LM.Button(x, y, 240, 38, 10, LM.content, function()
          if id == 'unlock_vip' then
            _G.OwenTrialAccess.OpenUnlock()
          elseif id == 'feedback_status' and _G.OwenAutoFeedback then
            _G.OwenAutoFeedback.ShowStatus()
          elseif id == 'reset' and _G.MWResetSettings then
            _G.MWResetSettings();
            LM.BuildContent()
          elseif id == 'collection' then
            LM.OpenCollection()
          end
        end)
      elseif row then
        local master = key == tab.master or (tab.headers and tab.headers[key]) or LM.UIType(row) == "title" or key:match("_Ex$") or key == "ModMenu_ModSkin" or key == "ModMenu_ModEmote" LM.RoundRect(x, y, cw, item.H - 8, 6, LM.C.line, 3, LM.content)
        LM.RoundRect(x + 2, y + 2, cw - 4, item.H - 12, 4, master and LM.C.navOn or LM.C.card, 4, LM.content)
        if master then
          LM.Rect(x, y, 4, item.H - 4, LM.C.violet, 4, LM.content)
        end
        if LM.UIType(row) == 'slider' then
          LM.RowSlider(row, key, x + 14, y + 7, cw - 28, 1)
        elseif row.SwitcherText then
          LM.RowDrop(row, key, x + 14, y + 7, cw - 28, 1)
        else
          LM.RowCheck(row, key, x + 14, y + 7, cw - 28, 1)
        end
      end
      y = y + item.H
    end
    LM.Text(string.format("%02d / %02d", LM.ViewPage, # pages), 656, 645, 14, LM.C.tabText, 0.5, 0.5, 6, LM.content)
    if # pages > 1 then
      LM.Text("< PREV", 236, 645, 15, LM.C.navText, 0, 0.5, 6, LM.content)
      LM.Text("NEXT >", 1076, 645, 15, LM.C.navText, 1, 0.5, 6, LM.content)
      LM.Button(236, 626, 110, 38, 10, LM.content, function()
        LM.ViewPage = math.max(1, LM.ViewPage - 1);
        LM.BuildContent()
      end)
      LM.Button(966, 626, 110, 38, 10, LM.content, function()
        LM.ViewPage = math.min( # pages, LM.ViewPage + 1);
        LM.BuildContent()
      end)
    end
  end
  function LM.RowCheck(R, key, x, y, cw, f)
    local function enabled()
      local v;
      pcall(function()
        v = R.GetFunc()
      end);
      return v == true or v == 1
    end
    LM.Text(LM.Label(key), x, y + 20, 16, LM.C.rowText, 0, 0.5, 6, LM.content)
    local track, thumb
    local function paint()
      LM.FxRemove(track);
      LM.FxRemove(thumb)
      local on = enabled()
      track = LM.RoundRect(x + cw - 58, y + 9, 54, 26, 12, on and LM.C.cyan or LM.C.track, 5, LM.content)
      thumb = LM.RoundRect(x + cw - 58 + (on and 32 or 3), y + 12, 19, 19, 9, on and LM.C.white or LM.C.knob, 6, LM.content)
      LM.content[ # LM.content + 1] = track;
      LM.content[ # LM.content + 1] = thumb
    end
    paint()
    LM.Button(x, y, cw, 40, 10, LM.content, function()
      local value = not enabled();
      if LM.SetToggle then
        LM.SetToggle(R, key, value)
      else
        R.SetFunc( nil, value)
      end;
      LM.BuildContent()
    end)
  end
  function LM.RowDrop(R, key, x, y, cw, f)
    f = f or 1
    local vals, texts = R.SwitcherValue or {}, R.SwitcherText or {}
    local function idx()
      local cur = nil;
      pcall(function()
        cur = R.GetFunc()
      end)
      for i, v in ipairs(vals) do
        if v == cur then
          return i
        end
      end
      return 1
    end
    local pw, ph = cw, 32 * f
    local rh = LM.RowH * f LM.Text(LM.Label(key), x, y + 9 * f, 16 * f, LM.C.rowText, 0, 0.5, 6, LM.content)
    y = y + 27 * f
    local py = y + (rh - ph) * 0.5
    local bw = 1.5 / LM.k
    local aw = ph LM.Rect(x, py, pw, ph, LM.C.comboEdge, 5, LM.content)
    LM.Rect(x + bw, py + bw, pw - 2 * bw, ph - 2 * bw, LM.C.comboBg, 6, LM.content)
    LM.Rect(x + pw - aw + bw, py + bw, aw - 2 * bw, ph - 2 * bw, LM.C.comboArrowBg, 6, LM.content)
    LM.Rect(x + pw - aw, py + bw, bw, ph - 2 * bw, LM.C.comboEdge, 7, LM.content)
    local asz = 13 * f LM.Img("ui_arrow", x + pw - aw + (aw - asz) * 0.5, py + (ph - asz) * 0.5, asz, asz, LM.C.rowText, 7, LM.content)
    local txt = LM.Text(LM.OptLabel(texts[idx()]), x + 10 * f, y + rh * 0.5, 19 * f, LM.C.pillText, 0, 0.5, 8, LM.content)
    LM.Button(x, y, pw, rh, 10, LM.content, function()
      LM.OpenDrop(R, vals, texts, idx, txt, x, y, pw, rh, f)
    end)
  end
  LM.drop = LM.drop or {}
  function LM.CloseDrop()
    if LM.drop and # LM.drop > 0 then
      LM.Clear(LM.drop)
    end
    LM.drop = {}
  end
  function LM.OpenDrop(R, vals, texts, idx, txt, x, y, pw, rh, f)
    LM.CloseDrop()
    local n = # vals
    if n == 0 then
      return
    end
    local itemH = 34 * f
    local pad = 5 * f
    local panelH = n * itemH + pad * 2
    local panelY = y + rh + 2 * f
    if panelY + panelH > 678 - 12 then
      panelY = y - 2 * f - panelH
    end
    local cur = idx()
    LM.Button(0, 0, 1104, 678, 40, LM.drop, function()
      LM.CloseDrop()
    end)
    local bw = 1.5 / LM.k LM.Rect(x, panelY, pw, panelH, LM.C.dropEdge, 44, LM.drop)
    LM.Rect(x + bw, panelY + bw, pw - 2 * bw, panelH - 2 * bw, LM.C.dropBg, 45, LM.drop)
    for i = 1, n do
      local iy = panelY + pad + (i - 1) * itemH
      local isCur = (i == cur)
      if isCur then
        LM.Rect(x + 4 * f, iy + 2 * f, pw - 8 * f, itemH - 4 * f, LM.C.navOn, 46, LM.drop)
      end
      local it = LM.Text(LM.OptLabel(texts[i]), x + 16 * f, iy + itemH * 0.5, 18 * f, isCur and LM.C.cyan or LM.C.rowText, 0, 0.5, 47, LM.drop)
      local hl = nil LM.Button(x, iy, pw, itemH, 48, LM.drop, function()
        pcall(R.SetFunc, nil, vals[i])
        if txt then
          pcall(function()
            txt.w:SetText(LM.OptLabel(texts[idx()]))
          end)
        end
        LM.CloseDrop()
        if R.Key == "ModMenu_AimProfileGroup" then
          LM.BuildContent()
        end
        if R.Key == "ModMenu_MenuLanguage" and type(_G.OwenRefreshMenuLanguage) ~= "function" then
          LM.BuildNav();
          LM.BuildTabs();
          LM.BuildContent()
        end
      end, function()
        pcall(function()
          if it and it.w then
            it.w:SetColorAndOpacity(LMslate(LM.C.cyan))
          end
        end)
        hl = LM.Rect(x + 4 * f, iy + 2 * f, pw - 8 * f, itemH - 4 * f, LM.C.navOn, 46, LM.drop)
      end, function()
        pcall(function()
          if it and it.w and not isCur then
            it.w:SetColorAndOpacity(LMslate(LM.C.rowText))
          end
        end)
        if hl and hl.w and slua.isValid(hl.w) then
          pcall(function()
            hl.w:RemoveFromParent()
          end)
        end
      end)
    end
  end
  function LM.RowSlider(R, key, x, y, cw, f)
    f = f or 1
    local mn, mx = R.MinValue or 0, R.MaxValue or 100
    local function getv()
      local v = mn;
      pcall(function()
        v = R.GetFunc() or mn
      end);
      return v
    end
    local v = getv()
    local tw = cw LM.Text(LM.Label(key), x, y + 14 * f, LM.Font * f, LM.C.rowText, 0, 0.5, 6, LM.content)
    local valTxt = LM.Text(R.SliderTextFunc and R.SliderTextFunc(v) or tostring(v), x + tw, y + 14 * f, LM.Font * f, LM.C.rowText, 1, 0.5, 6, LM.content)
    pcall(function()
      local sl = CGame:NewObjectFromPath("/Script/UMG.Slider", LM.root)
      if not sl or not slua.isValid(sl) then
        return
      end
      pcall(function()
        sl:SetSliderBarColor(LMcol(LM.C.track))
      end)
      pcall(function()
        sl:SetSliderHandleColor(FLinearColor(0, 0, 0, 0))
      end)
      pcall(function()
        sl:SetStepSize(1 / math.max(1, (mx - mn)))
      end)
      pcall(function()
        sl:SetValue((v - mn) / math.max(1e-6, (mx - mn)))
      end)
      pcall(function()
        sl.IsFocusable = false
      end)
      local ks = 22 * f
      local sy = y + 30 * f
      local function knobX(nv)
        return x + nv * (tw - ks)
      end
      local knob = LM.Img("ui_knob", knobX((v - mn) / math.max(1e-6, (mx - mn))), sy + (26 * f - ks) * 0.5, ks, ks, LM.C.knob, 11, LM.content)
      sl.OnValueChanged:Add(function(nv)
        pcall(function()
          local val = math.floor(mn + nv * (mx - mn) + 0.5)
          R.SetFunc( nil, val)
          if valTxt then
            local actual = getv();
            valTxt.w:SetText(R.SliderTextFunc and R.SliderTextFunc(actual) or tostring(actual))
          end
          if knob and knob.slot then
            knob.slot:SetPosition(FVector2D(knobX(nv) * LM.k, (sy + (26 * f - ks) * 0.5) * LM.k))
          end
        end)
      end)
      pcall(function()
        sl:SetWidgetVisibility(UEnums.ESlateVisibility.Visible)
      end)
      local slot = LM.root:AddChildToCanvas(sl)
      if slot then
        pcall(function()
          slot:SetAutoSize( false);
          slot:SetPosition(FVector2D(x * LM.k, (y + 30 * f) * LM.k));
          slot:SetSize(FVector2D(tw * LM.k, 26 * f * LM.k));
          slot:SetZOrder(10)
        end)
      end
      LM.Protect(sl)
      LM.content[ # LM.content + 1] = { w = sl, slot = slot }
    end)
  end
  function LM.Tick(pc)
    if Valid(pc) then
      _G.OwenNeonUIDrag.Tick(pc)
      local now = _G.RealNow()
      if LM.root and now >= (LM.NextLayoutCheck or 0) and not _G.OwenNeonUIDrag.Active then
        LM.NextLayoutCheck = now + .5
        local W, H = _G.OwenNeonUIDrag.Bounds(pc)
        if math.abs(W - (LM.ViewW or W)) > 1 or math.abs(H - (LM.ViewH or H)) > 1 then
          LM.Reset();
          LM.Create(pc)
        end
      end
    end
    if not Valid(pc) or type(pc.IsInputKeyJustPressed) ~= 'function' then
      return
    end
    if not LM.InputKeys then
      local now = _G.RealNow and _G.RealNow() or os.clock()
      if now < (LM.NextKeyProbe or 0) then
        return
      end;
      LM.NextKeyProbe = now + 1
      local ok, keys = pcall(function()
        local Key = import('Key');
        if not Key then
          return nil
        end
        local insert, escape = Key(), Key();
        insert.KeyName = 'Insert';
        escape.KeyName = 'Escape'
        return { Insert = insert, Escape = escape }
      end)
      if not ok or not keys then
        return
      end;
      LM.InputKeys = keys
    end
    local ok, pressed = pcall(pc.IsInputKeyJustPressed, pc, LM.InputKeys.Insert)
    if ok and (pressed == true or pressed == 1) then
      _G.OwenNeonMenus.Toggle(pc)
    elseif LM.open then
      ok, pressed = pcall(pc.IsInputKeyJustPressed, pc, LM.InputKeys.Escape)
      if ok and (pressed == true or pressed == 1) then
        if LM.drop and # LM.drop > 0 then
          LM.CloseDrop()
        else
          LM.SetOpen( false, pc)
        end
      end
    end
  end
  function LM.SetOpen(open, pc)
    LM.open = open and true or false
    if not LM.open then
      LM.CloseDrop();
      _G.OwenNeonUIDrag.End('menu')
    end
    if LM.open then
      if not LM.Create(pc) then
        return
      end
      LM.BuildContent()
    end
    if LM.root and slua.isValid(LM.root) then
      pcall(function()
        LM.root:SetWidgetVisibility(LM.open and UEnums.ESlateVisibility.Visible or UEnums.ESlateVisibility.Collapsed)
      end)
    end
  end
  function LM.Reset()
    if _G.OwenNeonUIDrag and _G.OwenNeonUIDrag.Active and _G.OwenNeonUIDrag.Active.Kind == 'menu' then
      _G.OwenNeonUIDrag.End('menu')
    end
    LM.CloseDrop();
    LM.Clear(LM.content);
    LM.Clear(LM.tabs);
    LM.Clear(LM.nav);
    LM.Clear(LM.items)
    if LM.root then
      if PlayerMapMarker._ProtectedWidgetStrs then
        PlayerMapMarker._ProtectedWidgetStrs[tostring(LM.root)] = nil
      end
      if slua.isValid(LM.root) then
        pcall(function()
          LM.root:RemoveFromParent()
        end)
      end
    end
    LM.root = nil;
    LM.rootSlot = nil;
    LM.drag = nil;
    LM.ViewPage = 1
  end
