    function NM.InstallV33Rows()
      local def = _G._ModMenuDef
      if not def or NM.RowDefinition == def then
        return
      end
      local AM = require('client.slua.umg.NewSetting.Item.AliasMap')
      local existing = {};
      local cats = {}
      for _, cat in ipairs(def.Category or {}) do
        cats[cat.Key] = cat
        for _, row in ipairs(cat.Stack or {}) do
          if row.Key then
            existing[row.Key] = true
          end
        end
      end
      local function add(cat, row)
        if existing[row.Key] then
          return
        end
        local target = cats[cat];
        if not target then
          return
        end
        target.Stack[ # target.Stack + 1] = row;
        existing[row.Key] = true
      end
      local function switch(cat, key, text, field)
        add(cat, { Key = key, UI = AM.Switcher, Text = text, GetFunc = function()
          return _G.MWConfig[field] == true
        end, SetFunc = function(context, value)
          if value == nil then
            value = context
          end;
          _G.MWConfig[field] = value == true or value == 1;
          return true
        end })
      end
      local function percent(key, text, field)
        add('Cat_Aimbot', { Key = key, UI = AM.Slider, Text = text, Min = 0, Max = 70, MinValue = 0,
        MaxValue = 70, min = 0, max = 70, GetFunc = function()
          return math.max(0, math.min(70, tonumber(_G.MWConfig[field]) or 70))
        end, SetFunc = function(context, value)
          if value == nil then
            value = context
          end;
          local n = tonumber(value) or 80;
          if n ~= n then
            n = 80
          end;
          _G.MWConfig[field] = math.max(0, math.min(70, n));
          return true
        end })
      end
      switch('Cat_ESPV2', 'ModMenu_EspPlayer_HPHorizontal', 'HORIZONTAL HP BAR', 'EspPlayerHPHorizontal')
      switch('Cat_Aimbot', 'ModMenu_AT_VRecoil_Ex', 'REDUCE VERTICAL RECOIL', 'VerticalRecoil')
      percent('ModMenu_AT_VRecoil_Value', 'VERTICAL RECOIL REDUCTION (%)', 'VRecoilReduction')
      switch('Cat_Aimbot', 'ModMenu_AT_HRecoil_Ex', 'REDUCE HORIZONTAL RECOIL', 'LessRecoil')
      percent('ModMenu_AT_HRecoil_Value', 'HORIZONTAL RECOIL REDUCTION (%)', 'HRecoilReduction')
      local weaponKeys = { 'ModMenu_EspItem_AR', 'ModMenu_EspItem_Sniper', 'ModMenu_EspItem_SMG', 'ModMenu_EspItem_Shotgun',
      'ModMenu_EspItem_LMG', 'ModMenu_EspItem_Pistol', 'ModMenu_EspItem_Melee', 'ModMenu_EspItem_Special' }
      add('Cat_ESP', {
        Key = 'ModMenu_ESPItemWeaponsAll',
        UI = AM.Switcher,
        Text = 'SHOW WEAPON ITEMS',
        GetFunc = function()
          local rows = LM.Rows() or {};
          for _,
          key in ipairs(weaponKeys) do
            local row = rows[key];
            if row and row.GetFunc and row.GetFunc() then
              return true
            end
          end;
          return false
        end,
        SetFunc = function(context, value)
          if value == nil then
            value = context
          end;
          local enabled = value == true or value == 1
          local rows = LM.Rows() or {};
          for _,
          key in ipairs(weaponKeys) do
            local row = rows[key];
            if row and row.SetFunc then
              row.SetFunc( nil, enabled)
            end
          end;
          return true
        end
      })
      NM.RowDefinition = def;
      _G.MWMenuRows = nil
    end
