    local function copy(keys, accept)
      local out = {};
      for _, key in ipairs(keys) do
        if not accept or accept(key) then
          out[ # out + 1] = key
        end
      end;
      return out
    end
    local function tab(name, keys)
      return { vn = name, en = name, keys = keys }
    end
    local esp = setting.Cat_ESP
    local function sectionKeys(master, keys)
      return copy(keys or esp.keys, function(key)
        if key == master then
          return true
        end
        local parent = tree[key] and tree[key].Parent
        local seen = {}
        while parent and not seen[parent] do
          seen[parent] = true;
          if parent == master then
            return true
          end;
          parent = tree[parent] and tree[parent].Parent
        end
        return false
      end)
    end
    local player = sectionKeys('ModMenu_EspPlayer_Ex')
    table.insert(player, 1, 'ModMenu_ESPTextSize')
    local outline = { 'ModMenu_EspOutline', 'ModMenu_OutlineThickness' }
    local function partition(keys, masters)
      local groups, claimed = {}, {}
      for i, master in ipairs(masters) do
        groups[i] = sectionKeys(master, keys)
        for _, key in ipairs(groups[i]) do
          claimed[key] = true
        end
      end
      return copy(keys, function(key)
        return not claimed[key]
      end), groups
    end
    local aim, aimGroups = partition(setting.Cat_Aimbot.keys, { 'ModMenu_V33_Hip_Enable', 'ModMenu_V33_SG_Enable',
    'ModMenu_V33_Scope_Enable', 'ModMenu_V33_Sniper_Enable', 'ModMenu_V33_Mortar_Enable' })
