    function LM.TreeDepth(key)
      local depth = 0;
      local seen = {};
      local parent = tree[key] and tree[key].Parent
      while parent and not seen[parent] do
        seen[parent] = true;
        depth = depth + 1;
        parent = tree[parent] and tree[parent].Parent
      end
      return depth
    end
    function LM.SetToggle(row, key, value)
      if not OwenNeonAuthorized() then
        return false
      end
      local result = row.SetFunc( nil, value)
      if result == false then
        return false
      end
      if key == 'ModMenu_EspPlayer_Ex' and not value then
        NM.DisablePlayerChildren(setting.Cat_ESP, LM.Rows() or {})
      end
      if _G.SaveModSettings then
        pcall(_G.SaveModSettings)
      end
      return result
    end
    function LM.PlanContent(tab)
      local pages = {
{}
      };
      local used = 0;
      local pending = nil
      local function flush()
        if pending then
          used = used + pending.H;
          pending = nil
        end
      end
      local function room(height)
        if used + height > 446 then
          pages[ # pages + 1] = {};
          used = 0
        end
      end
      local function add(item)
        if item.Master or item.Full then
          flush();
          room(item.H);
          item.Y = used;
          item.Col = 0;
          item.Width = 840
          pages[ # pages][ # pages[ # pages] + 1] = item;
          used = used + item.H
        elseif pending then
          local height = math.max(pending.H, item.H)
          if used + height > 446 then
            table.remove(pages[ # pages]);
            pages[ # pages + 1] = {};
            used = 0
            pending.Y = 0;
            pages[ # pages][1] = pending
          end
          item.Col = 1;
          item.Y = used;
          item.Width = 410
          pages[ # pages][ # pages[ # pages] + 1] = item;
          used = used + height;
          pending = nil
        else
          room(item.H);
          item.Col = 0;
          item.Y = used;
          item.Width = 410
          pages[ # pages][ # pages[ # pages] + 1] = item;
          pending = item
        end
      end
      local infoItems = {};
      local rows = LM.Rows() or {}
      for _, key in ipairs(tab.keys) do
        local row = rows[key]
        if key:sub(1, 6) == '_info:' then
          infoItems[ # infoItems + 1] = {
            Info = { LM.Translate('Device Info'), '' },
            H = 36,
            Col = 1,
            Width = 410
          }
          for _, info in ipairs(LM.DeviceInfo()) do
            infoItems[ # infoItems + 1] = { Info = info, H = 36, Col = 1, Width = 410 }
          end
        else
          local h = row and ((LM.UIType(row) == 'slider' or row.SwitcherText) and 84 or 64)
          if key:sub(1, 7) == '_title:' then
            h = 34
          elseif key:sub(1, 5) == '_btn:' then
            h = 48
          end
          if h then
            local meta = tree[key] or {};
            local item = { Key = key, Row = row, H = h, Depth = LM.TreeDepth(key), Master = meta.Header }
            if tab.deviceRight then
              if used + h > 446 then
                pages[ # pages + 1] = {};
                used = 0
              end
              item.Y = used;
              item.Col = 0;
              item.Width = 410;
              pages[ # pages][ # pages[ # pages] + 1] = item;
              used = used + h
            else
              add(item)
            end
          end
        end
      end
      if tab.deviceRight then
        local pi, y = 1, 0
        for _, item in ipairs(infoItems) do
          if y + item.H > 446 then
            pi = pi + 1;
            y = 0
          end
          pages[pi] = pages[pi] or {};
          item.Y = y;
          pages[pi][ # pages[pi] + 1] = item;
          y = y + item.H
        end
      end
      return pages
    end
    function LM.BuildContent()
      LM.CloseDrop();
      LM.Clear(LM.content);
      LM.drag = nil
      local tab = LM.Layout[LM.sec].tabs[LM.tab]
      local pages = LM.PlanContent(tab);
      LM.LastContentPlan = pages
      LM.PageCount = # pages;
      LM.ViewPage = math.max(1, math.min(LM.ViewPage or 1, # pages))
      for _, item in ipairs(pages[LM.ViewPage]) do
        local indent = math.min(48, (item.Depth or 0) * 16)
        local x = 236 + (item.Col or 0) * 430 + indent;
        local y = 166 + item.Y
        local cw = (item.Width or 410) - indent;
        local key, row = item.Key, item.Row
        if item.Info then
          LM.Rect(x, y, cw, 32, LM.C.card, 3, LM.content)
          LM.Text(item.Info[1], x + 12, y + 16, 16, LM.C.tabText, 0, 0.5, 6, LM.content)
          LM.Text(tostring(item.Info[2]), x + cw - 12, y + 16, 16, LM.C.rowText, 1, 0.5, 6, LM.content)
        elseif key:sub(1, 7) == '_title:' then
          LM.Text(key:sub(8), x, y + 17, 14, LM.C.cyan, 0, 0.5, 6, LM.content)
        elseif key:sub(1, 5) == '_btn:' then
          local id, label = key:sub(6):match('^(.-)|(.*)$')
          LM.Rect(x, y, cw, 38, LM.C.navOn, 4, LM.content)
          LM.Text(label or id, x + cw * .5, y + 19, 17, LM.C.cyan, 0.5, 0.5, 6, LM.content)
          LM.Button(x, y, cw, 38, 10, LM.content, function()
            if id == 'unlock_vip' then
              _G.OwenTrialAccess.OpenUnlock()
            elseif id == 'feedback_status' and _G.OwenAutoFeedback then
              _G.OwenAutoFeedback.ShowStatus()
            elseif id == 'reset' and _G.MWResetSettings then
              _G.MWResetSettings();
              LM.BuildContent()
            end
          end)
        elseif row then
          local height = item.H - 8
          if item.Master then
            LM.Rect(x, y, cw, height, LM.C.cyan, 3, LM.content)
            LM.Rect(x + 2, y + 2, cw - 4, height - 4, LM.C.navOn, 4, LM.content)
            LM.Rect(x + 2, y + 6, 4, height - 12, LM.C.cyan, 5, LM.content)
          else
            LM.Rect(x, y, cw, height, LM.C.card, 3, LM.content)
          end
          if LM.UIType(row) == 'slider' then
            LM.RowSlider(row, key, x + 14, y + 7, cw - 28, 1)
          elseif row.SwitcherText then
            LM.RowDrop(row, key, x + 14, y + 7, cw - 28, 1)
          else
            LM.RowCheck(row, key, x + 14, y + 7, cw - 28, 1)
          end
        end
      end
      LM.Text(string.format('%02d / %02d', LM.ViewPage, # pages), 656, 645, 14, LM.C.tabText, 0.5, 0.5, 6, LM.content)
      if # pages > 1 then
        local function pageButton(x, label, step)
          LM.Rect(x, 618, 132, 38, LM.C.cyan, 3, LM.content)
          LM.Rect(x + 2, 620, 128, 34, LM.C.navOn, 4, LM.content)
          LM.Text(label, x + 66, 637, 18, LM.C.cyan, 0.5, 0.5, 6, LM.content)
          LM.Button(x, 618, 132, 38, 10, LM.content, function()
            LM.ViewPage = math.max(1, math.min( # pages, LM.ViewPage + step));
            LM.BuildContent()
          end)
        end
        pageButton(236, '< PREV', - 1)
        pageButton(944, 'NEXT >', 1)
      end
    end
  end
  function NM.Mode()
    local value = tonumber((_G.MWConfig or {}).MenuMode)
    if value ~= 2 and value ~= 3 then
      return 1
    end
    return value
  end
  function NM.NativeEnabled()
    return OwenNeonAuthorized() and NM.Mode() ~= 1
  end
  function NM.Translate(value)
    if type(value) == 'number' then
      value = (_G._FakeTextMap or {})[value] or tostring(value)
    end
    return LM.Translate(value)
  end
  function NM.RefreshTreeItem(item)
    local data = item and item.Data
    local ancestors = data and data.OwenSettingAncestors
    if not ancestors or # ancestors == 0 then
      return
    end
    local stack = item:GetParentUI()
    if not stack or not stack.GetItemUI then
      return
    end
    for _, key in ipairs(ancestors) do
      local parent = stack:GetItemUI(key)
      if not parent or (parent.GetExpandState and not parent:GetExpandState()) then
        item:Collapsed();
        return
      end
      local getter = parent.Data and parent.Data.GetFunc
      if getter then
        local ok, value = pcall(getter, key)
        if ok and value ~= true and value ~= 1 then
          item:Collapsed();
          return
        end
      end
    end
    item:SelfHitTestInvisible()
  end
  function NM.InstallTreeEvents()
    if NM.TreeEventsInstalled then
      return
    end
    local ok, class = pcall(require, 'client.slua.umg.NewSetting.Item.Setting_Item_Base')
    if not ok or not class then
      return
    end
    local impl = class.__inner_impl or class
    for _, key in ipairs( { 'OnInitialize', 'OnSwitcherExpanded', '_RefreshExpandState' }) do
      local original = class[key]
      if type(original) == 'function' then
        local wrapped = function(self, ...)
          original(self, ...)
          if key == 'OnInitialize' and self.Data and self.Data.OwenSettingAncestors and # self.Data.OwenSettingAncestors > 1 then
            pcall(function()
              local style = require('client.slua.umg.NewSetting.SettingStyleLibrary')
              local margin = style.ExpandedMargin
              local slot = self.UIRoot and self.UIRoot.Slot
              if margin and slot and slot.SetPadding and FMargin then
                slot:SetPadding(FMargin(margin.Left + 16 * ( # self.Data.OwenSettingAncestors - 1), margin.Top, margin.Right, margin.Bottom))
              end
            end)
          end
          if self.Data and self.Data.OwenSettingAncestors then
            NM.RefreshTreeItem(self)
          end
        end
        rawset(impl, key, wrapped);
        rawset(class, key, wrapped)
      end
    end
    NM.TreeEventsInstalled = true
  end
  function NM.DisablePlayerChildren(tab, rows)
    for _, key in ipairs(tab.keys or {}) do
      local parent = (tab.parents or {})[key]
      local seen = {}
      while parent and not seen[parent] do
        seen[parent] = true
        if parent == 'ModMenu_EspPlayer_Ex' then
          local row = rows[key]
          if row and row.SetFunc and not row.SwitcherValue and not row.SwitcherText and LM.UIType(row) ~= 'slider' then
            row.SetFunc( nil, false)
            if _G.EventSystem and _G.EVENTTYPE_SETTING and _G.EVENTID_SETTING_OPTION_FORCEUPDATE then
              _G.EventSystem:postEvent(_G.EVENTTYPE_SETTING, _G.EVENTID_SETTING_OPTION_FORCEUPDATE, key)
            end
          end
          break
        end
        parent = (tab.parents or {})[parent]
      end
    end
  end
