  do
    local AM = require('client.slua.umg.NewSetting.Item.AliasMap')
    local G = _G.OwenGraphics
    local definitions = {
{ 'GraphicsResolutionPercent', 'ĐỘ PHÂN GIẢI RENDER(%)', 0, 100, 1 },
{ 'GraphicsShadow', 'CHẤT LƯỢNG BÓNG', - 1, 5, 1 },
{ 'GraphicsBloom', 'ĐỘ LÓE SÁNG BLOOM', - 1, 5, 1 },
{ 'GraphicsDOF', 'ĐỘ SÂU TRƯỜNG ẢNH', - 1, 3, 1 },
{ 'GraphicsPost', 'CHẤT LƯỢNG HẬU KỲ', - 1, 3, 1 },
{ 'GraphicsAA', 'KHỬ RĂNG CƯA MSAA', - 1, 4, 1 },
{ 'GraphicsAnisotropy', 'LỌC TEXTURE', - 1, 8, 1 },
{ 'GraphicsViewDistance', 'KHOẢNG CÁCH HIỂN THỊ CẢNH QUAN (%)', 0, 125, 100 },
{ 'GraphicsSceneLOD', 'KHOẢNG CÁCH LOD VẬT THỂ (%)', 0, 200, 100 },
{ 'GraphicsFoliageLOD', 'KHOẢNG CÁCH LOD CÂY CỎ (%)', 0, 150, 100 },
{ 'GraphicsMaterial', 'CHẤT LƯỢNG VẬT LIỆU CẢNH QUAN', - 1, 2, 1 },
    }
    local rows = LM.Rows() or {}
    local keys = { 'ModMenu_GraphicsCustomize' }
    rows.ModMenu_GraphicsBuildingLOD = { Key = 'ModMenu_GraphicsBuildingLOD', UI = AM.Slider, Text = 'LOD NHÀ / CÔNG TRÌNH (THỬ NGHIỆM)',
    Min = 0, Max = 2, MinValue = 0, MaxValue = 2, min = 0, max = 2, ExpandHandle = 'ModMenu_GraphicsCustomize',
    GetFunc = function()
      return tonumber(_G.MWConfig.GraphicsBuildingLOD) or 0
    end, SetFunc = function(context, value)
      if value == nil then
        value = context
      end
      local n = tonumber(value);
      if not n or n ~= n then
        return false
      end
      _G.MWConfig.GraphicsBuildingLOD = math.max(0, math.min(2, math.floor(n)))
      if _G.OwenBuildingLOD then
        _G.OwenBuildingLOD.Tick( true)
      end
      return true
    end, SliderTextFunc = function(n)
      return n == 0 and 'Tắt' or n == 1 and 'Giảm nhẹ' or 'Giảm mạnh'
    end }
    keys[ # keys + 1] = 'ModMenu_GraphicsBuildingLOD'
    NM.SettingNames.ModMenu_GraphicsBuildingLOD = { 'BUILDING LOD (EXPERIMENTAL)', 'LOD NHÀ / CÔNG TRÌNH (THỬ NGHIỆM)',
    '建筑 LOD（实验）' }
    LM.DisplayNames.ModMenu_GraphicsBuildingLOD = NM.SettingNames.ModMenu_GraphicsBuildingLOD
    local function findSpec(key)
      for _, spec in ipairs(G.Specs) do
        if spec.Key == key then
          return spec
        end
      end
    end
    for _, d in ipairs(definitions) do
      local key = 'ModMenu_' .. d[1];
      local spec = findSpec(d[1])
      local previous = rows[key] or (d[1] == 'GraphicsResolutionPercent' and rows.ModMenu_GraphicsResolution)
      local row = { Key = key, UI = AM.Slider, Text = d[2], Min = d[3], Max = d[4], MinValue = d[3],
      MaxValue = d[4], min = d[3], max = d[4], ExpandHandle = 'ModMenu_GraphicsCustomize' }
      row.GetFunc = function()
        local value = spec.Values[G.Index(spec, _G.MWConfig[spec.Key])]
        if value == 1 and (spec.Key == 'GraphicsAA' or spec.Key == 'GraphicsAnisotropy') then
          return 0
        end
        return value == false and d[3] or math.floor(value * d[5] + 0.5)
      end
      row.SetFunc = function(context, value)
        if value == nil then
          value = context
        end
        value = tonumber(value);
        if not value or value ~= value then
          return false
        end
        value = math.max(d[3], math.min(d[4], value))
        local index, best = 1, math.huge
        if value > d[3] then
          for i = 2, # spec.Values do
            local candidate = spec.Values[i] * d[5]
            if candidate == 1 and (spec.Key == 'GraphicsAA' or spec.Key == 'GraphicsAnisotropy') then
              candidate = 0
            end
            local distance = math.abs(candidate - value)
            if distance < best then
              index, best = i, distance
            end
          end
        end
        return G.Set(spec.Key, index)
      end
      row.SliderTextFunc = function(value)
        if value == d[3] then
          return 'Theo game'
        end
        if value == 0 then
          return 'Tắt (0)'
        end
        return tostring(value) .. ((d[5] == 100 or d[1] == 'GraphicsResolutionPercent') and '%' or '')
      end
      if previous then
        for k in pairs(previous) do
          previous[k] = nil
        end
        for k, v in pairs(row) do
          previous[k] = v
        end
        rows[key] = previous
      else
        rows[key] = row
      end
      keys[ # keys + 1] = key
      NM.SettingNames[key] = { spec.Text, d[2], spec.Text };
      LM.DisplayNames[key] = NM.SettingNames[key]
    end
    keys[ # keys + 1] = 'ModMenu_GraphicsGloveLOD'
    local overrides = {}
    for _, key in ipairs(keys) do
