        for key, value in pairs(tab.headers) do
          if not A.HiddenRow(key) then
            result.headers[key] = value
          end
        end
      end
      return result
    end
    local function layouts(all, native, level)
      if level == 'vip' then
        return all
      end
      local result = {}
      for _, group in ipairs(all or {}) do
        local skin = (native and group.key == 'Cat_Skin') or ( not native and group.name == 'Skin')
        if not skin or level == 'free' then
          local filtered = copy(group);
          filtered.tabs = {}
          for _, tab in ipairs(group.tabs or {}) do
            local visible = filteredTab(tab)
            if visible then
              filtered.tabs[ # filtered.tabs + 1] = visible
            end
          end
          local config = (native and group.key == 'Cat_Ban') or ( not native and group.name == 'Configs')
          if config and level == 'free' then
            if # filtered.tabs == 0 then
              filtered.tabs[1] = {
                vn = 'Settings',
                en = 'Settings',
                keys = {}
              }
            end
            table.insert(filtered.tabs[1].keys, 1, unlockKey)
          end
          if # filtered.tabs > 0 then
            result[ # result + 1] = filtered
          end
        end
      end
      return result
    end
    local getAccessRows = LM.Rows
    local guardedAccessRows
    LM.Rows = function( ...)
      local rows = getAccessRows( ...)
      if rows ~= guardedAccessRows then
        for _, row in pairs(rows or {}) do
          A.GuardRow(row)
        end
        guardedAccessRows = rows
      end
      return rows
    end
    function A.ApplyMenu()
      local selected = LM.Layout and LM.Layout[LM.sec or 1]
      local selectedName = selected and selected.name
      local level = A.Level()
      LM.Layout = layouts(uiAll, false, level)
      NM.SettingLayout = layouts(nativeAll, true, level)
      LM.sec = 1
      for i, group in ipairs(LM.Layout) do
        if group.name == selectedName then
          LM.sec = i;
          break
        end
      end
      local active = LM.Layout[LM.sec]
      LM.tab = math.max(1, math.min(LM.tab or 1, # (active and active.tabs or {})))
      LM.ViewPage = 1 A.GuardRows(_G._ModMenuDef)
      for _, row in pairs(LM.Rows() or {}) do
        A.GuardRow(row)
      end
      A.EnforceConfig()
    end
    function A.Refresh()
      A.ApplyMenu()
      if type(NM.Sync) == 'function' then
        NM.Sync()
      end
      if LM.root and LM.open then
        LM.BuildNav();
        LM.BuildTabs();
        LM.BuildContent()
      end
    end
    function A.OpenUnlock()
      if A.Level() ~= 'free' or type(_G.OwenRequestVipUnlock) ~= 'function' then
        return false
      end
      if LM.open then
        LM.SetOpen( false)
      end
      local ui = rawget(_G, 'UIManager')
      local config = ui and ui.UI_Config and ui.UI_Config.setting_main
      if config and type(ui.GetUI) == 'function' and type(ui.CloseUI) == 'function' then
        local found, view = pcall(ui.GetUI, config)
        if found and view then
          pcall(ui.CloseUI, config)
        end
      end
      local gs = rawget(_G, 'GameStatus')
      local ok, lobby = pcall(function()
        return gs and gs.IsInLobbyOrMainCity and gs.IsInLobbyOrMainCity()
      end)
      if not ok or not (lobby == true or lobby == 1) then
        return _G.OwenRequestVipUnlock()
      end
      return _G.OwenRequestVipUnlock()
    end
    _G.OwenOnAccessChanged = function()
      A.Refresh()
    end
  end
  function NM.Build()
    local AM = require('client.slua.umg.NewSetting.Item.AliasMap')
    NM.InstallTreeEvents()
    local page = NM.Page or { Key = 'ModMenu', UIKey = 'Setting_Page_Privacy', VisibilityFunc = NM.NativeEnabled }
    page.Text = _G.OwenTrialAccess.Level() == 'free' and 'DevLet FREE MENU' or 'DevLet VIP MENU'
    local categories = {}
    for gi, group in ipairs(NM.SettingLayout or LM.Layout) do
      local stack = {}
      for ti, tab in ipairs(group.tabs or {}) do
        local first = (LM.Rows() or {})[(tab.keys or {})[1]]
        if not tab.noHeading and ( not first or LM.UIType(first) ~= 'title') and not tostring((tab.keys or {})[1] or ''):find('_title:', 1, true) then
          stack[ # stack + 1] = { Key = 'NeonHeading_' .. gi .. '_' .. ti, UI = AM.Title, Text = LM.Translate(tab.en) }
        end
        local master = nil
        for _, key in ipairs(tab.keys or {}) do
          local row = (LM.Rows() or {})[key]
          if row then
            local copy = {}
            for k, v in pairs(row) do
              copy[k] = v
            end
            local lang = tonumber((_G.MWConfig or {}).MenuLanguage) or 1
            local names = NM.SettingNames and NM.SettingNames[key]
            copy.Text = names and names[lang] and LM.Upper(names[lang]) or LM.DisplayLabel(key, NM.Translate(row.Text))
            if row.SwitcherText then
              copy.SwitcherText = {}
              for i, text in ipairs(row.SwitcherText) do
                copy.SwitcherText[i] = NM.Translate(text)
              end
            end
            local kind = LM.UIType(row)
            if kind == 'slider' then
              copy.Min = row.Min or row.MinValue or row.min or 0;
              copy.Max = row.Max or row.MaxValue or row.max or 100
            end
            copy.ExpandHandle = master;
            copy.ExpandIndex = nil
            if NM.SettingLayout then
              copy.ExpandHandle = (tab.parents or {})[key]
              if (tab.headers or {})[key] then
                copy.UI = copy.ExpandHandle and not (tab.yellowHeaders or {})[key] and AM.Switcher or AM.TitleSwitcher;
                copy.ExpandIndex = 0
              else
                copy.UI = kind == 'slider' and AM.Slider or AM.Switcher
              end
              copy.OwenSettingAncestors = {}
              local parent = copy.ExpandHandle;
              local seen = {}
              while parent and not seen[parent] do
                seen[parent] = true;
                copy.OwenSettingAncestors[ # copy.OwenSettingAncestors + 1] = parent
                parent = (tab.parents or {})[parent]
              end
            elseif kind == 'title' then
              master = row.Key;
              copy.UI = AM.TitleSwitcher;
              copy.ExpandHandle = nil;
              copy.ExpandIndex = 0
            end
            if kind ~= 'slider' and not row.SwitcherValue and not row.SwitcherText then
              copy.SwitcherText = { LM.Translate('ON'), LM.Translate('OFF') }
            end
            if row.SwitcherText and # row.SwitcherText > 3 then
              copy.Width = 70;
              copy.Height = 36
            end
            if kind ~= 'slider' and not row.SwitcherValue then
              copy.GetFunc = function( ...)
                local v = row.GetFunc( ...);
                return v == true or v == 1
              end
            end
            if row.SetFunc then
              copy.SetFunc = function( ...)
                if not OwenNeonAuthorized() then
                  return false
                end
                local result = row.SetFunc( ...)
                if result ~= false then
                  if key == 'ModMenu_EspPlayer_Ex' and row.GetFunc and not row.GetFunc() then
                    NM.DisablePlayerChildren(tab, LM.Rows() or {})
                  end
                  if _G.SaveModSettings then
                    pcall(_G.SaveModSettings)
                  end
                  if LM.open then
                    LM.BuildContent()
                  end
                end
                return result
              end
            end
            stack[ # stack + 1] = copy
          elseif key:sub(1, 7) == '_title:' and AM.Title then
            stack[ # stack + 1] = { Key = 'NeonTitle_' .. gi .. '_' .. ti .. '_' .. # stack, UI = AM.Title,
            Text = LM.Translate(key:sub(8)) }
          elseif key == '_info:device' and AM.OpenWindow then
            stack[ # stack + 1] = {
              Key = 'NeonDeviceInfo',
              UI = AM.OpenWindow,
              Text = LM.Translate('Device Info'),
              GetFunc = function()
                local lines = {}
                for _,
                item in ipairs(LM.DeviceInfo()) do
                  lines[ # lines + 1] = tostring(item[1]) .. ': ' .. tostring(item[2])
                end
                return table.concat(lines, '\n')
              end
            }
          elseif key:sub(1, 5) == '_btn:' and AM.OpenWindow then
            local id, label = key:sub(6):match('^(.-)|(.*)$')
            stack[ # stack + 1] = { Key = 'NeonAction_' .. tostring(id), UI = AM.OpenWindow, Text = LM.Translate(label or id),
            GetFunc = id == 'feedback_status' and function()
              local feedback = _G.OwenAutoFeedback
              return feedback and feedback.StatusText and feedback.StatusText() or 'Feedback chưa khởi tạo'
            end or nil, SetFunc = function()
              if not OwenNeonAuthorized() then
                return
              end
              if id == 'unlock_vip' then
                _G.OwenTrialAccess.OpenUnlock()
              elseif id == 'feedback_status' and _G.OwenAutoFeedback then
                _G.OwenAutoFeedback.ShowStatus()
              elseif id == 'reset' and _G.MWResetSettings then
                _G.MWResetSettings();
                NM.Changed()
              elseif id == 'collection' then
                LM.OpenCollection()
              end
            end }
          end
        end
      end
      if # stack > 0 then
        categories[ # categories + 1] = {
          Key = group.key or ('NeonCat_' .. gi),
          Text = group.labels and LM.Upper(group.labels[tonumber((_G.MWConfig or {}).MenuLanguage) or 1] or group.name) or LM.Translate(group.name),
          Stack = stack
        }
      end
    end
    page.Category = categories;
    NM.Page = page
    return page
  end
  function NM.Catalog(catalog)
    local out = {}
    for k, v in pairs(catalog or {}) do
      if type(k) ~= 'number' then
        out[k] = v
      end
    end
    for _, page in ipairs(catalog or {}) do
      if page ~= NM.Page and not (type(page) == 'table' and page.Key == 'ModMenu') then
        out[ # out + 1] = page
      end
    end
    if NM.NativeEnabled() then
      table.insert(out, 1, NM.Build())
    end
    return out
  end
  function NM.Sync()
    if not OwenNeonAuthorized() or not _G._ModMenuDef then
      return false
    end
    local ok, pages = pcall(require, 'client.logic.NewSetting.SettingPageDefine')
    local ok2, catalog = pcall(require, 'client.logic.NewSetting.SettingCatalog')
    local UI = _G.UIManager
    if not ok or not ok2 or type(pages) ~= 'table' or type(catalog) ~= 'table' or not UI or type(UI.ShowUI) ~= 'function' then
      return false
    end
    if NM.NativeEnabled() then
      NM.Build()
    end
    for i = # catalog, 1, - 1 do
      if catalog[i] == NM.Page then
        table.remove(catalog, i)
      end
    end
    if NM.NativeEnabled() then
      pages.ModMenu = NM.Page;
      table.insert(catalog, 1, NM.Page)
    elseif pages.ModMenu == NM.Page then
      pages.ModMenu = nil
    end
    if not NM.Installed then
      local original = UI.ShowUI
      NM.OriginalShowUI = original
      NM.Wrapper = function(config, ...)
        local name = type(config) == 'table' and tostring(config.keyName or ''):lower() or ''
        if name:find('setting_main', 1, true) and not name:find('custom', 1, true) then
          local args = { ... };
          local n = select('#', ...)
          if type(args[1]) == 'table' then
            args[1] = NM.Catalog(args[1])
          end
          return original(config, (table.unpack or unpack)(args, 1, n))
        end
        return original(config, ...)
      end
      UI.ShowUI = NM.Wrapper;
      NM.Installed = true
    end
    return true
  end
  function NM.Changed()
    if _G.FpsButton then
      _G.FpsButton.SetVisible(_G.FpsButton.Enabled())
    end
    if NM.Mode() == 2 then
      LM.SetOpen( false)
      if _G.FpsButton then
        _G.FpsButton.open = false
      end
    end
    NM.Sync()
    if _G.SaveModSettings then
      pcall(_G.SaveModSettings)
    end
  end
  function _G.OwenRefreshMenuLanguage()
    if LM.root and LM.open then
      LM.BuildNav();
      LM.BuildTabs();
      LM.BuildContent()
    end
    if _G._ModMenuDef then
      NM.Sync()
    end
    local events = rawget(_G, 'EventSystem')
    if events and type(events.postEvent) == 'function' and _G.EVENTTYPE_SETTING and _G.EVENTID_SETTING_OPTION_FORCEUPDATE then
      events:postEvent(_G.EVENTTYPE_SETTING, _G.EVENTID_SETTING_OPTION_FORCEUPDATE, 'ModMenu_MenuLanguage')
    end
  end
  function NM.OpenNative()
    if not NM.NativeEnabled() or not NM.Sync() then
      return false
    end
    local UI = _G.UIManager
    local config = UI.UI_Config and UI.UI_Config.setting_main
    if not config then
      return false
    end
    local existing = UI.GetUI and UI.GetUI(config)
    if existing and type(existing.SwitchPageCategory) == 'function' then
      existing:SwitchPageCategory('ModMenu');
      return true
    end
    local catalog = require('client.logic.NewSetting.SettingCatalog')
    local window = UI.ShowUI(config, catalog)
    if window and type(window.SetPendingPage) == 'function' then
      window:SetPendingPage('ModMenu')
    end
    return window ~= nil
  end
  function NM.Toggle(pc)
    if not OwenNeonAuthorized() then
      return false
    end
    if NM.Mode() == 2 then
      local ok, opened = pcall(NM.OpenNative)
      if ok and opened then
        return true
      end
      LM.SetOpen( not LM.open, pc)
    else
      LM.SetOpen( not LM.open, pc)
    end
    if _G.FpsButton then
      _G.FpsButton.open = LM.open
    end
    return true
  end
  local function _VehAirFlag(v)
    return v:IsAirVehicle()
  end
  local function _VehShapeType(v)
    return v.VehicleShapeType
  end
  local function _VehClass(v)
    local c = v:GetClass()
    if c then
      return c:GetName()
    end
  end
  local function _VehPtero(v)
    return v.PterosaurMoveComponent
  end
  local function _VehHeli(v)
    return v.HelicopterVehicleMovement
  end
  local function _VehAircraft(v)
    return v.AircraftMovement
  end
  _G.MWAirMemo = setmetatable( {}, { __mode = 'k' })
  function _G.MWIsAirVeh(veh)
    if not Valid(veh) then
      return false
    end
    local memo = _G.MWAirMemo
    local hit = memo[veh]
    if hit ~= nil then
      return hit
    end
    if type(veh.IsAirVehicle) == "function" then
      local ok, res = pcall(_VehAirFlag, veh)
      if ok and (res == true or res == 1) then
        memo[veh] = true;
        return true
      end
    end
    local okSt, st = pcall(_VehShapeType, veh)
    if okSt and st ~= nil then
      if not _G.MWAirShapes then
        _G.MWAirShapes = {} pcall(function()
          local E = import("ESTExtraVehicleShapeType")
          if E then
            for _, k in ipairs( { "VST_UH60", "VST_HeavyUH60", "VST_Motorglider", "VST_WingMan", "VST_Fighter",
            "VST_Aircraft", "VST_Pterosaur" }) do
              if E[k] ~= nil then
                _G.MWAirShapes[E[k]] = true
              end
            end
          end
        end)
      end
      if _G.MWAirShapes[st] then
        memo[veh] = true;
        return true
      end
    end
    local okC, n = pcall(_VehClass, veh)
    if not okC or type(n) ~= "string" or n == "" then
      n = tostring(veh)
    end
    if n:find("UH60") or n:find("AH6") or n:find("Heli") or n:find("VH_Fighter") or n:find("Motorglider") or n:find("Aircraft") or n:find("Plane") or n:find("Glider") or n:find("Fighter") or n:find("Pterosaur") or n:find("BioVehicle") or n:find("Jet") or n:find("Wing") then
      memo[veh] = true;
      return true
    end
    local okP, pm = pcall(_VehPtero, veh)
    if okP and Valid(pm) then
      memo[veh] = true;
      return true
    end
    local okH, hm = pcall(_VehHeli, veh)
    if okH and Valid(hm) then
      memo[veh] = true;
      return true
    end
    local okA, am = pcall(_VehAircraft, veh)
    if okA and Valid(am) then
      memo[veh] = true;
      return true
    end
    memo[veh] = false
    return false
  end
  function _G.MWIsHeli(veh)
    if not Valid(veh) then
      return false
    end
    local n = "" pcall(function()
      local cls = veh:GetClass()
      if cls then
        n = cls:GetName() or ""
      end
    end)
    if n == "" then
      n = tostring(veh)
    end
    if n:find("Motorglider") or n:find("VH_Fighter") or n:find("Fighter") or n:find("Plane") or n:find("Glider") or n:find("Aircraft") or n:find("Pterosaur") or n:find("BioVehicle") or n:find("Jet") or n:find("Wing") then
      return false
    end
    local ok, hm = pcall(function()
      return veh.HelicopterVehicleMovement
    end)
    return (ok and Valid(hm)) and true or false
  end
  function _G.MWVehGrounded(veh)
    if not Valid(veh) then
      return true
    end
    local grounded = true pcall(function()
      local mc = veh.VehicleMovement or veh.MovementComponent
      if not (mc and Valid(mc)) then
        return
      end
      if type(mc.GetNumWheelsNotInAir) == "function" then
        grounded = (tonumber(mc:GetNumWheelsNotInAir()) or 1) > 0
      elseif type(mc.GetNumWheelsOnGround) == "function" then
        local n = mc:GetNumWheelsOnGround()
        grounded = (n == true) or (type(n) == "number" and n > 0)
      elseif type(mc.GetNumWheelsInAir) == "function" then
        grounded = (tonumber(mc:GetNumWheelsInAir()) or 0) < 4
      end
    end)
    return grounded
  end
