          if M.arwImg then
            M.arwImg.pos = FVector2D(0, 0);
            M.arwImg.scv = FVector2D(1, 1);
            M.arwImg._sz = nil pcall(function()
              M.arwImg.w:SetRenderTransformPivot(FVector2D(0.5, 0.5))
            end)
