  function _G.MBHitX.Tick(pc)
    do
      _G.MBHitX.Hide();
      return
    end
    local M = _G.MBHitX
    local DL = _G.DrawLine
    if not DL then
      return
    end
    if not (pc and slua.isValid(pc)) then
      M.Hide();
      return
    end
    local key = tostring(pc)
    if M.pcKey ~= key then
      M.pcKey = key pcall(function()
        pc.OnDamageToOther:Add(function()
          pcall(_G.MBHitX.OnDamage)
        end)
      end)
    end
    if not M.t then
      M.Hide();
      return
    end
    local now = _G.RealNow()
    local age = now - M.t
    if age > M.DUR then
      M.t = nil;
      M.Hide();
      return
    end
    local PMM = _G.PlayerMapMarker PMM._ScreenCenterCanvas(pc)
    local W = PMM._VpPxW or 1920
    local H = PMM._VpPxH or 1080
    local sc = H / M.RefH
    local S2C = PMM.ScreenPixelToCanvasLocalRaw
    local ux, uy = W * 0.5, H * 0.5
    local size = M.SIZE * sc
    local gap = size * M.GAP
    local len = size * 0.5 - gap
    local th = math.max(2, M.TH * sc)
    if not M.imgs or not _G.MWWidgetLive(M.imgs[1] and M.imgs[1].w) then
      M.Reset()
      local canvas = DL.GetCanvas()
      if not canvas then
        return
      end
      M.imgs = {}
      for i, q in ipairs(M.quads) do
        local ic = _G.MWIconImageAt(canvas, 0, 0, len, th, "hitx_stroke", 0, 0.5, M.Z)
        if not ic then
          M.Reset();
          return
        end
        pcall(function()
          ic.w:SetRenderTransformPivot(FVector2D(0, 0.5))
        end)
        local rotated = false pcall(function()
          if type(ic.w.SetRenderAngle) == "function" then
            ic.w:SetRenderAngle(q[3]);
            rotated = true
          end
        end)
        if not rotated then
          pcall(function()
            ic.w:SetRenderTransformAngle(q[3])
          end)
        end
        ic.pos = FVector2D(0, 0);
        ic.scv = FVector2D(1, 1)
        M.imgs[i] = ic
      end
    end
    local k = age / M.DUR
    local alpha = 1 - k * k
    local scale = 1.3 - 0.3 * math.min(1, age / M.POP)
    local col = nil pcall(function()
      col = FLinearColor(0, 1, 0, alpha)
    end)
    local d = 0.70710678
    for i, q in ipairs(M.quads) do
      local it = M.imgs[i]
      local x1, y1 = ux + q[1] * gap * d, uy + q[2] * gap * d
      local ax, ay = S2C(pc, x1, y1)
      if ax and it and it.w and slua.isValid(it.w) then
        it.pos.X, it.pos.Y = ax, ay pcall(function()
          it.slot:SetPosition(it.pos)
        end)
        it.scv.X, it.scv.Y = scale, scale pcall(function()
          it.w:SetRenderScale(it.scv)
        end)
        if col then
          pcall(function()
            it.w:SetColorAndOpacity(col)
          end)
        end
        if not M.shown then
          pcall(function()
            it.w:SetWidgetVisibility(UEnums.ESlateVisibility.HitTestInvisible)
          end)
        end
      end
    end
    M.shown = true
  end
