  do
    local previous = {}
    local function on(v)
      return v == true or v == 1
    end
    _G.OwenSyncFeatureLifecycle = function()
      local cfg = _G.MWConfig or {}
      if _G.OwenNativeVehicleMarks and not cfg.EspVehicle then
        _G.OwenNativeVehicleMarks.Stop()
      end
      if _G.OwenNativePlayerMarks and ( not on(cfg.EspPlayer) or not on(cfg.PlayerNativeMarkers)) then
        _G.OwenNativePlayerMarks.Stop()
