      if previous.Parts ~= parts then
        previous.Parts = parts
        if not parts and _G.OwenCosmeticAttachments then
          _G.OwenCosmeticAttachments.ClearAll()
        end
      end
      local icons = on(cfg.ModSkin) and (on(cfg.WeaponInventoryIcons) or on(cfg.AttachmentInventoryIcons))
      if previous.Icons ~= icons then
        previous.Icons = icons
        if not icons and _G.OwenBackpackSkinIcons then
          _G.OwenBackpackSkinIcons:Uninstall()
        end
      end
      local skeleton = on(cfg.EspPlayer) and on(cfg.EspPlayerSkeleton)
      local partial = skeleton and on(cfg.EspSkeletonSegmentColor)
      if previous.Skeleton ~= skeleton or previous.Partial ~= partial then
        previous.Skeleton, previous.Partial = skeleton, partial
        local marker = _G.PlayerMapMarker
        if marker then
          for key, sk in pairs(marker.Skel or {}) do
            if not partial then
              sk.TraceContext = nil;
              sk.SegmentVis = nil;
              sk.Boundaries = nil
            end
            if not skeleton and marker.HideSkel then
              marker.HideSkel(key)
            end
          end
        end
        local S = _G.OwenSkeletonBudget
        if S and not partial then
          S.TraceLeft = 0;
          S.TraceKey = nil;
          S.TraceContext = nil;
          S.PartialActive = false;
          S.NextTrace = 0
        end
      end
