  function _G.OwenGripStep(localPlayer)
    if not _G.MWConfig.FullGrip then
      return
    end
    local veh = localPlayer.CurrentVehicle or (type(localPlayer.GetVehicle) == "function" and localPlayer:GetVehicle())
    if not Valid(veh) then
      return
    end
    if type(veh.GetDriver) == "function" then
      local drv = veh:GetDriver()
      if not Valid(drv) or drv ~= localPlayer then
        return
      end
    end
    local vc = veh.VehicleCommon
    if not slua.isValid(vc) and type(veh.GetVehicleCommon) == "function" then
      vc = veh:GetVehicleCommon()
    end
    local mov = veh.VehicleMovement or veh.MovementComponent
    if slua.isValid(vc) then
      local wnum = 0 pcall(function()
        wnum = (type(vc.GetWheelsHPNum) == "function" and vc:GetWheelsHPNum()) or (vc.WheelsCurrentHP and vc.WheelsCurrentHP:Num()) or 0
      end)
      for i = 0, wnum - 1 do
        local destroyed = false
        if type(vc.IsWheelDestroyed) == "function" then
          local okW, valueW = pcall(vc.IsWheelDestroyed, vc, i)
          destroyed = okW and valueW == true
        end
        if destroyed then
          pcall(function()
            if vc.RestoreWheel then
              vc:RestoreWheel(i)
            end
          end)
          pcall(function()
            if mov and slua.isValid(mov) and mov.EnableVehicleWheel then
              mov:EnableVehicleWheel(i, true)
            end
          end)
        end
      end
      pcall(function()
        if vc.RefreshWheelState then
          vc:RefreshWheelState()
        end
      end)
    end
    if slua.isValid(mov) then
      local wheels = mov.WheelHubs or mov.Wheels
      if wheels and type(wheels.Num) == "function" then
        _G.MWState._gripMax = _G.MWState._gripMax or {}
        local store = _G.MWState._gripMax
        for i = 0, wheels:Num() - 1 do
          local w = wheels:Get(i)
          if slua.isValid(w) then
            local key = tostring(w)
            local rec = store[key]
            if not rec then
              rec = { lat = 0, lng = 0 };
              store[key] = rec
            end
            local lat = tonumber(w.LatStiffValue) or 0
            local lng = tonumber(w.LongStiffValue) or 0
            if lat > rec.lat then
              rec.lat = lat
            end
            if lng > rec.lng then
              rec.lng = lng
            end
            if rec.lat > 0 then
              w.LatStiffValue = rec.lat
            end
            if rec.lng > 0 then
              w.LongStiffValue = rec.lng
            end
            pcall(_G.OwenGripTire, w)
          end
        end
      end
    end
  end
