    if not itemsOK then
      pcall(_G.ItemLabels.Clear)
    end
    if _G.OwenNeonBomb then
      local bomb = _G.OwenNeonBomb _G.OwenRunFeature('bomb_overlay', _G.OwenAimOn(frameCfg.EspBombMaster) and _G.OwenAimOn(frameCfg.EspBombActive), bomb.Tick, bomb.Clear, bomb, pc, localPlayer)
    end
    if _G.OwenNeonArrow then
