      local arrowOK = _G.OwenRunFeature('arrow_overlay', _G.OwenAimOn(frameCfg.EspPlayer) and _G.OwenAimOn(frameCfg.EspAimArrow), arrow.Tick, arrow.Clear, arrow, pc)
