  function _G.OwenNeonGlyph(canvas, x, y, w, h, kind, z)
    local root = CGame:NewObjectFromPath('/Script/UMG.CanvasPanel', canvas)
    if not Valid(root) then
      return nil
    end
    local slot = canvas:AddChildToCanvas(root)
    if not slot then
      root:RemoveFromParent();
      return nil
    end
    slot:SetPosition(FVector2D(x, y));
    slot:SetSize(FVector2D(w, h));
    slot:SetAlignment(FVector2D(.5, .5));
    slot:SetZOrder(z or 100)
    root:SetWidgetVisibility(UEnums.ESlateVisibility.HitTestInvisible)
    local parts = {}
    local function line(px, py, pw, ph, angle, r, g, b)
      local bar = CGame:NewObjectFromPath('/Script/UMG.Border', root)
      if not Valid(bar) then
        return
      end
      bar:SetBrushColor(FLinearColor(r, g, b, 1));
      bar:SetWidgetVisibility(UEnums.ESlateVisibility.HitTestInvisible)
      local s = root:AddChildToCanvas(bar);
      if not s then
        bar:RemoveFromParent();
        return
      end
      s:SetPosition(FVector2D(px, py));
      s:SetSize(FVector2D(pw, ph));
      s:SetAlignment(FVector2D(.5, .5))
      bar:SetRenderTransformPivot(FVector2D(.5, .5));
      bar:SetRenderAngle(angle or 0);
      parts[ # parts + 1] = bar
    end
    if kind == 'peek' then
      line(w * .5, h * .12, w * .65, 3, 0, .60, .25, 1);
      line(w * .5, h * .88, w * .65, 3, 0, .60, .25, 1)
      line(w * .2, h * .4, w * .27, 4, - 45, .15, .9, 1);
      line(w * .2, h * .6, w * .27, 4, 45, .15, .9, 1)
      line(w * .8, h * .4, w * .27, 4, 45, .15, .9, 1);
      line(w * .8, h * .6, w * .27, 4, - 45, .15, .9, 1)
      line(w * .5, h * .5, 5, h * .32, 0, .85, .7, 1)
    else
      line(w * .36, h * .42, w * .62, 4, - 55, .8, .4, 1)
      line(w * .64, h * .42, w * .62, 4, 55, .8, .4, 1)
      line(w * .5, h * .65, 4, h * .4, 0, .15, .9, 1)
    end
    local item = { w = root, slot = slot, parts = parts }
    PlayerMapMarker._ProtectedWidgetStrs = PlayerMapMarker._ProtectedWidgetStrs or {} PlayerMapMarker._ProtectedWidgetStrs[tostring(root)] = true
    return item
  end
