        local idx = tonumber(data.AimFOVColor) or (sig and tonumber(sig.Color)) or (fov and fov.Color) or 6
        idx = math.max(1, math.min(6, math.floor(idx)))
        local c = rgb[idx] or rgb[6]
        ESP.ArrowColor = CAFLinearColor and CAFLinearColor(c[1], c[2], c[3], 0.95) or { R = c[1], G = c[2],
        B = c[3], A = 0.95 }
        ESP.FOVCircleColor = CAFLinearColor and CAFLinearColor(c[1], c[2], c[3], 0.7) or { R = c[1],
        G = c[2], B = c[3], A = 0.7 }
