          ESP.FOVCircleRadiusY = math.max(20, sig.RY or sig.RX)
        else
          local kind = fov and fov.CachedKind or "NORMAL"
          local ads = fov and fov.CachedADS
          local aimFov
          if kind == "MORTAR" then
            aimFov = tonumber(data.AimTouchMortarFOV) or 360
          elseif kind == "SHOTGUN" then
            aimFov = tonumber(data.AimTouchSGFOV) or 40
          elseif ads and kind == "SNIPER" then
            aimFov = tonumber(data.AimTouchSniperFOV) or 20
          elseif ads then
