              local pt1 = SBL.AbsoluteToLocal(cg, CAFVector2D and CAFVector2D(100, 100) or { X = 100,
              Y = 100 })
              if pt0 and pt1 then
                ESP._CanvasScaleX = (pt1.X - pt0.X) / 100
                ESP._CanvasScaleY = (pt1.Y - pt0.Y) / 100
                ESP._CanvasOffsetX = pt0.X
                ESP._CanvasOffsetY = pt0.Y
                success = true
              end
            end
          end
        end)
        if not success then
          local scale = 1.0
          local WLL = CAWidgetLayoutLibrary
          if WLL and WLL.GetViewportScale then
            scale = WLL.GetViewportScale(PC) or 1.0
