      function ESP.GetArrowAngleRad(PC, WorldLoc, CenterCanvas)
        local angle_rad = 0
        local ScreenPos = CAFVector2D and CAFVector2D(0, 0) or { X = 0, Y = 0 }
        local bProjectOK = false pcall(function()
          local res = PC:ProjectWorldLocationToScreen(WorldLoc, ScreenPos, true)
          bProjectOK = (res == true or res == 1)
        end)
        local front, side, vertical = nil, nil, nil
        local haveCamBasis = false pcall(function()
          local CamMgr = PC.PlayerCameraManager
          if not CAIsValid(CamMgr) and type(PC.GetPlayerCameraManager) == "function" then
            CamMgr = PC:GetPlayerCameraManager()
          end
          if not CAIsValid(CamMgr) then
            return
          end
          local CamLoc = CamMgr:GetCameraLocation()
          local CamRot = CamMgr:GetCameraRotation()
          local pitch, yaw = math.rad(CamRot.Pitch or 0), math.rad(CamRot.Yaw or 0)
          local cp, sp, cy, sy = math.cos(pitch), math.sin(pitch), math.cos(yaw), math.sin(yaw)
          local fx, fy, fz = cp * cy, cp * sy, sp
          local rx, ry = - sy, cy
          local ux, uy, uz = fy * 0 - fz * ry, fz * rx - fx * 0, fx * ry - fy * rx
          local dx, dy, dz = WorldLoc.X - CamLoc.X, WorldLoc.Y - CamLoc.Y, WorldLoc.Z - CamLoc.Z
          front = dx * fx + dy * fy + dz * fz
          side = dx * rx + dy * ry
          vertical = dx * ux + dy * uy + dz * uz
          haveCamBasis = true
        end)
        local behind = haveCamBasis and front and front < - 0.001
        if bProjectOK and not behind then
          local canvasPos = ESP.ScreenPixelToFOVCanvasLocal(PC, ScreenPos)
          local dx = canvasPos.X - CenterCanvas.X
          local dy = canvasPos.Y - CenterCanvas.Y
          if math.abs(dx) > 0.1 or math.abs(dy) > 0.1 then
            angle_rad = math.atan2 and math.atan2(dy, dx) or math.atan(dy, dx)
          end
        elseif haveCamBasis then
          local edgeX, edgeY
          if front > 0.001 then
            edgeX, edgeY = side / front, - vertical / front
          elseif front >= - 0.001 then
            edgeX, edgeY = side, - vertical
          else
            edgeX, edgeY = side, - front
          end
          if math.abs(edgeX) > 0.0001 or math.abs(edgeY) > 0.0001 then
            angle_rad = math.atan2 and math.atan2(edgeY, edgeX) or math.atan(edgeY, edgeX)
          end
        end
        return angle_rad
      end
      function ESP.UpdateCenterCircle(CenterCanvas)
        local G = rawget(_G, "Game") or Game
        if not ESP.ESPCanvas or not CAIsValid(ESP.ESPCanvas) then
          ESP.RemoveCenterCircle()
          return
        end
        local cx = CenterCanvas.X
        local cy = CenterCanvas.Y
        if not ESP.FOVCircleLines then
          ESP.FOVCircleLines = {}
        end
        local function DrawRing(linesTable, radiusX, radiusY, segments, thickness, color, zorder)
          for i = 1, segments do
            local angle1 = ((i - 1) / segments) * (2 * math.pi)
            local angle2 = (i / segments) * (2 * math.pi)
            local x1 = cx + math.cos(angle1) * radiusX
            local y1 = cy + math.sin(angle1) * radiusY
            local x2 = cx + math.cos(angle2) * radiusX
            local y2 = cy + math.sin(angle2) * radiusY
            local dx = x2 - x1
            local dy = y2 - y1
            local len = math.sqrt(dx * dx + dy * dy)
            local ang = (math.atan2 and math.atan2(dy, dx) or math.atan(dy, dx)) * (180.0 / math.pi)
            local lineData = linesTable[i]
            if not lineData then
              local Border = nil
              local CG = rawget(_G, "CGame") or CGame pcall(function()
                Border = CG:NewObjectFromPath("/Script/UMG.Border", ESP.ESPCanvas)
              end)
              if Border and slua.isValid(Border) then
                pcall(function()
                  Border:SetBrushColor(color)
                end)
                pcall(function()
                  Border:SetWidgetVisibility(UEnums.ESlateVisibility.SelfHitTestInvisible)
                end)
                pcall(function()
                  Border:SetRenderTransformPivot(CAFVector2D and CAFVector2D(0.0, 0.5) or { X = 0, Y = 0.5 })
                end)
                local Slot = ESP.ESPCanvas:AddChildToCanvas(Border)
                if Slot then
                  Slot:SetAutoSize( false);
                  Slot:SetZOrder(zorder)
                end
                lineData = { Widget = Border, Slot = Slot }
                linesTable[i] = lineData
              end
            end
            if lineData and lineData.Slot then
              pcall(function()
                lineData.Slot:SetPosition(CAFVector2D and CAFVector2D(x1, y1 - thickness / 2.0) or { X = x1,
                Y = y1 - thickness / 2.0 })
                lineData.Slot:SetSize(CAFVector2D and CAFVector2D(len + 0.5, thickness) or { X = len + 0.5,
                Y = thickness })
                lineData.Widget:SetRenderAngle(ang)
                lineData.Widget:SetWidgetVisibility(UEnums.ESlateVisibility.SelfHitTestInvisible)
              end)
            end
          end
        end
        DrawRing(ESP.FOVCircleLines, ESP.FOVCircleRadius or 250.0, ESP.FOVCircleRadiusY or ESP.FOVCircleRadius or 250.0, ESP.FOVCircleSegments or 72, ESP.FOVCircleThickness or 4.0, ESP.FOVCircleColor, 1)
      end
      function ESP.RemoveCenterCircle()
        for _, tbl in ipairs( { ESP.FOVCircleLines, ESP.FOVCircleGlowLines, ESP.FOVCircleInnerLines,
        ESP.FOVCircleOuterLines }) do
          if tbl then
            for _, lineData in pairs(tbl) do
              if lineData and lineData.Widget and slua.isValid(lineData.Widget) then
                pcall(function()
