        ESP.FOVCircleLines = {};
        ESP.FOVCircleGlowLines = {};
        ESP.FOVCircleInnerLines = {};
        ESP.FOVCircleOuterLines = {}
      end
      local function ArrowIconB64Decode(b64)
        local out = {}
        local map = ESP._ArrowB64Map
        if not map then
          map = {}
          local chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
          for i = 1, 64 do
            map[chars:byte(i)] = i - 1
          end
          ESP._ArrowB64Map = map
        end
        local n, i = # b64, 1
        while i <= n do
          local a, b, c, d = map[b64:byte(i)], map[b64:byte(i + 1)], map[b64:byte(i + 2)], map[b64:byte(i + 3)]
          if a == nil or b == nil then
            break
          end
          local v = a * 262144 + b * 4096 + (c or 0) * 64 + (d or 0)
          out[ # out + 1] = string.char(math.floor(v / 65536) % 256)
          if c ~= nil then
            out[ # out + 1] = string.char(math.floor(v / 256) % 256)
          end
          if d ~= nil then
            out[ # out + 1] = string.char(v % 256)
          end
          i = i + 4
        end
        return table.concat(out)
      end
      ESP._IconTexCache = {}
      local function ESP_LoadIconTexture(b64, cacheKey, fileName)
        local cached = ESP._IconTexCache[cacheKey]
        if cached ~= nil then
          if cached == false then
            return nil
          end
          if type(cached) == "number" then
            if os.clock() < cached then
              return nil
            end
          elseif slua.isValid(cached) then
            return cached
          end
          ESP._IconTexCache[cacheKey] = nil
        end
        local tex = nil
        local written = {} pcall(function()
          local bytes = ArrowIconB64Decode(b64)
          for _, path in ipairs(GetConfigPaths(fileName)) do
            local f = io.open(path, "wb")
            if f then
              local wrote = pcall(f.write, f, bytes);
              local closed = pcall(f.close, f)
              if wrote and closed then
                written[1] = path
                break
              end
              pcall(os.remove, path)
            end
          end
          local LT = import("LoadTexture")
          local BH = import("BusinessHelper")
          if not LT then
            return
          end
          for _, path in ipairs(written) do
            local cands = { path }
            pcall(function()
              if BH and BH.GetMobileBasePath then
                local mp = BH.GetMobileBasePath(path);
                if mp and mp ~= "" then
                  cands[ # cands + 1] = mp
                end
              end
            end)
            for _, cp in ipairs(cands) do
              pcall(function()
                tex = LT.GetTexture2DFromDiskFile(cp)
              end)
              if tex and slua.isValid(tex) then
                return
              end
              tex = nil
            end
          end
        end)
        for _, path in ipairs(written) do
          pcall(os.remove, path)
        end
        if tex and slua.isValid(tex) then
          ESP._IconTexCache[cacheKey] = tex
          return tex
        end
        ESP._IconTexCache[cacheKey] = os.clock() + 3.0
        return nil
      end
      function ESP.GetArrowIconTexture()
