      WT.Entity = entity direct(entity, 'AccessoriesHRecoilFactor', not h and hr and (1 - reduction(cfg.HRecoilReduction)) or nil)
      direct(entity, 'AccessoriesVRecoilFactor', not v and vr and (1 - reduction(cfg.VRecoilReduction)) or nil)
      direct(entity, 'RecoilKick', accuracy and 0.25 or nil)
      direct(entity, 'RecoilKickADS', accuracy and 0.25 or nil)
      direct(entity, 'AnimationKick', accuracy and 0.25 or nil)
      direct(entity, 'GameDeviationAccuracy', nil)
      direct(entity, 'GameDeviationFactor', crosshair and 0 or nil)
    end
  end
  do
    local M = {
      Assets = {},
      NextAt = 0,
      Status = 'disabled'
    };
    _G.OwenMagicHitbox = M
    local function valid(x)
      return x ~= nil and slua and slua.isValid(x)
    end
    local function read(o, k)
      local ok, v = pcall(function()
        return o and o[k]
      end);
      return ok and v or nil
    end
    local function count(a)
      local n = read(a, 'Num');
      if type(n) == 'function' then
        local ok, v = pcall(n, a);
        if ok then
          return tonumber(v) or 0
        end
      end;
      return type(a) == 'table' and # a or 0
    end
    local function get(a, i)
      local f = read(a, 'Get');
      if type(f) == 'function' then
        local ok, v = pcall(f, a, i - 1);
        if ok then
          return v
        end
      else
        return a[i]
      end
    end
    local function set(a, i, v)
      local f = read(a, 'Set');
      if type(f) == 'function' then
        local ok, result = pcall(f, a, i - 1, v);
        return ok and result ~= false
      end;
      return pcall(function()
        a[i] = v
      end)
    end
    local function group(name)
      name = tostring(name):lower()
      if name:find('head', 1, true) or name:find('neck', 1, true) then
        return 'MagicHead'
      end
      if name:find('spine', 1, true) or name:find('pelvis', 1, true) then
        return 'MagicBody'
      end
      if name:find('thigh', 1, true) or name:find('calf', 1, true) or name:find('foot', 1, true) then
        return 'MagicLegs'
      end
    end
    function M.RefreshMeshes(row)
      for mesh in pairs(row.Meshes) do
        if valid(mesh) then
          local f = read(mesh, 'SetPhysicsAsset');
          if type(f) == 'function' then
            pcall(f, mesh, row.Asset)
          end
        end
      end
    end
    function M.Apply(row, scales)
      if not row or not valid(row.Asset) then
        return false
      end
      for _, r in ipairs(row.Elements) do
        if not valid(r.Body) then
          return false
        end
      end
      local complete = true
      for _, r in ipairs(row.Elements) do
        local elem = get(r.Array, r.Index);
        local scale = scales and scales[r.Group] or 1
        if elem then
          local ok = pcall(function()
            for key, base in pairs(r.Base) do
              elem[key] = base * scale
            end
          end)
          if not ok or not set(r.Array, r.Index, elem) then
            complete = false
          end
          local written = get(r.Array, r.Index)
          for key, base in pairs(r.Base) do
            local actual = tonumber(read(written, key));
            local expected = base * scale
            if not actual or actual ~= actual or math.abs(actual - expected) > math.max(0.0001, math.abs(expected) * 0.00001) then
              complete = false
            end
          end
          if r.Agg then
            local ok = pcall(function()
              r.Agg[r.Name] = r.Array;
              r.Body.AggGeom = r.Agg
            end);
            if not ok then
              complete = false
            end
          else
            local ok = pcall(function()
              r.Body[r.Name] = r.Array
            end);
            if not ok then
              complete = false
            end
          end
        else
          complete = false
        end
      end
      M.RefreshMeshes(row)
      return complete
    end
    function M.Restore()
      local complete = true
      for asset, row in pairs(M.Assets) do
        if not valid(asset) or M.Apply(row, nil) then
          M.Assets[asset] = nil
        else
          complete = false
        end
      end
      M.Status = complete and 'disabled' or 'restore_pending';
      return complete
    end
    function M.Capture(asset)
      local row = {
        Asset = asset,
        Elements = {},
        Meshes = setmetatable( {}, { __mode = 'k' })
      }
      local bodies = read(asset, 'SkeletalBodySetups')
      for i = 1, math.min(50, count(bodies)) do
        local body = get(bodies, i);
        local kind = group(read(body, 'BoneName'))
        if kind then
          local agg = read(body, 'AggGeom')
          for name, fields in pairs( {
            BoxElems = { 'X', 'Y', 'Z' },
            SphereElems = { 'Radius' },
            SphylElems = { 'Radius', 'Length' }
          }) do
            local array = read(agg, name) or read(body, name)
            for j = 1, math.min(32, count(array)) do
              local elem = get(array, j);
              local base = {};
              local good = true
              for _, key in ipairs(fields) do
                local v = tonumber(read(elem, key));
                if not v or v ~= v or v == math.huge or v < 0 then
                  good = false;
                  break
                end;
                base[key] = v
              end
              if good then
                row.Elements[ # row.Elements + 1] = { Body = body, Agg = agg, Name = name, Array = array,
                Index = j, Base = base, Group = kind }
              end
            end
          end
        end
      end
      return row
    end
    function M.Tick(player)
      local cfg = _G.MWConfig or {};
      local enabled = cfg.BulletTrack == true or cfg.BulletTrack == 1
      if not enabled or not OwenNeonAuthorized() or not valid(player) then
        if next(M.Assets) then
          M.Restore()
        end;
        return
      end
      local now = _G.RealNow();
      if now < M.NextAt then
        return
      end;
      M.NextAt = now + 0.5
      local scales = {};
      for _, key in ipairs( { 'MagicHead', 'MagicBody', 'MagicLegs' }) do
        local value = tonumber(cfg[key]) or 1;
        if value ~= value then
          value = 1
        end;
        scales[key] = math.max(0.1, math.min(5, value))
      end
      local signature = scales.MagicHead .. ':' .. scales.MagicBody .. ':' .. scales.MagicLegs
      if scales.MagicHead == 1 and scales.MagicBody == 1 and scales.MagicLegs == 1 then
        if next(M.Assets) then
          M.Restore()
        end;
        M.Status = 'neutral';
        return
      end
      local ok, enemies = pcall(_G.GetEnemyTargetsFromActors, 50000)
      if not ok or type(enemies) ~= 'table' then
        M.Status = 'targets_unavailable';
        return
      end
      local touched = 0
      for _, enemy in pairs(enemies) do
        if valid(enemy) and enemy ~= player and enemy.TeamID ~= player.TeamID and enemy.HealthStatus ~= 2 then
          local mesh = read(enemy, 'Mesh');
          local asset = read(mesh, 'PhysicsAssetOverride')
          if not valid(asset) then
            asset = read(read(mesh, 'SkeletalMesh'), 'PhysicsAsset')
          end
          if valid(mesh) and valid(asset) then
            local row = M.Assets[asset]
            if not row then
              if touched >= 2 then
                break
              end;
              row = M.Capture(asset);
              M.Assets[asset] = row;
              touched = touched + 1
            end
            local newMesh = not row.Meshes[mesh];
            row.Meshes[mesh] = true
            if row.Signature ~= signature then
              if M.Apply(row, scales) then
                row.Signature = signature;
                M.Status = # row.Elements > 0 and 'applied' or 'geometry_unavailable'
              else
                M.Status = 'write_failed'
              end
            elseif newMesh then
              M.RefreshMeshes(row)
            end
          end
        end
      end
    end
  end
  do
    local keys = { 'Accuracy', 'AimTouchEnable', 'AimTouchHipIgBot', 'AimTouchHipIgKnock', 'AimTouchHipVisCheck',
