    _G.OwenNormalizeFeatureSwitches = function()
      local cfg = _G.MWConfig;
      if not cfg then
        return
      end
      for _, key in ipairs(keys) do
        local value = cfg[key];
        if value == 0 then
          cfg[key] = false
