  _G.OwenRestoreDisabledVehicleWalls = function()
    local cfg = _G.MWConfig or {};
    if cfg.EspVehicle == true or cfg.EspVehicle == 1 then
      return
    end
    for key, meshes in pairs(_G.OwenVehicleWallMeshes or {}) do
      local complete = true
      for _, mesh in ipairs(meshes) do
        if Valid(mesh) then
          local ok = pcall(function()
            if type(mesh.SetDrawDyeing) == 'function' then
              mesh:SetDrawDyeing( false);
              mesh:SetDrawHighlight( false);
              mesh:SetDrawIdeaOutline( false);
              mesh:SetRenderCustomDepth( false)
            end
          end)
          if not ok then
            complete = false
          end
        end
      end
      if complete then
        _G.OwenVehicleWallMeshes[key] = nil;
        if _G.VehWallState then
          _G.VehWallState[key] = nil
        end
      end
    end
