  _G.OwenUnlockFPSEnforce = function()
    local now = _G.RealNow()
    if now - (_G.MWState.LastFPSEnforce or 0) < 2 then
      return
    end
    _G.MWState.LastFPSEnforce = now
    local hud = slua_GameFrontendHUD
    local cfg = hud and hud:GetUserSettings()
    if not cfg then
      return
    end
    if cfg.BattleFPS ~= 8 then
      pcall(function()
        hud:BeginModifyUserSettings()
      end)
      cfg.BattleFPS = 8 pcall(function()
        hud:FinishModifyUserSettings()
      end)
    end
    local lib = import("STExtraBlueprintFunctionLibrary")
    local cur = lib and lib.GetConsoleVariableFloatValue("t.MaxFPS") or 0
    local target = tonumber(_G.MWConfig.TargetFPS) or 0
    if target <= 0 then
      target = 165
    end
    if _G.OwenNeonOriginalFPS == nil then
      _G.OwenNeonOriginalFPS = cur
    end
    if math.abs(cur - target) > 0.1 then
      local gi = require("client.common.ui_util").GetGameInstance()
      if gi then
        gi:ExecuteCMD("t.MaxFPS", tostring(target));
        gi:ExecuteCMD("r.FrameRateLimit", tostring(target))
      end
    end
  end
  _G.OwenSkinSlowTick = function(localPlayer)
    local isAlive = type(localPlayer.IsAlive) == "function" and localPlayer:IsAlive() or true
    if not isAlive then
      return
    end
    if _G.HandlePetLogic then
      _G.HandlePetLogic()
    end
    if not _G.AddOutfit then
      return
    end
    if _G.AddOutfit.isInRealMatch() then
      _G.AddOutfitLobbyRestored = false _G.AddOutfit.matchApplyAllSlots(localPlayer, false)
      if not _G.SmartWeaponWatcherActive then
        _G.AddOutfit.matchApplyWeaponSkin(localPlayer)
      end
    elseif _G.OwenLobbySkinHealthTick then
      _G.OwenLobbySkinHealthTick()
    end
  end
  local function MainLoop()
    if _G.OwenSyncDisplayTimers then
      _G.OwenSyncDisplayTimers()
    end
    if not _G._AimFrameTickRegistered then
      _G.OwenNormalizeFeatureSwitches()
    end
    if _G.OwenVehicleWallMeshes and next(_G.OwenVehicleWallMeshes) then
      pcall(_G.OwenRestoreDisabledVehicleWalls)
    end
    if not OwenNeonAuthorized() then
      if _G.OwenMagicHitbox then
        pcall(_G.OwenMagicHitbox.Restore)
      end;
      return
    end
    if _G.OwenHeldAttachmentCollectorTick and _G.OwenNeonLobbySceneAllowed and _G.OwenNeonLobbySceneAllowed() == true then
      local now = _G.RealNow()
      if now >= (_G.OwenHeldCollectorNext or 0) then
        _G.OwenHeldCollectorNext = now + 1 pcall(_G.OwenHeldAttachmentCollectorTick)
      end
    end
    if _G.OwenNeonNativeTick then
      pcall(_G.OwenNeonNativeTick)
    end
    if _G.OwenNeonWeatherTick then
      pcall(_G.OwenNeonWeatherTick)
    end
    if _G.OwenGraphics and (_G.MWConfig.GraphicsCustomize == true or _G.MWConfig.GraphicsCustomize == 1 or next(_G.OwenGraphics.Owned) or _G.OwenGraphics.Baseline or (_G.OwenGraphics.RestoreChecks and next(_G.OwenGraphics.RestoreChecks)) or (_G.OwenBuildingLOD and next(_G.OwenBuildingLOD.Rows))) then
      pcall(_G.OwenGraphics.Tick)
    end
    if _G.MWState.CustomTextData == nil then
      _G.MWState.CustomTextData = _G.MWDefaultTextData()
    end
    local GameplayData = _G._ML_GPD
    if not GameplayData then
      local okData, mod = pcall(require, "GameLua.GameCore.Data.GameplayData")
      if not okData or not mod then
        return
      end
      GameplayData = mod;
      _G._ML_GPD = mod
    end
    local pc = GameplayData.GetPlayerController()
    local localPlayer = nil
    if Valid(pc) then
      localPlayer = pc:GetPlayerCharacterSafety()
    end
    local outfit = _G.AddOutfit
    local skinOn = _G.MWConfig.ModSkin == true or _G.MWConfig.ModSkin == 1
    if outfit then
      if skinOn then
        if outfit.installEquipEventBridge then
          pcall(outfit.installEquipEventBridge)
        end
        if outfit.tickEquipmentSkins then
          pcall(outfit.tickEquipmentSkins, localPlayer)
        end
        if outfit.GloveLOD then
          pcall(outfit.GloveLOD.Tick, localPlayer)
        end
        if outfit.maintainSelectedGloves then
          pcall(outfit.maintainSelectedGloves)
        end
      else
        if type(_G.OwenRestoreWeaponSkin) == 'function' and next(_G.OwenWeaponRestoreState or {}) then
          pcall(_G.OwenRestoreWeaponSkin)
        end
        if outfit.GloveLOD and next(outfit.GloveLOD.Rows) then
          pcall(outfit.GloveLOD.Restore)
        end
        outfit.GloveRecovery = nil;
        outfit.GlovePollNext = nil;
        outfit.GloveNativeRecovery = nil;
        outfit.GloveADSState = nil
      end
    end
    if not Valid(localPlayer) then
      if _G.OwenMagicHitbox then
        pcall(_G.OwenMagicHitbox.Restore)
      end
      if _G.OwenWeaponTuning then
        pcall(_G.OwenWeaponTuning.Restore)
      end
      if _G.OwenNeonScopeTick then
        pcall(_G.OwenNeonScopeTick, nil, nil)
