      for key, data in pairs(_G.MWState.EnemyMarks) do
        if data and data.MIDs then
          for meshStr, midTable in pairs(data.MIDs) do
            for k, _ in pairs(midTable) do
              midTable[k] = nil
            end
          end
          data.MIDs = nil
        end
        if data and data.MIDs_V3 then
          for meshStr, midTable in pairs(data.MIDs_V3) do
            for k, _ in pairs(midTable) do
              midTable[k] = nil
            end
          end
          data.MIDs_V3 = nil
        end
      end
      if _G.MWState.EnemyMarks and next(_G.MWState.EnemyMarks) ~= nil then
        _G.MWState.EnemyMarks = {}
      end
      if _G.MWState.PrevGraphicsState and next(_G.MWState.PrevGraphicsState) ~= nil then
        _G.MWState.PrevGraphicsState = {}
      end
