        _G.ApplyWeaponGlow(localPlayer)
      end
    end
    if _G.MWConfig.ModSkin and _G.MWConfig.SkinDeadBox and _G.DeadBox_TemperRequest and (_G.NeedCheckDeadBoxTimer or 0) > 0 then
      pcall(_G.DeadBox_TemperRequest, pc)
    end
    if _G.MWConfig.ModSkin then
      local curTime = _G.RealNow()
      if not _G.LastSkinUpdateTime or (curTime - _G.LastSkinUpdateTime) > 2.5 then
        _G.LastSkinUpdateTime = curTime pcall(_G.OwenSkinSlowTick, localPlayer)
      end
