    pcall(_G.MWHiggs.Tick, pc)
    if not false and _G.MWHeliTurn then
      pcall(function()
        for _, o in pairs(_G.MWHeliTurn) do
          if Valid(o.hm) then
            if type(o.a) == "number" then
              o.hm.MaxBackWingTorqueVaule = o.a
            end
            if type(o.b) == "number" then
              o.hm.SecondMaxBackWingTorqueVaule = o.b
            end
          end
        end
        _G.MWHeliTurn = nil
      end)
    end
    if not false and _G.MWTankTurret then
      pcall(function()
        for _, o in pairs(_G.MWTankTurret) do
          if Valid(o.t) and type(o.s) == "number" then
            o.t.WeaponRotationLagSpeed = o.s
          end
        end
        _G.MWTankTurret = nil
      end)
    end
    if not false and _G.MWMecha then
      pcall(function()
        for _, o in pairs(_G.MWMecha) do
          if Valid(o.mc) then
            if type(o.jz) == "number" then
              o.mc.JumpZVel = o.jz
            end
            if type(o.jjz) == "number" then
              o.mc.JetJumpZVel = o.jjz
            end
            if type(o.jzv) == "number" then
              o.mc.JumpZVelocity = o.jzv
            end
            if type(o.mf) == "number" then
              o.mc.MaxForwardSpeed = o.mf
            end
            if type(o.mb) == "number" then
              o.mc.MaxBackwardSpeed = o.mb
            end
            if type(o.ml) == "number" then
              o.mc.MaxLateralSpeed = o.ml
            end
            if type(o.sr) == "number" then
              o.mc.SpeedRate = o.sr
            end
