                                local w = slua.getWorld()
                                if KSL and w then
                                  KSL.ExecuteConsoleCommand(w, "r.EnableDrawDyeingColor 1")
                                  KSL.ExecuteConsoleCommand(w, "r.CustomDepth 3")
                                  KSL.ExecuteConsoleCommand(w, "r.IdeaOutline.Enable 1")
                                  KSL.ExecuteConsoleCommand(w, "r.Highlight.Enable 1")
                                  _G.ConsoleNewWallReady = true
                                end
                              end
                              local LC = _G.OwenImp("LinearColor") or _G.FLinearColor
                              local visC = LC and LC(0, 22, 100, 100) or nil
                              local occC = LC and LC(100, 0, 0, 100) or nil
                              local vehMeshes = {} pcall(function()
                                local skels = veh:GetComponentsByClass(_G.OwenImp("SkeletalMeshComponent"))
                                if skels then
                                  for _, m in pairs(skels) do
                                    if slua.isValid(m) then
                                      table.insert(vehMeshes, m)
                                    end
                                  end
                                end
                              end)
                              pcall(function()
                                local statics = veh:GetComponentsByClass(_G.OwenImp("StaticMeshComponent"))
                                if statics then
                                  for _, m in pairs(statics) do
                                    if slua.isValid(m) then
                                      table.insert(vehMeshes, m)
