  _G.NeedCheckDeadBoxTimer = 0
  local function dbRead(object, key)
    local ok, value = pcall(function()
      return object and object[key]
    end)
    if ok then
      return value
    end
  end
  local function dbCall(object, key, ...)
    local fn = dbRead(object, key);
    if type(fn) ~= 'function' then
      return nil
    end
    local ok, value = pcall(fn, object, ...);
    if ok then
      return value
    end
  end
  local function dbValid(object)
    local ok, value = pcall(slua.isValid, object);
    return ok and value == true
  end
  _G.OwenQueueDeadBoxSkin = function(pc, record)
    if not (_G.MWConfig or {}).SkinDeadBox then
      return false
    end
    local pawn = dbCall(pc, 'GetPlayerCharacterSafety');
    if not dbValid(pawn) then
      return false
    end
    local weapon = dbCall(pawn, 'GetCurrentWeapon') or dbRead(pawn, 'CurrentWeapon')
    local id = tonumber(dbRead(dbCall(weapon, 'GetItemDefineID'), 'TypeSpecificID')) or 0
    local skin = tonumber((_G.AddOutfitLastAppliedSkin or {})[id]) or 0
    if skin <= 1000000 then
      local syn = dbRead(weapon, 'synData');
      local item = dbCall(syn, 'Get', 7)
      local ok, define = pcall(function()
        return item and slua.IndexReference(item, 'defineID')
      end)
      if ok then
        skin = tonumber(dbRead(define, 'TypeSpecificID')) or 0
      end
    end
    if skin <= 1000000 then
      skin = tonumber(dbRead(record, 'CauserWeaponAvatarID')) or 0
    end
    if dbRead(record, 'DamageType') == (UEnums.DamageType or {}).VehicleDamage then
      local vehicleSkin = tonumber(_G.CurrentEquipVehicleID) or 0
      if vehicleSkin > 0 then
        skin = tonumber(tostring(vehicleSkin) .. '1') or 0
      end
    end
    if skin <= 1000000 then
      return false
    end
    local key = dbRead(pc, 'PlayerKey') or dbRead(pawn, 'PlayerKey')
    if key == nil then
      return false
    end
    deadBoxPending = { Skin = skin, PlayerKey = tostring(key), Until = _G.RealNow() + 15 }
    _G.NeedCheckDeadBoxTimer = 30;
    _G.LastCheckDeadBoxTime = nil
    return true
  end
  local function dbCauserMatches(actor, key)
    local causer = dbRead(actor, 'DamageCauser')
    if not dbValid(causer) then
      return false
    end
    local function matches(object)
      local playerKey = dbRead(object, 'PlayerKey')
      return playerKey ~= nil and tostring(playerKey) == key
    end
    if matches(causer) then
      return true
    end
    return matches(dbCall(causer, 'GetOwner')) or matches(dbCall(causer, 'GetInstigator'))
  end
  _G.DeadBox_TemperRequest = function(pc)
    if not (_G.MWConfig or {}).SkinDeadBox then
      deadBoxPending = nil;
      _G.NeedCheckDeadBoxTimer = 0;
      return
    end
    if not deadBoxPending or (_G.NeedCheckDeadBoxTimer or 0) <= 0 then
      return
    end
    local now = _G.RealNow()
    if now > deadBoxPending.Until then
      deadBoxPending = nil;
      _G.NeedCheckDeadBoxTimer = 0;
      return
    end
    if _G.LastCheckDeadBoxTime and now - _G.LastCheckDeadBoxTime < 0.5 then
      return
    end
    local pawn = dbCall(pc, 'GetPlayerCharacterSafety');
    if not dbValid(pawn) then
      return
    end
    if tostring(dbRead(pc, 'PlayerKey') or dbRead(pawn, 'PlayerKey')) ~= deadBoxPending.PlayerKey then
      deadBoxPending = nil;
      _G.NeedCheckDeadBoxTimer = 0;
      return
    end
    _G.LastCheckDeadBoxTime = now;
    _G.NeedCheckDeadBoxTimer = _G.NeedCheckDeadBoxTimer - 1
    if not cached_GameplayStatics then
      cached_GameplayStatics = import('GameplayStatics');
      cached_ActorClass = import('Actor');
      cached_PlayerTombBox = import('PlayerTombBox')
    end
    if not _G.CachedActorArray_DB then
      _G.CachedActorArray_DB = slua.Array(UEnums.EPropertyClass.Object, cached_ActorClass)
    end
    local ui = require('client.common.ui_util');
    local instance = ui and ui.GetGameInstance()
    if not instance then
      return
    end
    local array = _G.CachedActorArray_DB
    if type(dbRead(array, 'Clear')) == 'function' then
      dbCall(array, 'Clear')
    end
    local result = cached_GameplayStatics.GetAllActorsOfClass(instance, cached_PlayerTombBox, array)
    local boxes = (type(dbRead(result, 'Num')) == 'function' or type(result) == 'table') and result or array
    local count = tonumber(dbCall(boxes, 'Num')) or (type(boxes) == 'table' and # boxes) or 0
    for i = 1, count do
      local actor = type(dbRead(boxes, 'Get')) == 'function' and dbCall(boxes, 'Get', i - 1) or boxes[i]
      if dbValid(actor) and not deadBoxApplied[actor] and dbCauserMatches(actor, deadBoxPending.PlayerKey) then
        local component = dbRead(actor, 'DeadBoxAvatarComponent_BP')
        if dbValid(component) then
          local ok, err = pcall(function()
            assert(type(dbRead(component, 'PreChangeItemAvatar')) == 'function' and type(dbRead(component, 'SyncChangeItemAvatar')) == 'function', 'avatar_methods_unavailable')
            if type(dbRead(component, 'ResetItemAvatar')) == 'function' then
              assert(component:ResetItemAvatar() ~= false, 'avatar_reset_failed')
            end
            assert(component:PreChangeItemAvatar(deadBoxPending.Skin) ~= false, 'avatar_prepare_failed')
            assert(component:SyncChangeItemAvatar(deadBoxPending.Skin) ~= false, 'avatar_sync_failed')
          end)
          if ok then
            deadBoxApplied[actor] = true
          end
          _G.OwenDeadBoxSkinStatus = ok and 'skin_requested' or tostring(err)
        end
      end
    end
  end
