      end
      if F.isValidWeaponPersistEntry(wid, res) then
        clean[wid] = res
      end
    end
    return clean
  end
  function F.indexWeaponSkin(resID, insID)
    resID, insID = tonumber(resID), tonumber(insID)
    if not resID or not insID then
      return
    end
    local c = F.cfg(resID)
    local st = F.subType(c)
    if not (GUN_SUB[st] or st == MELEE_ID) then
      return
    end
    local wid = F.weaponIdFromSkin(resID)
    wid = tonumber(wid)
    if not wid or wid <= 0 then
      return
    end
    R.byWeapon[wid] = R.byWeapon[wid] or {} R.byWeapon[wid][resID] = insID
  end
  function F.isInjectedIns(ins)
    return ins and R.insToRes[tonumber(ins)] ~= nil
  end
  function F.isSyntheticIns(ins)
    local id = tonumber(ins)
    return id ~= nil and R.syntheticIns[id] ~= nil
  end
  function F.noteSyntheticSelection(state, insID, resID)
    _G.OwenSkinSelectionStatus = state
    _G.OwenSkinSelectionDetail = { State = state, InsID = tonumber(insID), ResID = tonumber(resID) }
    local audit = rawget(_G, 'OwenSkinAudit')
    if audit and type(audit.Selection) == 'function' then
      pcall(audit.Selection, state, insID, resID)
    end
    if state == 'local_apply_error' or state == 'local_item_unavailable' or state == 'local_type_unsupported' then
      local now = os.clock()
      if now >= (F._lastSyntheticNoticeAt or 0) then
        F._lastSyntheticNoticeAt = now + 5 pcall(Notify, 'Chưa áp được skin. Hãy thử chọn lại skin.')
      end
    end
  end
  function F.getSyntheticItem(insID, resID)
    insID = tonumber(insID)
    local mapped = insID and R.syntheticIns[insID]
    if not mapped or R.insToRes[insID] ~= mapped then
      return nil
    end
    if resID ~= nil and tonumber(resID) ~= mapped then
      return nil
    end
    local entity = F.getEntity()
    if not entity or entity ~= R.syntheticEntity then
      return nil
    end
    local item = entity.GetDataByInsID and entity:GetDataByInsID(insID)
    if not item then
      return nil
    end
    if tonumber(item.insID or item.instid or item.ins_id) ~= insID then
      return nil
    end
    if tonumber(item.resID or item.res_id) ~= mapped then
      return nil
    end
    if item.count ~= nil and ( not tonumber(item.count) or tonumber(item.count) <= 0) then
      return nil
    end
    return item, mapped
  end
  function F.isMatchOnlyCosmeticSlot(slot)
    return slot == 'parachute' or slot == 'glider' or slot == 'footEffect' or slot == 'runTrail' or slot == 'footprint'
  end
  function F.isMatchOnlyCosmeticRes(resID)
    local st = tonumber(F.subType(F.cfg(resID)))
    return st == 423 or st == 453 or st == 454 or F.isParachuteRes(resID) or F.isGlideRes(resID) or GLIDER_SUBS[st] == true
  end
  function F.localSkinSlot(resID)
    local st = F.subType(F.cfg(resID))
    if GUN_SUB[st] or st == MELEE_ID then
      return 'weapon:' .. tostring(F.weaponIdFromSkin(resID))
    end
    if F.isParachuteRes(resID) then
      return 'parachute'
    end
    if F.isGlideRes(resID) or GLIDER_SUBS[st] then
      return 'glider'
    end
    if st == OUTFIT_SUB then
      return F.isSuitRes(resID) and 'outfit' or 'tshirt'
    end
    if st == HAT_SUB or HEAD_SUBS[st] then
      return 'head'
    end
    if BAG_SUBS[st] then
      return 'bag'
    end
    if HELMET_SUBS[st] then
      return 'helmet'
    end
    return 'subtype:' .. tostring(st)
  end
  function F.cancelLocalSkinSelection(insID)
    local id = tonumber(insID)
    local res = id and R.insToRes[id]
    if not res and id then
      local wd = require('client.slua.logic.wardrobe.wardrobe_data')
      local item = wd:GetHallDepotItemDataByInsID(id)
      res = item and tonumber(item.resID or item.res_id)
    end
    if res and F.LocalSkinSelections then
      local slot = F.localSkinSlot(res)
      F.LocalSkinSelections[slot] = nil
      if slot == 'outfit' or slot == 'tshirt' then
        F.LocalSkinSelections.outfit = nil;
        F.LocalSkinSelections.tshirt = nil
      end
    end
  end
  function F.selectLocalSkin(insID)
    insID = tonumber(insID)
    if not F.isSyntheticIns(insID) then
      return false
    end
    if F.skinOff() then
      F.noteSyntheticSelection('local_mod_disabled', insID);
      return false
    end
    local item, resID = F.getSyntheticItem(insID)
    if not item or not F.cfg(resID) then
      F.noteSyntheticSelection('local_item_unavailable', insID, resID);
      return false
    end
    if F.isMatchOnlyCosmeticRes(resID) and not F.isInRealMatch() then
      local slot = F.matchOnlySelectionSlot and F.matchOnlySelectionSlot(resID)
      if F.LocalSkinCleared and slot then
        F.LocalSkinCleared[slot] = nil
      end
      F.saveEquip(resID, insID)
      F.noteSyntheticSelection('local_saved_for_match', insID, resID)
      return true
    end
    local slot = F.localSkinSlot(resID)
    F.LocalSkinSelections = F.LocalSkinSelections or {}
    local request = { InsID = insID, ResID = resID, Entity = F.getEntity() }
    F.LocalSkinSelections[slot] = request
    if slot == 'outfit' then
      F.LocalSkinSelections.tshirt = nil
    elseif slot == 'tshirt' then
      F.LocalSkinSelections.outfit = nil
    end
    F.saveEquip(resID, insID)
    if not F.isResourcesReady(resID) then
      F.noteSyntheticSelection('local_resource_pending', insID, resID)
      F.requestResourceDownload(resID, function()
        if not F.skinOff() and F.LocalSkinSelections[slot] == request and F.getEntity() == request.Entity then
          F.selectLocalSkin(insID)
        end
      end)
      return true
    end
    local ok, applied = pcall(F.tryLocalWearByIns, insID)
    local state = not ok and 'local_apply_error' or (applied and 'local_apply_requested' or 'local_type_unsupported')
    F.noteSyntheticSelection(state, insID, resID)
    return ok and applied == true
  end
  function F.isInjectedRes(res)
    return res and R.resToIns[tonumber(res)] ~= nil
  end
  function F.isWeaponSkinRes(resID)
    resID = tonumber(resID)
    if not resID then
      return false
    end
    local st = F.subType(F.cfg(resID))
    return GUN_SUB[st] or st == MELEE_ID
  end
  function F.isWeaponSkinIns(insID)
    insID = tonumber(insID)
    if not insID then
      return false
    end
    local res = R.insToRes[insID]
    return res and F.isWeaponSkinRes(res)
  end
  function F.cleanArmoryPollution()
    pcall(function()
      local Arm = require("client.logic.armory.logic_armory")
      if not Arm.rsp_list then
        return
      end
      if Arm.rsp_list.install_list then
        for wid, entry in pairs(Arm.rsp_list.install_list) do
          local ins = tonumber(entry and entry.skin_id)
          if ins and not F.isWeaponSkinIns(ins) then
            Arm.rsp_list.install_list[wid] = nil
          end
        end
      end
      if Arm.rsp_list.skin_list then
        for wid, skins in pairs(Arm.rsp_list.skin_list) do
          if type(skins) == "table" then
            for resID in pairs(skins) do
              if not F.isWeaponSkinRes(tonumber(resID)) then
                skins[resID] = nil
              end
            end
          end
        end
      end
    end)
  end
  function F.depotSubType(insID, resID)
    resID = tonumber(resID) or tonumber(R.insToRes[insID])
    local st = F.subType(F.cfg(resID))
    if st then
      return st
    end
    local wd = require("client.slua.logic.wardrobe.wardrobe_data")
    local d = wd:GetHallDepotItemDataByInsID(insID)
    return d and tonumber(d.itemSubType)
  end
  function F.tryLocalWearByIns(insID)
    insID = tonumber(insID)
    if not insID then
      return false
    end
    if F.skinOff() then
      return false
    end
    local d, resID = F.getSyntheticItem(insID)
    if not d then
      return false
    end
    if not resID or resID <= 0 then
      return false
    end
    local st = F.depotSubType(insID, resID)
    local function mapLocal()
      if not R.insToRes[insID] then
        R.insToRes[insID] = resID
        R.resToIns[resID] = insID
      end
    end
    if st == GLOVES_SUB then
      mapLocal();
      F.putOnGloves(insID)
      return true
    end
    F.clearItemExpire(d, insID, resID)
    F.ensureDepotItemValid(insID, resID)
    if F.isParachuteRes(resID) then
      mapLocal();
      return F.putOnParachute(insID)
    end
    if F.isGlideRes(resID) or GLIDER_SUBS[st] then
      mapLocal();
      return F.putOnGlider(insID)
    end
    if st == OUTFIT_SUB then
      mapLocal()
      if F.isSuitRes(resID) or F.wardrobeTab(resID) == TAB_SUIT then
        F.putOnOutfit(insID)
      else
        F.putOnRoleWear(insID)
      end
      return true
    end
    if st == HAT_SUB or HEAD_SUBS[st] then
      mapLocal();
      F.putOnHat(insID)
      return true
    end
    if FACE_SUBS[st] then
      mapLocal();
      F.putOnFaceAccessory(insID)
      return true
    end
    if BODY_SUBS[st] or HELMET_SUBS[st] then
      mapLocal();
      F.putOnRoleWear(insID)
      return true
    end
    if not F.isInjectedIns(insID) then
      return false
    end
    if F.extraCosmeticSlot(st) then
      return F.putOnExtraCosmetic(insID)
    end
    if GUN_SUB[st] then
      local wid = F.weaponIdFromSkin(resID)
      if wid then
        F.equipWeaponSkin(wid, insID)
      end
      return true
    end
    if st == MELEE_ID then
      local wid = F.weaponIdFromSkin(R.insToRes[insID]);
      if wid then
        return F.equipWeaponSkin(wid, insID)
      end;
      return false
    end
    if F.isHallThemeRes(resID) and (F.isInjectedIns(insID) or F.isInjectedRes(resID)) then
      mapLocal()
      return F.putOnHallTheme(insID)
    end
    if F.isVehicleRes(resID) and (F.isInjectedIns(insID) or F.isInjectedRes(resID)) then
      mapLocal()
      return F.putOnVehicle(insID)
    end
    return false
  end
  function F.isHallThemeRes(resID)
    local c = F.cfg(tonumber(resID))
    if not c then
      return false
    end
    local t = c.ItemType or c.itemType
    return t == HALL_THEME_TYPE
  end
  function F.skinFamilyResourceIDs(res)
    res = tonumber(res)
    if not res or res <= 0 then
      return {}
    end
    local now = _G.RealNow()
    F.ResourceFamilyCache = F.ResourceFamilyCache or {}
    local cached = F.ResourceFamilyCache[res]
    if cached and now < cached.Until then
      return cached.IDs
    end
    local result, seen = {}, {}
    local function add(id)
      id = tonumber(id)
      if id and id > 0 and id % 1 == 0 and not seen[id] then
        seen[id] = true;
        result[ # result + 1] = id
      end
    end
    add(res)
    local cfg = F.cfg(res)
    local subtype = cfg and tonumber(F.subType(cfg))
    if not subtype or not (BAG_SUBS[subtype] or HELMET_SUBS[subtype]) then
      return result
    end
    local equipment = (F.NeonEquipmentFamilies or {})[res]
    if equipment then
      for n = 1, 3 do
        add(equipment[n])
      end
    end
    if F.levelSkinID then
      for n = 1, 3 do
        add(F.levelSkinID(res, n))
      end
    end
    pcall(function()
      local cfg = CDataTable.GetTableData('BackpackMapping', res)
      if cfg then
        add(cfg.SkinItemIDLv1);
        add(cfg.SkinItemIDLv2);
        add(cfg.SkinItemIDLv3);
        add(cfg.LobbyShowItemID)
      end
    end)
    table.sort(result)
    F.ResourceFamilyCache[res] = { IDs = result, Until = now + 10 }
    return result
  end
  function F.downloadResourceIDs(res)
    if not F.skinOff() and not F.isInRealMatch() and _G.OwenNeonLobbySceneAllowed and _G.OwenNeonLobbySceneAllowed() == true then
      return F.skinFamilyResourceIDs(res)
    end
    return { tonumber(res) }
  end
  function F.installFamilyDownload()
    F.ResourceFamilyCache = {}
    local ok, PM = pcall(require, 'client.slua.logic.download.puffer.puffer_manager')
    local success, constants = pcall(require, 'client.slua.logic.download.puffer_const')
    if not ok or not success or not PM or not constants or not constants.ENUM_DownloadType then
      return
    end
    if type(PM.Download) == 'function' and PM.Download ~= F.FamilyDownloadWrapper then
      local original = PM.Download
      local wrapper = function(kind, ids, ...)
        if kind ~= constants.ENUM_DownloadType.ODPAK or type(ids) ~= 'table' or F.skinOff() or F.isInRealMatch() or not (_G.OwenNeonLobbySceneAllowed and _G.OwenNeonLobbySceneAllowed() == true) then
          return original(kind, ids, ...)
        end
        local expanded, seen = {}, {}
        for _, id in ipairs(ids) do
          local items = F.isInjectedRes(tonumber(id)) and F.skinFamilyResourceIDs(id) or { id }
          for _, item in ipairs(items) do
            if not seen[item] then
              seen[item] = true;
              expanded[ # expanded + 1] = item
            end
          end
        end
        return original(kind, expanded, ...)
      end
      F.FamilyDownloadWrapper = wrapper;
      PM.Download = wrapper
    end
    pcall(function()
      local mgr = ModuleManager.GetModule(ModuleManager.CommonModuleConfig.puffer_odpak_manager)
      if not mgr or type(mgr.GetStateByItemID) ~= 'function' or mgr.GetStateByItemID == F.FamilyStateWrapper then
        return
      end
      local original = mgr.GetStateByItemID
      local wrapper = function(self, id, ...)
        local state = original(self, id, ...)
        if state ~= constants.ENUM_DownloadState.Done or F.skinOff() or F.isInRealMatch() or not (_G.OwenNeonLobbySceneAllowed and _G.OwenNeonLobbySceneAllowed() == true) or not F.isInjectedRes(tonumber(id)) then
          return state
        end
        for _, member in ipairs(F.skinFamilyResourceIDs(id)) do
          local pending = original(self, member, ...)
          if pending ~= constants.ENUM_DownloadState.Done then
            return pending
          end
        end
        return state
      end
      F.FamilyStateWrapper = wrapper;
      mgr.GetStateByItemID = wrapper
    end)
  end
  function F.isResourcesReady(resID)
    resID = tonumber(resID)
    if not resID or resID <= 0 then
      return false
    end
    if not F.isInjectedRes(resID) then
      return true
    end
    local ready = false pcall(function()
      local PufferConst = require("client.slua.logic.download.puffer_const")
      local mgr = ModuleManager.GetModule(ModuleManager.CommonModuleConfig.puffer_odpak_manager)
      if mgr and mgr.GetStateByItemID then
        ready = true
        for _, id in ipairs(F.downloadResourceIDs(resID)) do
          if mgr:GetStateByItemID(id) ~= PufferConst.ENUM_DownloadState.Done then
            ready = false;
            break
          end
        end
      end
    end)
    return ready
  end
  function F.resourceScene()
    if F.isInRealMatch and F.isInRealMatch() then
      return 'match'
    end
    if _G.OwenNeonLobbySceneAllowed and _G.OwenNeonLobbySceneAllowed() == true then
      return 'lobby'
    end
    return 'unknown'
  end
  function F.requestResourceDownload(resID, onReady)
    if F.skinOff() then
      return
    end
    if F.isMatchOnlyCosmeticRes(resID) and not F.isInRealMatch() then
      return
    end
    local requestedScene = F.resourceScene()
    if requestedScene == 'unknown' then
      return
    end
    if onReady then
      local original = onReady
      onReady = function()
        if not F.skinOff() and F.resourceScene() == requestedScene then
          return original()
        end
      end
    end
    resID = tonumber(resID)
    if not resID or resID <= 0 or not F.isInjectedRes(resID) then
      return
    end
    if F.isResourcesReady(resID) then
      if onReady then
        pcall(onReady)
      end
      return
    end
    F.resourceReadyCallbacks = F.resourceReadyCallbacks or {}
    if onReady then
      F.resourceReadyCallbacks[resID] = onReady
    end
    _G.AddOutfitDownloadQueued = _G.AddOutfitDownloadQueued or {}
    local pending = _G.AddOutfitDownloadQueued[resID]
    local now = _G.RealNow()
    if type(pending) == 'table' and now - pending.At < 60 then
      return
    end
    local ticket = { At = now }
    _G.AddOutfitDownloadQueued[resID] = ticket
    local ok = pcall(function()
      local PM = require("client.slua.logic.download.puffer.puffer_manager")
      local PufferConst = require("client.slua.logic.download.puffer_const")
      PM.Download(PufferConst.ENUM_DownloadType.ODPAK, F.downloadResourceIDs(resID), "AddOutfit", function()
        if _G.AddOutfitDownloadQueued[resID] ~= ticket then
          return
        end
        _G.AddOutfitDownloadQueued[resID] = nil
        local callback = F.resourceReadyCallbacks[resID]
        F.resourceReadyCallbacks[resID] = nil
        if callback and not F.skinOff() and F.isResourcesReady(resID) then
          pcall(callback)
        end
      end)
    end)
    if not ok then
      _G.AddOutfitDownloadQueued[resID] = nil
      F.resourceReadyCallbacks[resID] = nil
    end
  end
  function F.extraCosmeticSlot(st)
    st = tonumber(st)
    if st == 423 then
      return "footEffect"
    end
    if st == 453 then
      return "runTrail"
    end
    if st == 454 then
      return "footprint"
    end
    if st == 612 then
      return "fragSkin"
    end
    if st == 613 then
      return "smokeSkin"
    end
    if st == 614 then
      return "stunSkin"
    end
    if st == 615 then
      return "molotovSkin"
    end
  end
  function F.putOnExtraCosmetic(insID)
    insID = tonumber(insID)
    if not insID or F.skinOff() then
      return false
    end
    local resID = R.insToRes[insID]
    local st = resID and tonumber(F.subType(F.cfg(resID)))
    local slot = F.extraCosmeticSlot(st)
    if not slot then
      return false
    end
    if F.isMatchOnlyCosmeticSlot(slot) and not F.isInRealMatch() then
      F.saveEquip(resID, insID)
      return true
    end
    F.ensureDepotItemValid(insID, resID)
    F.ensureInjectedItemAlive( nil, resID, insID)
    if st >= 612 and st <= 615 then
      pcall(F.hookThrowCosmetics)
    end
    local fbd = require("client.slua.logic.wardrobe.fashionbag.fashionbag_data")
    local bagIndex = tonumber(fbd.use_index) or 1
    if st >= 612 and st <= 615 then
      fbd:PutOnThrowObjectSkin(insID, bagIndex)
    elseif st == 423 then
      DataMgr.UpdateFootEffect(insID)
    else
      DataMgr.UpdateCommonPutOnDataBy(st, insID)
    end
    F.saveEquip(resID, insID)
    if F.isInRealMatch and F.isInRealMatch() then
      pcall(F.applyMatchExtraCosmetics, F.getLocalChar())
    end
    local function applyVisual()
      if F.skinOff() or F.cache()[slot .. "Res"] ~= resID then
        return
      end
      if not _G.OwenNeonLobbySceneAllowed() then
        return
      end
      if (tonumber(fbd.use_index) or 1) ~= bagIndex then
        return
      end
      local WRH = require("client.network.Protocol.WardRobeHandler")
      WRH.on_depot_put_on_rsp(NET_OK, { res_id = resID, count = 1, instid = insID }, nil, bagIndex, insID, 0)
    end
    if F.isResourcesReady(resID) then
      applyVisual()
    else
      F.requestResourceDownload(resID, applyVisual)
    end
    if EventSystem and EVENTTYPE_WARDROBE and EVENTID_WARDROBE_UPDATE_ITEM_LIST then
      EventSystem:postEvent(EVENTTYPE_WARDROBE, EVENTID_WARDROBE_UPDATE_ITEM_LIST)
    end
    return true
  end
  function F.selectedThrowIns(st)
    st = tonumber(st)
    if F.skinOff() or not st or st < 612 or st > 615 then
      return nil
    end
    local slot = F.extraCosmeticSlot(st)
    local cch = F.cache()
    local res = tonumber(cch[slot .. "Res"] or (PERSIST.configSlots and PERSIST.configSlots[slot]))
    if not res or tonumber(F.subType(F.cfg(res))) ~= st then
      return nil
    end
    return R.resToIns[res]
  end
  function F.hookThrowCosmetics()
    local fbd = require("client.slua.logic.wardrobe.fashionbag.fashionbag_data")
    if not fbd._OwenThrowSelectionHook then
      local get, wear = fbd.GetThrowObjectSkin, fbd.IsThrowObjectWearing
      if type(get) == "function" and type(wear) == "function" then
        fbd.GetThrowObjectSkin = function(self, st, index)
          if index == nil or tonumber(index) == tonumber(self.use_index) then
            local ins = F.selectedThrowIns(st);
            if ins then
              return ins
            end
          end
          return get(self, st, index)
        end
        fbd.IsThrowObjectWearing = function(self, ins)
          if F.skinOff() then
            return wear(self, ins)
          end
          local res = R.insToRes[tonumber(ins)]
          local st = tonumber(F.depotSubType(tonumber(ins), res))
          local selected = st and F.selectedThrowIns(st)
          if selected then
            return selected == tonumber(ins)
          end
          return wear(self, ins)
        end
        fbd._OwenThrowSelectionHook = true
      end
    end
    local wl = require("client.slua.logic.wardrobe.logic_wardrobe_new")
    if not wl._OwenThrowValidityHook and type(wl.IsWearValid) == "function" then
      local original = wl.IsWearValid
      wl.IsWearValid = function(self, ins, ...)
        local res = not F.skinOff() and R.insToRes[tonumber(ins)]
        local st = res and tonumber(F.subType(F.cfg(res)))
        if st and st >= 612 and st <= 615 then
          return true
        end
        return original(self, ins, ...)
      end
      wl._OwenThrowValidityHook = true
    end
    local edit = require("client.slua.logic.wardrobe.fashionbag.FashionBagEditUtils")
    if not edit._OwenThrowEditHook and type(edit.PutOnThrowObject) == "function" then
      local put, has, get = edit.PutOnThrowObject, edit.IsItemInTryMap, edit.GetThrowObjectInsIDBySubType
      edit.PutOnThrowObject = function(self, data, ...)
        local result = put(self, data, ...)
        local ins = type(data) == "table" and tonumber(data.ins_id or data.insID or data.instid)
        local res = ins and R.insToRes[ins]
        local st = res and tonumber(F.subType(F.cfg(res)))
        if not F.skinOff() and st and st >= 612 and st <= 615 then
          F.putOnExtraCosmetic(ins)
        end
        return result
      end
      if type(has) == "function" then
        edit.IsItemInTryMap = function(self, res, bTakeOff, data, ...)
          local st = not F.skinOff() and tonumber(F.subType(F.cfg(tonumber(res))))
          local ins = st and F.selectedThrowIns(st)
          if ins and bTakeOff ~= true then
            return R.insToRes[ins] == tonumber(res)
          end
          return has(self, res, bTakeOff, data, ...)
        end
      end
      if type(get) == "function" then
        edit.GetThrowObjectInsIDBySubType = function(self, st, ...)
          return F.selectedThrowIns(st) or get(self, st, ...)
        end
      end
      edit._OwenThrowEditHook = true
    end
