  function F.reapplyExtraCosmetics()
    if F.skinOff() then
      return
    end
    local cch = F.cache()
    for _, slot in ipairs( { "footEffect", "runTrail", "footprint", "fragSkin", "smokeSkin", "stunSkin",
    "molotovSkin" }) do
      local ins = cch[slot .. "Ins"]
      if ins and F.isInjectedIns(ins) then
        F.putOnExtraCosmetic(ins)
      end
    end
