  function F.ensureInjectedResources()
    local seen = {}
    local function visit(value, depth)
      if depth > 4 then
        return
      end
      if type(value) == 'table' then
        for _, entry in pairs(value) do
          visit(entry, depth + 1)
        end
      elseif type(value) == 'number' and R.resToIns[value] and not seen[value] then
        seen[value] = true;
        F.requestResourceDownload(value)
      end
    end
    visit(F.cache(), 0);
    visit(MATCH_CONFIG, 0)
  end
