  function F.cacheWeaponSkinFromIns(weaponID, insID)
    weaponID, insID = tonumber(weaponID), tonumber(insID)
    if not weaponID or not insID or insID <= 0 then
      return
    end
    if F.isInjectedIns(insID) then
      F.saveWeaponToCache(weaponID, R.insToRes[insID], insID)
      return
    end
    pcall(function()
      local wd = require("client.slua.logic.wardrobe.wardrobe_data")
      local d = wd:GetValidHallDepotItemDataByInsID(insID) or wd:GetHallDepotItemDataByInsID(insID)
      if d and d.resID and tonumber(d.resID) > 0 then
        F.saveWeaponToCache(weaponID, tonumber(d.resID), insID)
      end
    end)
  end
  function F.saveEquip(resID, insID)
    resID, insID = tonumber(resID), tonumber(insID)
    if not resID or not insID then
      return
    end
    if F.localWearRequestFor and F.isSyntheticIns(insID) then
      local request = F.localWearRequestFor(resID)
      if request and request.Entity == F.getEntity() and request.ResID ~= resID then
        return
      end
    end
    local c = F.cfg(resID)
    local st = F.subType(c)
    local slot = F.matchOnlySelectionSlot and F.matchOnlySelectionSlot(resID)
    if slot and F.LocalSkinCleared and F.LocalSkinCleared[slot] and F.isSyntheticIns(insID) then
      return
    end
    local cch = F.cache()
    if st == OUTFIT_SUB then
      if F.wardrobeTab(resID) == TAB_CLOTHES then
        cch.tshirtRes, cch.tshirtIns = resID, insID
        _G.AddOutfitLastLobbyTshirtRes = resID F.persistRememberSlot("tshirt", resID)
      else
        cch.outfitRes, cch.outfitIns = resID, insID
        _G.AddOutfitLastLobbyOutfitRes = resID F.persistRememberSlot("outfit", resID)
        F.invalidateSocialWearCache()
      end
    elseif st == HAT_SUB then
      cch.hatRes, cch.hatIns = resID, insID
      _G.AddOutfitLastLobbyHatRes = resID F.persistRememberSlot("hat", resID)
    elseif st == MASK_SUB then
      cch.maskRes, cch.maskIns = resID, insID
      _G.AddOutfitLastLobbyMaskRes = resID F.persistRememberSlot("mask", resID)
    elseif st == GLASS_SUB then
      cch.glassRes, cch.glassIns = resID, insID
      _G.AddOutfitLastLobbyGlassRes = resID F.persistRememberSlot("glass", resID)
    elseif st == PANTS_SUB then
      cch.pantsRes, cch.pantsIns = resID, insID
      _G.AddOutfitLastLobbyPantsRes = resID F.persistRememberSlot("pants", resID)
    elseif st == SHOES_SUB then
      cch.shoesRes, cch.shoesIns = resID, insID
      _G.AddOutfitLastLobbyShoesRes = resID F.persistRememberSlot("shoes", resID)
    elseif BAG_SUBS[st] then
      cch.bagRes, cch.bagIns = resID, insID
      _G.AddOutfitLastLobbyBagRes = resID F.persistRememberSlot("bag", resID)
    elseif HELMET_SUBS[st] then
      cch.helmetRes, cch.helmetIns = resID, insID
      _G.AddOutfitLastLobbyHelmetRes = resID F.persistRememberSlot("helmet", resID)
    elseif st == PARACHUTE_SUB then
      cch.parachuteRes, cch.parachuteIns = resID, insID
      _G.AddOutfitLastLobbyParachuteRes = resID F.persistRememberSlot("parachute", resID)
    elseif F.isGlideRes(resID) then
      cch.gliderRes, cch.gliderIns = resID, insID
      _G.AddOutfitLastLobbyGliderRes = resID F.persistRememberSlot("glider", resID)
    elseif st == GLOVES_SUB then
      cch.glovesRes, cch.glovesIns = resID, insID
      _G.AddOutfitLastLobbyGlovesRes = resID F.persistRememberSlot("gloves", resID)
    elseif F.extraCosmeticSlot(st) then
      local slot = F.extraCosmeticSlot(st)
      cch[slot .. "Res"], cch[slot .. "Ins"] = resID, insID F.persistRememberSlot(slot, resID)
    elseif GUN_SUB[st] then
      local wid = F.weaponIdFromSkin(resID)
      if wid then
        F.saveWeaponToCache(wid, resID, insID)
      end
    elseif st == MELEE_ID then
      F.saveWeaponToCache(MELEE_ID, resID, insID)
    end
    _matchApplied = false F.perfInvalidateLobby()
    F.persistMarkDirty()
  end
  function F.findWornInsBySubType(st, filterFn)
    st = tonumber(st)
    if not st then
      return nil
    end
    local wd = require("client.slua.logic.wardrobe.wardrobe_data")
    local AvatarData = require("client.logic.data.AvatarData")
    for _, ins in pairs(AvatarData.GetRoleWear()) do
      ins = tonumber(ins)
      if ins and ins > 0 then
        local d = wd:GetHallDepotItemDataByInsID(ins)
        if d and tonumber(d.itemSubType) == st then
          local res = tonumber(d.resID)
          if not filterFn or filterFn(res, d) then
            return ins, res
          end
        end
      end
    end
    return nil
  end
