  function F.restoreHelmetIconSelection(bag)
    if type(bag) ~= 'table' or not F.lobbyWorkAllowed() then
      return bag
    end
    if F.LocalSkinCleared and F.LocalSkinCleared.helmet then
      return bag
    end
    local cache = F.cache()
    local res = tonumber(cache.helmetRes)
    local ins = tonumber(cache.helmetIns) or (res and tonumber(R.resToIns[res]))
    if not res or res <= 0 or not ins or ins <= 0 or not F.isInjectedIns(ins) then
      return bag
    end
    local data = F.getSyntheticItem and F.getSyntheticItem(ins, res)
    if not data then
      return bag
    end
    bag.helmet_skin = ins
    bag.helmet_skin_list = bag.helmet_skin_list or {}
    local level = tonumber(bag.helmet_level) or 3
    for index = 1, 3 do
      if index == level or (tonumber(bag.helmet_skin_list[index]) or 0) <= 0 then
        bag.helmet_skin_list[index] = ins
      end
    end
    if DataMgr then
      DataMgr.equipmentSkinInsIDTable = DataMgr.equipmentSkinInsIDTable or {} DataMgr.equipmentSkinInsIDTable[505] = ins
    end
    return bag
  end
  function F.installHelmetIconRestore()
    local fbd = package and package.loaded and package.loaded['client.slua.logic.wardrobe.fashionbag.fashionbag_data']
    if type(fbd) ~= 'table' or type(fbd.GetCurrentFashionBag) ~= 'function' then
      return
    end
    local hook = F.HelmetIconRestoreHook
    if hook and hook.Module == fbd and fbd.GetCurrentFashionBag == hook.Wrapped then
      return
    end
    local original = fbd.GetCurrentFashionBag
    local wrapped = function( ...)
      local results = table.pack(original( ...))
      local current = _G.AddOutfit
      if current and not current.HelmetIconRestoreBusy then
        current.HelmetIconRestoreBusy = true pcall(current.restoreHelmetIconSelection, results[1])
        current.HelmetIconRestoreBusy = false
      end
      return table.unpack(results, 1, results.n)
    end
    fbd.GetCurrentFashionBag = wrapped
    F.HelmetIconRestoreHook = { Module = fbd, Original = original, Wrapped = wrapped }
  end
