  function F.putOnHallTheme(insID)
    if not _G.OwenNeonLobbySceneAllowed() then
      return false
    end
    if _G.OwenCloseCollectionForTheme then
      _G.OwenCloseCollectionForTheme()
    end
    insID = tonumber(insID)
    if not insID or not F.isInjectedIns(insID) then
      return false
    end
    local resID = R.insToRes[insID]
    if F.applyHallThemeDisplay(resID, insID) then
      F.setHallThemeManual(resID, insID)
      return true
    end
    return false
