  function F.isParachuteRes(resID)
    return F.subType(F.cfg(tonumber(resID))) == PARACHUTE_SUB
  end
  function F.isGlideRes(resID)
    resID = tonumber(resID)
    if not resID then
      return false
    end
    local st = F.subType(F.cfg(resID))
    if GLIDER_SUBS[st] then
      return true
    end
    local ok, r = pcall(function()
      local MDH = require("client.logic.avatar.ModelDisplayTypeHelper")
      if MDH.IsGlideByItemID and MDH.IsGlideByItemID(resID) then
        return true
      end
      local wd = require("client.slua.logic.wardrobe.wardrobe_data")
      return wd.IsGlideType(st)
    end)
    return ok and r == true
  end
  function F.isVehicleRes(resID)
    resID = tonumber(resID)
    if not resID or F.isChassisLightId(resID) then
      return false
    end
    local st = tonumber(F.subType(F.cfg(resID)))
    if not st or st == CHASSIS_LIGHT_SUB then
      return false
    end
    local c = F.cfg(resID)
    if c and tonumber(c.WardrobeMainTab) == PAGE_VEHICLE then
      return st >= 900
    end
    return st >= 900 and st < 7000
  end
  function F.ensureInjectedItemAlive(entity, resID, insID)
    entity = entity or F.getEntity()
    insID = tonumber(insID) or (resID and R.resToIns[tonumber(resID)])
    if not entity or not insID then
      return nil
    end
    local ok, item = pcall(function()
      return entity:GetDataByInsID(insID)
    end)
    if not ok then
      return nil
    end
    if entity == R.syntheticEntity and F.isSyntheticIns(insID) then
      local synthetic = F.getSyntheticItem(insID, resID)
      if synthetic then
        F.clearItemExpire(synthetic, insID, resID)
      end
    end
    return item
