  function F.putOnVehicle(insID)
    insID = tonumber(insID)
    if not insID then
      return false
    end
    local resID = R.insToRes[insID]
    if not resID or not F.isVehicleRes(resID) then
      return false
    end
    F.ensureInjectedItemAlive( nil, resID, insID)
    if not F.isResourcesReady(resID) then
      F.modifyInjectedVehicleSlot(insID, 1, true)
      F.setLobbyVehicleManual(F.vehicleSubType(resID), resID, insID)
      F.requestResourceDownload(resID, function()
        if F.skinOff() or not _G.OwenNeonLobbySceneAllowed() then
          return
        end
        if tonumber(PERSIST.lobbyVehicleResID) ~= resID then
          return
        end
        local slots = PERSIST.configVehicleSlots and PERSIST.configVehicleSlots[F.vehicleSubType(resID)]
        if slots and tonumber(slots[1]) == resID then
          F.putOnVehicle(insID)
        end
      end)
      return true
    end
    local item = { res_id = resID, resID = resID, instid = insID, ins_id = insID, insID = insID, expire_ts = 0,
    expireTS = 0, count = 1, }
    local WRH = require("client.network.Protocol.WardRobeHandler")
    WRH.on_depot_put_on_rsp(NET_OK, item, nil, 1, insID, 0)
    F.setLobbyVehicleManual(F.vehicleSubType(resID), resID, insID)
    pcall(function()
      local TabSurveillance = require("client.slua.logic.wardrobe.tab_surveillance")
      TabSurveillance.VehicleChange()
    end)
    pcall(function()
      if EventSystem and EVENTTYPE_WARDROBE and EVENTID_WARDROBE_UPDATE_ITEM_LIST then
        EventSystem:postEvent(EVENTTYPE_WARDROBE, EVENTID_WARDROBE_UPDATE_ITEM_LIST)
      end
    end)
    return true
  end
  function F.isChassisLightId(id)
    return CHASSIS_LIGHT_IDS[tonumber(id)] == true
