  function F.vehicleAvatarTemper()
    local vehicle = F.getCurrentVehicleForSkin()
    if not slua.isValid(vehicle) then
      return
    end
    local av = F.getVehicleAvatarComp(vehicle)
    if not slua.isValid(av) then
      return
    end
    local defaultId = 0 pcall(function()
      defaultId = tonumber(av:GetDefaultAvatarID()) or 0
    end)
    if defaultId <= 0 then
      return
    end
    local shape = nil pcall(function()
      shape = tonumber(import("AvatarUtils").GetVehicleShapeBySkinID(defaultId))
    end)
    local skinId = nil
    if VEHSEL.override and slua.isValid(VEHSEL.overrideVehicle) and VEHSEL.overrideVehicle == vehicle then
      skinId = VEHSEL.override
    end
    if not skinId and shape then
      skinId = VEHSEL.byShape[shape]
    end
    if not skinId then
      skinId = F.getDesiredVehicleSkinForShape(shape)
    end
    skinId = tonumber(skinId)
    if not skinId or skinId <= 0 or skinId == defaultId then
      return
    end
    local cur = 0 pcall(function()
      cur = tonumber(vehicle.GetAvatarId and vehicle:GetAvatarId()) or 0
    end)
    if cur <= 0 then
      pcall(function()
        cur = tonumber(vehicle.GetVehicleSkinItemID and vehicle:GetVehicleSkinItemID()) or 0
      end)
    end
    if cur == skinId then
      return
    end
    F.forceVehicleAvatar(skinId, vehicle)
  end
  function F.vehicleSkinTick()
    if F.skinOff() or not F.isInRealMatch() then
      return
    end
    F.vehicleAvatarTemper()
    local now = _G.RealNow()
    if now - _vehTickLastApply < 5.3 then
      return
    end
    _vehTickLastApply = now
    local pc = F.getPC()
    if slua.isValid(pc) and (pc ~= _G.OwenVehicleSkinSyncPC or pc.PlayerState ~= _G.OwenVehicleSkinSyncState) then
      F.applyVehicleSkinsToPC(pc)
    end
  end
  function F.startVehicleSkinTicker()
    pcall(function()
      if not _ticker then
        return
      end
      if _G.AddOutfitVehTickerId then
        return
      end
      if _ticker.AddTimerLoop then
        _G.AddOutfitVehTickerId = _ticker.AddTimerLoop(1.0, function()
          local fn = _G.AddOutfit and _G.AddOutfit.vehicleSkinTick
          if fn then
            pcall(fn)
          end
        end, - 1, 1.17)
      end
    end)
  end
  function F.matchApplyVehicleSkin(skinId)
    if F.skinOff() then
      return false
    end
    skinId = tonumber(skinId)
    if not skinId or skinId <= 0 then
      return false
    end
    local vehicle = F.getCurrentVehicleForSkin()
    VEHSEL.override = skinId
    VEHSEL.overrideVehicle = slua.isValid(vehicle) and vehicle or nil pcall(function()
      local UAvatarUtils = import("AvatarUtils")
      local shape = tonumber(UAvatarUtils.GetVehicleShapeBySkinID(skinId))
      if shape and shape >= 0 then
        VEHSEL.byShape[shape] = skinId
      end
      local av = F.getVehicleAvatarComp(vehicle)
      if slua.isValid(av) then
        local defaultId = tonumber(av:GetDefaultAvatarID()) or 0
        if defaultId > 0 then
          local defShape = tonumber(UAvatarUtils.GetVehicleShapeBySkinID(defaultId))
          if defShape and defShape >= 0 then
            VEHSEL.byShape[defShape] = skinId
          end
        end
      end
    end)
    F.applyVehicleSkinsToPC(F.getPC())
    local ok = F.forceVehicleAvatar(skinId, vehicle)
    F.startVehicleSkinTicker()
    return ok
  end
  function F.autoApplyVehicleSkinOnEnter(vehicle)
    if F.skinOff() then
      return
    end
    if not slua.isValid(vehicle) then
      return
    end
    F.syncVehicleCacheFromDataMgr()
    F.applyVehicleSkinsToPC(F.getPC())
    F.startVehicleSkinTicker()
    F.later(0.35, function()
      pcall(F.vehicleAvatarTemper)
    end)
    F.later(0.9, function()
      pcall(F.vehicleAvatarTemper)
    end)
    F.later(0.5, function()
      local skinId = nil pcall(function()
        skinId = tonumber(vehicle.GetAvatarId and vehicle:GetAvatarId())
      end)
      F.scheduleChassisLightApply(vehicle, skinId)
    end)
