    if tonumber(resID) == 1400708 then
      return false
    end
    if not cfg or (F.NeonEquipmentFamilies and F.NeonEquipmentFamilies[tonumber(resID)]) then
      return false
    end
    local subtype = tonumber(F.subType(cfg))
    local quality = tonumber(cfg.ItemQuality or cfg.itemQuality or cfg.Quality)
    return (subtype == 403 or subtype == 404 or subtype == 405) and quality ~= nil and quality <= 1
  end
  function F.clothingIconUsable(resID, cfg)
    local subtype = cfg and tonumber(F.subType(cfg))
    if subtype ~= 401 and subtype ~= 403 and subtype ~= 404 and subtype ~= 405 and subtype ~= 407 then
      return true
    end
    local ok, ui = pcall(require, 'client.common.ui_util')
    local pakOK, pak = pcall(require, 'client.common.pak_util')
    if not ok or not ui or not pakOK or not pak or type(pak.IsPufferDownloaded) ~= 'function' then
      return true
    end
    local default
    if type(ui.GetDefaultIcon) == 'function' then
      local success, value = pcall(ui.GetDefaultIcon, resID);
      if success then
        default = value
      end
    end
    local hasIcon = false
    for _, key in ipairs( { 'ItemBigIcon', 'ItemSmallIcon' }) do
      local path = cfg[key]
      if type(path) == 'string' and path ~= '' and path ~= 'None' and path ~= default then
        hasIcon = true
        local success, downloaded = pcall(pak.IsPufferDownloaded, path)
        if success and downloaded then
          return true
        end
      end
    end
    if hasIcon and type(ui.GetItemBigIcon) == 'function' then
      F.ClothingIconRequests = F.ClothingIconRequests or {}
      local now = _G.RealNow()
      if now >= (F.ClothingIconRequests[resID] or 0) then
        F.ClothingIconRequests[resID] = now + 30 pcall(ui.GetItemBigIcon, resID)
      end
    end
    return false
  end
  function F.injectOne(entity, resID, insID)
    resID, insID = tonumber(resID), tonumber(insID)
    if not entity or not resID or not insID then
      return false
    end
    if R.syntheticEntity ~= entity then
      R.syntheticIns = {};
      R.syntheticEntity = entity
      F.LocalSkinSelections = {}
    end
    local cfg = F.cfg(resID)
    if not cfg then
      return false
    end
    if F.neonLowQualityClothing(resID, cfg) then
      return false
    end
    local ownedIns = F.firstInsForRes(entity, resID)
    local ownedValid = ownedIns and F.ensureDepotItemValid(ownedIns, resID)
    if ownedIns and ownedValid then
      F.ensureInjectedItemAlive(entity, resID, ownedIns)
      pcall(function()
        local d = entity.GetDataByInsID and entity:GetDataByInsID(ownedIns)
        if not d and entity._data then
          d = entity._data[ownedIns]
        end
        if d and entity.LoadConfigForData then
          entity:LoadConfigForData(d, CDataTable.GetTableData)
        end
      end)
      R.resToIns[resID] = ownedIns
      R.insToRes[ownedIns] = resID F.indexWeaponSkin(resID, ownedIns)
      return true
    end
    local row = { instid = insID, res_id = resID, count = 1, lock_cnt = 0, isnew = 0, valid_hours = 0,
    expire_ts = 0, }
    if entity.GetDataByInsID and entity:GetDataByInsID(insID) then
      return false
    end
    if entity:AddData(row) == false then
      return false
    end
    R.syntheticIns[tonumber(insID)] = tonumber(resID)
    pcall(function()
      if entity.LoadConfigForData and CDataTable and CDataTable.GetTableData then
        local data = entity.GetDataByInsID and entity:GetDataByInsID(insID)
        if not data and entity._data then
          data = entity._data[insID]
          if not data then
            local last = entity._data[entity._DataCount or # entity._data]
            if last and tonumber(last.instid or last.insID) == insID then
              data = last
            end
          end
        end
        entity:LoadConfigForData(data or row, CDataTable.GetTableData)
      end
    end)
    R.insToRes[insID] = resID
    R.resToIns[resID] = insID F.indexWeaponSkin(resID, insID)
    return true
  end
