  function F.extendClothingCatalog()
    local C = F.ClothingCatalog
    if not C then
      C = {
        Seen = {},
        Added = 0,
        Pending = {}
      };
      F.ClothingCatalog = C
      for _, id in ipairs(ITEMS) do
        C.Seen[id] = true
      end
      local memo = _G.OwenClothingExtra
      if memo and type(memo.Ids) == 'table' and memo.Ids[1] then
        for _, id in ipairs(memo.Ids) do
          if not C.Seen[id] then
            C.Seen[id] = true;
            C.Pending[ # C.Pending + 1] = id;
            C.Added = C.Added + 1
          end
        end
        table.sort(C.Pending);
        for _, id in ipairs(C.Pending) do
          ITEMS[ # ITEMS + 1] = id
        end
        C.Pending = nil;
        C.Done = true;
        C.Status = 'memo'
        return true
      end
    end
    if C.Done then
      return true
    end
    if not C.Rows then
      if not CDataTable or type(CDataTable.GetTable) ~= 'function' then
        C.Done = true;
        C.Status = 'table_api_unavailable';
        return true
      end
      local ok, rows = pcall(CDataTable.GetTable, 'Item')
      if not ok or type(rows) ~= 'table' then
        C.Done = true;
        C.Status = 'item_table_unavailable';
        return true
      end
      C.Rows = rows;
      C.Status = 'scanning'
    end
    local start = os.clock();
    local count = 0
    while count < 512 and os.clock() - start < 0.002 do
      local key, row = next(C.Rows, C.Key);
      C.Key = key
      if key == nil then
        table.sort(C.Pending);
        for _, id in ipairs(C.Pending) do
          ITEMS[ # ITEMS + 1] = id
        end
        _G.OwenClothingExtra = { Ids = C.Pending }
        C.Pending = nil;
        C.Rows = nil;
        C.Done = true;
        C.Status = 'complete';
        return true
      end
      count = count + 1
      if type(row) == 'table' then
        local subtype = tonumber(row.ItemSubType or row.itemSubType)
        if subtype == 401 or subtype == 402 or subtype == 403 or subtype == 404 or subtype == 405 or subtype == 406 or subtype == 407 or subtype == 452 then
          local id = tonumber(row.ItemID or row.itemID or row.ID or key)
          if id and id > 0 and id % 1 == 0 and not C.Seen[id] then
            local ok, cfg
            if id == key then
              ok, cfg = true, row
            else
              ok, cfg = pcall(F.cfg, id)
            end
            if ok and cfg and tonumber(F.subType(cfg)) == subtype then
              C.Pending[ # C.Pending + 1] = id;
              C.Seen[id] = true;
              C.Added = C.Added + 1
            end
          end
        end
      end
    end
    return false
  end
  function F.injectAll(entity)
    if F.skinOff() or not (_G.OwenNeonLobbySceneAllowed and _G.OwenNeonLobbySceneAllowed() == true) then
      return false
    end
    local state = F.NeonInjectState
    if state and state.Done and not F.NeonInjectDirty and (entity == nil or state.Entity == entity) then
      return state.Added > 0
    end
    if F.NeonInjectDirty then
      F.NeonInjectDirty = false
      if state then
        state.Done = false;
        state.Cursor = 1;
        state.Pass = 0;
        state.Missing = {};
        state.Work = nil
      end
    end
    if F.installNeonEquipmentLevels then
      F.installNeonEquipmentLevels()
    end
    entity = entity or F.getEntity()
    if not entity or not entity.bInit then
      return false
    end
    if not F.extendClothingCatalog() then
      if not F._CatalogInjectPending then
        F._CatalogInjectPending = true F.later(0.03, function()
          F._CatalogInjectPending = false
          if F.skinOff() or not _G.OwenNeonLobbySceneAllowed() or F.getEntity() ~= entity then
            return
          end
          F.injectAll(entity)
        end)
      end
      return false
    end
    local state = F.NeonInjectState
    if not state or state.Entity ~= entity then
      state = {
        Entity = entity,
        Cursor = 1,
        Added = 0,
        Pending = false,
        Done = false,
        Missing = {},
        Pass = 0
      };
      F.NeonInjectState = state
    end
    if state.Done then
      return state.Added > 0
    end
    if state.Running then
      return false
    end
    state.Running = true
    local started = os.clock();
    local count = 0
    local workSize = state.Work and # state.Work or # ITEMS
    while state.Cursor <= workSize and count < 128 do
      local cursor = state.Cursor;
      local index = state.Work and state.Work[cursor] or cursor;
      local id = ITEMS[index];
      state.Cursor = cursor + 1;
      count = count + 1
      local ok, inserted = pcall(F.injectOne, entity, id, INS_BASE + index)
      if ok and inserted then
        state.Added = state.Added + 1
        local c = F.cfg(id);
        local st = F.subType(c)
        if GUN_SUB[st] or st == MELEE_ID then
          pcall(F.injectArmory, id, R.resToIns[id])
        end
      elseif not F.cfg(id) then
        state.Missing[ # state.Missing + 1] = index
      end
      if os.clock() - started >= 0.004 then
        break
      end
    end
    state.Running = false
    if state.Cursor > workSize and # state.Missing > 0 and state.Pass < 2 then
      state.Work = state.Missing;
      state.Missing = {};
      state.Cursor = 1;
      state.Pass = state.Pass + 1
      workSize = # state.Work
    end
    if state.Cursor > workSize then
      state.Done = true
      if not _G.AddOutfitUnexpireDone then
        _G.AddOutfitUnexpireDone = true;
        pcall(F.reviveExpiredOwned, entity)
      end
      pcall(F.mergeRevivedIntoMaps);
      pcall(F.sanitizeAllInjectedExpire);
      pcall(F.ensureInjectedResources)
      if _G.OwenBuildSuitFamilies then
        _G.OwenBuildSuitFamilies()
      end
      if _G.OwenInstallSuitLevels then
        _G.OwenInstallSuitLevels()
      end
      F.scheduleInjectRefresh()
      local firstTime = not _G.AddOutfitLobbyInitDone;
      _G.AddOutfitLobbyInitDone = true
      if F.afterInjectApply then
        pcall(F.afterInjectApply, firstTime)
      end
      return state.Added > 0
    end
    if not state.Pending then
      state.Pending = true F.later(0.03, function()
        state.Pending = false
        if F.NeonInjectState ~= state or F.skinOff() or not _G.OwenNeonLobbySceneAllowed() or F.getEntity() ~= entity then
          return
        end
        F.injectAll(entity)
      end)
    end
    return false
  end
  function F.refreshWardrobe()
    if F.skinOff() or not (_G.OwenNeonLobbySceneAllowed and _G.OwenNeonLobbySceneAllowed() == true) then
      return false
    end
    pcall(function()
      if EventSystem and EVENTTYPE_WARDROBE then
        if EVENTID_WARDROBE_UPDATE_ITEM_LIST then
          EventSystem:postEvent(EVENTTYPE_WARDROBE, EVENTID_WARDROBE_UPDATE_ITEM_LIST)
        end
        if EVENTID_WARDROBE_UPDATE_AVATAR_LIST then
          EventSystem:postEvent(EVENTTYPE_WARDROBE, EVENTID_WARDROBE_UPDATE_AVATAR_LIST)
        end
        if EVENTID_WARDROBE_UPDATE_GUN_LIST then
          EventSystem:postEvent(EVENTTYPE_WARDROBE, EVENTID_WARDROBE_UPDATE_GUN_LIST, - 1)
        end
      end
    end)
  end
  function F.refreshWardrobeOnce()
    if LOBBY.wardrobeRefreshed then
      return
    end
    LOBBY.wardrobeRefreshed = true F.refreshWardrobe()
  end
  function F.scheduleInjectRefresh()
    if F.skinOff() or not (_G.OwenNeonLobbySceneAllowed and _G.OwenNeonLobbySceneAllowed() == true) then
      return false
    end
    LOBBY.injectRefreshGen = (LOBBY.injectRefreshGen or 0) + 1
    local gen = LOBBY.injectRefreshGen F.later(0.4, function()
      if gen ~= LOBBY.injectRefreshGen then
        return
      end
      F.refreshWardrobe()
    end)
  end
