    local slot = 8 pcall(function()
      local wfu = require("client.slua.logic.wardrobe.fashionbag.wardrobe_fashion_utils")
      local idx = wfu.GetRoleWearIndexBySubType and wfu:GetRoleWearIndexBySubType(GLOVES_SUB)
      if idx then
        slot = idx
      end
    end)
    local olditem
    if oldIns and oldIns ~= insID then
      olditem = { res_id = oldRes or R.insToRes[oldIns], count = 1, instid = oldIns }
    end
    local WRH = require("client.network.Protocol.WardRobeHandler")
    local item = { res_id = resID, count = 1, instid = insID, color = d.color, pattern = d.pattern, expire_ts = 0 }
    WRH.on_depot_put_on_rsp(NET_OK, item, olditem, slot, insID, oldIns or 0)
    pcall(function()
      local logic_wardrobe_avatar = require("client.slua.logic.wardrobe.logic_wardrobe_avatar")
      logic_wardrobe_avatar:AddToWearInfo(GLOVES_SUB, insID, resID, d.color or 0, d.pattern or 0)
      DataMgr.UpdateRoleWearData(insID, oldIns or 0)
      logic_wardrobe_avatar:AvatarChange(resID, true, d.color, d.pattern)
    end)
    pcall(function()
      local wl = require("client.slua.logic.wardrobe.logic_wardrobe_new")
      if wl.SetClickItemInsId then
        wl:SetClickItemInsId(insID)
      end
    end)
    pcall(function()
      if EventSystem and EVENTTYPE_WARDROBE then
        if EVENTID_WARDROBE_UPDATE_ITEM_LIST then
          EventSystem:postEvent(EVENTTYPE_WARDROBE, EVENTID_WARDROBE_UPDATE_ITEM_LIST)
        end
        if EVENTID_WARDROBE_UPDATE_AVATAR_LIST then
          EventSystem:postEvent(EVENTTYPE_WARDROBE, EVENTID_WARDROBE_UPDATE_AVATAR_LIST)
        end
      end
    end)
    if F.GloveLOD then
      F.GloveLOD.Next = 0
    end
    if F.PendingWear.gloves == insID then
      F.PendingWear.gloves = nil
    end
    F.invalidateSocialWearCache()
    return true
  end
  function F.ensureDepotItemValid(insID, resID)
    insID, resID = tonumber(insID), tonumber(resID)
    if not insID or insID <= 0 then
      return false
    end
    if F.isSyntheticIns(insID) and not F.skinOff() then
      local item = F.getSyntheticItem(insID, resID)
      if item then
        item.expire_ts, item.expireTS, item.expireTs = 0, 0, 0 item.valid_hours, item.validHours = 0, 0
        return true, item
      end
      return false
    end
    local ok, item = pcall(function()
      local wd = require('client.slua.logic.wardrobe.wardrobe_data')
      return wd:GetValidHallDepotItemDataByInsID(insID)
    end)
    if not ok or type(item) ~= 'table' then
      return false
    end
    if resID and tonumber(item.res_id or item.resID) ~= resID then
      return false
    end
    return true, item
  end
  function F.clearItemExpire(itemData, insID, resID)
    local valid, item = F.ensureDepotItemValid(insID, resID)
    if valid and F.isSyntheticIns(insID) and not F.skinOff() and type(itemData) == 'table' then
      local rowIns = tonumber(itemData.ins_id or itemData.insID or itemData.instid)
      local rowRes = tonumber(itemData.res_id or itemData.resID)
      if ( not rowIns or rowIns == tonumber(insID)) and rowRes == tonumber(item.resID or item.res_id) then
        itemData.expire_ts, itemData.expireTS, itemData.expireTs = 0, 0, 0 itemData.valid_hours, itemData.validHours = 0, 0
      end
    end
    return valid, item
  end
  function F.refreshAirborneSelectionUI(widget, slot, force)
    if not F.lobbyWorkAllowed() or not widget then
      return
    end
    local cache = F.cache()
    local res = tonumber(PERSIST.configSlots and PERSIST.configSlots[slot]) or tonumber(cache[slot .. 'Res'])
    local ins = tonumber(cache[slot .. 'Ins'])
    local function selected(data)
      local id = tonumber(data and (data.res_id or data.resID))
      local dataSlot = id and F.matchOnlySelectionSlot and F.matchOnlySelectionSlot(id)
      if dataSlot and dataSlot ~= slot then
        return data.isUsing == true
      end
      if not res or res <= 0 then
        return false
      end
      if id then
        return id == res
      end
      return ins ~= nil and tonumber(data and (data.ins_id or data.insID or data.instid)) == ins
    end
    for _, key in ipairs( { 'AllItemList', 'itemList' }) do
      for _, data in pairs(type(widget[key]) == 'table' and widget[key] or {}) do
        if type(data) == 'table' then
          data.isUsing = selected(data)
        end
      end
    end
    local seen = {}
    for _, key in ipairs( { 'LoopScrollGridSkins', 'LoopScrollGrid_Normal', 'LoopScrollBox' }) do
      local grid = widget[key]
      if grid and not seen[grid] and type(grid.GetItemCount) == 'function' and type(grid.GetItemData) == 'function' then
        seen[grid] = true
        local ok, count = pcall(grid.GetItemCount, grid)
        if ok then
          for index = 1, tonumber(count) or 0 do
            local got, data = pcall(grid.GetItemData, grid, index)
            if got and type(data) == 'table' then
              local value = selected(data);
              local changed = data.isUsing ~= value
              data.isUsing = value
              if (changed or force or value) and type(grid.RefreshItem) == 'function' then
                pcall(grid.RefreshItem, grid, index, data)
              end
            end
          end
        end
      end
    end
  end
  function F.installAirborneSelectionUI(class, slot, initializer)
    local impl = class and (class.__inner_impl or class)
    if type(impl) ~= 'table' then
      return
    end
    for _, name in ipairs( { 'ClickItem', 'OnClickItem' }) do
      local fn = class[name]
      if type(fn) == 'function' then
        rawset(impl, name, fn);
        rawset(class, name, fn)
      end
    end
    if impl._OwenSelectionListPatched then
      return
    end
    local original = class[initializer]
    if type(original) ~= 'function' then
      return
    end
    local wrapped = function(self, ...)
      local result = table.pack(original(self, ...))
      pcall(F.refreshAirborneSelectionUI, self, slot, true)
      return table.unpack(result, 1, result.n)
    end
    rawset(impl, initializer, wrapped);
    rawset(class, initializer, wrapped)
    impl._OwenSelectionListPatched = true
  end
  function F.clearMatchOnlySelection(widget, data, slot, ins, res)
    if not F.lobbyWorkAllowed() or F.skinOff() or not F.isMatchOnlyCosmeticSlot(slot) or not F.isSyntheticIns(ins) or F.matchOnlySelectionSlot(res) ~= slot then
      return false
    end
    local cache = F.cache()
    local desired = tonumber(PERSIST.configSlots and PERSIST.configSlots[slot]) or tonumber(cache[slot .. 'Res'])
    if desired ~= res then
      return false
    end
    F.LocalSkinCleared = F.LocalSkinCleared or {};
    F.LocalSkinCleared[slot] = true
    if F.LocalSkinSelections then
      F.LocalSkinSelections[slot] = nil
    end
    if F.PendingWear then
      F.PendingWear[slot] = nil
    end
    if F.resourceReadyCallbacks then
      F.resourceReadyCallbacks[res] = nil
    end
    pcall(F.takeOffInjected, ins)
    cache[slot .. 'Res'] = nil;
    cache[slot .. 'Ins'] = nil
    if PERSIST.configSlots then
      PERSIST.configSlots[slot] = nil
    end
    local globals = { parachute = 'AddOutfitLastLobbyParachuteRes', glider = 'AddOutfitLastLobbyGliderRes',
    footEffect = 'AddOutfitLastLobbyFootEffectRes', runTrail = 'AddOutfitLastLobbyRunTrailRes', footprint = 'AddOutfitLastLobbyFootprintRes' }
    if globals[slot] then
      _G[globals[slot]] = nil
    end
    if MATCH_CONFIG then
      MATCH_CONFIG[slot .. 'Res'] = nil;
      MATCH_CONFIG[slot .. 'Ins'] = nil
    end
    pcall(function()
      local bagData = require('client.slua.logic.wardrobe.fashionbag.fashionbag_data')
      local bag = bagData.GetCurrentFashionBag and bagData:GetCurrentFashionBag()
      if bag then
        local fields = slot == 'parachute' and { 'parachute' } or slot == 'glider' and { 'gliding', 'aircraft_put_id' } or {}
        for _, field in ipairs(fields) do
          if tonumber(bag[field]) == ins then
            bag[field] = 0
          end
        end
      end
    end)
    pcall(function()
      if slot == 'footEffect' then
        if tonumber(DataMgr.foot_special_effect_id) == ins then
          DataMgr.UpdateFootEffect(0)
        end
      elseif slot == 'runTrail' or slot == 'footprint' then
        local st = slot == 'runTrail' and 453 or 454
        if DataMgr.GetCommonPutOnDataBy and tonumber(DataMgr.GetCommonPutOnDataBy(st)) == ins then
          DataMgr.UpdateCommonPutOnDataBy(st, 0)
        end
      end
    end)
    data.isUsing = false
    if widget.ChangeItemStatusByInsID then
      pcall(widget.ChangeItemStatusByInsID, widget, ins, false, 'isUsing')
    elseif widget.ChangeItemStatus then
      pcall(widget.ChangeItemStatus, widget, ins, false)
    end
    F.refreshAirborneSelectionUI(widget, slot, true)
    F.persistMarkDirty()
    return true
  end
  function F.selectAirborneForMatch(widget, itemData, slot)
    if F.skinOff() then
      return false
    end
    local ins = tonumber(itemData and (itemData.ins_id or itemData.insID))
    local res = tonumber(itemData and (itemData.res_id or itemData.resID))
    if not ins or not res then
      return false
    end
    local desired = tonumber(PERSIST.configSlots and PERSIST.configSlots[slot]) or tonumber(F.cache()[slot .. 'Res'])
    if desired == res and F.isSyntheticIns(ins) then
      return F.clearMatchOnlySelection(widget, itemData, slot, ins, res)
    end
    if F.LocalSkinCleared then
      F.LocalSkinCleared[slot] = nil
    end
    local old = F.cache()[slot .. 'Ins']
    F.saveEquip(res, ins)
    local function mark(id, value)
      if not id then
        return
      end
      if widget.ChangeItemStatusByInsID then
        pcall(widget.ChangeItemStatusByInsID, widget, id, value, 'isUsing')
      elseif widget.ChangeItemStatus then
        pcall(widget.ChangeItemStatus, widget, id, value)
      end
    end
    if old and old ~= ins then
      mark(old, false)
    end
    itemData.isUsing = true;
    mark(ins, true)
    F.refreshAirborneSelectionUI(widget, slot, true)
    return true
  end
  function F.onGlideClick(self, itemData)
    if not itemData then
      return
    end
    local insID = tonumber(itemData.ins_id)
    local resID = tonumber(itemData.res_id)
    F.clearItemExpire(itemData, insID, resID)
    local isGlide = resID and F.isGlideRes(resID)
    if not isGlide and itemData.itemSubType then
      isGlide = GLIDER_SUBS[tonumber(itemData.itemSubType)] == true
    end
    if insID and resID and isGlide then
      if not F.isInRealMatch() then
        return F.selectAirborneForMatch(self, itemData, 'glider')
      end
      F.saveEquip(resID, insID)
      if F.putOnGlider(insID) then
        pcall(function()
          if self.ShowGlide then
            self:ShowGlide(resID)
          end
          if self.ChangeItemStatus then
            self:ChangeItemStatus(insID, true)
          end
        end)
        return
      end
    end
    if _G.AddOutfitGlideClickOrig then
      F.clearItemExpire(itemData, insID, resID)
      return _G.AddOutfitGlideClickOrig(self, itemData)
    end
  end
  function F.onParachuteClick(self, itemData)
    if not itemData then
      return
    end
    local insID = tonumber(itemData.ins_id)
    local resID = tonumber(itemData.res_id)
    F.clearItemExpire(itemData, insID, resID)
    if insID and resID and F.isParachuteRes(resID) then
      if not F.isInRealMatch() then
        return F.selectAirborneForMatch(self, itemData, 'parachute')
      end
      F.saveEquip(resID, insID)
      if F.putOnParachute(insID) then
        pcall(function()
          if self.ChangeItemStatus then
            self:ChangeItemStatus(insID, true)
          end
        end)
        return
      end
    end
    if _G.AddOutfitParaClickOrig then
      return _G.AddOutfitParaClickOrig(self, itemData)
    end
  end
  function F.hookAirborneClick()
    pcall(F.installWardrobeSelectionControls)
    pcall(function()
      local WG = require("client.slua.umg.Wardrobe.subtab_gliding")
      if WG then
        if not WG._AddOutfitGlideWrapped then
          WG._AddOutfitGlideWrapped = true
          _G.AddOutfitGlideClickOrig = WG.ClickItem
        end
        WG.ClickItem = function(self, itemData)
          return F.onGlideClick(self, itemData)
        end
      end
      local WP = require("client.slua.umg.Wardrobe.subtab_parachute")
      if WP then
        if not WP._OwenParachuteSelectionWrapped and type(WP.OnClickItem) == 'function' then
          local original = WP.OnClickItem
          WP.OnClickItem = function(self, widget, index)
            local data = self.GetSkins and self:GetSkins(index)
            local ins = data and tonumber(data.ins_id or data.insID)
            if ins and F.isSyntheticIns(ins) then
              if F.skinOff() then
                return false
              end
              return F.onParachuteClick(self, data)
            end
            return original(self, widget, index)
          end
          WP._OwenParachuteSelectionWrapped = true
        end
        if not WP._AddOutfitParaWrapped then
          WP._AddOutfitParaWrapped = true
          _G.AddOutfitParaClickOrig = WP.ClickItem
        end
        WP.ClickItem = function(self, itemData)
          return F.onParachuteClick(self, itemData)
        end
        F.installAirborneSelectionUI(WP, 'parachute', 'InitParachuteSkin')
      end
      if WG then
        F.installAirborneSelectionUI(WG, 'glider', 'InitGlidingList')
      end
    end)
    pcall(function()
      local fbd = require("client.slua.logic.wardrobe.fashionbag.fashionbag_data")
      if fbd and not fbd._OwenAirborneSelectionGetters then
        for _, spec in ipairs( {
{ 'GetParachute', 'parachute' },
{ 'GetAircraftOrGliding', 'glider' }
        }) do
          local key, slot = spec[1], spec[2]
          local original = fbd[key]
          if type(original) == 'function' then
            fbd[key] = function(self, ...)
              if not F.skinOff() then
                local c = F.cache();
                local res = tonumber(c[slot .. 'Res'])
                local ins = res and F.resolveInsForRes(res) or tonumber(c[slot .. 'Ins'])
                if ins and F.isSyntheticIns(ins) then
                  return ins
                end
              end
              return original(self, ...)
            end
          end
        end
        fbd._OwenAirborneSelectionGetters = true
      end
      if fbd and not fbd._AddOutfitAirborneFBHooked then
        fbd._AddOutfitAirborneFBHooked = true
        local oG = fbd.UpdateAircraftOrGliding
        fbd.UpdateAircraftOrGliding = function(self, putOnID, bAircraft)
          local r = oG(self, putOnID, bAircraft)
          local ins = tonumber(putOnID)
          if ins and ins > 0 then
            local wd = require("client.slua.logic.wardrobe.wardrobe_data")
            local d = wd:GetValidHallDepotItemDataByInsID(ins) or wd:GetHallDepotItemDataByInsID(ins)
            local res = d and tonumber(d.resID)
            if res and F.isGlideRes(res) then
              F.saveEquip(res, ins)
            end
          end
          return r
        end
        local oP = fbd.UpdateParachute
        if oP then
          fbd.UpdateParachute = function(self, insID)
            local r = oP(self, insID)
            local ins = tonumber(insID)
            if ins and ins > 0 then
              local wd = require("client.slua.logic.wardrobe.wardrobe_data")
              local d = wd:GetValidHallDepotItemDataByInsID(ins) or wd:GetHallDepotItemDataByInsID(ins)
              local res = d and tonumber(d.resID)
              if res and F.isParachuteRes(res) then
                F.saveEquip(res, ins)
              end
            end
            return r
          end
        end
      end
    end)
    pcall(function()
      if not ModuleManager or not ModuleManager.GetModule then
        return
      end
      local FB = ModuleManager.GetModule(ModuleManager.LobbyModuleConfig.FashionBagEditUtils)
      if FB and not FB._AddOutfitFBBagHooked then
        FB._AddOutfitFBBagHooked = true
        local o = FB.PutOnFashionBagItem
        FB.PutOnFashionBagItem = function(self, itemData)
          if itemData then
            F.clearItemExpire(itemData, itemData.ins_id, itemData.res_id)
          end
          local r = o(self, itemData)
          if itemData then
            local res = tonumber(itemData.res_id)
            local ins = tonumber(itemData.ins_id)
            if res and ins and (F.isGlideRes(res) or F.isParachuteRes(res)) then
              F.saveEquip(res, ins)
            end
          end
          return r
        end
      end
    end)
  end
  function F.putOnParachute(insID)
    if F.skinOff() then
      return false
    end
    insID = tonumber(insID)
    local resID = R.insToRes[insID]
    if not resID then
      local wd = require("client.slua.logic.wardrobe.wardrobe_data")
      local d = wd:GetValidHallDepotItemDataByInsID(insID) or wd:GetHallDepotItemDataByInsID(insID)
      resID = d and tonumber(d.resID)
    end
    if not resID or not F.isParachuteRes(resID) then
      return false
    end
    if not R.insToRes[insID] then
      R.insToRes[insID] = resID
    end
    F.ensureDepotItemValid(insID, resID)
    F.saveEquip(resID, insID)
    if not F.isInRealMatch() then
      return true
    end
    F.ensureInjectedItemAlive( nil, resID, insID)
    local ready = F.isResourcesReady(resID)
    if not ready then
      F.requestResourceDownload(resID)
    end
    pcall(function()
      local fbd = require("client.slua.logic.wardrobe.fashionbag.fashionbag_data")
      if fbd.SetParachute then
        fbd:SetParachute(insID)
      end
      if fbd.UpdateParachute then
        fbd:UpdateParachute(insID)
      end
    end)
    if ready then
      local item = { res_id = resID, resID = resID, instid = insID, ins_id = insID, insID = insID, expire_ts = 0,
      expireTS = 0, count = 1, }
      local WRH = require("client.network.Protocol.WardRobeHandler")
      WRH.on_depot_put_on_rsp(NET_OK, item, nil, 1, insID, 0)
    end
    return true
  end
  function F.putOnGlider(insID)
    if F.skinOff() then
      return false
    end
    insID = tonumber(insID)
    local resID = R.insToRes[insID]
    if not resID then
      local wd = require("client.slua.logic.wardrobe.wardrobe_data")
      local d = wd:GetValidHallDepotItemDataByInsID(insID) or wd:GetHallDepotItemDataByInsID(insID)
      resID = d and tonumber(d.resID)
    end
    if not resID or resID <= 0 then
      return false
    end
    local st = F.depotSubType(insID, resID)
    if not F.isGlideRes(resID) and not GLIDER_SUBS[st] then
      return false
    end
    if not R.insToRes[insID] then
      R.insToRes[insID] = resID
    end
    F.ensureDepotItemValid(insID, resID)
    F.saveEquip(resID, insID)
    if not F.isInRealMatch() then
      return true
    end
    F.ensureInjectedItemAlive( nil, resID, insID)
    local ready = F.isResourcesReady(resID)
    if not ready then
      F.requestResourceDownload(resID, function()
        if F.skinOff() or F.cache().gliderRes ~= resID then
          return
        end
        if F.isInRealMatch() then
          F.putOnGlider(insID)
        end
      end)
    end
    local bAircraft = false pcall(function()
      local ModelDisplayTypeHelper = require("client.logic.avatar.ModelDisplayTypeHelper")
      local st = F.subType(F.cfg(resID))
      bAircraft = not ModelDisplayTypeHelper.IsGlideSmoke(st)
    end)
    pcall(function()
      local fbd = require("client.slua.logic.wardrobe.fashionbag.fashionbag_data")
      if fbd.UpdateAircraftOrGliding then
        fbd:UpdateAircraftOrGliding(insID, bAircraft)
      elseif fbd.SetGliding then
        fbd:SetGliding(insID)
        if DataMgr.UpdateEffect then
          DataMgr.UpdateEffect(insID)
        end
      end
    end)
    if ready then
      local item = { res_id = resID, resID = resID, instid = insID, ins_id = insID, insID = insID, expire_ts = 0,
      expireTS = 0, count = 1, }
      local WRH = require("client.network.Protocol.WardRobeHandler")
      WRH.on_depot_put_on_rsp(NET_OK, item, nil, 1, insID, 0)
    elseif EventSystem and EVENTTYPE_WARDROBE and EVENTID_WARDROBE_UPDATE_ITEM_LIST then
      EventSystem:postEvent(EVENTTYPE_WARDROBE, EVENTID_WARDROBE_UPDATE_ITEM_LIST)
    end
    return true
  end
  function F.syncAirborneToDataMgr()
    if F.skinOff() or not F.isInRealMatch() then
      return
    end
    F.applyPersistSlotsToCache()
    local cch = F.cache()
    local paraRes = F.getDesiredParachuteRes()
    local gliderRes = F.getDesiredGliderRes()
    if paraRes and paraRes > 0 and not cch.parachuteIns then
      cch.parachuteIns = F.resolveInsForRes(paraRes)
      cch.parachuteRes = paraRes
    end
    if gliderRes and gliderRes > 0 and not cch.gliderIns then
      cch.gliderIns = F.resolveInsForRes(gliderRes)
      cch.gliderRes = gliderRes
    end
    pcall(function()
      local fbd = require("client.slua.logic.wardrobe.fashionbag.fashionbag_data")
      if cch.parachuteIns and tonumber(cch.parachuteIns) > 0 then
        if fbd.SetParachute then
          fbd:SetParachute(cch.parachuteIns)
        end
        if DataMgr.roleData then
          DataMgr.roleData.parachute = tostring(cch.parachuteIns)
        end
      end
      if cch.gliderIns and tonumber(cch.gliderIns) > 0 then
        local bAircraft = false
        if cch.gliderRes then
          pcall(function()
            local MDH = require("client.logic.avatar.ModelDisplayTypeHelper")
            bAircraft = not MDH.IsGlideSmoke(F.subType(F.cfg(cch.gliderRes)))
          end)
        end
        if fbd.UpdateAircraftOrGliding then
          fbd:UpdateAircraftOrGliding(cch.gliderIns, bAircraft)
        elseif fbd.SetGliding then
          fbd:SetGliding(cch.gliderIns)
          if DataMgr.UpdateEffect then
            DataMgr.UpdateEffect(cch.gliderIns)
          end
        end
        if DataMgr.roleData then
          if bAircraft then
            DataMgr.roleData.aircraft_put_id = tostring(cch.gliderIns)
            DataMgr.gliding = cch.gliderIns
          else
            DataMgr.roleData.gliding = tostring(cch.gliderIns)
          end
        end
      end
    end)
  end
  function F.putOnGenericInjected(insID)
    insID = tonumber(insID)
    local resID = R.insToRes[insID]
    if not resID then
      return
    end
    if not F.isResourcesReady(resID) then
      F.requestResourceDownload(resID)
      return
    end
    F.saveEquip(resID, insID)
    local WRH = require("client.network.Protocol.WardRobeHandler")
    WRH.on_depot_put_on_rsp(NET_OK, { res_id = resID, count = 1, instid = insID }, nil, 1, insID, 0)
  end
  function F.clearEquipCache(resID)
    local st = F.subType(F.cfg(resID))
    local cch = F.cache()
    if st == OUTFIT_SUB then
      if F.wardrobeTab(resID) == TAB_CLOTHES then
        cch.tshirtRes, cch.tshirtIns = nil, nil
        _G.AddOutfitLastLobbyTshirtRes = nil F.persistForgetSlot("tshirt")
      else
        cch.outfitRes, cch.outfitIns = nil, nil
        _G.AddOutfitLastLobbyOutfitRes = nil F.persistForgetSlot("outfit")
      end
    elseif st == HAT_SUB or HEAD_SUBS[st] then
      cch.hatRes, cch.hatIns = nil, nil
      _G.AddOutfitLastLobbyHatRes = nil F.persistForgetSlot("hat")
    elseif st == MASK_SUB then
      cch.maskRes, cch.maskIns = nil, nil
      _G.AddOutfitLastLobbyMaskRes = nil F.persistForgetSlot("mask")
    elseif st == GLASS_SUB then
      cch.glassRes, cch.glassIns = nil, nil
      _G.AddOutfitLastLobbyGlassRes = nil F.persistForgetSlot("glass")
    elseif st == PANTS_SUB then
      cch.pantsRes, cch.pantsIns = nil, nil
      _G.AddOutfitLastLobbyPantsRes = nil F.persistForgetSlot("pants")
    elseif st == SHOES_SUB then
      cch.shoesRes, cch.shoesIns = nil, nil
      _G.AddOutfitLastLobbyShoesRes = nil F.persistForgetSlot("shoes")
    elseif BAG_SUBS[st] then
      cch.bagRes, cch.bagIns = nil, nil
      _G.AddOutfitLastLobbyBagRes = nil F.persistForgetSlot("bag")
    elseif HELMET_SUBS[st] then
      cch.helmetRes, cch.helmetIns = nil, nil
      _G.AddOutfitLastLobbyHelmetRes = nil F.persistForgetSlot("helmet")
    elseif st == PARACHUTE_SUB then
      cch.parachuteRes, cch.parachuteIns = nil, nil
      _G.AddOutfitLastLobbyParachuteRes = nil F.persistForgetSlot("parachute")
    elseif F.isGlideRes(resID) then
      cch.gliderRes, cch.gliderIns = nil, nil
      _G.AddOutfitLastLobbyGliderRes = nil F.persistForgetSlot("glider")
    elseif st == GLOVES_SUB then
      if F.PendingWear then
        F.PendingWear.gloves = nil
      end
      cch.glovesRes, cch.glovesIns = nil, nil
      _G.AddOutfitLastLobbyGlovesRes = nil F.persistForgetSlot("gloves")
    elseif F.extraCosmeticSlot(st) then
      local slot = F.extraCosmeticSlot(st)
      if cch[slot .. "Res"] == tonumber(resID) then
        cch[slot .. "Res"], cch[slot .. "Ins"] = nil, nil F.persistForgetSlot(slot)
      end
    end
    _matchApplied = false F.invalidateSocialWearCache()
    F.perfInvalidateLobby()
    F.persistMarkDirty()
  end
  function F.takeOffInjected(insID)
    insID = tonumber(insID)
    pcall(F.cancelLocalSkinSelection, insID)
    local resID = R.insToRes[insID]
    if not resID then
      return
    end
    local st = F.subType(F.cfg(resID))
    pcall(function()
      local WRH = require("client.network.Protocol.WardRobeHandler")
      WRH.on_depot_put_down_rsp(NET_OK, { res_id = resID, count = 1 }, insID)
    end)
    pcall(function()
      local AvatarData = require("client.logic.data.AvatarData")
      AvatarData.RemoveRoleWearDataByValue(insID)
    end)
    if st == HAT_SUB or HEAD_SUBS[st] then
      pcall(function()
        local fbd = require("client.slua.logic.wardrobe.fashionbag.fashionbag_data")
        local bag = fbd.GetCurrentFashionBag and fbd:GetCurrentFashionBag()
        if bag and tonumber(bag.head_show) == insID then
          fbd:SetHeadShow(0)
        end
      end)
    end
    if BAG_SUBS[st] or HELMET_SUBS[st] then
      pcall(function()
        local t = DataMgr.equipmentSkinInsIDTable
        if t then
          for _, k in ipairs( { st, 504, 505 }) do
            if tonumber(t[k]) == insID then
              t[k] = 0
            end
          end
        end
        local fbd = require("client.slua.logic.wardrobe.fashionbag.fashionbag_data")
        local bag = fbd.GetCurrentFashionBag and fbd:GetCurrentFashionBag()
        if bag then
          if tonumber(bag.bag_skin) == insID then
            bag.bag_skin = 0
          end
          if tonumber(bag.helmet_skin) == insID then
            bag.helmet_skin = 0
          end
        end
      end)
    end
    F.clearEquipCache(resID)
    pcall(F.syncFashionBagRolewear)
  end
  function F.syncWeaponArmorySilent(weaponID, insID)
    weaponID, insID = tonumber(weaponID), tonumber(insID)
    if not weaponID or not insID or not F.isInjectedIns(insID) then
      return
    end
    local resID = R.insToRes[insID]
    if not resID then
      return
    end
    local Arm = require("client.logic.armory.logic_armory")
    Arm.rsp_list = Arm.rsp_list or {
      skin_list = {},
      install_list = {}
    }
    Arm.rsp_list.install_list = Arm.rsp_list.install_list or {} F.injectArmory(resID, insID)
    Arm.rsp_list.install_list[weaponID] = { skin_id = insID }
    pcall(function()
      local fbd = require("client.slua.logic.wardrobe.fashionbag.fashionbag_data")
      if fbd.UpdateCurrentFashionBagWeaponSkin then
        fbd:UpdateCurrentFashionBagWeaponSkin(weaponID, insID)
      end
    end)
  end
  function F.equipWeaponSkin(weaponID, insID, forceVisual)
    weaponID, insID = tonumber(weaponID), tonumber(insID)
    if not weaponID or not insID or not F.isInjectedIns(insID) then
      return false
    end
    local resID = R.insToRes[insID]
    if not resID then
      return false
    end
    if not _G.OwenNeonLobbySceneAllowed() then
      F.syncWeaponArmorySilent(weaponID, insID);
      return false
    end
    _G.AddOutfitWeaponEquipped = _G.AddOutfitWeaponEquipped or {}
    if not forceVisual and F.isWeaponVisuallyEquipped(weaponID, insID) then
      F.syncWeaponArmorySilent(weaponID, insID)
      return false
    end
    F.saveEquip(resID, insID)
    local Arm = require("client.logic.armory.logic_armory")
    local fbd = require("client.slua.logic.wardrobe.fashionbag.fashionbag_data")
    local HT = require("client.logic.lobby.hall_theme_utils")
    local wgl = require("client.slua.logic.wardrobe.logic_wardrobe_gun")
    F.injectArmory(resID, insID)
    Arm.rsp_list.install_list[weaponID] = { skin_id = insID }
    if fbd.UpdateCurrentFashionBagWeaponSkin then
      fbd:UpdateCurrentFashionBagWeaponSkin(weaponID, insID)
    end
    local bagIdx = fbd:GetFashionBagUseIndex()
    HT.proc_skin_list_chg("weapon_skin", weaponID, insID, bagIdx, {})
    wgl:SetGunID(weaponID)
    wgl:UpdateCurrentGunAvatar(weaponID, insID)
    if EventSystem and EVENTTYPE_ARMORY and EVENTID_ARMORY_EQUIP_STAT_CHANGE then
      EventSystem:postEvent(EVENTTYPE_ARMORY, EVENTID_ARMORY_EQUIP_STAT_CHANGE, resID)
    end
    if EventSystem and EVENTTYPE_WARDROBE and EVENTID_WARDROBE_UPDATE_CURRENT_PUT_ON_GUN then
      EventSystem:postEvent(EVENTTYPE_WARDROBE, EVENTID_WARDROBE_UPDATE_CURRENT_PUT_ON_GUN, resID)
    end
    _G.AddOutfitWeaponEquipped[weaponID] = insID
    return true
  end
  local SOCIAL = _G.AddOutfitSocialState or {} _G.AddOutfitSocialState = SOCIAL
  SOCIAL.debGen = SOCIAL.debGen or 0
  SOCIAL.wearPatchKey = SOCIAL.wearPatchKey or nil
  SOCIAL.snapshotKey = SOCIAL.snapshotKey or nil
  SOCIAL.fullSnapshot = SOCIAL.fullSnapshot or nil
  function F.socialDebounce(sec, fn)
    SOCIAL.debGen = (SOCIAL.debGen or 0) + 1
    local gen = SOCIAL.debGen F.later(sec, function()
      if gen ~= SOCIAL.debGen then
        return
      end
      pcall(fn)
    end)
  end
  function F.getLobbyCurPage()
    if F.isInRealMatch() or not _G.OwenNeonLobbySceneAllowed() then
      return nil
    end
    local p = nil pcall(function()
      local LMC = require("client.slua.logic.lobby.Main.Lobby_Main_Control")
      if LMC.GetCurPage then
        p = LMC.GetCurPage()
      end
    end)
    return p
  end
  function F.isLobbyLeftPage()
    return ENUM_LobbyPageType and F.getLobbyCurPage() == ENUM_LobbyPageType.Left
  end
  function F.getWeaponSkinResFast()
    local cch = F.cache()
    local wid = tonumber(DataMgr.Weapon_ID) or 0
    local w = wid > 0 and cch.weapons[wid] or nil
    if w and w.resID and w.resID > 0 then
      return w.resID
    end
    if wid > 0 then
      return nil
    end
    for _, ww in pairs(cch.weapons) do
      if ww.resID and ww.resID > 0 then
        return ww.resID
      end
    end
    return nil
  end
  function F.resolveLobbyWeaponSkinRes()
    if LOBBY.skinResolved then
      return LOBBY.cachedSkin
    end
    local wid = tonumber(DataMgr.Weapon_ID) or 0
    local skin = F.getWeaponSkinResFast()
    if skin and skin > 0 then
      return skin
    end
    if wid > 0 then
      local fromMatch = F.getMatchWeaponSkin(wid)
      if fromMatch and fromMatch > 0 then
        return fromMatch
      end
    end
    if wid == 0 and MATCH_CONFIG.weaponSkins then
      for _, s in pairs(MATCH_CONFIG.weaponSkins) do
        s = tonumber(s)
        if s and s > 0 then
          return s
        end
      end
    end
    pcall(function()
      local Arm = require("client.logic.armory.logic_armory")
      local entry = Arm.rsp_list and Arm.rsp_list.install_list and Arm.rsp_list.install_list[wid > 0 and wid or 101004]
      local insID = tonumber(entry and entry.skin_id) or 0
      if insID > 0 and F.isInjectedIns(insID) then
        skin = tonumber(R.insToRes[insID])
      elseif insID > 0 then
        local wd = require("client.slua.logic.wardrobe.wardrobe_data")
        local d = wd:GetHallDepotItemDataByInsID(insID)
        if d and d.resID then
          skin = tonumber(d.resID)
        end
      end
    end)
    if skin and skin > 0 then
      return skin
    end
    pcall(function()
      local wgl = require("client.slua.logic.wardrobe.logic_wardrobe_gun")
      if wgl.GetSkinIdByWeaponID and wid > 0 then
        local insID = tonumber(wgl:GetSkinIdByWeaponID(wid)) or 0
        if insID > 0 and F.isInjectedIns(insID) then
          skin = tonumber(R.insToRes[insID])
        end
      end
    end)
    LOBBY.skinResolved = true
    LOBBY.cachedSkin = (skin and skin > 0) and skin or nil
    return LOBBY.cachedSkin
  end
  function F.resolveLobbyOutfitRes()
    if LOBBY.outfitResolved then
      return LOBBY.cachedOutfit
    end
    local cch = F.cache()
    local outfitRes = tonumber(cch.outfitRes) or 0
    if outfitRes > 0 then
      LOBBY.outfitResolved = true
      LOBBY.cachedOutfit = outfitRes
      return outfitRes
    end
    outfitRes = tonumber(_G.AddOutfitLastLobbyOutfitRes) or 0
    if outfitRes > 0 then
      LOBBY.outfitResolved = true
      LOBBY.cachedOutfit = outfitRes
      return outfitRes
    end
    if MATCH_CONFIG.outfitRes and tonumber(MATCH_CONFIG.outfitRes) > 0 then
      LOBBY.outfitResolved = true
      LOBBY.cachedOutfit = tonumber(MATCH_CONFIG.outfitRes)
      return LOBBY.cachedOutfit
    end
    local injectedRes, anyRes pcall(function()
      local AvatarData = require("client.logic.data.AvatarData")
      local wd = require("client.slua.logic.wardrobe.wardrobe_data")
      local function resFromIns(ins)
        ins = tonumber(ins)
        if not ins or ins <= 0 then
          return nil
        end
        if F.isInjectedIns(ins) then
          return tonumber(R.insToRes[ins])
        end
        local d = wd:GetHallDepotItemDataByInsID(ins)
        return d and tonumber(d.resID) or nil
      end
      for _, ins in pairs(AvatarData.GetRoleWear()) do
        local res = resFromIns(ins)
        if res and F.isSuitRes(res) then
          if F.isInjectedRes(res) then
            injectedRes = res
          end
          anyRes = anyRes or res
        end
      end
      local fbd = require("client.slua.logic.wardrobe.fashionbag.fashionbag_data")
      local bag = fbd.GetCurrentFashionBag and fbd:GetCurrentFashionBag()
      if bag and bag.rolewear_list then
        for _, ins in pairs(bag.rolewear_list) do
          local res = resFromIns(ins)
          if res and F.isSuitRes(res) then
            if F.isInjectedRes(res) then
              injectedRes = res
            end
            anyRes = anyRes or res
          end
        end
      end
    end)
    if injectedRes and injectedRes > 0 then
      LOBBY.outfitResolved = true
      LOBBY.cachedOutfit = injectedRes
      return injectedRes
    end
    if anyRes and anyRes > 0 then
      LOBBY.outfitResolved = true
      LOBBY.cachedOutfit = anyRes
      return anyRes
    end
    LOBBY.outfitResolved = true
    LOBBY.cachedOutfit = nil
    return nil
  end
  function F.rememberLobbyOutfitRes(resID)
    resID = tonumber(resID)
    if not resID or resID <= 0 or not F.isSuitRes(resID) then
      return
    end
    _G.AddOutfitLastLobbyOutfitRes = resID F.invalidateLobbyResolved()
    local cch = F.cache()
    if not cch.outfitRes or cch.outfitRes <= 0 then
      cch.outfitRes = resID
      if F.isInjectedRes(resID) then
        cch.outfitIns = R.resToIns[resID]
      end
    end
  end
  function F.wearPatchKey()
    local outfit = F.resolveLobbyOutfitRes() or 0
    local skin = F.resolveLobbyWeaponSkinRes() or 0
    local openGun = 1 pcall(function()
      local lds = require("client.slua.logic.wardrobe.logic_display_setting")
      if lds.data and lds.data.OpenGun ~= nil then
        openGun = lds.data.OpenGun and 1 or 0
      end
    end)
    return outfit .. "_" .. skin .. "_" .. openGun
  end
  function F.syncDepotShowWeaponFlags(depot)
    depot = depot or {} pcall(function()
      local lds = require("client.slua.logic.wardrobe.logic_display_setting")
      if lds.data then
        if lds.data.OpenGun ~= nil then
          depot.weapon = lds.data.OpenGun
        end
        if lds.data.OpenSocialWeapon ~= nil then
          depot.social_weapon = lds.data.OpenSocialWeapon
        end
      end
    end)
    return depot
  end
  function F.applyInjectedPspace(roleData)
    if not roleData then
      return
    end
    roleData.bshow = true
    roleData.pspace_wear_ext = roleData.pspace_wear_ext or {}
    local outfitRes = F.resolveLobbyOutfitRes()
    if outfitRes and outfitRes > 0 then
      roleData.pspace_wear_ext[ENUM_AVATAR_SHOW_TYPE.SHOW_POS_CLOTH] = { outfitRes, 0, 0 }
    end
    local skinRes = F.resolveLobbyWeaponSkinRes()
    if skinRes and skinRes > 0 then
      roleData.pspace_wear_ext[ENUM_AVATAR_SHOW_TYPE.SHOW_POS_WEAPON] = { 0, 0, 0 }
      roleData.pspace_wear_ext[ENUM_AVATAR_SHOW_TYPE.SHOW_POS_WEAPONSKIN] = { skinRes, 0, 0 }
      roleData.depot_show_info = roleData.depot_show_info or {}
      if roleData.depot_show_info.weapon == nil then
        roleData.depot_show_info.weapon = true
      end
    end
    roleData.depot_show_info = F.syncDepotShowWeaponFlags(roleData.depot_show_info)
  end
  function F.lobbyWorkAllowed()
    return not F.skinOff() and not F.isInRealMatch() and _G.OwenNeonLobbySceneAllowed and _G.OwenNeonLobbySceneAllowed() == true
  end
  function F.patchSelfWearCache(force)
    if not F.lobbyWorkAllowed() then
      return false
    end
    local key = F.wearPatchKey()
    if not force and SOCIAL.wearPatchKey == key then
      return false
    end
    SOCIAL.wearPatchKey = key
    SOCIAL.snapshotKey = nil
    SOCIAL.fullSnapshot = nil
    local myUid = tonumber(DataMgr.roleData.uid)
    if not myUid then
      return false
    end
    local changed = false pcall(function()
      local BD = ModuleManager.GetModule(ModuleManager.DataModuleConfig.BasicDataAvatarWearInfo)
      local d = BD:GetCacheData(myUid)
      if not d then
        BD:OnHandleMsgDataAndCallback(myUid, F.buildLocalRoleDataForCoupleAvatar())
        return true
      end
      local oldCloth = d.pspace_wear_ext and d.pspace_wear_ext[ENUM_AVATAR_SHOW_TYPE.SHOW_POS_CLOTH]
      local oldSkin = d.pspace_wear_ext and d.pspace_wear_ext[ENUM_AVATAR_SHOW_TYPE.SHOW_POS_WEAPONSKIN]
      F.applyInjectedPspace(d)
      local nc = d.pspace_wear_ext[ENUM_AVATAR_SHOW_TYPE.SHOW_POS_CLOTH]
      local ns = d.pspace_wear_ext[ENUM_AVATAR_SHOW_TYPE.SHOW_POS_WEAPONSKIN]
      if oldCloth ~= nc or oldSkin ~= ns or not d.bshow then
        changed = true
      end
    end)
    return force or changed
  end
  function F.requestSocialAvatarRefresh()
    if not F.lobbyWorkAllowed() then
      return false
    end
    pcall(function()
      if EventSystem and EVENTTYPE_LOBBY_SOCIAL and EVENTID_SOCIAL_LOBBY_REFRESH_AVATAR then
        EventSystem:postEvent(EVENTTYPE_LOBBY_SOCIAL, EVENTID_SOCIAL_LOBBY_REFRESH_AVATAR)
      end
    end)
  end
  function F.onSocialWearDirty(forceRefresh)
    if not F.lobbyWorkAllowed() then
      return false
    end
    SOCIAL.lastHandSkin = nil
    if F.patchSelfWearCache(forceRefresh) then
      F.requestSocialAvatarRefresh()
    end
  end
  function F.buildLocalRoleDataForCoupleAvatar()
    local key = F.wearPatchKey()
    if SOCIAL.fullSnapshot and SOCIAL.snapshotKey == key then
      return SOCIAL.fullSnapshot
    end
    F.syncWeaponCacheFromLobby()
    local cch = F.cache()
    local ad = DataMgr.avatarData or {}
    local gender = tonumber(ad.gamegender) or 2
    if gender < 1 then
      gender = 2
    end
    local data = {
      uid = DataMgr.roleData.uid,
      gender = gender,
      bshow = true,
      pspace_wear_ext = {
[ENUM_AVATAR_SHOW_TYPE.SHOW_POS_HEAD] = { tonumber(ad.headid) or 401993, 0, 0 },
[ENUM_AVATAR_SHOW_TYPE.SHOW_POS_HAIR] = { tonumber(ad.hairid) or 40601001, 0, 0 },
[ENUM_AVATAR_SHOW_TYPE.SHOW_POS_WEAPON] = { 0, 0, 0 },
[ENUM_AVATAR_SHOW_TYPE.SHOW_POS_WEAPONSKIN] = { 0, 0, 0 },
      },
      depot_show_info = { weapon = true, social_weapon = true, idle = true, helmet = F.lobbySlotVisible('helmet'),
      bag = F.lobbySlotVisible('bag'), vehicle = true, hand = true, },
    }
    local outfitRes = F.resolveLobbyOutfitRes()
    if outfitRes and outfitRes > 0 then
      data.pspace_wear_ext[ENUM_AVATAR_SHOW_TYPE.SHOW_POS_CLOTH] = { outfitRes, 0, 0 }
    end
    local skinRes = F.resolveLobbyWeaponSkinRes()
    if skinRes and skinRes > 0 then
      data.pspace_wear_ext[ENUM_AVATAR_SHOW_TYPE.SHOW_POS_WEAPON][1] = 0
      data.pspace_wear_ext[ENUM_AVATAR_SHOW_TYPE.SHOW_POS_WEAPONSKIN][1] = skinRes
    end
    data.depot_show_info = F.syncDepotShowWeaponFlags(data.depot_show_info)
    SOCIAL.fullSnapshot = data
    SOCIAL.snapshotKey = F.wearPatchKey()
    return data
  end
  local _myUidCached
  function F.isMyWearData(wearData)
    local uid = DataMgr and DataMgr.roleData and tonumber(DataMgr.roleData.uid)
    return uid ~= nil and wearData ~= nil and tonumber(wearData.uid) == uid
  end
  function F.mergeInjectedWeaponIntoWearData(wearData)
    if not F.isMyWearData(wearData) then
      return
    end
    local skinRes = F.resolveLobbyWeaponSkinRes()
    wearData.depot_show_info = F.syncDepotShowWeaponFlags(wearData.depot_show_info)
    if not skinRes or skinRes <= 0 then
      return
    end
    wearData.mainWeaponInfo = wearData.mainWeaponInfo or {
      weaponResId = 0,
      weaponSkinId = 0,
      diyInfo = { diyWeaponId = 0, diyDefaultScheme = false, diyScheme = nil },
    }
    if wearData.mainWeaponInfo.weaponSkinId == skinRes and (tonumber(wearData.mainWeaponInfo.weaponResId) or 0) == 0 then
      return
    end
    wearData.mainWeaponInfo.weaponSkinId = skinRes
    wearData.mainWeaponInfo.weaponResId = 0
  end
  function F.equipSocialHandWeapon(avatar, skinRes)
    if not F.lobbyWorkAllowed() then
      return false
    end
    if not avatar or not skinRes or skinRes <= 0 then
      return
    end
    if SOCIAL.lastHandSkin == skinRes then
      return
    end
    SOCIAL.lastHandSkin = skinRes pcall(function()
      avatar:PutonEquipment(skinRes, nil, { bIsUse = true })
    end)
  end
  function F.shouldShowHandWeapon()
    local show = true pcall(function()
      local lds = require("client.slua.logic.wardrobe.logic_display_setting")
      if lds.data and lds.data.OpenGun ~= nil then
        show = lds.data.OpenGun ~= false
      end
    end)
    return show
  end
  function F.mergeInjectedOutfitIntoWearData(wearData)
    if not F.isMyWearData(wearData) then
      return
    end
    local outfitRes = F.resolveLobbyOutfitRes()
    if not outfitRes or outfitRes <= 0 then
      return
    end
    F.rememberLobbyOutfitRes(outfitRes)
    local AvatarData = require("client.logic.data.AvatarData")
    local converted = AvatarData.ConvertToAvatarCustom( { outfitRes, 0, 0 })
    if not converted then
      return
    end
    wearData.WearInfoList = wearData.WearInfoList or {}
    local replaced = false
    for i, e in ipairs(wearData.WearInfoList) do
      if e and e.ItemID and F.isSuitRes(e.ItemID) then
        wearData.WearInfoList[i] = converted
        replaced = true
        break
      end
    end
    if not replaced then
      table.insert(wearData.WearInfoList, converted)
    end
  end
  function F.mergeInjectedIntoWearData(wearData)
    if not wearData then
      return
    end
    F.mergeInjectedWeaponIntoWearData(wearData)
    F.mergeInjectedOutfitIntoWearData(wearData)
  end
  function F.getLobbyRestoreTarget()
    local uid = DataMgr and DataMgr.roleData and DataMgr.roleData.uid
    if not uid then
      return nil
    end
    local ok, manager = pcall(require, 'client.logic.avatar.logic_team_avatar_manager')
    if not ok or not manager or type(manager.GetAvatarByUid) ~= 'function' then
      return nil
    end
    local got, avatar = pcall(manager.GetAvatarByUid, tostring(uid))
    if not got or not avatar or type(avatar.GetModel) ~= 'function' then
      return nil
    end
    local modelOK, model = pcall(avatar.GetModel, avatar)
    if not modelOK or not model or not slua.isValid(model) then
      return nil
    end
    local compOK, comp = pcall(function()
      if type(avatar.GetModelAvatarComp) == 'function' then
        return avatar:GetModelAvatarComp()
      end
      return model.CharacterAvatarComp2_BP
    end)
    if not compOK or not comp or not slua.isValid(comp) then
      return nil
    end
    return avatar, model, comp
  end
  function F.lobbySlotVisible(slot)
    if slot ~= 'bag' and slot ~= 'helmet' then
      return true
    end
    local ok, display = pcall(require, 'client.slua.logic.wardrobe.logic_display_setting')
    local fn = ok and display and display[slot == 'bag' and 'ShowBag' or 'ShowHelmet']
    if type(fn) == 'function' then
      local got, value = pcall(fn)
      if got and value ~= nil then
        return value ~= false and value ~= 0
      end
    end
    local flags = DataMgr and DataMgr.roleData and DataMgr.roleData.depot_show_info
    return not flags or (flags[slot] ~= false and flags[slot] ~= 0)
  end
  function F.applyLobbyHiddenEquipment(avatar)
    if not F.lobbyWorkAllowed() or not avatar then
      return
    end
    local ok, comp = pcall(avatar.GetModelAvatarComp, avatar)
    if not ok or not comp or not slua.isValid(comp) or not comp.SetAvatarVisibility then
      return
    end
    local enums = import('EAvatarSlotType')
    for _, row in ipairs( {
{ 'bag', 'EAvatarSlotType_BackpackEquipemtSlot' },
{ 'helmet', 'EAvatarSlotType_HelmetEquipemtSlot' }
    }) do
      if not F.lobbySlotVisible(row[1]) and enums[row[2]] then
        pcall(comp.SetAvatarVisibility, comp, enums[row[2]], false, true)
      end
    end
  end
  function F.matchOnlySelectionSlot(res)
    if F.isParachuteRes(res) then
      return 'parachute'
    end
    if F.isGlideRes(res) then
      return 'glider'
    end
    local slot = F.extraCosmeticSlot(F.subType(F.cfg(res)))
    if slot and F.isMatchOnlyCosmeticSlot(slot) then
      return slot
    end
  end
  function F.localSelectionCheckmark(cell, data)
    if not F.lobbyWorkAllowed() or type(data) ~= 'table' then
      return
    end
    local ins = tonumber(data.ins_id or data.insID or data.instid)
    local res = tonumber(data.res_id or data.resID)
    if not ins or not res then
      return
    end
    local slot = F.matchOnlySelectionSlot(res)
    local desired = slot and (tonumber(PERSIST.configSlots and PERSIST.configSlots[slot]) or tonumber(F.cache()[slot .. 'Res']))
    if not desired then
      if slot and F.LocalSkinCleared and F.LocalSkinCleared[slot] and F.isSyntheticIns(ins) then
        data.isUsing = false
        if cell and type(cell.SetUsingState) == 'function' then
          cell:SetUsingState( false)
        end
      end
      return
    end
    local selectedIns = tonumber(F.cache()[slot .. 'Ins'])
    if not F.isSyntheticIns(ins) and not (selectedIns and F.isSyntheticIns(selectedIns)) then
      return
    end
    data.isUsing = res == desired and ( not selectedIns or ins == selectedIns)
    if cell and type(cell.SetUsingState) == 'function' then
      cell:SetUsingState(data.isUsing)
    end
  end
  function F.installWardrobeSelectionControls()
    if not F.lobbyWorkAllowed() then
      return
    end
    local function publish(class, key, fn)
      rawset(class.__inner_impl or class, key, fn);
      rawset(class, key, fn)
    end
    pcall(function()
      local base = require('client.slua.umg.Wardrobe.subtab_item_list_base')
      local impl = base.__inner_impl or base
      if impl._OwenSelectedCellRender then
        return
      end
      local original = base.OnPostInitView publish(base, 'OnPostInitView', function(self, cell, data, ...)
        local result = table.pack(original(self, cell, data, ...))
        pcall(F.localSelectionCheckmark, cell, data)
        return table.unpack(result, 1, result.n)
      end)
      impl._OwenSelectedCellRender = true
    end)
    for _, path in ipairs( { 'client.slua.umg.Wardrobe.subtab_parachute', 'client.slua.umg.Wardrobe.subtab_gliding',
    'client.slua.umg.Wardrobe.subtab_foot_effect' }) do
      pcall(function()
        local class = require(path);
        local impl = class.__inner_impl or class
        if impl._OwenLocalEffectClick then
          return
        end
        local original = class.OnClickItem
        if type(original) ~= 'function' then
          return
        end
        publish(class, 'OnClickItem', function(self, cell, index, ...)
          local grid = self.LoopScrollGrid_Normal or self.LoopScrollGridSkins or self.LoopScrollBox
          local data = grid and grid.GetItemData and grid:GetItemData(index)
          if not data and self.GetSkins then
            data = self:GetSkins(index)
          end
          local ins = data and tonumber(data.ins_id or data.insID or data.instid)
          local res = data and tonumber(data.res_id or data.resID)
          local slot = res and F.matchOnlySelectionSlot(res)
          if F.lobbyWorkAllowed() and slot and ins and F.isSyntheticIns(ins) and F.getSyntheticItem(ins, res) then
            local result = F.selectAirborneForMatch(self, data, slot)
            F.localSelectionCheckmark(cell, data)
            return result
          end
          return original(self, cell, index, ...)
        end)
        impl._OwenLocalEffectClick = true
      end)
    end
  end
  function F.selectedLobbyClothesSlot()
    local slots = PERSIST.configSlots or {}
    local outfit, shirt = tonumber(slots.outfit), tonumber(slots.tshirt)
    if outfit and outfit > 0 then
      return 'outfit'
    end
    if shirt and shirt > 0 then
      return 'tshirt'
    end
    local cache = F.cache()
    if tonumber(cache.outfitRes) and tonumber(cache.outfitRes) > 0 then
      return 'outfit'
    end
    if tonumber(cache.tshirtRes) and tonumber(cache.tshirtRes) > 0 then
      return 'tshirt'
    end
  end
  function F.lobbyRenderMatches(avatar, key, res, displayRes)
    if F.lobbyWorkAllowed and not F.lobbyWorkAllowed() then
      return false, 'outside_lobby'
    end
    local slots = { outfit = 5, tshirt = 5, hat = 3, helmet = 9, mask = 4, glass = 12, pants = 6, shoes = 7,
    gloves = 16, bag = 8 }
    local slot = slots[key]
    if not slot or not avatar then
      return false, 'render_slot_unknown'
    end
    local ok, comp = pcall(function()
      return avatar:GetModelAvatarComp()
    end)
    if not ok or not comp or not slua.isValid(comp) then
      return false, 'render_component_pending'
    end
    local getter = comp.GetMeshCompBySlot
    if type(getter) ~= 'function' then
      return false, 'render_api_unavailable'
    end
    local got, mesh = pcall(getter, comp, slot)
    if not got or not mesh or not slua.isValid(mesh) then
      return false, 'mesh_pending'
    end
    local loaded, asset = pcall(function()
      return mesh.SkeletalMesh or mesh.StaticMesh
    end)
    if not loaded or not asset or not slua.isValid(asset) then
      return false, 'mesh_asset_pending'
    end
    local read, value = pcall(function()
      return mesh.bVisible
    end)
    if not read or (value ~= true and value ~= 1) then
      return false, 'mesh_hidden_or_unconfirmed'
    end
    local hidden, hide = pcall(function()
      return mesh.bHiddenInGame
    end)
    if hidden and (hide == true or hide == 1) then
      return false, 'mesh_hidden'
    end
    local check = comp.GetEquippedItemDefineID3
    if type(check) == 'function' then
      local success, item = pcall(check, comp, slot)
      local id;
      pcall(function()
        id = item and tonumber(item.TypeSpecificID)
      end)
      if not success or not id or (id ~= res and id ~= displayRes) then
        return false, 'native_slot_mismatch'
      end
    end
    return true, 'render_confirmed'
  end
  function F.confirmLobbyWear(avatar, checkOnly)
    local cache = F.cache()
    local expected = {}
    local expectedKeys = {}
    for _, slot in ipairs( {
{ 'clothes', 'outfitRes', 'outfitIns' },
{ 'clothes', 'tshirtRes', 'tshirtIns' },
{ 'head', 'hatRes', 'hatIns' },
{ 'head', 'helmetRes', 'helmetIns' },
{ 'mask', 'maskRes', 'maskIns' },
{ 'glass', 'glassRes', 'glassIns' },
{ 'pants', 'pantsRes', 'pantsIns' },
{ 'shoes', 'shoesRes', 'shoesIns' },
{ 'gloves', 'glovesRes', 'glovesIns' },
{ 'bag', 'bagRes', 'bagIns' }
    }) do
      local key = slot[2]:gsub('Res$', '')
      local desired = tonumber(PERSIST.configSlots and PERSIST.configSlots[key])
      local res, ins = desired or tonumber(cache[slot[2]]), tonumber(cache[slot[3]])
      local selected = ( not F.lobbySlotVisible or F.lobbySlotVisible(key)) and (slot[1] ~= 'clothes' or F.selectedLobbyClothesSlot() == (slot[2] == 'outfitRes' and 'outfit' or 'tshirt'))
      if selected and res and res > 0 and ((desired and desired > 0) or (ins and F.isInjectedIns(ins))) then
        expected[slot[1]] = res;
        expectedKeys[slot[1]] = key
      end
    end
    if not next(expected) then
      return true
    end
    if not avatar or type(avatar.GetEquipments) ~= 'function' then
      return false
    end
    local function worn()
      local ok, items = pcall(avatar.GetEquipments, avatar)
      if not ok or type(items) ~= 'table' then
        return nil
      end
      local found = {}
      for _, item in pairs(items) do
        local id = tonumber(item and item.itemID)
        if id then
          found[id] = true
        end
      end
      return found
    end
    local found = worn()
    if not found then
      return false
    end
    local function displayed(res)
      for _, name in ipairs( { '_GetReplaceItemID', '_GetDisplayItemID' }) do
        if type(avatar[name]) == 'function' then
          local ok, value = pcall(avatar[name], avatar, res)
          if ok and tonumber(value) and tonumber(value) > 0 then
            res = tonumber(value)
          end
        end
      end
      return res
    end
    local pending = false
    for name, res in pairs(expected) do
      local rendered, why = F.lobbyRenderMatches(avatar, expectedKeys[name], res, displayed(res))
      if not found[displayed(res)] or not rendered then
        F.LobbyRenderStatus = why or 'equipment_missing'
        pending = true
        if not checkOnly and type(avatar.PutonEquipment) == 'function' then
          pcall(avatar.PutonEquipment, avatar, res, nil, { bIsUse = true })
        end
      end
    end
    if not pending then
      F.LobbyRenderStatus = 'render_confirmed';
      return true
    end
    found = worn()
    if not found then
      return false
    end
    for name, res in pairs(expected) do
      local rendered, why = F.lobbyRenderMatches(avatar, expectedKeys[name], res, displayed(res))
      if not found[displayed(res)] or not rendered then
        return false, why or 'equipment_missing'
      end
    end
    return true
  end
  function F.lobbyPersistSlotReady(slot)
    local cch = F.cache()
    local desired = tonumber(PERSIST.configSlots and PERSIST.configSlots[slot[1]])
    local res, ins = tonumber(cch[slot[2]]), tonumber(cch[slot[3]])
    if desired and desired > 0 and (res ~= desired or not ins or ins <= 0) then
      return false
    end
    if res and res > 0 then
      if not ins or ins <= 0 then
        return false
      end
      if not F.isResourcesReady(res) then
        F.requestResourceDownload(res)
        return false
      end
    end
    return true
  end
  function F.lobbyPersistSlotsReady()
    local ready = true
    for _, slot in ipairs(PERSIST_SLOTS) do
      local bodySelected = (slot[1] ~= 'outfit' and slot[1] ~= 'tshirt') or slot[1] == F.selectedLobbyClothesSlot()
      if bodySelected and not F.isMatchOnlyCosmeticSlot(slot[1]) and not F.lobbyPersistSlotReady(slot) then
        ready = false
      end
    end
    return ready
  end
  function F.reapplyLobbyEquipped()
    if F.skinOff() then
      return false
    end
    if not _G.OwenNeonLobbySceneAllowed() then
      return false
    end
    F.syncWeaponCacheFromLobby()
    F.applyPersistSlotsToCache()
    local allSlotsReady = F.lobbyPersistSlotsReady()
    local avatar = F.getLobbyRestoreTarget()
    if not avatar then
      return false
    end
    local curPage = F.getLobbyCurPage()
    if ENUM_LobbyPageType and curPage == ENUM_LobbyPageType.Left then
      F.onSocialWearDirty( true)
      return false
    end
    local cch = F.cache()
    if F.selectedLobbyClothesSlot() == 'outfit' and F.lobbyPersistSlotReady( { 'outfit', 'outfitRes',
    'outfitIns' }) and cch.outfitIns and F.isInjectedIns(cch.outfitIns) then
      F.putOnOutfit(cch.outfitIns)
    end
    if F.lobbyPersistSlotReady( { 'hat', 'hatRes', 'hatIns' }) and cch.hatIns and F.isInjectedIns(cch.hatIns) then
      F.putOnHat(cch.hatIns)
    end
    if F.lobbyPersistSlotReady( { 'mask', 'maskRes', 'maskIns' }) and cch.maskIns and F.isInjectedIns(cch.maskIns) then
      F.putOnRoleWear(cch.maskIns)
    end
    if F.lobbyPersistSlotReady( { 'glass', 'glassRes', 'glassIns' }) and cch.glassIns and F.isInjectedIns(cch.glassIns) then
      F.putOnRoleWear(cch.glassIns)
    end
    if F.selectedLobbyClothesSlot() == 'tshirt' and F.lobbyPersistSlotReady( { 'tshirt', 'tshirtRes',
    'tshirtIns' }) and cch.tshirtIns and F.isInjectedIns(cch.tshirtIns) then
      F.putOnRoleWear(cch.tshirtIns)
    end
    if F.lobbyPersistSlotReady( { 'pants', 'pantsRes', 'pantsIns' }) and cch.pantsIns and F.isInjectedIns(cch.pantsIns) then
      F.putOnRoleWear(cch.pantsIns)
    end
    if F.lobbyPersistSlotReady( { 'shoes', 'shoesRes', 'shoesIns' }) and cch.shoesIns and F.isInjectedIns(cch.shoesIns) then
      F.putOnRoleWear(cch.shoesIns)
    end
    if ( not F.lobbySlotVisible or F.lobbySlotVisible('bag')) and F.lobbyPersistSlotReady( { 'bag', 'bagRes',
    'bagIns' }) and cch.bagIns and F.isInjectedIns(cch.bagIns) then
      F.putOnRoleWear(cch.bagIns)
    end
    if ( not F.lobbySlotVisible or F.lobbySlotVisible('helmet')) and F.lobbyPersistSlotReady( { 'helmet',
    'helmetRes', 'helmetIns' }) and cch.helmetIns and F.isInjectedIns(cch.helmetIns) then
      F.putOnRoleWear(cch.helmetIns)
    end
    if F.lobbyPersistSlotReady( { 'gloves', 'glovesRes', 'glovesIns' }) and cch.glovesIns and F.isInjectedIns(cch.glovesIns) then
      F.putOnGloves(cch.glovesIns)
    end
    local mainWid = tonumber(DataMgr.Weapon_ID) or 0
    local w = mainWid > 0 and cch.weapons[mainWid] or nil
    if w and w.resID and w.resID > 0 then
      if w.insID and F.isInjectedIns(w.insID) then
        F.equipWeaponSkin(mainWid, w.insID)
      else
        pcall(function()
          DataMgr.InitWeaponData(mainWid, w.resID, w.insID or 0)
        end)
      end
    end
    pcall(function()
      local uid = tostring(DataMgr.roleData.uid)
      local LAM = require("client.logic.avatar.LobbyAvatarManager")
      local TAM = require("client.logic.avatar.logic_team_avatar_manager")
      if w and w.resID and w.resID > 0 and TAM.GetAvatarByUid(uid) then
        LAM.EquipWeapon(uid, { weaponId = mainWid, skinId = w.resID }, nil, true)
      end
    end)
    F.reapplyVehicleSlotsFromConfig( true)
    F.reapplyHallThemeFromConfig( true)
    F.reapplyWeaponsFromConfig()
    pcall(F.applyVehicleSkinsToPC)
    if F.applyLobbyHiddenEquipment then
      F.applyLobbyHiddenEquipment(avatar)
    end
    return allSlotsReady and F.confirmLobbyWear(avatar)
  end
  F.scheduleLobbyReapplyOnce = function()
    if LOBBY.reapplyDone or LOBBY.reapplyScheduled then
      return
    end
    LOBBY.reapplyScheduled = true F.later(2.0, function()
      LOBBY.reapplyScheduled = false
      if LOBBY.reapplyDone then
        return
      end
      LOBBY.reapplyDone = F.reapplyLobbyEquipped() == true
    end)
  end
  function F.hookLobbySwipePersistence()
    if _G.AddOutfitLobbySwipeHooked then
      return
    end
    SOCIAL.swipeHooks = SOCIAL.swipeHooks or {}
    local hooks = SOCIAL.swipeHooks
    local function install(key, fn)
      if hooks[key] then
        return
      end
      local ok, result = pcall(fn)
      if ok and result ~= false then
        hooks[key] = true
      end
    end
    install(1, function()
      local BD = ModuleManager.GetModule(ModuleManager.DataModuleConfig.BasicDataAvatarWearInfo)
      if not BD or type(BD.on_get_avatar_show_rsp) ~= "function" then
        return false
      end
      local oRsp = BD.on_get_avatar_show_rsp
      BD.on_get_avatar_show_rsp = function(self, res, target_uid, data)
        oRsp(self, res, target_uid, data)
        if not F.lobbyWorkAllowed() then
          return
        end
        if tonumber(target_uid) == tonumber(DataMgr.roleData.uid) then
          F.patchSelfWearCache( true)
          SOCIAL.forceAvatarRedraw = true
          SOCIAL.lastHandSkin = nil
          if ENUM_LobbyPageType and F.getLobbyCurPage() == ENUM_LobbyPageType.Left then
            F.requestSocialAvatarRefresh()
          end
        end
      end
    end)
    install(2, function()
      local AC = require("client.slua.logic.avatar.avatar_common")
      if not AC or type(AC.GetWearDataFromRoleData) ~= "function" or type(AC.UpdateAvatar) ~= "function" then
        return false
      end
      local oGetWear = AC.GetWearDataFromRoleData
      AC.GetWearDataFromRoleData = function(roleData)
        if not F.lobbyWorkAllowed() then
          return oGetWear(roleData)
        end
        if roleData and roleData.uid ~= nil and tonumber(roleData.uid) == tonumber(DataMgr.roleData.uid) and not F.skinOff() then
          F.applyInjectedPspace(roleData)
        end
        local wearData = oGetWear(roleData)
        if not F.skinOff() and wearData and roleData and roleData.uid ~= nil and tonumber(roleData.uid) == tonumber(DataMgr.roleData.uid) then
          F.mergeInjectedIntoWearData(wearData)
        end
        return wearData
      end
      local oUp = AC.UpdateAvatar
      AC.UpdateAvatar = function(avatar, wearData, isShowWeapon, isShowHelmet, isShowBag)
        if not F.lobbyWorkAllowed() then
          return oUp(avatar, wearData, isShowWeapon, isShowHelmet, isShowBag)
        end
        if not F.skinOff() and F.isMyWearData(wearData) then
          F.mergeInjectedIntoWearData(wearData)
        end
        local showGun = isShowWeapon
        if F.isMyWearData(wearData) and not F.skinOff() then
          showGun = isShowWeapon and F.shouldShowHandWeapon()
        end
        if F.isMyWearData(wearData) and wearData.depot_show_info then
          showGun = showGun and wearData.depot_show_info.weapon ~= false
        end
        if F.isMyWearData(wearData) and F.isLobbyLeftPage() then
          for _, e in ipairs(wearData.WearInfoList or {}) do
            if e and e.ItemID and F.isInjectedRes(e.ItemID) and F.isSuitRes(e.ItemID) then
              F.rememberLobbyOutfitRes(e.ItemID)
              break
            end
          end
        end
        local ret = oUp(avatar, wearData, showGun, isShowHelmet, isShowBag)
        if F.isMyWearData(wearData) then
          pcall(F.applyLobbyHiddenEquipment, avatar)
        end
        if not F.skinOff() and showGun and F.isMyWearData(wearData) and avatar then
          local skin = tonumber(wearData.mainWeaponInfo and wearData.mainWeaponInfo.weaponSkinId) or 0
          if skin <= 0 then
            skin = F.resolveLobbyWeaponSkinRes() or 0
          end
          if skin > 0 then
            F.equipSocialHandWeapon(avatar, skin)
          end
        end
        return ret
      end
    end)
    install(3, function()
      local CA = require("client.logic.avatar.CoupleAvatar")
      local Cfg = require("client.slua.logic.lobby.Left.CoupleAvatarConfig")
      if not CA or type(CA.Update) ~= "function" or type(CA.OnReceiveData) ~= "function" or type(CA.CheckSelfIsHideAvatar) ~= "function" then
        return false
      end
      local oMulti = CA._UpdateMultiAvatar
      if oMulti then
        CA._UpdateMultiAvatar = function(self, avatar, avatarType)
          if not F.lobbyWorkAllowed() then
            return oMulti(self, avatar, avatarType)
          end
          local isSelf = avatarType == Cfg.AvatarType.Self and self.SelfUID and tostring(self.SelfUID) == tostring(DataMgr.roleData.uid)
          if isSelf and not F.skinOff() then
            pcall(function()
              local BD = ModuleManager.GetModule(ModuleManager.DataModuleConfig.BasicDataAvatarWearInfo)
              local d = BD:GetCacheData(tonumber(self.SelfUID))
              if d then
                F.applyInjectedPspace(d)
              end
            end)
            if SOCIAL.forceAvatarRedraw then
              self.CompareDataCache[avatarType] = nil
              SOCIAL.forceAvatarRedraw = nil
            end
          end
          oMulti(self, avatar, avatarType)
          if isSelf and not F.skinOff() and self.isShowWeapon ~= false and F.shouldShowHandWeapon() then
            local skin = F.resolveLobbyWeaponSkinRes()
            if skin and skin > 0 then
              F.equipSocialHandWeapon(avatar, skin)
            end
          end
        end
      end
      local oHideCheck = CA.CheckSelfIsHideAvatar
      CA.CheckSelfIsHideAvatar = function(self, nSelfUId, tRoleData)
        if not F.lobbyWorkAllowed() then
          return oHideCheck(self, nSelfUId, tRoleData)
        end
        if not F.skinOff() and tostring(nSelfUId) == tostring(DataMgr.roleData.uid) then
          return false
        end
        return oHideCheck(self, nSelfUId, tRoleData)
      end
      local oUpdate = CA.Update
      CA.Update = function(self)
        if not F.lobbyWorkAllowed() then
          return oUpdate(self)
        end
        if not F.isLobbyLeftPage() then
          return oUpdate(self)
        end
        local isSelf = self.SelfUID and tostring(self.SelfUID) == tostring(DataMgr.roleData.uid)
        local oHide = CA.HideAvatars
        if isSelf then
          CA.HideAvatars = function()
          end
        end
        local ok, err = pcall(oUpdate, self)
        CA.HideAvatars = oHide
      end
      local oRecv = CA.OnReceiveData
      CA.OnReceiveData = function(self, uid, data)
        if not F.lobbyWorkAllowed() then
          return oRecv(self, uid, data)
        end
