  function F.hookWardrobeData()
    F.installHelmetIconRestore()
    pcall(function()
      local wd = require('client.slua.logic.wardrobe.wardrobe_data')
      wd._OwenLocalSkinDataWrappers = wd._OwenLocalSkinDataWrappers or {}
      local installed = wd._OwenLocalSkinDataWrappers
      for _, name in ipairs( { 'GetHallDepotItemDataByInsID', 'GetValidHallDepotItemDataByInsID' }) do
