          local wrapper = function(self, insID, ...)
            if not F.skinOff() and F.isSyntheticIns(insID) then
              local item = F.getSyntheticItem(insID)
              if item then
                return item
              end
            end
            return original(self, insID, ...)
          end
          wd[name] = wrapper;
          installed[name] = wrapper
        end
      end
      for _, name in ipairs( { 'HasItem', 'HasValidItem', 'CheckHasPermanentItem' }) do
        local original = wd[name]
        if type(original) == 'function' and installed[name] ~= original then
          local wrapper = function(self, resID, ...)
            local source
            if name == 'CheckHasPermanentItem' then
              source = select(1, ...)
            else
              source = select(2, ...)
            end
            if not F.skinOff() and source == nil then
              local res = tonumber(resID)
              local ins = res and R.resToIns[res]
              if ins and F.isSyntheticIns(ins) and F.getSyntheticItem(ins, res) then
                return true
              end
            end
            return original(self, resID, ...)
          end
          wd[name] = wrapper;
          installed[name] = wrapper
        end
      end
    end)
  end
  function F.hookPageFilter()
    pcall(function()
      local wl = require("client.slua.logic.wardrobe.logic_wardrobe_new")
      if wl._AddOutfitPageFilterHooked then
        return
      end
      local o1 = wl.IsValidCurrentPageItem
      if type(o1) ~= "function" then
        return
      end
      wl._AddOutfitPageFilterHooked = true
      wl.IsValidCurrentPageItem = function(self, mainTab, subTab, v, t)
        if F.skinOff() then
          return o1(self, mainTab, subTab, v, t)
        end
        local id = type(v) == "table" and tonumber(v.resID or v.res_id)
        if id and F.NeonHiddenRows[id] then
          return false
        end
        local cfg = id and F.cfg(id)
        local ins = type(v) == "table" and tonumber(v.insID or v.instid)
        if ins and F.isSyntheticIns(ins) and not F.clothingIconUsable(id, cfg) then
          return false
        end
        if F.neonHideWardrobeItem and F.neonHideWardrobeItem(id, cfg) then
          return false
        end
        if F.neonLowQualityClothing(id, cfg) then
          return false
        end
        if id and F.isInjectedRes(id) then
          local itemTab = tonumber(v.subTabType)
          if not itemTab or itemTab <= 0 then
            itemTab = F.wardrobeTab(id)
          end
          if itemTab and itemTab == tonumber(subTab) then
            if tonumber(mainTab) == PAGE_AVATAR or tonumber(mainTab) == PAGE_VEHICLE then
              return true
            end
            if tonumber(mainTab) == PAGE_PARACHUTE and F.isHallThemeRes(id) then
              return true
            end
          end
        end
        return o1(self, mainTab, subTab, v, t)
      end
      local o2 = wl.IsCanUse
      if type(o2) == "function" then
        wl.IsCanUse = function(self, resId)
          if F.isInjectedRes(resId) then
            return true
          end
          return o2(self, resId)
        end
      end
      local o3 = wl.IsCharacterUse
      if type(o3) == "function" then
        wl.IsCharacterUse = function(self, resId)
          if F.isInjectedRes(resId) then
            return true
          end
          return o3(self, resId)
        end
      end
      local o4 = wl.GetWardrobeInsIdByResId
      if type(o4) == "function" then
        wl.GetWardrobeInsIdByResId = function(self, resid)
          resid = tonumber(resid)
          if F.isInjectedRes(resid) then
            return R.resToIns[resid]
          end
          return o4(self, resid)
        end
      end
    end)
  end
