  do
    local R = {
      Status = 'idle',
      Applied = 0,
      Hooks = {}
    };
    _G.OwenResultCosmetics = R
    local function resultSlot(id)
      local cfg = F.cfg(id)
      if not cfg then
        return nil
      end
      local bp = cfg.BPID and CDataTable.GetTableData('AvatarBPTable', cfg.BPID)
      local template = bp and tonumber(bp.TemplateID)
      if template and template > 0 then
        return math.floor(template / 1000)
      end
    end
    local function copyResult(value)
      local out = {};
      for k, v in pairs(value or {}) do
        out[k] = v
      end;
      return out
    end
    function R.Apply(logic)
      local nameTag = _G.OwenSelectedNameTag and _G.OwenSelectedNameTag()
      local skinEnabled = not F.skinOff()
      if not skinEnabled and not nameTag then
        R.Status = 'disabled';
        return false
      end
      local uid = DataMgr and DataMgr.roleData and DataMgr.roleData.uid
      if not uid then
        R.Status = 'uid_unavailable';
        return false
      end
      local data = logic and logic.ResultData
      local rows = data and data.TeammateRoleInfos
      if type(rows) ~= 'table' then
        R.Status = 'result_rows_unavailable';
        return false
      end
      for i, info in ipairs(rows) do
        if tostring(info.uid) == tostring(uid) then
          local own = copyResult(info);
          local wear = {}
          for _, item in ipairs(info.BP_ARRAY_AvatarList or {}) do
            wear[ # wear + 1] = copyResult(item)
          end
          local outfit = F.getDesiredOutfit()
          local selections = { outfit or F.getDesiredWear('tshirtRes', 'tshirtRes', 'AddOutfitLastLobbyTshirtRes'),
          F.getDesiredWear('pantsRes', 'pantsRes', 'AddOutfitLastLobbyPantsRes'), F.getDesiredWear('shoesRes', 'shoesRes', 'AddOutfitLastLobbyShoesRes') }
          local changed = false
          if skinEnabled then
            selections[4] = F.getDesiredWear('glovesRes', 'glovesRes', 'AddOutfitLastLobbyGlovesRes')
            for n = 1, 4 do
              local id = tonumber(selections[n]);
              local slot = id and resultSlot(id)
              if id and id > 0 and slot then
                for j = # wear, 1, - 1 do
                  if resultSlot(wear[j].ItemID) == slot then
                    table.remove(wear, j)
                  end
                end
                wear[ # wear + 1] = { ItemID = id, ColorID = 0, PatternID = 0 };
                changed = true
              end
            end
            for _, pair in ipairs( {
{ 'weaponId', 'weaponSkinId' },
{ 'secondWeaponId', 'secondWeaponSkinId' }
            }) do
              local base = tonumber(info[pair[1]]) or 0
              local skin = base > 0 and tonumber(F.findTargetSkinForWeaponRes(base))
              if skin and skin > 0 and F.resolveWeaponTypeID(F.weaponIdFromSkin(skin)) == F.resolveWeaponTypeID(base) then
                own[pair[2]] = skin;
                changed = true
              end
            end
          end
          if nameTag and tonumber(info.brand_id) ~= nameTag then
            own.brand_id = nameTag;
            changed = true
          end
          if changed then
            own.BP_ARRAY_AvatarList = wear
            local updated = copyResult(rows);
            updated[i] = own;
            data.TeammateRoleInfos = updated
            R.Applied = R.Applied + 1;
            R.Status = 'local_result_applied';
            R.UID = tostring(uid)
          else
            R.Status = 'no_saved_selection'
          end
          return changed
        end
      end
      R.Status = 'local_result_missing';
      return false
    end
    function F.hookBattleResultCosmetics()
      local path = 'GameLua.Mod.BRMod.Client.BattleResult.ShowAvatar.BattleResultShowAvatarLogic'
      if R.Hooks[path] then
        return
      end
      local ok, mod = pcall(require, path)
      if not ok or type(mod) ~= 'table' or type(mod.InitRoleInfoList) ~= 'function' then
        R.Status = 'hook_unavailable';
        return
      end
      local impl = rawget(mod, '__inner_impl') or mod
      local original = mod.InitRoleInfoList
      local unpack = unpack or table.unpack
      local function pack( ...)
        return { n = select('#', ...), ... }
      end
      local function hooked(self, ...)
        pcall(R.Apply, self)
        local values = pack(original(self, ...))
        local applied, err = pcall(R.Apply, self)
        if not applied then
          R.Status = 'apply_error';
          R.Error = tostring(err)
        end
        return unpack(values, 1, values.n)
      end
      rawset(impl, 'InitRoleInfoList', hooked);
      if impl ~= mod then
        rawset(mod, 'InitRoleInfoList', hooked)
      end
      R.Hooks[path] = true;
      R.Status = 'hook_installed'
    end
  end
