  function F.getLocalChar()
    local cached, cachedAt = F._CharCache, F._CharCacheAt
    if cached and cachedAt then
      local t = (_G.RealNow and _G.RealNow()) or os.clock()
      if t - cachedAt < 0.2 then
        local okv, alive = pcall(slua.isValid, cached)
        if okv and alive == true then
          return cached
        end
        F._CharCache, F._CharCacheAt = nil, nil
      end
    end
    local GD = _G.OwenReq("GameLua.GameCore.Data.GameplayData")
    if not GD then
      F.LastCharSource = 'no_gamedata';
      return nil
    end
    local pc = nil
    local okp, value = pcall(GD.GetPlayerController)
    if okp then
      pc = value
    end
    local function done(c, source)
      F.LastCharSource = source F._CharCache, F._CharCacheAt = c, (_G.RealNow and _G.RealNow()) or os.clock()
      return c
    end
    if pc and slua.isValid(pc) then
      if type(pc.GetPlayerCharacterSafety) == 'function' then
        local okc, c = pcall(pc.GetPlayerCharacterSafety, pc)
        if okc and c and slua.isValid(c) then
          return done(c, 'pc_safety')
        end
      end
      if type(pc.GetCurPlayerCharacter) == 'function' then
        local okc, c = pcall(pc.GetCurPlayerCharacter, pc)
        if okc and c and slua.isValid(c) then
          return done(c, 'pc_cur')
        end
      end
    end
    if type(GD.GetLocalCharacter) == 'function' then
      local okl, c = pcall(GD.GetLocalCharacter)
      if okl and c and slua.isValid(c) then
        return done(c, 'gd_local')
      end
    end
    local okc, c = pcall(GD.GetPlayerCharacter)
    if okc and c and slua.isValid(c) then
      return done(c, 'gd_char')
    end
    F.LastCharSource = pc and slua.isValid(pc) and 'pc_no_pawn' or 'no_controller'
    return nil
  end
