  function F.getDesiredOutfit()
    local slots = PERSIST.configSlots or {}
    if tonumber(slots.tshirt) and tonumber(slots.tshirt) > 0 then
      return nil
    end
    if tonumber(slots.outfit) and tonumber(slots.outfit) > 0 then
      return tonumber(slots.outfit)
    end
    if MATCH_CONFIG.outfitRes and MATCH_CONFIG.outfitRes > 0 then
      return MATCH_CONFIG.outfitRes
    end
    local wornSuitRes pcall(function()
      local _, res = F.findWornInsBySubType(OUTFIT_SUB, function(r)
        return F.isSuitRes(r)
      end)
      wornSuitRes = tonumber(res)
    end)
    if wornSuitRes and wornSuitRes > 0 then
      return wornSuitRes
    end
    local tshirtWorn = false pcall(function()
      local ins = F.findWornInsBySubType(OUTFIT_SUB, function(r)
        return F.isTshirtRes(r)
      end)
      tshirtWorn = ins ~= nil
    end)
    if tshirtWorn then
      return nil
    end
    F.syncBodyCacheFromLobby()
    local c = F.cache()
    if c.outfitRes and tonumber(c.outfitRes) > 0 then
      return tonumber(c.outfitRes)
    end
    local pr = PERSIST.configSlots and tonumber(PERSIST.configSlots.outfit)
    if pr and pr > 0 then
      return pr
    end
    return tonumber(_G.AddOutfitLastLobbyOutfitRes) or nil
  end
  function F.matchApplyOutfit(char)
    local outfitRes = F.getDesiredOutfit()
    if not outfitRes then
      return true
    end
    if not F.isResourcesReady(outfitRes) then
      F.requestResourceDownload(outfitRes)
      return false
    end
    local comp = F.getAvatarComp2(char)
    if not comp then
      return false
    end
    local ok = F.setMakeSkin(comp, outfitRes, F.CUST_SLOT.ClothesEquipemtSlot, { allowPutOn = true })
    return ok
  end
  function F.getDesiredHat()
