  function F.matchApplyFaceWear(char)
    if F.skinOff() or not F.isInRealMatch() then
      return false
    end
    local maskRes = F.getDesiredMask()
    local glassRes = F.getDesiredGlass()
    local assetsReady = true
    for _, id in pairs( { maskRes, glassRes }) do
      if tonumber(id) and tonumber(id) > 0 and not F.isResourcesReady(id) then
        F.requestResourceDownload(id);
        assetsReady = false
      end
    end
    if not assetsReady then
      return false
