    end
    local comp = F.getAvatarComp2(char)
    if not comp then
      return false
    end
    local ok, changed = false, false pcall(function()
      local EAvatarSlotType = import("EAvatarSlotType")
      local ESyncOperation = import("ESyncOperation")
      local net = comp.NetAvatarData
      local applyData = net and net.SlotSyncData
      local function forceApplySlot(resID, slotID, slotNameStr)
        if not resID or resID <= 0 then
          return
        end
        local slotEnum = EAvatarSlotType and EAvatarSlotType[slotNameStr]
        local needRep = false
        if applyData and slua.isValid(applyData) then
          local found = false
          for i = 0, applyData:Num() - 1 do
            local equipment = applyData:Get(i)
            if equipment and equipment.SlotID == slotID then
              found = true
              local cur = tonumber(equipment.ItemId) or tonumber(equipment.ItemID) or 0
              if cur ~= resID then
                F.ensureSkinDownload(resID)
                equipment.ItemId = resID
                if equipment.ItemID ~= nil then
                  equipment.ItemID = resID
                end
                if equipment.FakeItemID ~= nil then
                  equipment.FakeItemID = resID
                end
                applyData:Set(i, equipment)
                needRep = true
              end
              break
            end
          end
          if not found then
            F.ensureSkinDownload(resID)
            local entry = import("AvatarSyncData")()
            entry.SlotID = slotID
            entry.ItemId = resID
            entry.ItemID = resID
            entry.FakeItemID = resID
            entry.OperationType = ESyncOperation.PutOn applyData:Add(entry)
            needRep = true
          end
        end
        _G.FaceWearStateCache = _G.FaceWearStateCache or setmetatable( {}, { __mode = "k" })
        local compCache = _G.FaceWearStateCache[comp]
        if type(compCache) ~= "table" then
          compCache = {};
          _G.FaceWearStateCache[comp] = compCache
        end
        local cacheKey = slotID
        if needRep or compCache[cacheKey] ~= resID then
          if slotEnum then
            if comp.CancelHideAvatarBySlot then
              comp:CancelHideAvatarBySlot(slotEnum)
            end
            if comp.SetAvatarVisibility then
              comp:SetAvatarVisibility(slotEnum, true, true)
            end
          end
          if comp.PutOnCustomEquipmentByID then
            comp:PutOnCustomEquipmentByID(resID)
          end
          compCache[cacheKey] = resID
          ok = true;
          changed = true
        else
          if slotEnum and comp.CancelHideAvatarBySlot then
            comp:CancelHideAvatarBySlot(slotEnum)
          end
          ok = true
        end
      end
      forceApplySlot(maskRes, F.CUST_SLOT.FaceEquipemtSlot, "EAvatarSlotType_FaceEquipemtSlot")
      forceApplySlot(glassRes, F.CUST_SLOT.GlassEquipemtSlot, "EAvatarSlotType_GlassEquipemtSlot")
      if changed and comp.OnRep_BodySlotStateChanged then
        comp:OnRep_BodySlotStateChanged()
      end
    end)
    return ok
  end
  _G.OwenGloveCatalog = {
    Items = {},
    ByRes = {},
    Scanned = false,
    Error = nil,
    Count = 0
  }
  function _G.OwenGloveCatalog.Scan(force)
    local C = _G.OwenGloveCatalog
    if C.Scanned and not force then
      return C.Count
    end
    C.Scanned = true;
    C.Items = {};
    C.ByRes = {};
    C.Count = 0;
    C.Error = nil
    local cdt = rawget(_G, 'CDataTable')
    if not cdt then
      C.Scanned = false;
      C.Error = 'no_cdatatable';
      return 0
    end
    local rows = nil
    if type(cdt.GetTableByFilter) == 'function' then
      local ok, value = pcall(cdt.GetTableByFilter, 'Item', 'ItemSubType', 452)
      if ok and type(value) == 'table' then
        rows = value
      end
    end
    if not rows and type(cdt.GetTableByFilter) == 'function' then
      local ok, value = pcall(cdt.GetTableByFilter, 'Item', 'SubType', 452)
      if ok and type(value) == 'table' then
        rows = value
      end
    end
    if not rows then
      C.Scanned = false;
      C.Error = 'filter_unavailable';
      return 0
    end
    local function num(v)
      v = tonumber(v)
      if v and v > 0 then
        return v
      end
    end
    for key, row in pairs(rows) do
      local res = num(row and (row.ID or row.Id or row.ItemID)) or num(key)
      if res then
        local name = row and (row.ItemName or row.Name) or nil
        local quality = row and num(row.Quality) or 0
        local entry = { Res = res, Name = (type(name) == 'string' and name ~= '') and name or tostring(res),
        Quality = quality }
        C.Items[ # C.Items + 1] = entry
        C.ByRes[res] = entry
      end
    end
    table.sort(C.Items, function(a, b)
      if a.Quality ~= b.Quality then
        return a.Quality > b.Quality
      end
      return a.Res < b.Res
    end)
    C.Count = # C.Items
    if C.Count == 0 then
      C.Scanned = false;
      C.Error = 'no_glove_rows'
    end
    return C.Count
  end
  function _G.OwenGloveCatalog.Get(index)
    local C = _G.OwenGloveCatalog
    if not C.Scanned then
      C.Scan()
    end
    index = tonumber(index) or 0
    if index < 1 or index > C.Count then
      return nil
    end
    return C.Items[index]
  end
  _G.OwenWardrobeGloves = {
    Enabled = true,
    Limit = 60,
    Injected = 0,
    LastError = nil,
    Patched = false,
    Completed = setmetatable( {}, { __mode = 'k' })
  }
  function _G.OwenWardrobeGloves.Inject(entity)
    local W = _G.OwenWardrobeGloves
    if not W.Enabled or not F.lobbyWorkAllowed() then
      return 0
    end
    if not entity or type(entity.AddData) ~= 'function' then
      W.LastError = 'no_entity';
      return 0
    end
    if W.Completed[entity] then
      return 0
    end
    local catalog = _G.OwenGloveCatalog
    if not catalog then
      W.LastError = 'no_catalog';
      return 0
    end
    catalog.Scan()
    if catalog.Count <= 0 then
      W.LastError = 'empty_catalog';
      return 0
    end
    local index = entity.ResIDToIndexArrayMap
    local count, added, failed = 0, 0, false
    for i = 1, catalog.Count do
      if added >= W.Limit then
        break
      end
      local entry = catalog.Items[i]
      local res = entry and tonumber(entry.Res)
      if res and res > 0 then
        local known = index and index[res]
        if not known or (type(known) == 'table' and next(known) == nil) then
          local now = tonumber(os.time()) or 0
          local insID = (now * 4294967296) + ((W.Sequence or 0) + 1)
          W.Sequence = (W.Sequence or 0) + 1
          local ok, result = pcall(entity.AddData, entity, { instid = insID, res_id = res, count = 1,
          lock_cnt = 0, isnew = 0, valid_hours = 0, expire_ts = 0, color = 0, pattern = 0 })
          if ok and result ~= false then
            added = added + 1
          else
            failed = true
          end
        end
        count = count + 1
      end
    end
    W.Injected = added
    if not failed and count == catalog.Count then
      W.Completed[entity] = true
    end
    if added > 0 then
      W.LastError = nil
    else
      W.LastError = 'already_present'
    end
    return added
  end
  function _G.OwenWardrobeGloves.Install()
    local W = _G.OwenWardrobeGloves
    if W.Patched then
      return true
    end
    local ok, module = pcall(require, 'client.slua.logic.wardrobe.wardrobe_data')
    if not ok or type(module) ~= 'table' then
      W.LastError = 'module_unavailable';
      return false
    end
    local patched = false
    for _, name in ipairs( { 'GetArrayHallDepotItemInfo', 'GetArrayHallDepotItemInfo_Emote', 'GetHallDepotItemListByResID',
    'GetHallDepotItemDataByResID' }) do
      local original = rawget(module, name)
      if type(original) == 'function' and not rawget(module, '_OwenOrig_' .. name) then
        rawset(module, '_OwenOrig_' .. name, original)
        rawset(module, name, function( ...)
          pcall(_G.OwenWardrobeGloves.ApplyNow)
          return original( ...)
        end)
        patched = true
      end
    end
    if not patched then
      W.LastError = 'read_path_missing';
      return false
    end
    W.Patched = true
    W.LastError = nil
    return true
  end
  function _G.OwenWardrobeGloves.ApplyNow()
    local W = _G.OwenWardrobeGloves
    if not W.Enabled or not F.lobbyWorkAllowed() then
      return 0
    end
    local now = _G.RealNow()
    if now < (W.NextAttempt or 0) then
      return 0
    end
    W.NextAttempt = now + 1
    local ok, center = pcall(require, 'client.slua.logic.wardrobe.logic_wardrobe_data_center')
    if not ok or type(center) ~= 'table' or type(center.GetWardrobeData) ~= 'function' then
      W.LastError = 'center_unavailable';
      return 0
    end
    local got, entity = pcall(center.GetWardrobeData)
    if not got or not entity then
      W.LastError = 'entity_unavailable';
      return 0
    end
    return _G.OwenWardrobeGloves.Inject(entity)
  end
