  function F.getDesiredWear(configKey, cacheResKey, globalKey, syncFn)
    if configKey == 'glovesRes' and F.lobbyWorkAllowed() then
      local W = _G.OwenWardrobeGloves
      if W and W.Enabled and not W.Patched then
        pcall(W.Install)
      end
      if W and W.Enabled and W.Patched then
        pcall(W.ApplyNow)
      end
    end
    local fixed = MATCH_CONFIG[configKey] and tonumber(MATCH_CONFIG[configKey])
    if fixed and fixed > 0 then
      return fixed
    end
    local persistKey = cacheResKey and cacheResKey:gsub("Res$", "")
    if persistKey and PERSIST.configSlots then
      local pr = tonumber(PERSIST.configSlots[persistKey])
      if pr and pr > 0 then
        return pr
      end
    end
    if syncFn then
      syncFn()
    end
    local v = F.cache()[cacheResKey]
    if v and tonumber(v) > 0 then
      return tonumber(v)
    end
    return tonumber(_G[globalKey]) or nil
  end
  local EQUIP_APPLY = {
    lastBagWrite = 0,
    lastHelmetWrite = 0,
    Next = 0,
    Slots = {},
    Mappings = {},
    Busy = setmetatable( {}, { __mode = 'k' })
  }
  F.EquipmentSkinState = EQUIP_APPLY
  function F.levelSkinID(baseSkin, level)
    baseSkin, level = tonumber(baseSkin), tonumber(level)
    if not baseSkin or baseSkin <= 0 or not level or level < 1 or level > 3 or level % 1 ~= 0 then
      return 0
    end
    local key = tostring(baseSkin) .. ':' .. level
    if EQUIP_APPLY.Mappings[key] then
      return EQUIP_APPLY.Mappings[key]
    end
    local base = F.cfg(baseSkin);
    local subtype = base and tonumber(F.subType(base))
    local bag = subtype and BAG_SUBS[subtype];
    local helmet = subtype and HELMET_SUBS[subtype]
    if not bag and not helmet then
      return 0
    end
    local function valid(id)
      id = tonumber(id);
      if not id or id <= 0 then
        return nil
      end
      local cfg = F.cfg(id);
      local st = cfg and tonumber(F.subType(cfg))
      if st and ((bag and BAG_SUBS[st]) or (helmet and HELMET_SUBS[st])) then
        return id
      end
    end
    local field = ( { 'SkinItemIDLv1', 'SkinItemIDLv2', 'SkinItemIDLv3' })[level]
    local ok, row = pcall(CDataTable.GetTableData, 'BackpackMapping', baseSkin)
    local mapped = ok and row and valid(row[field])
    if not mapped then
      local family = F.NeonEquipmentFamilies and F.NeonEquipmentFamilies[baseSkin]
      mapped = family and valid(family[level])
    end
    if not mapped and type(CDataTable.GetTableDataByFilter) == 'function' then
      for _, column in ipairs( { 'SkinID', 'SkinItemIDLv1', 'SkinItemIDLv2', 'SkinItemIDLv3' }) do
        local found, value = pcall(CDataTable.GetTableDataByFilter, 'BackpackMapping', column, baseSkin)
        if found and value then
          mapped = valid(value[field]);
          if mapped then
            break
          end
        end
      end
    end
    if mapped then
      EQUIP_APPLY.Mappings[key] = mapped;
      return mapped
    end
    return 0
  end
  function F.noteEquipmentSkin(name, status, selected, target, level, physical)
    local row = EQUIP_APPLY.Slots[name] or {};
    EQUIP_APPLY.Slots[name] = row
    local signature = table.concat( { status, tostring(selected), tostring(target), tostring(level),
    tostring(physical) }, ':')
    row.Status, row.Selected, row.Target, row.Level, row.PhysicalID = status, selected, target, level, physical
    if row.Signature ~= signature then
      row.Signature = signature
      local audit = rawget(_G, 'OwenSkinAudit')
      if audit and type(audit.Equipment) == 'function' then
        pcall(audit.Equipment, name, status, target, level)
      end
    end
    return row
  end
