  function F.metroRestoreValue(comp, slot, saved)
    local enums = import('EAvatarSlotType')
    local flag
    if slot == enums.EAvatarSlotType_HelmetEquipemtSlot then
      flag = comp.bReplaceHighLvHelmet
    elseif slot == enums.EAvatarSlotType_BackpackEquipemtSlot then
      flag = comp.bReplaceHighLvBackpack
    end
    if flag ~= true and flag ~= 1 then
      return saved.Input or saved.Physical
    end
    return saved.Original
