  function F.restoreMetroEquipmentSlot(comp, slot)
    local rows = F.MetroEquipmentState.Owned[comp]
    local saved = rows and rows[slot]
    if not saved then
      return true
    end
    if not slua.isValid(comp) then
      F.MetroEquipmentState.Owned[comp] = nil;
      return true
    end
    local ok, restored = pcall(function()
      local sync = comp:GetSlotSyncData(slot)
      if not sync or tonumber(sync.AdditionalItemID) ~= saved.Physical or tonumber(sync.ItemID) ~= saved.Applied then
        return true
      end
      local current = sync.ItemID;
      sync.ItemID = F.metroRestoreValue(comp, slot, saved)
      local changed, result = pcall(comp.ChangeSlotSyncData, comp, sync)
      if not changed or result == false then
        sync.ItemID = current;
        return false
      end
      return true
    end)
    if ok and restored then
      rows[slot] = nil
      if not next(rows) then
        F.MetroEquipmentState.Owned[comp] = nil
      end
      return true
    end
    return false
  end
  function F.restoreMetroEquipmentOverrides()
    for comp, rows in pairs(F.MetroEquipmentState.Owned) do
      local slots = {};
      for slot in pairs(rows) do
        slots[ # slots + 1] = slot
      end
      for _, slot in ipairs(slots) do
        F.restoreMetroEquipmentSlot(comp, slot)
      end
    end
  end
  function F.metroEquipmentTarget(comp, slot, physical, bSelf)
    if not (bSelf == true or bSelf == 1) or F.skinOff() or not F.isInRealMatch() or not F.isLocalEquipmentComp(comp) then
      return nil
    end
    local enums = import('EAvatarSlotType');
    local utils = import('BackpackUtils')
    local kind, level, selected
    if slot == enums.EAvatarSlotType_HelmetEquipemtSlot then
      if comp.bReplaceHighLvHelmet ~= true and comp.bReplaceHighLvHelmet ~= 1 then
        return nil
      end
      kind = 'helmet';
      level = utils.GetEquipmentHelmetLevel(physical)
      selected = F.getDesiredWear('helmetRes', 'helmetRes', 'AddOutfitLastLobbyHelmetRes', F.syncBodyCacheFromLobby)
    elseif slot == enums.EAvatarSlotType_BackpackEquipemtSlot then
      if comp.bReplaceHighLvBackpack ~= true and comp.bReplaceHighLvBackpack ~= 1 then
        return nil
      end
      kind = 'bag';
      level = utils.GetEquipmentBagLevel(physical)
      selected = F.getDesiredWear('bagRes', 'bagRes', 'AddOutfitLastLobbyBagRes', F.syncBodyCacheFromLobby)
    else
      return nil
    end
    level = tonumber(level);
    selected = tonumber(selected)
    if not level or level <= 3 or level > 32 or level % 1 ~= 0 or not selected or selected <= 0 then
      return nil
    end
    local target = F.levelSkinID(selected, 3)
    if target <= 0 then
      return nil
    end
    if not F.isResourcesReady(target) then
      F.requestResourceDownload(target);
      return nil
    end
    return target, kind
  end
  function F.bindMetroEquipmentHooks(comp)
    if type(comp) ~= 'table' then
      return
    end
    for _, row in pairs(F.MetroEquipmentState.Hooks) do
      for key, entry in pairs(row) do
        local cached = rawget(comp, key)
        if cached == entry.Original then
          rawset(comp, key, entry.Wrapper)
        end
      end
