  end
  function F.installMetroEquipmentHooks()
    local ok, module = pcall(require, 'GameLua.Mod.TPlan.Component.MetroCharacterAvatarComponent')
    if not ok or type(module) ~= 'table' then
      F.MetroHookStatus = 'module_unavailable';
      return false
    end
    local impl = rawget(module, '__inner_impl') or module
    local registry = F.MetroEquipmentState.Hooks
    local rows = registry[impl] or {};
    registry[impl] = rows
    local function install(key, kind)
      local original = rawget(impl, key) or module[key]
      if type(original) ~= 'function' then
        return false
      end
      local old = rows[key]
      if old and old.Wrapper == original then
        rawset(module, key, original);
        return true
      end
      local function pack( ...)
        return { n = select('#', ...), ... }
      end
      local unpackValues = table.unpack or unpack
      local wrapper = function(self, ...)
        local results = pack(original(self, ...))
        local current = rawget(_G, 'AddOutfit')
        if kind == 'target' then
          local slot, skin, physical, team, bSelf = ...
          if current and current.metroEquipmentTarget then
            pcall(function()
              local target = current.metroEquipmentTarget(self, slot, physical, bSelf)
              local state = current.MetroEquipmentState
              local owned = state.Owned[self]
              local saved = owned and owned[slot]
              if target and tonumber(results[1]) and tonumber(results[1]) > 0 then
                if not owned then
                  owned = {};
                  state.Owned[self] = owned
                end
                if not saved or saved.Physical ~= tonumber(physical) then
                  saved = { Original = tonumber(results[1]), Input = tonumber(skin), Physical = tonumber(physical) };
                  owned[slot] = saved
                else
                  if tonumber(results[1]) ~= saved.Applied then
                    saved.Original = tonumber(results[1])
                  end
                  if tonumber(skin) ~= saved.Applied then
                    saved.Input = tonumber(skin)
                  end
                end
                saved.Applied = target;
                results[1] = target
              elseif saved and saved.Physical == tonumber(physical) then
                if tonumber(results[1]) == saved.Applied then
                  results[1] = current.metroRestoreValue(self, slot, saved)
                end
                owned[slot] = nil;
                if not next(owned) then
                  state.Owned[self] = nil
                end
              end
            end)
          end
        elseif current and current.EquipmentSkinState then
          pcall(function()
            if current.isLocalEquipmentComp(self) then
              current.EquipmentSkinState.Next = 0
            end
          end)
        end
        return unpackValues(results, 1, results.n)
      end
      rawset(impl, key, wrapper);
      rawset(module, key, wrapper)
      rows[key] = { Original = original, Wrapper = wrapper }
      return true
    end
    local target = install('GetReplaceHighLvEquipmentAvatar', 'target')
    local rectify = install('ProcessClientAvatarRectify', 'rectify')
    F.MetroHookStatus = target and rectify and 'installed' or 'partial' rawset(module, '_OwenEquipmentRectifyWrapper', rows.ProcessClientAvatarRectify and rows.ProcessClientAvatarRectify.Wrapper)
    return target and rectify
  end
  function F.applyEquipSkinToComp(comp, bagRes, helmetRes)
    if F.skinOff() or not F.isInRealMatch() or not comp or not slua.isValid(comp) or not F.isLocalEquipmentComp(comp) then
      return false, false, false
    end
    if EQUIP_APPLY.Busy[comp] then
      return false, false, false
    end
    local imported, slots, utils, putOn = pcall(function()
      local operation = import('ESyncOperation')
      return import('EAvatarSlotType'), import('BackpackUtils'), tonumber(operation.PutOn) or 0
    end)
    if not imported then
      return false, false, false
    end
    local metro = F.isMetroEquipmentComp(comp)
    if metro then
      if F.MetroHookStatus ~= 'installed' then
        pcall(F.installMetroEquipmentHooks)
      end
      F.bindMetroEquipmentHooks(comp)
      if comp.bLocalSettingReplace ~= true and comp.bLocalSettingReplace ~= 1 and type(comp.InitLocalSettingReplace) == 'function' then
        pcall(comp.InitLocalSettingReplace, comp)
      end
    end
    EQUIP_APPLY.Busy[comp] = true
    local applied, found, ready = false, false, true
    local now = (_G.RealNow and _G.RealNow()) or os.clock()
    local function doSlot(name, slot, res, levelFn)
      res = tonumber(res) or 0
      if res <= 0 then
        if metro then
          F.restoreMetroEquipmentSlot(comp, slot)
        end
        F.noteEquipmentSkin(name, 'not_selected');
        return
      end
      local sync = slot and comp.GetSlotSyncData and comp:GetSlotSyncData(slot)
      if not sync then
        F.noteEquipmentSkin(name, 'slot_pending', res);
        ready = false;
        return
      end
      local cur = tonumber(sync.ItemID) or 0
      local physical = tonumber(sync.AdditionalItemID) or 0
      if name == 'helmet' and physical <= 0 then
        local row = F.noteEquipmentSkin(name, 'no_physical_helmet', res);
        row.RequestKey = nil;
        return
      end
      if tonumber(sync.OperationType) ~= putOn or (cur <= 0 and physical <= 0) then
        local row = F.noteEquipmentSkin(name, 'not_equipped', res);
        row.RequestKey = nil;
        return
      end
      found = true
      local level
      if type(levelFn) == 'function' then
        local ok, value = pcall(levelFn, physical > 0 and physical or cur)
        if ok then
          level = tonumber(value)
        end
      end
      if not level or level <= 0 then
        local family = F.NeonEquipmentFamilies and F.NeonEquipmentFamilies[cur]
        if family then
          for n = 1, 3 do
            if tonumber(family[n]) == cur then
              level = n;
              break
            end
          end
        end
      end
      if not level or level ~= level or level < 1 or level > 32 or level % 1 ~= 0 then
        F.noteEquipmentSkin(name, 'equipment_level_unavailable', res, nil, nil, physical);
        ready = false;
        return
      end
      if metro and level > 3 then
        local flag
        if name == 'helmet' then
          flag = comp.bReplaceHighLvHelmet
        else
          flag = comp.bReplaceHighLvBackpack
        end
        if flag ~= true and flag ~= 1 then
          if not F.restoreMetroEquipmentSlot(comp, slot) then
            ready = false
          end
          F.noteEquipmentSkin(name, 'metro_native_high_level', res, nil, level, physical);
          return
        end
      end
      local target = F.levelSkinID(res, math.min(level, 3))
      if target <= 0 then
        F.noteEquipmentSkin(name, 'mapping_unavailable', res, nil, level, physical);
        ready = false;
        return
      end
      if not F.isResourcesReady(target) then
        F.requestResourceDownload(target)
        F.noteEquipmentSkin(name, 'resource_pending', res, target, level, physical);
        ready = false;
        return
      end
      local meshOK = true
      if type(comp.GetMeshCompBySlot) == 'function' then
        local ok, mesh = pcall(comp.GetMeshCompBySlot, comp, slot)
        meshOK = ok and mesh ~= nil and slua.isValid(mesh)
      end
      local row = EQUIP_APPLY.Slots[name] or {};
      EQUIP_APPLY.Slots[name] = row
      local requestKey = tostring(comp) .. ':' .. res .. ':' .. physical .. ':' .. level .. ':' .. target
      if row.RequestKey ~= requestKey then
        row.RequestKey = requestKey;
        row.Attempts = 0;
        row.NextRequest = 0
      end
      if cur == target and meshOK then
        row.Attempts = 0;
        F.noteEquipmentSkin(name, 'active', res, target, level, physical);
        return
      end
      if cur == target and (now < (row.NextRequest or 0) or (row.Attempts or 0) >= 3) then
        F.noteEquipmentSkin(name, 'mesh_pending', res, target, level, physical);
        ready = false;
        return
      end
      if metro and level > 3 then
        if now < (row.NextRequest or 0) or (row.Attempts or 0) >= 3 then
          ready = false;
          return
        end
        row.Attempts = (row.Attempts or 0) + 1;
        row.NextRequest = now + 1.5
        local called = false
        if F.MetroHookStatus == 'installed' and type(comp.ProcessClientAvatarRectify) == 'function' then
          called = pcall(comp.ProcessClientAvatarRectify, comp)
        end
        local after = comp.GetSlotSyncData and comp:GetSlotSyncData(slot)
        local active = called and after and tonumber(after.ItemID) == target F.noteEquipmentSkin(name, active and 'metro_active' or 'metro_native_pending', res, target, level, physical)
        applied = applied or active;
        ready = ready and active
        return
      end
      if type(comp.ChangeSlotSyncData) ~= 'function' then
        F.noteEquipmentSkin(name, 'slot_update_api_unavailable', res, target, level, physical);
        ready = false;
        return
      end
      row.Attempts = (row.Attempts or 0) + 1;
      row.NextRequest = now + 1.5
      sync.ItemID = target
      local changed, value = pcall(comp.ChangeSlotSyncData, comp, sync)
      if not changed or value == false then
        sync.ItemID = cur F.noteEquipmentSkin(name, 'slot_update_failed', res, target, level, physical);
        ready = false;
        return
      end
      applied = true
      EQUIP_APPLY[name == 'bag' and 'lastBagWrite' or 'lastHelmetWrite'] = target F.noteEquipmentSkin(name, 'apply_requested', res, target, level, physical)
      ready = false
    end
    for _, task in ipairs( {
{ 'bag', slots.EAvatarSlotType_BackpackEquipemtSlot, bagRes, utils.GetEquipmentBagLevel },
{ 'helmet', slots.EAvatarSlotType_HelmetEquipemtSlot, helmetRes, utils.GetEquipmentHelmetLevel }
    }) do
      local ok = pcall(doSlot, task[1], task[2], task[3], task[4])
      if not ok then
        F.noteEquipmentSkin(task[1], 'lua_error', tonumber(task[3]));
        ready = false
      end
    end
    EQUIP_APPLY.Busy[comp] = nil
    return applied, found, ready
  end
  function F.matchApplyEquipmentSkin(char, bagRes, helmetRes)
    if F.skinOff() or not char or not slua.isValid(char) then
      return false
    end
    bagRes, helmetRes = tonumber(bagRes) or 0, tonumber(helmetRes) or 0
    if bagRes <= 0 and helmetRes <= 0 then
      return true
    end
    local comp = F.getAvatarComp2(char)
    if not comp or not slua.isValid(comp) then
      return false
    end
    local applied, found, ready = F.applyEquipSkinToComp(comp, bagRes, helmetRes)
    if applied and type(comp.OnRep_BodySlotStateChanged) == 'function' then
      pcall(comp.OnRep_BodySlotStateChanged, comp)
    end
    return ready == true
  end
  function F.tickEquipmentSkins(char)
    if F.skinOff() then
      EQUIP_APPLY.Next = 0;
      EQUIP_APPLY.Owner = nil;
      return
    end
    local now = (_G.RealNow and _G.RealNow()) or os.clock()
    if now < EQUIP_APPLY.Next then
      return
    end
    if not F.isInRealMatch() then
      EQUIP_APPLY.Next = 0;
      EQUIP_APPLY.Owner = nil;
      return
    end
    EQUIP_APPLY.Next = now + 1.5
    char = char or F.getLocalChar()
    if not char or not slua.isValid(char) then
      return
    end
    if EQUIP_APPLY.Owner ~= char then
      EQUIP_APPLY.Owner = char;
      EQUIP_APPLY.Slots = {}
    end
    local bag = F.getDesiredWear('bagRes', 'bagRes', 'AddOutfitLastLobbyBagRes', F.syncBodyCacheFromLobby)
    local helmet = F.getDesiredWear('helmetRes', 'helmetRes', 'AddOutfitLastLobbyHelmetRes', F.syncBodyCacheFromLobby)
    F.matchApplyEquipmentSkin(char, bag, helmet)
  end
  function F.markEquipDirty()
    F.EquipDirty = true
    EQUIP_APPLY.Next = 0
    F.GlovePollNext = 0
    if F.GloveLOD then
      F.GloveLOD.Next = 0
    end
    local now = (_G.RealNow and _G.RealNow()) or os.clock()
    if now >= (F._InjectDirtyGuard or 0) then
      F.NeonInjectDirty = true
      F._InjectDirtyGuard = now + 3
    end
  end
  function F.installEquipEventBridge()
    if F._EquipBridge then
      return true
    end
    local now = (_G.RealNow and _G.RealNow()) or os.clock()
    if now < (F._EquipBridgeNext or 0) then
      return false
    end
    F._EquipBridgeNext = now + 2 pcall(function()
      if EventSystem and type(EventSystem.registEvent) == 'function' and EVENTTYPE_WARDROBE and EVENTID_WARDROBE_UPDATE_PUT_ON_DATA then
        EventSystem:registEvent(EVENTTYPE_WARDROBE, EVENTID_WARDROBE_UPDATE_PUT_ON_DATA, F.markEquipDirty)
        F._EquipBridge = true
      end
    end)
    return F._EquipBridge == true
  end
  function F.hookEquipmentRectify()
    return F.installMetroEquipmentHooks()
  end
  function F.applyMatchGlider(comp, res, freeFall)
    local slot = F.CUST_SLOT.GlideEquipemtSlot pcall(function()
      slot = import('EAvatarSlotType').EAvatarSlotType_GlideEquipemtSlot or slot
    end)
    local function equipped()
      local id pcall(function()
        if comp.GetEquippedItemDefineID3 then
          local item = comp:GetEquippedItemDefineID3(slot);
          id = item and tonumber(item.TypeSpecificID)
        end
        if not id or id <= 0 then
          local sync = comp.GetSlotSyncData and comp:GetSlotSyncData(slot)
          id = sync and (tonumber(sync.ItemID) or tonumber(sync.ItemId))
        end
      end)
      return id
    end
    local id = equipped()
    if id ~= res then
      if F.patchWearNetAvatar then
        pcall(F.patchWearNetAvatar, comp, res, 'EAvatarSlotType_GlideEquipemtSlot', true)
      end
      if comp.PutOnCustomEquipmentByID then
        local ok, result = pcall(comp.PutOnCustomEquipmentByID, comp, res)
        if not ok or result == false then
          return false
        end
      end
      id = equipped()
    end
    if id ~= res then
      return false
    end
    if freeFall then
      local ok, mesh = pcall(function()
        return comp.GetMeshCompBySlot and comp:GetMeshCompBySlot(slot)
      end)
      if not ok or not mesh or not slua.isValid(mesh) then
        return false
      end
      if mesh.bVisible ~= true and mesh.bVisible ~= 1 then
        if not comp.SetAvatarVisibility then
          return false
        end
        local shown = pcall(comp.SetAvatarVisibility, comp, slot, true, true)
        if not shown then
          return false
        end
        if mesh.bVisible ~= true and mesh.bVisible ~= 1 then
          return false
        end
      end
    end
    return true
  end
  function F.applyAirborneSlots(char, forceInAir)
    if not F.isCharacterAirborne(char) then
      return false
    end
    if not F.isInRealMatch() then
      return false
    end
    if F.skinOff() or not char or not slua.isValid(char) then
      return false
    end
    local comp = F.getAvatarComp2(char)
    if not comp or not slua.isValid(comp) then
      return false
    end
    F._airborneCosmeticState = F._airborneCosmeticState or setmetatable( {}, { __mode = 'k' })
    local record = F._airborneCosmeticState[comp] or {};
    F._airborneCosmeticState[comp] = record
    local inAir = forceInAir == true or F.isCharacterAirborne(char)
    local phase = char.ParachuteState
    local freeFall = false pcall(function()
      freeFall = phase == import("EParachuteState").PS_FreeFall
    end)
    local any = false
    local function apply(res, slot, key)
      res = tonumber(res);
      if not res or res <= 0 then
        return
      end
      any = true
      if not F.isResourcesReady(res) then
        F.requestResourceDownload(res, function()
          if not F.skinOff() and F.isInRealMatch() and char == F.getLocalChar() and F.isCharacterAirborne(char) then
            F.applyAirborneSlots(char, true)
          end
        end)
        return
      end
      if key ~= 'Glider' and record[key] == res and record.Phase == phase and record.InAir == inAir then
        return
      end
      local now = _G.RealNow()
      local attempt = record[key .. 'Attempt']
      if attempt and attempt.ID == res and attempt.Phase == phase and now < attempt.Next then
        return
      end
      record[key .. 'Attempt'] = { ID = res, Phase = phase, Next = now + 0.5 }
      local applied = false
      if tonumber(F.subType(F.cfg(res))) == 415 then
        if comp.PutOnCustomEquipmentByID then
          if F.patchWearNetAvatar then
            F.patchWearNetAvatar(comp, res, 'EAvatarSlotType_GlideEquipemtSlot', true)
          end
          local ok, result = pcall(comp.PutOnCustomEquipmentByID, comp, res);
          applied = ok and result ~= false
          if _G.OwenMatchCosmeticDiagnostics then
            local entry = _G.OwenMatchCosmeticDiagnostics.glideSmoke or {};
            _G.OwenMatchCosmeticDiagnostics.glideSmoke = entry
            entry.ID = res;
            entry.Status = 'native_equip_requested'
          end
        end
      elseif key == 'Glider' then
        applied = F.applyMatchGlider(comp, res, freeFall)
      else
        applied = F.setMakeSkin(comp, res, slot, { inAir = inAir, allowPutOn = true })
      end
      if applied then
        record[key] = res
      end
    end
    apply(F.getDesiredParachuteRes(), F.CUST_SLOT.ParachuteEquipemtSlot, 'Parachute')
    apply(F.getDesiredGliderRes(), F.CUST_SLOT.GlideEquipemtSlot, 'Glider')
    record.InAir = inAir;
    record.Phase = phase
    return any
  end
  function F.stopAirborneCosmetics()
    local state = F._airborneMaintenance
    F._airborneMaintenance = nil;
    F._airborneTickState = nil
    if state and state.Handle and state.Char and state.Char.RemoveGameTimer then
      pcall(state.Char.RemoveGameTimer, state.Char, state.Handle)
    end
  end
  function F.airborneCosmeticTick(char)
    if F.skinOff() or not F.isInRealMatch() or not char or not slua.isValid(char) or not F.isCharacterAirborne(char) then
      F.stopAirborneCosmetics();
      return false
    end
    local previous = F._airborneMaintenance
    if previous and previous.Char == char then
      return true
    end
    F.stopAirborneCosmetics()
    if F.syncAirborneToDataMgr then
      F.syncAirborneToDataMgr()
    end
    F.applyAirborneSlots(char, true)
    if type(char.AddGameTimer) ~= 'function' then
      return false
    end
    local state = { Char = char };
    F._airborneMaintenance = state
    local ok, handle = pcall(char.AddGameTimer, char, 0.5, true, function()
      if F._airborneMaintenance ~= state then
        return
      end
      if _G.AddOutfit ~= F or F.skinOff() or not F.isInRealMatch() or not slua.isValid(char) or char ~= F.getLocalChar() or not F.isCharacterAirborne(char) then
        F.stopAirborneCosmetics();
        return
      end
      F.applyAirborneSlots(char, true)
    end)
    if ok and handle ~= nil and handle ~= false then
      state.Handle = handle;
      return true
    end
    F._airborneMaintenance = nil;
    return false
  end
  function F.onAirbornePhaseChanged(char, phase)
    local localChar = F.getLocalChar()
    if char ~= localChar then
      local function identity(value)
        local ok, native = pcall(function()
          return value and value.Object
        end)
        return ok and native or value
      end
      if not localChar or identity(char) ~= identity(localChar) then
        return
      end
    end
    F._airbornePhaseRevision = (F._airbornePhaseRevision or 0) + 1
    if phase == EParachuteState.PS_None or phase == EParachuteState.PS_Landing then
      F.stopAirborneCosmetics();
      return
    end
    if F.isCharacterAirborne(localChar) then
      F.airborneCosmeticTick(localChar)
    elseif F.later then
      local revision = F._airbornePhaseRevision F.later(0, function()
        if revision == F._airbornePhaseRevision and localChar == F.getLocalChar() and F.isCharacterAirborne(localChar) then
          F.airborneCosmeticTick(localChar)
        end
      end)
    end
  end
  function F.matchApplyBodyWear(char)
    local pieces = {}
    if not F.getDesiredOutfit() then
      pieces[ # pieces + 1] = { F.getDesiredWear("tshirtRes", "tshirtRes", "AddOutfitLastLobbyTshirtRes", F.syncBodyCacheFromLobby),
      F.CUST_SLOT.ClothesEquipemtSlot, "Shirt", }
    end
    pieces[ # pieces + 1] = { F.getDesiredWear("pantsRes", "pantsRes", "AddOutfitLastLobbyPantsRes", F.syncBodyCacheFromLobby),
    F.CUST_SLOT.PantsEquipemtSlot, "Pants" }
    pieces[ # pieces + 1] = { F.getDesiredWear("shoesRes", "shoesRes", "AddOutfitLastLobbyShoesRes", F.syncBodyCacheFromLobby),
    F.CUST_SLOT.ShoesEquipemtSlot, "Shoes" }
    local any, okAll = false, true
    for _, p in ipairs(pieces) do
      local res, slot, label = p[1], p[2], p[3]
      if res and res > 0 then
        any = true
        okAll = F.matchApplyWearItem(char, res, slot, label) and okAll
      end
    end
    local anyAir = F.isCharacterAirborne(char) and F.applyAirborneSlots(char, true)
    if anyAir then
      any = true
    end
    local bagRes = F.getDesiredWear("bagRes", "bagRes", "AddOutfitLastLobbyBagRes", F.syncBodyCacheFromLobby)
    local helmetRes = F.getDesiredWear("helmetRes", "helmetRes", "AddOutfitLastLobbyHelmetRes", F.syncBodyCacheFromLobby)
    if (tonumber(bagRes) or 0) > 0 or (tonumber(helmetRes) or 0) > 0 then
      any = true
      okAll = F.matchApplyEquipmentSkin(char, bagRes, helmetRes) and okAll
    end
    local glovesOK = F.matchApplyGloves(char)
    return ( not any or okAll) and glovesOK
  end
  function F.gloveTransitionActive(char)
    if not char then
      return false
    end
    local now = _G.RealNow()
    local state = F.GloveADSState
    if not state or state.Char ~= char then
      state = { Char = char, Until = 0 };
      F.GloveADSState = state
    end
    local ok, ads = pcall(_G.OwenProbe.ADS, char)
    if ok and ads then
      state.Until = now + 0.5;
      return true
    end
    return now < state.Until
  end
  do
    local G = {
      Build = 'gloves-low-lod-v1',
      Rows = setmetatable( {}, { __mode = 'k' }),
      Next = 0,
      Status = 'idle'
    }
    F.GloveLOD = G
    local function readRaw(object, key)
      return object and object[key]
    end
    local function read(object, key)
      local ok, value = pcall(readRaw, object, key)
      if ok then
        return value
      end
    end
    local function valid(object)
      if object == nil then
        return false
      end
      local ok, value = pcall(slua.isValid, object);
      return ok and value == true
    end
    local function integer(value)
      local n = tonumber(value)
      if n and n == n and n >= 0 and n < 65536 and n % 1 == 0 then
        return n
      end
    end
    local function restoreMesh(mesh, row)
      if not valid(mesh) then
        return true
      end
      if integer(read(mesh, 'MinLodModel')) ~= row.Target then
        return true
      end
      local setter = read(mesh, 'SetMinLOD')
      if type(setter) ~= 'function' then
        return false
      end
      local currentOverride = read(mesh, 'bOverrideMinLOD')
      local ok = pcall(setter, mesh, row.OriginalMin)
      if not ok or integer(read(mesh, 'MinLodModel')) ~= row.OriginalMin then
        return false
      end
      if type(row.OriginalOverride) == 'boolean' and currentOverride == row.AppliedOverride then
        local written = pcall(function()
          mesh.bOverrideMinLOD = row.OriginalOverride
        end)
        if not written then
          return false
        end
      end
      return true
    end
    function G.Restore()
      local complete = true
      local started = os.clock()
      for mesh, row in pairs(G.Rows) do
        if restoreMesh(mesh, row) then
          G.Rows[mesh] = nil
        else
          complete = false
        end
        if os.clock() - started >= 0.003 then
          complete = false;
          break
        end
      end
      G.Status = complete and 'restored' or 'restore_pending';
      G.Next = 0
      return complete
    end
    function G.ApplyAvatar(comp, seen, owner)
      if not (_G.MWConfig.GraphicsCustomize == true or _G.MWConfig.GraphicsCustomize == 1) or not (_G.MWConfig.GraphicsGloveLOD == true or _G.MWConfig.GraphicsGloveLOD == 1) then
        return G.Restore()
      end
      if F.skinOff() or not valid(comp) then
        return false
      end
      owner = owner or F.getLocalChar()
      if F.gloveTransitionActive(owner) then
        G.Status = 'native_ads';
        return false
      end
      local slot = F.CUST_SLOT.HandEffectEquipemtSlot
      local getter = read(comp, 'GetMeshCompBySlot')
      if slot == nil or type(getter) ~= 'function' then
        G.Status = 'slot_api_unavailable';
        return false
      end
      local ok, mesh = pcall(getter, comp, slot)
      if not ok or not valid(mesh) then
        G.Status = 'mesh_pending';
        return false
      end
      if read(mesh, 'bVisible') == false or read(mesh, 'bVisible') == 0 then
        G.Status = 'native_hidden';
        return false
      end
      if not owner then
        local getOwner = read(comp, 'GetOwner')
        if type(getOwner) == 'function' then
          local got, value = pcall(getOwner, comp);
          if got then
            owner = value
          end
        end
      end
      if valid(owner) and read(owner, 'Mesh') == mesh then
        G.Status = 'shared_body_mesh';
        return false
      end
      for _, otherSlot in ipairs( { F.CUST_SLOT.ClothesEquipemtSlot, F.CUST_SLOT.PantsEquipemtSlot, F.CUST_SLOT.ShoesEquipemtSlot }) do
        if otherSlot ~= slot then
          local got, other = pcall(getter, comp, otherSlot)
          if got and other == mesh then
            G.Status = 'shared_body_mesh';
            return false
          end
        end
      end
      local info = read(mesh, 'LODInfo');
      local num = read(info, 'Num')
      if type(num) ~= 'function' then
        G.Status = 'lod_info_unavailable';
        return false
      end
      local counted, count = pcall(num, info);
      count = counted and integer(count)
      if not count or count < 1 or count > 64 then
        G.Status = 'lod_info_unavailable';
        return false
      end
      if count == 1 then
        G.Status = 'single_lod';
        return true
      end
      local setter = read(mesh, 'SetMinLOD');
      local current = integer(read(mesh, 'MinLodModel'))
      if type(setter) ~= 'function' or current == nil then
        G.Status = 'min_lod_api_unavailable';
        return false
      end
      local asset = read(mesh, 'SkeletalMesh');
      local row = G.Rows[mesh]
      if row and row.Asset ~= asset then
        if not restoreMesh(mesh, row) then
          G.Status = 'restore_pending';
          return false
        end
        G.Rows[mesh] = nil;
        row = nil;
        current = integer(read(mesh, 'MinLodModel'))
        if current == nil then
          G.Status = 'min_lod_api_unavailable';
          return false
        end
      end
      local target = count - 1
      if seen then
        seen[mesh] = true
      end
      if row and row.Applied then
        G.Status = 'native_lod_preserved';
        return true
      end
      if current == target then
        G.Status = 'low_lod_active';
        return true
      end
      if not row then
        row = { Asset = asset, OriginalMin = current, OriginalOverride = read(mesh, 'bOverrideMinLOD'),
        Target = target }
        G.Rows[mesh] = row
      else
        row.Target = target
      end
      local applied = pcall(setter, mesh, target)
      row.AppliedOverride = read(mesh, 'bOverrideMinLOD')
      if not applied or integer(read(mesh, 'MinLodModel')) ~= target then
        G.Status = 'write_unconfirmed';
        return false
      end
      row.Applied = true
      G.Status = 'low_lod_active';
      return true
    end
    function G.Tick()
      if not (_G.MWConfig.GraphicsCustomize == true or _G.MWConfig.GraphicsCustomize == 1) or not (_G.MWConfig.GraphicsGloveLOD == true or _G.MWConfig.GraphicsGloveLOD == 1) then
        if next(G.Rows) then
          G.Restore()
        end;
        return
      end
      if F.skinOff() then
        if next(G.Rows) then
          G.Restore()
        end
        return
      end
      local now = (_G.RealNow and _G.RealNow()) or os.clock()
      if now < G.Next then
        return
      end;
      G.Next = now + 1.5
      if F.gloveTransitionActive(F.getLocalChar()) then
        G.Status = 'native_ads';
        return
      end
      local seen = {}
      local function visit(owner)
        if not valid(owner) then
          return
        end
        local ok, comp = pcall(F.getAvatarComp2, owner)
        if ok and valid(comp) then
          G.ApplyAvatar(comp, seen, owner)
        end
      end
      local inMatch = F.isInRealMatch()
      if inMatch then
        visit(F.getLocalChar())
      elseif _G.OwenNeonLobbySceneAllowed and _G.OwenNeonLobbySceneAllowed() == true then
        local uid = DataMgr and DataMgr.roleData and DataMgr.roleData.uid
        local manager = package.loaded['client.logic.avatar.logic_team_avatar_manager']
        if uid ~= nil and manager and type(manager.GetModel) == 'function' then
          local ok, owner = pcall(manager.GetModel, tostring(uid));
          if ok then
            visit(owner)
          end
        end
      end
      for mesh, row in pairs(G.Rows) do
        if not seen[mesh] and restoreMesh(mesh, row) then
          G.Rows[mesh] = nil
        end
      end
    end
  end
  function F.ensureSelectedGloveSlot(comp, res, slot)
    if F.skinOff() or not F.isInRealMatch() or res <= 0 then
      return false
    end
    local ok, result = pcall(function()
      local data = comp.NetAvatarData and comp.NetAvatarData.SlotSyncData
      if not data or not slua.isValid(data) then
        return false
      end
      for i = 0, data:Num() - 1 do
        local row = data:Get(i)
        if row and tonumber(row.SlotID) == slot then
          return true
        end
      end
      local row = import('AvatarSyncData')()
      row.SlotID = slot;
      row.ItemId = res;
      row.ItemID = res;
      row.AdditionalItemID = res
      row.OperationType = import('ESyncOperation').PutOn data:Add(row)
      if comp.OnRep_BodySlotStateChanged then
        comp:OnRep_BodySlotStateChanged()
      end
      return true
    end)
    return ok and result == true
  end
  function F.rebuildSelectedGloves(comp, res, observed, mesh)
    if F.skinOff() or not F.isInRealMatch() or not comp or not slua.isValid(comp) or F.gloveTransitionActive(F.getLocalChar()) or type(comp.PutOnCustomEquipmentByID) ~= 'function' then
      return false
    end
    F.GloveNativeRecovery = F.GloveNativeRecovery or setmetatable( {}, { __mode = 'k' })
    local row = F.GloveNativeRecovery[comp]
    if not row or row.Res ~= res then
      row = { Res = res, Attempts = 0, Next = 0 };
      F.GloveNativeRecovery[comp] = row
    end
    local now = _G.RealNow()
    if now < row.Next or row.Attempts >= 3 then
      return false
    end
    row.Attempts = row.Attempts + 1;
    row.Next = now + 1
    return pcall(comp.PutOnCustomEquipmentByID, comp, res)
  end
  function F.matchApplyGloves(char)
    if F.skinOff() or not F.isInRealMatch() or not char or not slua.isValid(char) or char ~= F.getLocalChar() then
      return false
    end
    if F.gloveTransitionActive(char) then
      return false
    end
    local res = tonumber(F.getDesiredWear('glovesRes', 'glovesRes', 'AddOutfitLastLobbyGlovesRes', F.syncBodyCacheFromLobby)) or 0
    if res <= 0 then
      return true
    end
    if not F.isResourcesReady(res) then
      F.requestResourceDownload(res);
      return false
    end
    local comp = F.getAvatarComp2(char);
    if not comp then
      return false
    end
    local slot = F.CUST_SLOT.HandEffectEquipemtSlot pcall(function()
      slot = import('EAvatarSlotType').EAvatarSlotType_HandEffectEquipemtSlot or slot
    end)
    F.GloveNativeRecovery = F.GloveNativeRecovery or setmetatable( {}, { __mode = 'k' })
    local row = F.GloveNativeRecovery[comp]
    if not row or row.Res ~= res then
      row = { Res = res, Attempts = 0, Next = 0 };
      F.GloveNativeRecovery[comp] = row
    end
    local function equipped()
      local id pcall(function()
        if comp.GetEquippedItemDefineID3 then
          local item = comp:GetEquippedItemDefineID3(slot);
          id = item and tonumber(item.TypeSpecificID)
        end
        if not id or id <= 0 then
          local sync = comp.GetSlotSyncData and comp:GetSlotSyncData(slot);
          id = sync and tonumber(sync.ItemID or sync.ItemId)
        end
      end)
      return id
    end
    local observed = equipped()
    if observed ~= res then
      row.Confirmed = nil F.ensureSelectedGloveSlot(comp, res, slot)
      F.setMakeSkin(comp, res, slot, { allowPutOn = false })
      if equipped() ~= res then
        F.rebuildSelectedGloves(comp, res, observed, nil)
      end
      if equipped() ~= res then
        return false
      end
    end
    if type(comp.GetMeshCompBySlot) == 'function' then
      local ok, mesh = pcall(comp.GetMeshCompBySlot, comp, slot)
      if not ok or not mesh or not slua.isValid(mesh) then
        if row.Confirmed then
          return true
        end
        local now = _G.RealNow();
        row.MissingSince = row.MissingSince or now
        if now - row.MissingSince < 1.5 then
          return false
        end
        F.rebuildSelectedGloves(comp, res, equipped(), nil)
        ok, mesh = pcall(comp.GetMeshCompBySlot, comp, slot)
        if not ok or not mesh or not slua.isValid(mesh) then
          return false
        end
      end
      row.MissingSince = nil
    end
    row.Confirmed = true
    if F.GloveLOD then
      pcall(F.GloveLOD.ApplyAvatar, comp, nil, char)
    end
    return true
  end
  function F.maintainSelectedGloves()
    if F.skinOff() then
      F.GloveRecovery = nil;
      F.GloveNativeRecovery = nil;
      F.GloveADSState = nil;
      return
    end
    local pollNow = _G.RealNow()
    if pollNow < (F.GlovePollNext or 0) then
      return
    end
    F.GlovePollNext = pollNow + 1.5
    if not F.isInRealMatch() then
      F.GloveNativeRecovery = nil;
      F.GloveADSState = nil
    end
    if not F.isInRealMatch() and not (_G.OwenNeonLobbySceneAllowed and _G.OwenNeonLobbySceneAllowed() == true) then
      return
    end
    local res = tonumber(F.getDesiredWear('glovesRes', 'glovesRes', 'AddOutfitLastLobbyGlovesRes', F.syncBodyCacheFromLobby)) or 0
    if res <= 0 then
      F.GloveRecovery = nil;
      return
    end
    local char = F.getLocalChar();
    local lobby = _G.OwenNeonLobbySceneAllowed and _G.OwenNeonLobbySceneAllowed() == true
    local comp = not lobby and char and F.getAvatarComp2(char) or nil
    local key = tostring(res) .. ':' .. tostring(lobby)
    local row = F.GloveRecovery
    if not row or row.Char ~= char or row.Comp ~= comp or row.Key ~= key then
      row = { Char = char, Comp = comp, Key = key, Next = 0, Attempts = 0 };
      F.GloveRecovery = row
    end
    local now = _G.RealNow();
    if now < row.Next then
      return
    end;
    row.Next = now + 1
    if not F.isResourcesReady(res) then
      row.WaitingForResource = true
      if (row.DownloadAttempts or 0) < 10 then
        row.DownloadAttempts = (row.DownloadAttempts or 0) + 1;
        F.requestResourceDownload(res)
      end
      return
    end
    if row.WaitingForResource then
      row.WaitingForResource = nil;
      row.Attempts = 0
    end
    if lobby then
      local ins = R.resToIns[res]
      if not ins then
        return
      end
      local worn = F.findWornInsBySubType(GLOVES_SUB)
      if tonumber(worn) ~= tonumber(ins) or row.Applied ~= res then
        if row.Attempts >= 10 then
          return
        end;
        row.Attempts = row.Attempts + 1
        if F.putOnGloves(ins) == true then
          row.Applied = res
        end
      end
    elseif F.isInRealMatch() and char and slua.isValid(char) then
      if F.gloveTransitionActive(char) then
        return
      end
      if row.Attempts >= 10 then
        return
      end
      local ok = F.matchApplyGloves(char)
      if ok then
        row.Attempts = 0
      else
        row.Attempts = row.Attempts + 1
      end
    end
  end
  function F.matchApplyAllSlots(char, forceRefresh)
    if F.skinOff() or not F.isInRealMatch() then
      return false
    end
    if not char then
      return false
    end
    F.syncGlobalWearSkins()
    local comp = F.getAvatarComp2(char)
    if not comp then
      return false
    end
    local entries = {}
    local function add(skin, slot)
      skin = tonumber(skin)
      if skin and skin > 0 and slot then
        entries[ # entries + 1] = { skin, slot }
      end
    end
    add(_G.SuitSkin, F.CUST_SLOT.ClothesEquipemtSlot)
    add(_G.PantsSkin, F.CUST_SLOT.PantsEquipemtSlot)
    add(_G.ShoesSkin, F.CUST_SLOT.ShoesEquipemtSlot)
    local ok = false
    if # entries > 0 then
      ok = F.applySlotSkinBatch(comp, entries, { forceRep = forceRefresh ~= false })
      if not ok then
        for _, e in ipairs(entries) do
          if F.setMakeSkin(comp, e[1], e[2], { allowPutOn = true }) then
            ok = true
          end
        end
      end
    end
    if F.isCharacterAirborne(char) then
      F.applyAirborneSlots(char, true)
    end
    local bagRes = F.getDesiredWear("bagRes", "bagRes", "AddOutfitLastLobbyBagRes", F.syncBodyCacheFromLobby)
    local helmetRes = F.getDesiredWear("helmetRes", "helmetRes", "AddOutfitLastLobbyHelmetRes", F.syncBodyCacheFromLobby)
    if (tonumber(bagRes) or 0) > 0 or (tonumber(helmetRes) or 0) > 0 then
      ok = F.matchApplyEquipmentSkin(char, bagRes, helmetRes) or ok
    end
    local glovesOK = F.matchApplyGloves(char)
    local hatOK = F.matchApplyHat(char)
    local faceOK = F.matchApplyFaceWear(char)
    return (ok or # entries == 0) and glovesOK and hatOK and faceOK
  end
  function F.matchApplyHat(char)
    if F.skinOff() or not F.isInRealMatch() then
      return false
    end
    local hatRes = tonumber(F.getDesiredHat())
    if not hatRes or hatRes <= 0 then
      return true
    end
    char = char or F.getLocalChar()
    if not char then
      return false
    end
    local comp = F.getAvatarComp2(char)
    if not comp then
      return false
    end
    if not F.isResourcesReady(hatRes) then
      F.requestResourceDownload(hatRes)
      return false
    end
    local slotID = F.CUST_SLOT.HatEquipemtSlot
    local ok, changed = false, false pcall(function()
      local net = comp.NetAvatarData
      if not net then
        return
      end
      local applyData = net.SlotSyncData
      if not applyData or not slua.isValid(applyData) then
        return
      end
      local found = false
      for i = 0, applyData:Num() - 1 do
        local equipment = applyData:Get(i)
        if equipment and equipment.SlotID == slotID then
          found = true
          local cur = tonumber(equipment.ItemId) or tonumber(equipment.ItemID) or 0
          local putOn = import('ESyncOperation').PutOn
          if cur ~= hatRes or equipment.OperationType ~= putOn then
            F.ensureSkinDownload(hatRes)
            equipment.OperationType = putOn
            equipment.ItemId = hatRes
            if equipment.ItemID ~= nil then
              equipment.ItemID = hatRes
            end
            if equipment.FakeItemID ~= nil then
              equipment.FakeItemID = hatRes
            end
            applyData:Set(i, equipment)
            changed = true
          end
          ok = true
          break
        end
      end
      if not found then
        F.ensureSkinDownload(hatRes)
        local ESyncOperation = import("ESyncOperation")
        local entry = import("AvatarSyncData")()
        entry.SlotID = slotID
        entry.ItemId = hatRes
        entry.ItemID = hatRes
        entry.FakeItemID = hatRes
        entry.OperationType = ESyncOperation.PutOn applyData:Add(entry)
        changed = true
        ok = true
      end
      if changed and comp.OnRep_BodySlotStateChanged then
        comp:OnRep_BodySlotStateChanged()
      end
    end)
    return ok
  end
  do
    local states = setmetatable( {}, { __mode = 'k' })
    function F.onMatchHeadwearMeshReady(comp)
      if F.skinOff() or not F.isInRealMatch() or not F.isLocalEquipmentComp(comp) then
        return
      end
      local ids = { tonumber(F.getDesiredHat()) or 0, tonumber(F.getDesiredGlass()) or 0 }
      local signature = ids[1] .. ':' .. ids[2]
      local row = states[comp]
      if not row or row.Signature ~= signature then
        row = { Signature = signature, Attempts = 0 };
        states[comp] = row
      end
      if row.Pending or row.Attempts >= 2 then
        return
      end
      local missing = false
      for i, slot in ipairs( { F.CUST_SLOT.HatEquipemtSlot, F.CUST_SLOT.GlassEquipemtSlot }) do
        if ids[i] > 0 then
          local ok, ready = pcall(function()
            local sync = comp.GetSlotSyncData and comp:GetSlotSyncData(slot)
            if sync and ((tonumber(sync.HideState) or 0) > 0 or sync.bForceHideState == true or sync.bForceHideState == 1 or (tonumber(sync.ForceHideState) or 0) > 0) then
              return true
            end
            local id = comp.GetEquippedItemDefineID3 and comp:GetEquippedItemDefineID3(slot)
            local mesh = comp.GetMeshCompBySlot and comp:GetMeshCompBySlot(slot)
            return id and tonumber(id.TypeSpecificID) == ids[i] and mesh and slua.isValid(mesh)
          end)
          if not ok or not ready then
            missing = true
          end
        end
      end
      if not missing then
        return
      end
      row.Pending = true;
      row.Attempts = row.Attempts + 1 F.later(0.1, function()
        if states[comp] ~= row then
          return
        end
        row.Pending = nil
        if F.skinOff() or not F.isInRealMatch() or not F.isLocalEquipmentComp(comp) or signature ~= ((tonumber(F.getDesiredHat()) or 0) .. ':' .. (tonumber(F.getDesiredGlass()) or 0)) then
          return
        end
        local char = F.getLocalChar()
        local _fwCache = _G.FaceWearStateCache and _G.FaceWearStateCache[comp]
        if type(_fwCache) == "table" then
          _fwCache[F.CUST_SLOT.GlassEquipemtSlot] = nil
        end
        F.matchApplyHat(char);
        F.matchApplyFaceWear(char)
      end)
    end
  end
  local _avatarItemsRegistered = false
  function F.getDesiredWeaponSkins()
    if PERF.desiredSkins then
      return PERF.desiredSkins
    end
    F.syncWeaponCacheFromLobby()
    local out, seen = {}, {}
    local function add(res)
      res = tonumber(res)
      if res and res > 0 and not seen[res] then
        seen[res] = true;
        out[ # out + 1] = res
      end
    end
    for wid, w in pairs(F.cache().weapons) do
      if w.resID then
        add(w.resID)
      end
    end
    if MATCH_CONFIG.weaponSkins then
      for _, res in pairs(MATCH_CONFIG.weaponSkins) do
        add(res)
      end
    end
    PERF.desiredSkins = out
    return out
  end
  function F._cacheSkinTarget(weaponResID, skin)
    if skin and skin > 0 then
      PERF.skinTarget[weaponResID] = skin
    else
      PERF.skinTarget[weaponResID] = 0
    end
    return skin
  end
  local GUN_MASTER_SYN_SLOT = 7
  function F.findSkinSlotInSynData(weapon)
    if not slua.isValid(weapon) or not slua.isValid(weapon.synData) then
      return GUN_MASTER_SYN_SLOT, 0
    end
    local arr = weapon.synData
    local function read(slot)
      local ok, row = pcall(arr.Get, arr, slot);
      if not ok or not row then
        return 0
      end
      local ok2, ref = pcall(slua.IndexReference, row, 'defineID')
      local id = ok2 and ref and tonumber(ref.TypeSpecificID) or 0
      if id and ((id >= 101000 and id < 109000) or F.weaponIdFromSkin(id)) then
        return id
      end
      return 0
    end
    local id = read(GUN_MASTER_SYN_SLOT);
    if id > 0 then
      return GUN_MASTER_SYN_SLOT, id
    end
    local count = arr.Num and arr:Num() or 0
    for slot = 0, math.min(count - 1, 15) do
      id = read(slot);
      if id > 0 then
        return slot, id
      end
    end
    return GUN_MASTER_SYN_SLOT, 0
  end
  function F.resolveWeaponTypeID(weaponResID)
    weaponResID = tonumber(weaponResID) or 0
    if weaponResID <= 0 then
      return 0
    end
    local found = 0 pcall(function()
      local wc = CDataTable.GetTableData("WeaponConfig", weaponResID)
      if wc then
        found = tonumber(wc.WeaponID or wc.WeaponId or wc.weaponID or 0)
      end
    end)
    if found > 0 then
      return found
    end
    pcall(function()
      local ic = CDataTable.GetTableData("Item", weaponResID)
      if ic then
        found = tonumber(ic.WeaponID or ic.weaponId or 0)
      end
    end)
    if found > 0 then
      return found
    end
    return tonumber(F.weaponIdFromSkin(weaponResID)) or weaponResID
  end
  function F.findTargetSkinForWeaponRes(weaponResID)
    weaponResID = tonumber(weaponResID) or 0
    if weaponResID <= 0 then
      return nil
    end
    local cached = PERF.skinTarget[weaponResID]
    if cached ~= nil then
      return cached == 0 and nil or cached
    end
    local memSkin = F.getMatchWeaponSkin(weaponResID)
    if memSkin then
      return F._cacheSkinTarget(weaponResID, memSkin)
    end
    local typeID = F.resolveWeaponTypeID(weaponResID)
    if typeID > 0 and typeID ~= weaponResID then
      memSkin = F.getMatchWeaponSkin(typeID)
      if memSkin then
        return F._cacheSkinTarget(weaponResID, memSkin)
      end
    end
    if MATCH_CONFIG.weaponSkins and MATCH_CONFIG.weaponSkins[weaponResID] then
      local fixed = tonumber(MATCH_CONFIG.weaponSkins[weaponResID])
      if fixed and fixed > 0 then
        return F._cacheSkinTarget(weaponResID, fixed)
      end
    end
    for _, skinRes in ipairs(F.getDesiredWeaponSkins()) do
      local wid = F.weaponIdFromSkin(skinRes)
      if wid and tonumber(wid) == weaponResID then
        return F._cacheSkinTarget(weaponResID, skinRes)
      end
    end
    local typeID = F.resolveWeaponTypeID(weaponResID)
    if typeID > 0 and typeID ~= weaponResID then
      if MATCH_CONFIG.weaponSkins and MATCH_CONFIG.weaponSkins[typeID] then
        local fixed = tonumber(MATCH_CONFIG.weaponSkins[typeID])
        if fixed and fixed > 0 then
          return F._cacheSkinTarget(weaponResID, fixed)
        end
      end
      for _, skinRes in ipairs(F.getDesiredWeaponSkins()) do
        local wid = F.weaponIdFromSkin(skinRes)
        if wid and tonumber(wid) == typeID then
          return F._cacheSkinTarget(weaponResID, skinRes)
        end
      end
    end
    local avatarMatch = nil pcall(function()
      local AU = import("AvatarUtils")
      local weaponBase = AU.GetWeaponAvatarParentID(AU.GetBPIDByResID(weaponResID), false)
      if not weaponBase or weaponBase <= 0 then
        return
      end
      for _, skinRes in ipairs(F.getDesiredWeaponSkins()) do
        local skinBase = AU.GetWeaponAvatarParentID(AU.GetBPIDByResID(skinRes), false)
        if skinBase and skinBase > 0 and skinBase == weaponBase then
          avatarMatch = skinRes
          return
        end
      end
    end)
    if avatarMatch then
      return F._cacheSkinTarget(weaponResID, avatarMatch)
    end
    PERF.skinTarget[weaponResID] = 0
    return nil
  end
  function F.getSynMasterSkinID(weapon)
    if not slua.isValid(weapon) then
      return 0
    end
    local id = 0 pcall(function()
      local slot, tid = F.findSkinSlotInSynData(weapon)
      id = tid
      if id == 0 then
        local arr = weapon.synData
        if not arr or not slua.isValid(arr) then
          return
        end
        local att = arr:Get(GUN_MASTER_SYN_SLOT)
        if not att then
          return
        end
        id = slua.IndexReference(att, "defineID").TypeSpecificID or 0
      end
    end)
    return id
  end
  _G.AddOutfitSkinIdMappings = _G.AddOutfitSkinIdMappings or {} _G.AddOutfitLastAppliedSkin = _G.AddOutfitLastAppliedSkin or {}
  function F.buildSkinMappings()
    if not PERF.mappingsDirty then
      return
    end
    F.syncWeaponCacheFromLobby()
    PERF.mappingsDirty = false
    local m = _G.AddOutfitSkinIdMappings
    for k in pairs(m) do
      m[k] = nil
    end
    for rawWid, w in pairs(F.cache().weapons) do
      local wid = tonumber(rawWid)
      if wid and w.resID and w.resID > 0 then
        m[wid] = { tonumber(w.resID) }
      end
    end
    if MATCH_CONFIG.weaponSkins then
      for rawWeaponKey, rawSkinRes in pairs(MATCH_CONFIG.weaponSkins) do
        local weaponKey, skinRes = tonumber(rawWeaponKey), tonumber(rawSkinRes)
        if weaponKey and skinRes and skinRes > 0 and not m[weaponKey] then
          m[weaponKey] = { skinRes }
        end
      end
    end
    _G.OwenWeaponSkinEpoch = (_G.OwenWeaponSkinEpoch or 0) + 1
    _G.OwenWeaponApplied = nil
  end
  function F.get_skin_id(currentGunId, maxIt)
    currentGunId = tonumber(currentGunId) or 0
    maxIt = tonumber(maxIt) or 0
    if currentGunId <= 0 and maxIt <= 0 then
      return 0
    end
    F.buildSkinMappings()
    if maxIt > 0 then
      local fromMem = F.getMatchWeaponSkin(maxIt)
      if fromMem then
        return fromMem
      end
    end
    local fromMem2 = F.getMatchWeaponSkin(F.resolveWeaponTypeID(currentGunId))
    if fromMem2 then
      return fromMem2
    end
    local m = _G.AddOutfitSkinIdMappings
    if maxIt > 0 and m[maxIt] and m[maxIt][1] then
      return tonumber(m[maxIt][1])
    end
    local list = m[currentGunId]
    if list and list[1] then
      return tonumber(list[1])
    end
    local typeId = F.resolveWeaponTypeID(currentGunId)
    if typeId > 0 and m[typeId] and m[typeId][1] then
      return tonumber(m[typeId][1])
    end
    local target = F.findTargetSkinForWeaponRes(maxIt > 0 and maxIt or currentGunId)
    if target then
      return target
    end
    return currentGunId
  end
