            lines[ # lines + 1] = number(skin) .. ' | Weapon ID: ' .. tostring(owner or 'unknown') .. ' | Weapon: ' .. label(owner and row('Item', owner), names[owner] or 'unknown'):gsub('[\r\n\t]', ' ') .. ' | Skin: ' .. tostring(m.SkinName or ('Skin ' .. skin)):gsub('[\r\n\t]', ' ') .. ' | Level (raw): ' .. tostring(m.Level or 'unknown') .. ' | Status: ' .. tostring(E.Missing[skin])
          end
        end
        return table.concat(lines, '\n') .. '\n'
