      local function save()
        E.WriteError = 'export_disabled';
        return false
      end
      _G.OwenAttachmentCollectorTick = function()
        if _G.OwenPublicNoLogs then
          return
        end
        if E.Finished then
          return
        end
        local now = _G.RealNow();
        if now < E.NextTick then
          return
        end;
        E.NextTick = now + .5
        if not (_G.OwenNeonLobbySceneAllowed and _G.OwenNeonLobbySceneAllowed()) then
          E.Status = 'paused_outside_lobby';
          return
        end
        if E.Complete then
          if now < E.NextWrite then
            return
          end;
          E.NextWrite = now + 10
          E.WriteAttempts = (E.WriteAttempts or 0) + 1
          if save() then
            E.Finished = true;
            E.Status = 'complete'
          else
            E.Status = 'export_write_failed'
          end
          return
        end
        if not CDataTable or not CDataTable.GetTableData then
          E.Status = 'waiting_for_game_tables'
          if now >= E.NextWrite then
            E.NextWrite = now + 15;
            save()
          end
          return
        end
        if now < (E.RetryAt or 0) then
          if now >= E.NextWrite then
            E.NextWrite = now + 15;
            save()
          end
          return
        end
        if not E.Initialized then
          initialize()
          save();
          E.NextWrite = now + 15
        end
        discover()
        attachTables()
        E.Discovering = next(E.Tables) ~= nil
        E.Status = 'collecting'
        local deadline = os.clock() + .004
        for i = 1, 2 do
          local id = E.Queue[E.Index];
          if not id then
            break
          end
          E.Index = E.Index + 1;
          collect(id)
          if os.clock() >= deadline then
            break
          end
        end
        if now >= E.NextWrite then
          E.NextWrite = now + 15;
          save()
        end
        if E.Index > # E.Queue and not E.Discovering then
          if E.Pass < 3 then
            E.Pass = E.Pass + 1;
            E.Index = 1;
            E.RetryAt = now + 30;
            E.Status = 'waiting_for_retry'
          else
            E.Complete = true;
            E.NextWrite = 0;
            E.Status = 'ready_to_export'
          end
        end
      end
    end
    local FULL_EQUIVALENT_BASES = {
[204011] = { 204007, 204004, 204015 },
[204007] = { 204011, 204004, 204015 },
[204004] = { 204011, 204007, 204015 },
[204015] = { 204011, 204007, 204004 },
[204012] = { 204008, 204005 },
[204008] = { 204012, 204005 },
[204005] = { 204012, 204008 },
[204013] = { 204009, 204006 },
[204009] = { 204013, 204006 },
[204006] = { 204013, 204009 },
