    local function FullTargetForBase(skinId, baseId, dyn, defMap)
      skinId, baseId = tonumber(skinId) or 0, tonumber(baseId) or 0
      if skinId <= 0 or baseId <= 0 then
        return nil
      end
      local target = dyn and tonumber(dyn[baseId]) or nil
      if target and target > 0 and target ~= baseId then
        return target
      end
      target = defMap and tonumber(defMap[baseId]) or nil
      if target and target > 0 and target ~= baseId then
        return target
      end
      local vip = _G.VIP_Attachments and _G.VIP_Attachments[skinId]
      local idx = _G.BaseAttachToIndex and _G.BaseAttachToIndex[baseId]
      target = vip and idx and tonumber(vip[idx]) or nil
      if target and target > 0 and target ~= baseId then
        return target
      end
      for _, other in ipairs(FULL_EQUIVALENT_BASES[baseId] or {}) do
        local alternative = dyn and tonumber(dyn[other]) or nil
        if not alternative or alternative <= 0 or alternative == other then
          alternative = defMap and tonumber(defMap[other]) or nil
        end
        if ( not alternative or alternative <= 0 or alternative == other) and vip then
          local index = _G.BaseAttachToIndex and _G.BaseAttachToIndex[other]
          alternative = index and tonumber(vip[index]) or nil
        end
        if alternative and alternative > 0 and alternative ~= other then
          return alternative
        end
      end
      return nil
    end
    local function FullTargetForEmptySlot(skinId, slot, dyn, defMap)
      for _, base in ipairs(FULL_SLOT_BASES[slot] or {}) do
        local target = FullTargetForBase(skinId, base, dyn, defMap)
        if target and target > 0 then
          return target, base
        end
      end
      if defMap then
        local allowed = {}
        for _, base in ipairs(FULL_SLOT_BASES[slot] or {}) do
          allowed[base] = true
        end
        for rawBase, rawTarget in pairs(defMap) do
          local base, target = tonumber(rawBase), tonumber(rawTarget)
          if base and target and target > 0 and allowed[base] then
            return target, base
          end
        end
      end
      return nil, nil
    end
    local function FullTargetsForEmptySlot(skinId, slot, dyn, defMap)
      local result, seen = {}, {}
      for _, base in ipairs(FULL_SLOT_BASES[slot] or {}) do
        local target = FullTargetForBase(skinId, base, dyn, defMap)
        if target and target ~= base and not seen[target] then
          seen[target] = true;
          result[ # result + 1] = target
        end
      end
      return result
    end
    local function FullRecoverBase(skinId, itemId, slot, dyn, defMap)
      itemId = tonumber(itemId) or 0
      if itemId <= 0 then
        return 0
      end
      if itemId < 1000000 then
        return itemId
      end
      local parent = FullParentId(itemId)
      if parent > 0 then
        return parent
      end
      for _, base in ipairs(FULL_SLOT_BASES[slot] or {}) do
        if FullTargetForBase(skinId, base, dyn, defMap) == itemId then
          return base
        end
      end
      local vipIdx = _G.VipAttachToIndex and _G.VipAttachToIndex[itemId]
      if vipIdx and _G.BaseAttachToIndex then
        for base, idx in pairs(_G.BaseAttachToIndex) do
          if tonumber(idx) == tonumber(vipIdx) then
            for _, candidate in ipairs(FULL_SLOT_BASES[slot] or {}) do
              if tonumber(candidate) == tonumber(base) then
                return tonumber(base)
              end
            end
          end
        end
      end
      return 0
    end
    local function FullRefresh(weapon, wac, touched)
      if not touched or not next(touched) then
        return false
      end
      local delay = weapon.DelayHandleAvatarMeshChanged
      local immediate = weapon.HandleAvatarMeshChanged
      local reload = slua.isValid(wac) and wac.ReloadAllEquippedAvatar
      if type(delay) ~= 'function' and type(immediate) ~= 'function' and type(reload) ~= 'function' then
        return false
      end
      if slua.isValid(wac) then
        for slot in pairs(touched) do
          pcall(function()
            if wac.ClearMeshPathCacheBySlot then
              wac:ClearMeshPathCacheBySlot(slot)
            end
          end)
          pcall(function()
            if wac.ClearMeshBySlot then
              wac:ClearMeshBySlot(slot, true, true)
            end
          end)
        end
      end
      local function accepted(fn, object, ...)
        if type(fn) ~= 'function' then
          return false
        end
        local ok, result = pcall(fn, object, ...)
        return ok and result ~= false
      end
      if accepted(delay, weapon) then
        return true
      end
      if accepted(immediate, weapon) then
        return true
      end
      return accepted(reload, wac, 1)
    end
