    function V.CurrentWeapon(owner)
      local manager = call(owner, 'GetWeaponManager') or field(owner, 'WeaponManagerComponent')
      for _, name in ipairs( { 'GetCurrentUsingWeapon', 'GetCurrentWeapon' }) do
