      value = call(manager, 'GetCurrentShootWeapon') or call(owner, 'GetCurrentShootWeapon')
      if live(value) then
        return value, 'shoot_weapon_fallback'
      end
      return nil, 'unavailable'
    end
    local function inventoryHas(owner, weapon)
      local now = _G.RealNow();
      local cache = V.Inventory
      if not cache or not sameNative(cache.Owner, owner) or now >= cache.Until then
        cache = {
          Owner = owner,
          Until = now + 1,
          Weapons = {}
        };
        V.Inventory = cache
        local manager = call(owner, 'GetWeaponManager') or field(owner, 'WeaponManagerComponent')
        local list = call(manager, 'GetAllInventoryWeaponList', false)
        local count = tonumber(call(list, 'Num')) or 0
        for index = 0, math.min(count, 8) - 1 do
          local item = call(list, 'Get', index)
          if live(item) then
