    function V.EquippedID(weapon, nativeSlot)
      local getter = field(weapon, 'GetAttachmentItemHandle')
      if type(getter) ~= 'function' then
        return 0, 'equipment_api_unavailable'
      end
      local ok, handle = pcall(getter, weapon, nativeSlot)
      if not ok then
        return 0, 'equipment_read_failed'
      end
      if not live(handle) then
        return 0, 'no_equipped_handle'
      end
      local id = tonumber(field(call(handle, 'GetDefineID'), 'TypeSpecificID')) or 0
      if id <= 0 then
        return 0, 'equipped_id_unavailable'
      end
      local function contains(list, target)
        if not list then
          return false
        end
        local count = tonumber(call(list, 'Num'))
        if count then
          for i = 0, math.min(count, 64) - 1 do
            if tonumber(call(list, 'Get', i)) == target then
              return true
            end
          end
        elseif type(list) == 'table' then
          local n = 0
          for _, value in pairs(list) do
            n = n + 1;
            if n > 64 then
              break
            end;
            if tonumber(value) == target then
              return true
            end
          end
        end
        return false
      end
      if contains(field(weapon, 'DefaultAttachedAttachmentID'), id) then
        return 0, 'native_default_attachment', id
      end
      local attached = field(weapon, 'AttachedAttachmentID')
      if attached and not contains(attached, id) then
        return 0, 'not_in_attached_inventory'
      end
      return id, 'native_equipped_handle'
