    local function pathOf(value)
      if type(value) == 'string' and value:sub(1, 1) == '/' then
        return value
      end
      if value and type(value) ~= 'string' then
        local name = field(value, 'AssetPathName')
        if name then
          local text = tostring(name);
          if text:sub(1, 1) == '/' then
            return text
          end
        end
        local text = call(value, 'ToString')
        if type(text) == 'string' and text:sub(1, 1) == '/' then
          return text
        end
        local ok, text = pcall(tostring, value)
        if ok and text:sub(1, 1) == '/' then
          return text
        end
      end
    end
    local function renderMesh(obj, preferSkeletal)
      local package = field(obj, 'MeshPackage')
      if package then
        for _, name in ipairs(preferSkeletal and { 'skMesh', 'stMesh', 'skMeshLod', 'stMeshLod', 'skCutMesh',
        'stCutMesh' } or { 'stMesh', 'skMesh', 'stMeshLod', 'skMeshLod', 'stCutMesh', 'skCutMesh' }) do
          local path = pathOf(field(package, name))
          if path then
            return path, name:sub(1, 2) == 'sk', 'MeshPackage.' .. name
          end
        end
      end
      for _, name in ipairs( { 'SkeletalMesh', 'SkeletonMesh', 'StaticMesh', 'Mesh', 'MeshPath' }) do
        local value = field(obj, name)
        if value and value ~= '' then
          local path = pathOf(value)
          local ok, valid = pcall(live, value)
          if path or (type(value) ~= 'string' and ok and valid) then
            return path or value, name == 'SkeletalMesh' or name == 'SkeletonMesh', name
          end
        end
      end
