      'SkeletalMeshComponent' }) do
        local ok, components = pcall(function()
          if not handle or not handle.GetComponentsByClass then
            return nil
          end
          return handle:GetComponentsByClass(import(className))
        end)
        if ok and components then
          local count = tonumber(call(components, 'Num')) or 0
          local found, sk, source, ambiguous
          for index = 0, math.min(count, 16) - 1 do
            local comp = call(components, 'Get', index)
            local value, isSkeletal, name = renderMesh(comp, preferSkeletal)
            if value then
              if found and not sameNative(found, value) then
                ambiguous = true;
                break
              end
              found, sk, source = value, isSkeletal, className .. '.' .. tostring(name)
            end
          end
          if found and not ambiguous then
            return found, sk, source
          end
        end
      end
    end
