            local okFactory, factoryError = pcall(function()
              local factory = import('BackpackUtils')
              local makeID = _G.FItemDefineID
              local owner = F.getLocalChar and F.getLocalChar()
              local outer = owner and (field(owner, 'Object') or owner)
              if not outer or not factory or type(field(factory, 'CreateBattleItemHandle')) ~= 'function' or not makeID then
                return
              end
              local define = makeID(2, id)
              local instance = factory.CreateBattleItemHandle(define, outer, false)
              if not live(instance) then
                return
              end
              entry.ReadHandle = instance
              if type(field(instance, 'Init')) == 'function' then
                instance:Init(define)
              end
              local actual = call(instance, 'GetDefineID') or field(instance, 'DefineID')
              assert(tonumber(field(actual, 'TypeSpecificID')) == id, 'attachment_initialized_id_mismatch')
              local initialized = call(instance, 'GetAttachmentConfig')
              if initialized then
                handle = instance;
                cfg = initialized;
                entry.HandleSource = 'initialized_item'
              end
            end)
            if not okFactory then
              entry.HandleError = tostring(factoryError):sub(1, 180)
            end
            entry.PackageFields = nil
            local value, isSkeletal, name = renderMesh(cfg, preferSkeletal);
            entry.MeshSource = 'attachment_config.' .. tostring(name)
            if not value then
              value, isSkeletal, name = renderMesh(handle, preferSkeletal);
              entry.MeshSource = 'class_handle.' .. tostring(name)
            end
            if not value then
              value, isSkeletal, name = componentMesh(handle, preferSkeletal);
              entry.MeshSource = 'class_component.' .. tostring(name)
            end
            if not value then
              entry.RuntimeFields = nil
              local details = {}
              for _, key in ipairs( { 'StaticMesh', 'SkeletonMesh', 'SkeletalMesh', 'Mesh', 'MeshPath' }) do
                details[ # details + 1] = key .. '[cfg=' .. tostring(field(cfg, key)):sub(1, 140) .. ',handle=' .. tostring(field(handle, key)):sub(1, 140) .. ']'
              end
              entry.Metadata = table.concat(details, ';')
              fail('attachment_mesh_metadata_missing');
              entry.Retry = _G.RealNow() + 120;
              return
            end
            local parent = field(cfg, 'ParentID');
            parent = tonumber(parent) or tonumber(field(parent, 'TypeSpecificID'))
            entry.ParentID = parent loadMesh(value, isSkeletal, field(cfg, 'SocketName'), attachmentSockets(cfg), field(cfg, 'MeshPackage'), parent, attachmentRole(cfg))
          end)
          if not success then
            fail('attachment_config_read_failed')
          end
        end)
      end)
      if not ok then
        fail('attachment_resource_request_failed')
      end
      return entry.Descriptor
    end
    local enumNames = { [0] = 'GunPoint', [1] = 'LowerRail', [2] = 'Magazine', [3] = 'Gunstock', [4] = 'OpticalSight' }
    V.Previews = {}
    function V.CaptureLobby(weapon)
      if not OwenNeonAuthorized() or F.skinOff() or F.isInRealMatch() then
        return
      end
      local wac = field(weapon, 'WeaponAvatarComp_BP')
      if not live(wac) and weapon.GetWeaponAvatarComponent then
        wac = weapon:GetWeaponAvatarComponent()
      end
      if not live(wac) then
        return
      end
      local skin = 0
      if wac.GetEquippedItemDefineID then
        local id = wac:GetEquippedItemDefineID(7);
        skin = tonumber(id and id.TypeSpecificID) or 0
      end
      if skin <= 0 then
        skin = tonumber(field(wac, 'CachedLoadedID')) or 0
      end
      if skin <= 0 then
        return
      end
      local parent = field(wac, 'MasterBoneComponent');
      if not live(parent) then
        return
      end
      local slots = {};
      local getter = wac.GetMeshCompBySlotID or wac.GetMeshCompbySlotID
      if type(getter) ~= 'function' or not wac.GetEquippedItemDefineID then
        return
      end
      for slot = 0, 4 do
        local ok = pcall(function()
          local sockets = import('EWeaponAttachmentSocketType')
          local nativeSlot = field(sockets, enumNames[slot]);
          if nativeSlot == nil then
            nativeSlot = slot
          end
          local comp = getter(wac, nativeSlot);
          if not live(comp) or not comp.GetAttachSocketName then
            return
          end
          if comp.GetAttachParent and not sameNative(comp:GetAttachParent(), parent) then
            return
          end
          local socket = comp:GetAttachSocketName()
          if not socket or tostring(socket) == '' or tostring(socket) == 'None' or not parent.DoesSocketExist or not parent:DoesSocketExist(socket) then
            return
          end
          local id = wac:GetEquippedItemDefineID(nativeSlot);
          id = tonumber(id and id.TypeSpecificID) or 0
          local sk, sm = field(comp, 'SkeletalMesh'), field(comp, 'StaticMesh');
          local mesh = live(sk) and sk or sm
          if id <= 0 or not live(mesh) then
            return
          end
          local materials = {}
          if comp.GetNumMaterials and comp.GetMaterial then
            for index = 0, math.min(tonumber(comp:GetNumMaterials()) or 0, 16) - 1 do
              materials[index] = comp:GetMaterial(index)
            end
          end
          slots[slot] = { FromLobby = true, Target = id, Mesh = mesh, Skeletal = live(sk) and true or false,
          Socket = socket, Transform = comp.GetRelativeTransform and comp:GetRelativeTransform() or nil,
          Materials = materials }
        end)
        if not ok then
          V.PreviewStatus = 'capture_slot_unavailable'
        end
      end
      if not next(slots) then
        V.PreviewStatus = 'preview_meshes_not_ready';
        return
      end
      local count, oldest, oldTime = 0, nil, math.huge
      for key, entry in pairs(V.Previews) do
        count = count + 1;
        if entry.Time < oldTime then
          oldest = key;
          oldTime = entry.Time
        end
      end
      if not V.Previews[skin] and count >= 8 then
        V.Previews[oldest] = nil
      end
      V.Previews[skin] = { Slots = slots, Time = _G.RealNow() };
      V.PreviewStatus = 'captured';
      V.PreviewSkin = skin;
      V.PreviewError = nil
    end
    function V.SyncLobbyHook()
      local selected = OwenNeonAuthorized() and not F.skinOff()
      local active = selected and _G.OwenNeonLobbySceneAllowed and _G.OwenNeonLobbySceneAllowed() == true
      if not active then
        if V.LobbyHook and V.LobbyHook.Class.OnAvatarChanged == V.LobbyHook.Wrapped then
          V.LobbyHook.Class.OnAvatarChanged = V.LobbyHook.Original
        end
        V.LobbyHook = nil;
        if not selected and next(V.Previews) then
          V.Previews = {}
        end
        V.PreviewStatus = selected and 'cached_for_match' or 'off';
        return
      end
      if V.LobbyHook or _G.RealNow() < (V.NextLobbyHook or 0) then
        return
      end
      V.NextLobbyHook = _G.RealNow() + 5
      local ok, err = pcall(function()
        local class = require('client.lobby_ue_object.Actor.LobbyWeapon');
        local original = class.OnAvatarChanged assert(type(original) == 'function', 'lobby_avatar_callback_unavailable')
        local wrapped = function(self, ...)
          pcall(V.CaptureLobby, self);
          return original(self, ...)
        end
        class.OnAvatarChanged = wrapped;
        V.LobbyHook = { Class = class, Original = original, Wrapped = wrapped }
        if not F.isInRealMatch() then
          local mgr = require('client.logic.avatar.logic_team_avatar_manager')
          local uid = DataMgr and DataMgr.roleData and DataMgr.roleData.uid
          local pawn = uid and mgr.GetModel(uid)
          local wm = pawn and pawn.BP_LobbyWeaponManager
          local weapon = wm and wm.GetUsingWeapon and wm:GetUsingWeapon()
          if live(weapon) then
            V.CaptureLobby(weapon)
          end
        end
      end)
      if not ok then
        V.PreviewStatus = 'hook_or_bootstrap_unavailable';
        V.PreviewError = tostring(err)
      end
    end
    local function previewPart(skin, slot, target)
      local preview = V.Previews[skin];
      local desc = preview and preview.Slots[slot]
      if desc and desc.Target == target and live(desc.Mesh) then
        return desc
      end
    end
    local function applyMaterials(comp, desc)
      if comp.SetMaterial then
        for index, mat in pairs(desc.Materials or {}) do
          if live(mat) then
            comp:SetMaterial(index, mat)
          end
        end
      end
      if live(desc.Material) and comp.SetMaterial then
        local name = desc.MaterialSlotName;
        local index = materialIndex(comp, name)
        if index >= 0 then
          comp:SetMaterial(index, desc.Material)
        else
          V.LastError = 'attachment_material_slot_missing:' .. tostring(name)
        end
      end
    end
    V.NativeEmpty = setmetatable( {}, { __mode = 'k' })
    local function nativeContext(weapon)
      local ctx = V.NativeEmpty[weapon];
      if ctx then
        return ctx, weapon
      end
      for other, row in pairs(V.NativeEmpty) do
        if sameNative(other, weapon) then
          return row, other
        end
      end
    end
    local function nativePart(wac, slot)
      local name = type(field(wac, 'GetMeshCompBySlotID')) == 'function' and 'GetMeshCompBySlotID' or 'GetMeshCompbySlotID'
      local comp = call(wac, name, slot)
      if sameNative(comp, field(wac, 'MasterBoneComponent')) then
        return nil
      end
      return live(comp) and comp or nil
    end
    local function restoreEmptySlot(row)
      if not row then
        return
      end
      if row.Hidden and live(row.Component) and field(row.Component, 'bHiddenInGame') == true then
        pcall(row.Component.SetHiddenInGame, row.Component, row.WasHidden, false)
      end
      if row.Applied then
        restore(row)
      end
    end
    function V.ClearNativeEmpty(weapon)
      local ctx, key = nativeContext(weapon);
      if not ctx then
        return
      end
      weapon = key
      V.NativeEmpty[weapon] = nil
      for _, row in pairs(ctx.Applied) do
        restoreEmptySlot(row)
      end
      if ctx.Delegate and ctx.Callback and type(field(ctx.Delegate, 'Remove')) == 'function' then
        pcall(ctx.Delegate.Remove, ctx.Delegate, ctx.Handle or ctx.Callback)
      end
    end
    function V.SyncNativeEmpty(weapon, wac, skin)
      local ctx, key = nativeContext(weapon)
      if key then
        weapon = key
      end
      if ctx and ctx.Busy then
        return
      end
      if not enabled() or not live(weapon) or not live(wac) then
        V.ClearNativeEmpty(weapon);
        return
      end
      local owner = call(weapon, 'GetOwnerPawn')
      if not sameNative(owner, F.getLocalChar()) then
        V.ClearNativeEmpty(weapon);
        return
      end
      if ctx and not sameNative(ctx.WAC, wac) then
        V.ClearNativeEmpty(weapon);
        ctx = nil
      end
      if not ctx then
        ctx = {
          WAC = wac,
          Base = {},
          Applied = {}
        };
        V.NativeEmpty[weapon] = ctx
      end
      ctx.Skin = skin;
      ctx.Busy = true;
      ctx.Unresolved = nil
      local ok, err = pcall(function()
        local sockets = import('EWeaponAttachmentSocketType')
        local baseID = tonumber(call(weapon, 'GetWeaponID')) or tonumber(field(call(weapon, 'GetItemDefineID'), 'TypeSpecificID'))
        local loaded = tonumber(field(wac, 'CachedLoadedID'))
        local bare = baseID and loaded == baseID
        local full = fullEnabled()
        for slot = 0, 4 do
          local nativeSlot = field(sockets, enumNames[slot]);
          if nativeSlot == nil then
            nativeSlot = slot
          end
          local comp = nativePart(wac, nativeSlot)
          local id, source, defaultID = V.EquippedID(weapon, nativeSlot)
          local empty = source == 'native_default_attachment' or source == 'no_equipped_handle' or source == 'not_in_attached_inventory'
          local owned = ctx.Applied[slot]
          if owned and ( not sameNative(owned.Component, comp) or id > 0 or full or not empty) then
            restoreEmptySlot(owned);
            ctx.Applied[slot] = nil;
            owned = nil
          end
          local sm = field(comp, 'StaticMesh');
          local sk = field(comp, 'SkeletalMesh')
          local skeletal = not live(sm) and live(sk);
          local mesh = skeletal and sk or sm
          if bare and empty and live(comp) and live(mesh) then
            local materials = {}
            local count = math.min(tonumber(call(comp, 'GetNumMaterials')) or 0, 16)
            for index = 0, count - 1 do
              materials[index] = call(comp, 'GetMaterial', index)
            end
            ctx.Base[slot] = { Mesh = mesh, Skeletal = skeletal, Materials = materials }
          end
          if not full and empty and live(comp) then
            local baseline = ctx.Base[slot]
            if baseline and baseline.Skeletal ~= skeletal then
              baseline = nil
            end
            if not baseline and (slot == 2 or slot == 3 or slot == 4) and source == 'native_default_attachment' and defaultID >= 200000 and defaultID < 300000 then
              local desc = V.Asset(defaultID, skeletal)
              if desc and live(desc.Mesh) and desc.Skeletal == skeletal then
                baseline = desc
              end
            end
            local materials = baseline and baseline.Materials
            if baseline and not materials and live(baseline.Material) then
              local index = materialIndex(comp, baseline.MaterialSlotName)
              if index >= 0 then
                materials = { [index] = baseline.Material }
              end
            end
            local differs = baseline and mesh ~= baseline.Mesh
            for index, mat in pairs(materials or {}) do
              if call(comp, 'GetMaterial', index) ~= mat then
                differs = true
              end
            end
            if baseline and live(mesh) and differs then
              if not owned then
                owned = {
                  Component = comp,
                  Original = mesh,
                  Skeletal = skeletal,
                  Materials = {}
                };
                ctx.Applied[slot] = owned
              end
              local method = skeletal and 'SetSkeletalMesh' or 'SetStaticMesh'
              if type(field(comp, method)) == 'function' then
                if owned.Applied and mesh ~= owned.Applied then
                  owned.Original = mesh
                end
                local count = math.min(tonumber(call(comp, 'GetNumMaterials')) or 0, 16)
                for index = 0, count - 1 do
                  local current = call(comp, 'GetMaterial', index);
                  local saved = owned.Materials[index]
                  if not saved then
                    owned.Materials[index] = { Original = current }
                  elseif saved.Applied and current ~= saved.Applied then
                    saved.Original = current
                  end
                end
                if mesh ~= baseline.Mesh then
                  setMesh(comp, baseline.Mesh, skeletal)
                end
                owned.Applied = baseline.Mesh
                if not baseline.Materials and type(field(comp, 'ClearOverrideMaterials')) == 'function' then
                  comp:ClearOverrideMaterials()
                end
                for index, mat in pairs(materials or {}) do
                  if type(field(comp, 'SetMaterial')) == 'function' then
                    comp:SetMaterial(index, mat)
                  end
                end
                for index, saved in pairs(owned.Materials) do
                  saved.Applied = call(comp, 'GetMaterial', index)
                end
              end
            elseif not baseline and (slot == 0 or slot == 1) and type(field(comp, 'SetHiddenInGame')) == 'function' then
              local hidden = field(comp, 'bHiddenInGame')
              if type(hidden) == 'boolean' and hidden ~= true then
                if not owned then
                  owned = { Component = comp };
                  ctx.Applied[slot] = owned
                end
                owned.WasHidden = hidden;
                owned.Hidden = true;
                comp:SetHiddenInGame( true, false)
              end
            elseif not baseline and (slot == 2 or slot == 3 or slot == 4) then
              ctx.Unresolved = 'default_base_mesh_unavailable:' .. slot
            end
          end
        end
        local delegate = field(wac, 'OnWeaponPartsRender')
        if not ctx.Callback and delegate and type(field(delegate, 'Add')) == 'function' then
          local callback = function()
            if V.NativeEmpty[weapon] ~= ctx or ctx.Busy then
              return
            end
            pcall(V.SyncNativeEmpty, weapon, wac, ctx.Skin)
          end
          local added, handle = pcall(delegate.Add, delegate, callback)
          if added and handle ~= false then
            ctx.Delegate = delegate;
            ctx.Callback = callback;
            ctx.Handle = handle
          end
        end
      end)
      ctx.Busy = false;
      ctx.Error = not ok and tostring(err) or nil
      local issue = ctx.Error or ctx.Unresolved
      ctx.LastIssue = issue
    end
    function V.Apply(weapon, skin, wac)
      if not enabled() or not live(weapon) or ( not fullEnabled() and not realSkinEnabled()) then
        V.Status = 'disabled_or_invalid_weapon';
        V.Clear(weapon);
        return false
      end
      local owner = call(weapon, 'GetOwnerPawn')
      if not live(owner) or not sameNative(owner, F.getLocalChar()) then
        V.Status = 'not_local_owner';
        V.Clear(weapon);
        return false
      end
      local inspect = _G.OwenWeaponInspect
      if inspect and inspect.IsPlaying and inspect.IsPlaying(owner) then
        V.Status = 'inspect_in_progress';
        return false
      end
      local current, source = V.CurrentWeapon(owner)
      local held = sameNative(current, weapon)
      if not held and not inventoryHas(owner, weapon) then
        V.Clear(weapon);
        return false
      end
      V.IsHeld = held
      V.CurrentSource = source;
      V.LastSkin = skin
      wac = wac or field(weapon, 'WeaponAvatarComponent')
      if not live(wac) then
        V.Status = 'avatar_not_ready';
        V.Clear(weapon);
        return false
      end
      local sockets = import('EWeaponAttachmentSocketType')
      local parent = field(wac, 'MasterBoneComponent')
      if not live(parent) then
        V.Status = 'parent_mesh_not_ready';
        V.Clear(weapon);
        return false
      end
      local full = fullEnabled()
      local realEnabled = realSkinEnabled()
      V.SyncNativeEmpty(weapon, wac, skin)
      local equipped, equipmentSources = {}, {}
      if not full then
        local attached = false
        for slot = 0, 4 do
          local nativeSlot = field(sockets, enumNames[slot]);
          if nativeSlot == nil then
            nativeSlot = slot
          end
          local id, source = V.EquippedID(weapon, nativeSlot)
          equipped[slot], equipmentSources[slot] = id, source
          if id > 0 then
            attached = true
          end
        end
        if not attached then
          V.Clear(weapon, true);
          V.Status = 'real_only_no_attachments';
          V.EquipmentSources = equipmentSources
          return false
        end
      end
      V.Status = 'no_matching_attachment';
      V.LastError = nil
      local st = V.Weapons[weapon]
      if not st then
        for key, value in pairs(V.Weapons) do
          if sameNative(key, weapon) then
            V.Weapons[key] = nil;
            V.Weapons[weapon] = value;
            st = value;
            break
          end
        end
      end
      if st and (st.Skin ~= skin or not sameNative(st.Parent, parent)) then
        V.Clear(weapon);
        st = nil
      end
      if not st then
        st = {
          Skin = skin,
          Parent = parent,
          Parts = {},
          RealParts = {},
          Failures = {},
          Diagnostics = {},
          EmptyChoices = {}
        };
        V.Weapons[weapon] = st
      end
      st.EmptyChoices = st.EmptyChoices or {} st.Diagnostics = st.Diagnostics or {};
      V.Diagnostics = st.Diagnostics
      st.RealParts = st.RealParts or {}
      if not full then
        for slot, part in pairs(st.Parts) do
          destroy(part);
          st.Parts[slot] = nil
        end
        st.EmptyChoices = {}
      end
      local dyn, defaults = FullDynamicMap(skin), FullDefaultMap(skin)
      if not st.ParentCandidates or _G.RealNow() >= (st.NextCandidateScan or 0) then
        st.CandidateDynamic = dyn;
        st.CandidateDefault = defaults;
        st.NextCandidateScan = _G.RealNow() + 2
        st.ParentCandidates = {};
        local seen = {}
        for _, mapping in ipairs( {
          dyn or {},
          defaults or {}
        }) do
          local count = 0
          for rawBase, rawTarget in pairs(mapping) do
            count = count + 1;
            if count > 64 or # st.ParentCandidates >= 8 then
              break
            end
            local base, target = tonumber(rawBase), tonumber(rawTarget)
            if base and target and target ~= base and not (_G.BaseAttachToIndex and _G.BaseAttachToIndex[base]) and not seen[target] then
              seen[target] = true;
              st.ParentCandidates[ # st.ParentCandidates + 1] = target
            end
          end
        end
      end
      st.ParentMap = st.ParentMap or {};
      st.RoleMap = st.RoleMap or {};
      st.ParentResolved = st.ParentResolved or {};
      local changed = false
      for _, target in ipairs(st.ParentCandidates) do
        if not st.ParentResolved[target] then
          local descriptor = V.Asset(target)
          local parent = descriptor and descriptor.ParentID
          if descriptor then
            st.ParentResolved[target] = true
          end
          if parent and parent >= 200000 and parent < 300000 then
            st.ParentMap[parent] = target;
            changed = true
          end
          local role = descriptor and descriptor.NativeRole
          if role then
            if st.RoleMap[role] and st.RoleMap[role] ~= target then
              st.RoleMap[role] = false
            elseif st.RoleMap[role] ~= false then
              st.RoleMap[role] = target
            end
          end
        end
      end
      if next(st.ParentMap) then
        if changed or st.DynamicSource ~= dyn or not st.EffectiveMap then
          st.EffectiveMap = {};
          st.DynamicSource = dyn
          for base, target in pairs(st.ParentMap) do
            st.EffectiveMap[base] = target
          end
          for base, target in pairs(dyn or {}) do
            st.EffectiveMap[base] = target
          end
        end
        dyn = st.EffectiveMap
      end
      local created = false
      for slot = 0, 4 do
        local nativeSlot = field(sockets, enumNames[slot]);
        if nativeSlot == nil then
          nativeSlot = slot
        end
        local row = weapon.synData and weapon.synData:Get(nativeSlot);
        local ref = FullRef(row)
        local avatarID = tonumber(ref and ref.TypeSpecificID) or 0
        local id = full and avatarID or (equipped[slot] or 0)
        local diag = st.Diagnostics[slot];
        if not diag then
          diag = {};
          st.Diagnostics[slot] = diag
        end
        diag.Material = nil;
        diag.AvatarID = avatarID
        diag.EquipmentSource = full and 'full_avatar_mode' or equipmentSources[slot]
        diag.Role, diag.NativeSlot, diag.ID, diag.Target, diag.Outcome, diag.AssetKey = enumNames[slot], nativeSlot, id, nil, 'no_mapping', nil
        local part = st.Parts[slot]
        if id > 0 and realEnabled then
          destroy(part);
          st.Parts[slot] = nil
          local base = FullRecoverBase(skin, id, slot, dyn, defaults)
          local target = FullTargetForBase(skin, base, dyn, defaults)
          if not target then
            target = FullTargetForBase(skin, base, st.ParentMap, nil)
          end
          if not target and (slot == 2 or slot == 3) then
            target = st.RoleMap[enumNames[slot]] or nil
          end
          diag.Target = target
          local getter = wac.GetMeshCompBySlotID or wac.GetMeshCompbySlotID
          local comp = type(getter) == 'function' and getter(wac, nativeSlot) or nil
          if not live(comp) and wac.GetAvatarEntity then
            local entity = wac:GetAvatarEntity(nativeSlot, - 1);
            comp = live(entity) and field(entity, 'MeshComponent')
          end
          local real = st.RealParts[slot]
          if real and ( not sameNative(real.Component, comp) or real.ID ~= id or real.Target ~= target) then
            restore(real);
            st.RealParts[slot] = nil;
            real = nil
          end
          if target and live(comp) then
            local preferSkeletal = type(field(comp, 'SetSkeletalMesh')) == 'function' and type(field(comp, 'SetStaticMesh')) ~= 'function'
            diag.AssetKey = preferSkeletal and tostring(target) .. ':sk' or target
            local desc = previewPart(skin, slot, target) or V.Asset(target, preferSkeletal)
            if desc and live(desc.Mesh) then
              local key = desc.Skeletal and 'SkeletalMesh' or 'StaticMesh'
              local setter = desc.Skeletal and comp.SetSkeletalMesh or comp.SetStaticMesh
              local current = field(comp, key)
              if type(setter) == 'function' and live(current) then
                if not real then
                  real = { Component = comp, ID = id, Target = target, Original = current, Skeletal = desc.Skeletal };
                  st.RealParts[slot] = real
                end
                if current ~= desc.Mesh then
                  if real.Applied and current ~= real.Applied then
                    real.Original = current
                  end
                  if comp.ClearOverrideMaterials and comp.GetNumMaterials and comp.GetMaterial then
                    real.Materials = real.Materials or {}
                    for index = 0, math.min(tonumber(comp:GetNumMaterials()) or 0, 16) - 1 do
                      local saved = real.Materials[index];
                      local mat = comp:GetMaterial(index)
                      if not saved then
                        real.Materials[index] = { Original = mat }
                      elseif saved.Applied and mat ~= saved.Applied then
                        saved.Original = mat
                      end
                    end
                  end
                  local ok, err = pcall(setMesh, comp, desc.Mesh, desc.Skeletal)
                  if ok and sameNative(field(comp, key), desc.Mesh) then
                    real.Applied = desc.Mesh
                    if comp.ClearOverrideMaterials and real.Materials then
                      call(comp, 'ClearOverrideMaterials')
                      for index, saved in pairs(real.Materials) do
                        saved.Applied = comp:GetMaterial(index)
                      end
                    end
                    if desc.FromLobby then
                      V.PreviewUsed = (V.PreviewUsed or 0) + 1
                    end
                  else
                    V.LastError = ok and 'attachment_mesh_write_not_confirmed:' .. tostring(target) or tostring(err)
                  end
                else
                  real.Applied = desc.Mesh
                end
                if real.Applied and sameNative(field(comp, key), real.Applied) and desc.FromLobby and comp.GetMaterial and comp.SetMaterial then
                  real.Materials = real.Materials or {}
