    end
    local function active()
      return not F.skinOff() and F.isInRealMatch()
    end
    function F.getExtraMatchRes(slot, subtype)
      local res = tonumber((PERSIST.configSlots or {})[slot]) or tonumber(F.cache()[slot .. 'Res'])
      if not res or res <= 0 or tonumber(F.subType(F.cfg(res))) ~= subtype then
        return nil
      end
      return res
    end
    local function ready(res, fn)
      if F.isResourcesReady(res) then
        return true
      end
      F.requestResourceDownload(res, function()
        if active() then
          pcall(fn)
        end
      end)
      return false
    end
    function F.applyMatchConsumables(pc)
      if not active() or not same(pc, F.getPC()) then
        return false
      end
      local avatar = pc.InitialConsumableAvatar
      if not avatar then
        return false
      end
      local record = state[pc] or {};
      state[pc] = record
      local changed = false
      for _, spec in pairs(throwSlots) do
        local res = F.getExtraMatchRes(spec[1], spec[2]);
        local field = spec[3]
        if res and ready(res, function()
          F.applyMatchConsumables(pc)
        end) then
          if not record[field] then
            record[field] = { Original = avatar[field] }
          end
          if tonumber(avatar[field]) ~= res then
            avatar[field] = res;
            changed = true
          end
          record[field].Applied = res
          if record[field].Registered ~= res and pc.AddToGrenadeAvatarItemList then
            pc:AddToGrenadeAvatarItemList(res);
            record[field].Registered = res
          end
        end
      end
      if changed then
        pc.InitialConsumableAvatar = avatar
      end
      if F.prepareFragBoundVisual then
        pcall(F.prepareFragBoundVisual)
      end
      return true
    end
    function F.applyMatchExtraCosmetics(char)
      if not active() or not same(char, F.getLocalChar()) then
        return false
      end
      local comp = F.getAvatarComp2(char);
      local complete = F.applySelectedAppearance(char)
      if comp and slua.isValid(comp) then
        local record = state[comp] or {};
        state[comp] = record
        local function apply(slot, subtype, field, notify, method)
          local res = F.getExtraMatchRes(slot, subtype)
          if not res then
            return
          end
          if not ready(res, function()
            F.applyMatchExtraCosmetics(char)
          end) then
            complete = false;
            diagnostic(slot, res, 'download_pending');
            return
          end
          local mgr = managers[comp] or comp.AdditionEffectMgr
          if not mgr then
            complete = false;
            diagnostic(slot, res, 'manager_missing');
            return
          end
          if not record[field] then
            record[field] = { Original = comp[field] }
          end
          local old = comp[field]
          if tonumber(comp[field]) ~= res then
            comp[field] = res
          end;
          record[field].Applied = res
          if tonumber(mgr[field]) ~= res then
            local ok, err = pcall(function()
              if mgr[method] then
                mgr[method](mgr, res)
              elseif comp[notify] then
                comp[notify](comp, old)
              else
                error('effect_setter_missing')
              end
            end)
            if not ok then
              complete = false;
              diagnostic(slot, res, 'apply_error', tostring(err));
              return
            end
          end
          local handle = mgr.HandleMap and mgr.HandleMap[res]
          local entries = mgr.ItemEffectMap and mgr.ItemEffectMap[res]
          if mgr.HandleMap then
            if not handle then
              diagnostic(slot, res, 'handle_pending');
              complete = false
            elseif not entries or # entries == 0 then
              diagnostic(slot, res, 'effect_config_empty');
              complete = false
            else
              diagnostic(slot, res, 'loaded')
            end
          else
            diagnostic(slot, res, 'setter_applied')
          end
        end
        apply('runTrail', 453, 'MoveEffectItem', 'OnRep_MoveEffectItem', 'SetMoveEffectItem')
        apply('footprint', 454, 'FootStepEffectItem', 'OnRep_FootStepEffectItem', 'SetFootStepEffectItem')
        local foot = F.getExtraMatchRes('footEffect', 423)
        if foot then
          local enums = import('EAvatarSlotType')
          local slot = enums and enums.EAvatarSlotType_FootEffectEquipemtSlot
          if slot then
            if ready(foot, function()
              F.applyMatchExtraCosmetics(char)
            end) then
              if record.FootApplied ~= foot then
                if F.matchApplyWearItem(char, foot, slot, 'FootEffect') then
                  record.FootApplied = foot
                else
                  complete = false
                end
              end
            else
              complete = false
            end
          else
            complete = false
          end
        end
      elseif F.getExtraMatchRes('runTrail', 453) or F.getExtraMatchRes('footprint', 454) or F.getExtraMatchRes('footEffect', 423) then
        complete = false
      end
      local pc = F.getPC()
      if pc and slua.isValid(pc) then
        F.applyMatchConsumables(pc)
      end
      return complete
    end
    function F.applyMatchThrowWeapon(weapon)
      if not active() or not weapon or not slua.isValid(weapon) then
        return false
      end
      local def = weapon.GetItemDefineID and weapon:GetItemDefineID()
      local spec = def and throwSlots[tonumber(def.TypeSpecificID)]
      if not spec then
        return false
      end
      local owner = weapon.GetOwnerPawn and weapon:GetOwnerPawn() or (weapon.GetOwner and weapon:GetOwner())
      if not same(owner, F.getLocalChar()) then
        return false
      end
      local res = F.getExtraMatchRes(spec[1], spec[2]);
      if not res then
        return false
      end
      if not ready(res, function()
        F.applyMatchThrowWeapon(weapon)
      end) then
        return false
      end
      F.applyMatchConsumables(F.getPC())
      local comp = weapon.GrenadeAvatarComponent or weapon.GrenadeAvatarComponent_BP
      if not comp or not slua.isValid(comp) then
        return false
      end
      local record = state[comp] or {};
      state[comp] = record
      if record.Skin == res then
        return false
      end
      if comp.ChangeItemAvatar then
        comp:ChangeItemAvatar(res, false)
      elseif comp.PreChangeGrenadeAvatar then
        comp:PreChangeGrenadeAvatar(res)
      else
        return false
      end
      record.Skin = res;
      return true
    end
    local function nativeObject(object)
      if not object then
        return nil
      end
      local ok, value = pcall(function()
        return object.Object
      end)
      return ok and value or object
    end
    local function valid(object)
      local native = nativeObject(object);
      if not native then
        return false
      end
      local ok, result = pcall(slua.isValid, native);
      return ok and result == true
    end
    local function localProjectile(object)
      return active() and valid(object) and object.GetInstigatorControllerSafety and same(object:GetInstigatorControllerSafety(), F.getPC())
    end
    function F.applyProjectileFlightSkin(object)
      if not localProjectile(object) then
        return false
      end
      local comp = object.GrenadeAvatarComponent_BP
      if not valid(comp) or not comp.ChangeItemAvatar then
        return false
      end
      local selected = object.GetAvatarID and object:GetAvatarID(F.getPC().InitialConsumableAvatar) or 0
      local subtype = tonumber(F.subType(F.cfg(selected)))
      local spec
      for _, candidate in pairs(throwSlots) do
        if candidate[2] == subtype then
          spec = candidate;
          break
        end
      end
      if not spec then
        return false
      end
      local res = F.getExtraMatchRes(spec[1], spec[2]);
      if not res then
        return false
      end
      local record = state[object] or {};
      state[object] = record
      if record.FlightSkin ~= res then
        record.FlightSkin = res;
        record.FlightAttempts = 0;
        record.FlightPending = nil
      end
      if record.FlightApplying or record.FlightPending then
        return false
      end
      if comp.GetCurGrenadeAvatarID and tonumber(comp:GetCurGrenadeAvatarID()) == res then
        return true
      end
      if not F.isResourcesReady(res) then
        record.FlightPending = res diagnostic('projectile_flight', res, 'resource_pending')
        F.requestResourceDownload(res, function()
          if record.FlightPending ~= res then
            return
          end
          record.FlightPending = nil
          if localProjectile(object) and F.getExtraMatchRes(spec[1], spec[2]) == res and same(object.GrenadeAvatarComponent_BP, comp) then
            pcall(F.applyProjectileFlightSkin, object)
          end
        end)
        return false
      end
      if (record.FlightAttempts or 0) >= 3 then
        diagnostic('projectile_flight', res, 'retry_limit');
        return false
      end
      record.FlightAttempts = (record.FlightAttempts or 0) + 1;
      record.FlightApplying = true
      local ok, err = pcall(comp.ChangeItemAvatar, comp, res, false)
      record.FlightApplying = nil diagnostic('projectile_flight', res, ok and 'avatar_requested' or 'avatar_error', not ok and tostring(err) or nil)
      return ok
    end
    function F.syncProjectileEffects(object, phase)
      if not localProjectile(object) then
        return false
      end
      local comp = object.GrenadeAvatarComponent_BP
      if not valid(comp) then
        return false
      end
      local skin = comp.GetCurGrenadeAvatarID and comp:GetCurGrenadeAvatarID() or 0
      local selected = object.GetAvatarID and object:GetAvatarID(F.getPC().InitialConsumableAvatar) or 0
      local subtype = tonumber(F.subType(F.cfg(selected))) or 0
      local key = 'projectile_' .. tostring(subtype) .. '_' .. phase
      local ok, err = pcall(function()
        if object.ResetGrenadeAvatar then
          object:ResetGrenadeAvatar()
        end
      end)
      diagnostic(key, skin, ok and 'resource_map_refreshed' or 'refresh_error', ok and nil or tostring(err))
      local entry = diagnostics[key];
      entry.FxIndex = comp.OverrideFXIndex;
      entry.Selected = selected
      local fields = {};
      local map = comp.AssetObjectMap
      local resources = object.GetGrenadeAvatarResourceMap and object:GetGrenadeAvatarResourceMap()
      if map and map.Get and type(resources) == 'table' then
        for source, target in pairs(resources) do
          local assetOK, asset = pcall(map.Get, map, source)
          fields[ # fields + 1] = tostring(source) .. ':' .. tostring(assetOK and valid(asset)) .. '/applied:' .. tostring(valid(object[target]))
        end
      end
      entry.Fields = table.concat(fields, ',')
      return ok
    end
    function F.applySmokeProjectileVisual(object, inActive)
      if not localProjectile(object) then
        return false
      end
      local res = F.getExtraMatchRes('smokeSkin', 613);
      if not res then
        return false
      end
      local ok, config = pcall(require, 'GameLua.Mod.BaseMod.GamePlay.Actor.Projectile.SpecificProjectile.SmokeBomb.SmokeBombConfig')
      local effect = ok and config and config.SkinIDToEffect and config.SkinIDToEffect[res]
      if not effect then
        diagnostic('smoke_effect', res, 'no_visual_mapping');
        return false
      end
      local record = state[object] or {};
      state[object] = record
      if record.SmokeSkin ~= res then
        record.SmokeSkin = res;
        record.SmokeRequests = {}
      end
      local requests = record.SmokeRequests
      local function apply(field, path, activate)
        local component = object[field]
        if not path or path == '' or not valid(component) or not component.SetTemplate then
          return
        end
        local item = requests[field]
        if item and item.Asset and item.Path == path then
          if component.Template ~= item.Asset then
            component:SetTemplate(item.Asset)
          end
          if activate and not item.Activated and component.SetActive then
            component:SetActive( true, true);
            item.Activated = true
          end
          return
        end
        if item and item.Path == path and item.Pending then
          item.ActivateWanted = item.ActivateWanted or activate;
          return
        end
        item = { Path = path, Pending = true, ActivateWanted = activate };
        requests[field] = item
        local loader = object.AsyncLoadAsset
        if not loader then
          item.Pending = false;
          diagnostic('smoke_effect', res, 'loader_missing');
          return
        end
        diagnostic('smoke_effect', res, 'asset_pending')
        local loaded, err = pcall(loader, object, path, function(asset)
          item.Pending = false
          if not localProjectile(object) or F.getExtraMatchRes('smokeSkin', 613) ~= res or requests[field] ~= item then
            return
          end
          if not valid(asset) then
            diagnostic('smoke_effect', res, 'asset_missing', path);
            return
          end
          local target = object[field];
          if not valid(target) or not target.SetTemplate then
            return
          end
          local previous = state[target] or {};
          state[target] = previous
          if not previous.SmokeTemplate then
            previous.SmokeTemplate = { Original = target.Template }
          end
          target:SetTemplate(asset);
          previous.SmokeTemplate.Applied = asset;
          item.Asset = asset
          if item.ActivateWanted and target.SetActive then
            target:SetActive( true, true);
            item.Activated = true
          end
          diagnostic('smoke_effect', res, 'template_applied')
        end)
        if not loaded then
          item.Pending = false;
          diagnostic('smoke_effect', res, 'load_error', tostring(err))
        end
      end
      apply('Smoking', effect.SmokeParticlePath, inActive == true)
      if not inActive then
        apply('P_White_Smoke_02', effect.SmokeTailParticlePath, false)
      end
      return true
    end
    do
      local cache = {};
      local cacheCount = 0;
      local loading = 0
      local sequences = {}
      function F.clearBoundGrenadeSequences()
        for i = # sequences, 1, - 1 do
          local actor = sequences[i];
          if valid(actor) and actor.K2_DestroyActor then
            pcall(actor.K2_DestroyActor, actor)
          end
          sequences[i] = nil
        end
      end
      local function path(value)
        if type(value) == 'string' then
          return value:sub(1, 1) == '/' and value or nil
        end
        if value and value.ToString then
          local ok, text = pcall(value.ToString, value);
          if ok and type(text) == 'string' and text:sub(1, 1) == '/' then
            return text
          end
        end
      end
      function F.prepareFragBoundVisual()
        if not active() then
          return nil
        end
        local res = F.getExtraMatchRes('fragSkin', 612);
        if not res then
          return nil
        end
        local item = cache[res];
        local now = os.clock()
        if item and (valid(item.SequenceAsset) or valid(item.Asset)) then
          return item, res
        end
        if item and item.Pending and now - (item.Started or now) > 10 then
          item.Pending = false;
          item.Token = nil;
          loading = math.max(0, loading - 1)
        end
        if item and (item.Pending or now < (item.NextTry or 0)) then
          return nil, res
        end
        if not item then
          if cacheCount >= 8 then
            for key, value in pairs(cache) do
              if not value.Pending then
                cache[key] = nil;
                cacheCount = cacheCount - 1;
                break
              end
            end
            if cacheCount >= 8 then
              return nil, res
            end
          end
          item = {};
          cache[res] = item;
          cacheCount = cacheCount + 1
        end
        item.NextTry = now + 5
        if not item.Path and not item.SequencePath then
          local ok, binding = pcall(CDataTable.GetTableData, 'GrenadeKillGunBindMap', res)
          if ( not ok or not binding) and CDataTable.GetTable then
            local rowsOK, rows = pcall(CDataTable.GetTable, 'GrenadeKillGunBindMap')
            binding = rowsOK and rows and (rows[res] or rows[tostring(res)])
            ok = binding ~= nil
          end
          local candidates = {}
          local function add(list)
            if not list then
              return
            end
            if type(list) == 'table' and not list.Num then
              for i, id in ipairs(list) do
                if i > 16 then
                  break
                end;
                candidates[ # candidates + 1] = id
              end
            else
              pcall(function()
                for i = 0, math.min(list:Num(), 16) - 1 do
                  candidates[ # candidates + 1] = list:Get(i)
                end
              end)
            end
          end
          if ok and binding then
            add(binding.UnlockFxGunIDList_a or binding.UnlockFxGunIDList)
            add(binding.GunIDList_a or binding.GunIDList)
            if binding.FxGunID or binding.WeaponID then
              candidates[ # candidates + 1] = binding.FxGunID or binding.WeaponID
            end
          end
          for _, id in ipairs(candidates) do
            local rowOK, row = pcall(CDataTable.GetTableData, 'GrenadeBindWeaponFx', tonumber(id))
            if ( not rowOK or not row) and CDataTable.GetTable then
              local rowsOK, rows = pcall(CDataTable.GetTable, 'GrenadeBindWeaponFx');
              row = rowsOK and rows and (rows[tonumber(id)] or rows[tostring(id)])
            end
            local effect = row and path(row.FxPath)
            local sequence = row and path(row.FxSeqPath)
            if effect or sequence then
              item.Path = effect;
              item.SequencePath = sequence;
              item.BoundID = tonumber(id);
              break
            end
          end
          if not item.Path and not item.SequencePath then
            diagnostic('frag_bound_effect', res, 'no_visual_mapping');
            return nil, res
          end
        end
        local useSequence = item.SequencePath and not item.SequenceFailed
        local assetPath = useSequence and item.SequencePath or item.Path
        if not assetPath then
          item.SequenceFailed = nil;
          return nil, res
        end
        if loading >= 2 then
          return nil, res
        end
        pcall(function()
          local manager = require('client.slua.logic.download.puffer.puffer_manager')
          local const = require('client.slua.logic.download.puffer.puffer_const')
          local downloadType = const.ENUM_DownloadType.ODPAK
          for _, resource in ipairs( { item.BoundID, assetPath }) do
            local done = manager.GetState and const.ENUM_DownloadState and manager.GetState(downloadType, { resource }) == const.ENUM_DownloadState.Done
            if not done then
              manager.Download(downloadType, { resource })
            end
          end
        end)
        item.Pending = true;
        item.Started = now;
        local token = {};
        item.Token = token;
        loading = loading + 1 diagnostic('frag_bound_effect', res, 'asset_pending')
        local function callback(asset)
          if not item.Pending or item.Token ~= token then
            return
          end
          item.Pending = false;
          loading = math.max(0, loading - 1)
          if not active() or F.getExtraMatchRes('fragSkin', 612) ~= res then
            return
          end
          if valid(asset) then
            if useSequence then
              item.SequenceAsset = asset
            else
              item.Asset = asset
            end
            diagnostic('frag_bound_effect', res, useSequence and 'sequence_ready' or 'asset_ready')
          else
            if useSequence then
              item.SequenceFailed = true
            end
            diagnostic('frag_bound_effect', res, 'asset_missing', assetPath)
          end
        end
        local ok, err = pcall(function()
          if slua.AsyncLoadAsset then
            slua.AsyncLoadAsset(assetPath, callback)
          else
            require('client.slua_ui_framework.util').GetAssetAsync(assetPath, callback)
          end
        end)
        if not ok then
          item.Pending = false;
          loading = math.max(0, loading - 1);
          if useSequence then
            item.SequenceFailed = true
          end;
          diagnostic('frag_bound_effect', res, 'load_error', tostring(err))
        end
        return (valid(item.SequenceAsset) or valid(item.Asset)) and item or nil, res
      end
      function F.applyFragBoundParticle(object)
        if not localProjectile(object) then
          return false
        end
        local item, res = F.prepareFragBoundVisual()
        if not item or not valid(item.Asset) then
          return false
        end
        object.ExplodeParticleSystem = item.Asset diagnostic('frag_bound_effect', res, 'particle_assigned')
        return true
      end
      local function explosionLocation(object)
        local native = nativeObject(object)
        local getter = native and native.K2_GetActorLocation
        local source = 'native_actor'
        local ok, location
        if getter then
          ok, location = pcall(getter, native)
        end
        if not ok or not location then
          source = 'lua_actor';
          ok, location = pcall(object.K2_GetActorLocation, object)
        end
        if not ok or not location then
          return nil, source
        end
        local x, y, z = tonumber(location.X), tonumber(location.Y), tonumber(location.Z)
        if not x or not y or not z or x ~= x or y ~= y or z ~= z or math.abs(x) > 1e9 or math.abs(y) > 1e9 or math.abs(z) > 1e9 then
          return nil, source
        end
        return FVector(x, y, z), source
      end
      function F.playFragBoundVisual(object)
        if not localProjectile(object) then
          return false
        end
        local item, res = F.prepareFragBoundVisual();
        if not item then
          return false
        end
        local record = state[object] or {};
        state[object] = record
        if record.BoundEffectPlayed then
          return true
        end
        local location, locationSource = explosionLocation(object)
        if not location then
          diagnostic('frag_bound_effect', res, 'position_unavailable');
          return false
        end
        record.ExplosionLocation = location
        local positionText = 'source:' .. locationSource .. ',xyz:' .. tostring(location.X) .. ',' .. tostring(location.Y) .. ',' .. tostring(location.Z)
        local scaleFactor = tonumber(_G.MWConfig and _G.MWConfig.FragFxScale) or 500
        if scaleFactor ~= scaleFactor then
          scaleFactor = 500
        end
        scaleFactor = math.max(100, math.min(500, scaleFactor)) / 100
        if valid(item.SequenceAsset) and item.SequencePath then
          for i = # sequences, 1, - 1 do
            if not valid(sequences[i]) then
              table.remove(sequences, i)
            end
          end
          if # sequences >= 8 then
            local oldest = table.remove(sequences, 1);
            if valid(oldest) then
              pcall(oldest.K2_DestroyActor, oldest)
            end
          end
          local created
          local played, actor = pcall(function()
            local transformType = rawget(_G, 'FTransform') or import('Transform')
            local transform = transformType(FRotator(0, 0, 0), location, FVector(scaleFactor, scaleFactor, scaleFactor))
            local instance = Game:PlayLevelSequence(object, item.SequencePath, transform, '/Game/Arts_PlayerBluePrints/DeadBox/DeadBoxSmoke/BP_DeadBoxSmokeSeqActor.BP_DeadBoxSmokeSeqActor_C', false)
            if not valid(instance) then
              return nil
            end
            created = instance
            sequences[ # sequences + 1] = instance instance:SetLifeSpan(30)
            instance:Play(0)
            return instance
          end)
          if played and valid(actor) then
            record.BoundEffectPlayed = true;
            diagnostic('frag_bound_effect', res, 'sequence_spawned');
            diagnostics.frag_bound_effect.Fields = positionText;
            return true
          end
          if valid(created) and created.K2_DestroyActor then
            pcall(created.K2_DestroyActor, created)
          end
          for i = # sequences, 1, - 1 do
            if sequences[i] == created then
              table.remove(sequences, i)
            end
          end
          diagnostic('frag_bound_effect', res, 'sequence_spawn_failed', played and nil or tostring(actor))
          item.SequenceAsset = nil;
          item.SequenceFailed = true;
          item.NextTry = 0
          if not valid(item.Asset) then
            F.prepareFragBoundVisual();
            return false
          end
        end
        local world = object.GetWorld and object:GetWorld() or nativeObject(object)
        if not valid(world) then
          diagnostic('frag_bound_effect', res, 'world_invalid');
          return false
        end
        local particle = import('GameplayStatics').SpawnEmitterAtLocation(nativeObject(world), nativeObject(item.Asset), location, FRotator(0, 0, 0), FVector(scaleFactor, scaleFactor, scaleFactor), true)
        if not valid(particle) then
          diagnostic('frag_bound_effect', res, 'spawn_failed');
          return false
        end
        record.BoundEffectPlayed = true;
        diagnostic('frag_bound_effect', res, 'spawned');
        diagnostics.frag_bound_effect.Fields = positionText
        return true
      end
    end
    local unpackResults = table.unpack or unpack
    local function resultPack( ...)
      return { n = select('#', ...), ... }
    end
    local function projectileSkin(object)
      local comp = object.GrenadeAvatarComponent_BP or object.GrenadeAvatarComponent
      return comp and comp.GetCurGrenadeAvatarID and comp:GetCurGrenadeAvatarID() or 0
    end
    function F.finishFragBoundEffect(object)
      if not active() then
        return false
      end
      if not valid(object) then
        diagnostic('frag_explosion_callback', 0, 'actor_invalid_before_fx')
        diagnostics.frag_explosion_callback.Fields = 'lua_type:' .. type(object) .. ',native_type:' .. type(nativeObject(object))
        return false
      end
      if not localProjectile(object) then
        diagnostic('frag_explosion_callback', 0, 'local_owner_not_resolved');
        return false
      end
      local skin = projectileSkin(object)
      if tonumber(F.subType(F.cfg(skin))) ~= 612 then
        diagnostic('frag_explosion_callback', skin, 'not_frag_or_missing_item_config');
        return false
      end
      diagnostic('frag_explosion_callback', skin, 'entered')
      local ok, result = pcall(F.playFragBoundVisual, object)
