      record.InNativeExplosion = true
      local saved = {}
      local native = nativeObject(object)
      local targets = { object };
      if native ~= object then
        targets[ # targets + 1] = native
      end
      for _, target in ipairs(targets) do
        local scaleOK, scale = pcall(function()
          return target.ExplosionTemplateScale
        end)
        if scaleOK and scale ~= nil then
          local valueOK, x = pcall(function()
            return scale.X
          end)
          local zero = valueOK and type(x) == 'number' and FVector(0, 0, 0) or (type(scale) == 'number' and 0 or nil)
          if zero ~= nil then
            local setOK = pcall(function()
              target.ExplosionTemplateScale = zero
            end)
            if setOK then
              saved[ # saved + 1] = { Target = target, Key = 'ExplosionTemplateScale', Value = scale,
