        end
        for _, key in ipairs( { 'ExplosionTemplate', 'ExplodeParticleSystem' }) do
          local ok, value = pcall(function()
            return target[key]
          end)
          if ok and valid(value) then
            local cleared = pcall(function()
              target[key] = nil
            end)
            local readOK, current = pcall(function()
              return target[key]
            end)
            if cleared and readOK and current == nil then
              saved[ # saved + 1] = { Target = target, Key = key, Value = value }
            end
          end
        end
      end
      diagnostic('frag_native_visual', projectileSkin(object), # saved > 0 and 'suppressed_during_native' or 'no_exposed_visual_asset')
      local fields = {};
      for _, entry in ipairs(saved) do
        fields[ # fields + 1] = entry.Key
      end
      diagnostics.frag_native_visual.Fields = table.concat(fields, ',')
