      for _, entry in ipairs(saved) do
        if valid(entry.Target) then
          pcall(function()
            if entry.Applied ~= nil or entry.Target[entry.Key] == nil then
              entry.Target[entry.Key] = entry.Value
            end
          end)
        end
      end
      record.InNativeExplosion = nil
      if not results[1] then
