    function F.restoreMatchExtraCosmetics()
      if F.clearBoundGrenadeSequences then
        F.clearBoundGrenadeSequences()
      end
      for object, record in pairs(state) do
        if valid(object) then
          if record.BeginWrapper and object.BeginInEffect == record.BeginWrapper then
            pcall(function()
              if type(object) == 'table' then
                rawset(object, 'BeginInEffect', record.BeginOriginal)
              else
                object.BeginInEffect = record.BeginOriginal
              end
            end)
