          local changed = false
          for _, spec in pairs(throwSlots) do
            local field = spec[3];
            local entry = record[field]
            if avatar and entry and avatar[field] == entry.Applied then
              avatar[field] = entry.Original or 0;
              changed = true
            end
          end
          if changed then
            object.InitialConsumableAvatar = avatar;
            if object.InitGrenadeAvatarList then
              pcall(object.InitGrenadeAvatarList, object, false)
            end
          end
          for _, spec in ipairs( {
{ 'MoveEffectItem', 'OnRep_MoveEffectItem' },
{ 'FootStepEffectItem', 'OnRep_FootStepEffectItem' }
          }) do
            local entry = record[spec[1]]
            if entry and object[spec[1]] == entry.Applied then
              local old = object[spec[1]];
              object[spec[1]] = entry.Original or 0;
              if object[spec[2]] then
                pcall(object[spec[2]], object, old)
              end
            end
          end
        end
      end
      state = setmetatable( {}, { __mode = 'k' })
    end
    function F.hookMatchExtraCosmetics()
