  function F.weaponRefLive(obj)
    if not obj then
      return false
    end
    local ok, result = pcall(slua.isValid, obj)
    return ok and result == true
  end
  function F.weaponSkinError(err)
    local text = tostring(err)
    return debug and debug.traceback and debug.traceback(text, 2) or text
  end
  _G.OwenWeaponRestoreState = _G.OwenWeaponRestoreState or {}
  local function weaponStateKey(weapon)
    local ok, native = pcall(function()
      return weapon.Object
    end)
    return tostring(ok and native or weapon)
  end
  function F.readSynRow(array, index)
    local ok, row = pcall(function()
      return array and array:Get(index)
    end)
    if not ok or not row then
      return nil
    end
    local ref pcall(function()
      ref = slua.IndexReference(row, "defineID")
    end)
    if ref == nil then
      pcall(function()
        ref = row.defineID
      end)
    end
    return row, ref, ref and tonumber(ref.TypeSpecificID)
  end
  function F.weaponSkinBusy()
    local ok, ch = pcall(F.getLocalChar)
    if not ok or not F.weaponRefLive(ch) then
      return false
    end
    local now = _G.RealNow()
    local state = F.WeaponSkinBusy
    if not state or state.Char ~= ch then
      state = { Char = ch, Until = 0, Since = 0 };
      F.WeaponSkinBusy = state
    end
    local busy = false pcall(function()
      local function on(v)
        return v == true or v == 1
      end
      busy = on(ch.bIsGunADS) or on(ch.bIsWeaponAiming) or on(ch.bIsADS) or on(ch.bIsFiringADS) or on(ch.bIsWeaponFiring) or on(ch.bIsFiring) or on(ch.bIsReloading)
    end)
    if busy then
      if state.Since == 0 then
        state.Since = now
      end
      if now - state.Since > 5 then
        state.Since = 0;
        state.Until = 0;
        return false
      end
      state.Until = now + 0.5
      return true
    end
    state.Since = 0
    return now < state.Until
  end
  function F.captureWeaponBody(weapon, weaponId)
    if not F.weaponRefLive(weapon) then
      return nil
    end
    local key = weaponStateKey(weapon)
    local state = _G.OwenWeaponRestoreState[key]
    if state then
      return state
    end
    local _, ref0, current = F.readSynRow(weapon.synData, 7)
    local savedType = nil
    if ref0 then
      pcall(function()
        savedType = ref0.Type
      end)
    end
    state = { Weapon = weapon, WeaponId = weaponId, SkinId = current, SkinType = savedType, AppliedSkin = 0 }
    _G.OwenWeaponRestoreState[key] = state
    return state
  end
  function F.restoreWeaponBody(weapon)
    if not F.weaponRefLive(weapon) then
      return false
    end
    local key = weaponStateKey(weapon)
    local state = _G.OwenWeaponRestoreState[key]
    if not state then
      return false
    end
    _G.OwenWeaponRestoreState[key] = nil
    if not state.SkinId or state.AppliedSkin == 0 then
      return false
    end
    local row, ref, current = F.readSynRow(weapon.synData, 7)
    if not ref then
      return false
    end
    if current ~= state.AppliedSkin or current == state.SkinId then
      return false
    end
    local done = pcall(function()
      ref.TypeSpecificID = state.SkinId
      if state.SkinType ~= nil and ref.Type ~= nil then
        ref.Type = state.SkinType
      end
      if weapon.synData:Set(7, row) == false then
        error('weapon_body_restore_rejected')
      end
    end)
    if not done then
      return false
    end
    if _G.OwenWeaponApplied then
      _G.OwenWeaponApplied[weapon] = nil
    end
    local okWac, wac = pcall(function()
      return weapon.WeaponAvatarComponent
    end)
    pcall(F.refreshWeaponVisual, weapon, okWac and wac or nil, { [7] = true })
    return true
  end
  _G.OwenRestoreWeaponSkin = function(baseWeaponId)
    local restored = 0
    for key, state in pairs(_G.OwenWeaponRestoreState) do
      if not F.weaponRefLive(state.Weapon) then
        _G.OwenWeaponRestoreState[key] = nil
      elseif baseWeaponId == nil or tonumber(state.WeaponId) == tonumber(baseWeaponId) then
        if F.restoreWeaponBody(state.Weapon) then
          restored = restored + 1
        end
      end
    end
    return restored
  end
