  function F.matchApplyWeaponSkin(char)
    if not _avatarItemsRegistered then
      _avatarItemsRegistered = F.registerWeaponAvatarItems(char)
    end
    local curWeapon = char.GetCurrentWeapon and char:GetCurrentWeapon()
    if not slua.isValid(curWeapon) then
      return false
    end
    local currentVisualID = 0 pcall(function()
      local wac = curWeapon.WeaponAvatarComponent
      if slua.isValid(wac) then
        currentVisualID = wac.CachedLoadedID or 0
      end
    end)
    local curWeaponResID = 0 pcall(function()
      curWeaponResID = curWeapon:GetItemDefineID().TypeSpecificID
    end)
    local targetSkin = F.findTargetSkinForWeaponRes(curWeaponResID) or curWeaponResID
    local isVisualMatched = false
    if currentVisualID > 0 and currentVisualID == targetSkin then
      isVisualMatched = true
    end
    if not _G.SmartWeaponWatcherActive then
      pcall(function()
        local ticker = require("common.time_ticker")
        if ticker and ticker.AddTimerLoop then
          local handle = ticker.AddTimerLoop(0, function()
            if F.skinOff() then
              return
            end
            if _G.AddOutfit and not _G.AddOutfit.isInRealMatch() then
              return
            end
            local pController = F.getPC()
            if not pController or not slua.isValid(pController) then
              return
            end
            local pChar = pController:GetPlayerCharacterSafety()
            if not pChar or not slua.isValid(pChar) then
              return
            end
            local WeaponManager = pChar:GetWeaponManager()
            if not WeaponManager or not slua.isValid(WeaponManager) then
              return
            end
            local inventory = _G.OwenWeaponWatchInventory
            local nowInventory = _G.RealNow()
            if not inventory or inventory.Owner ~= pChar or inventory.Manager ~= WeaponManager or nowInventory >= (inventory.Until or 0) or not slua.isValid(inventory.List) then
              inventory = inventory or {};
              _G.OwenWeaponWatchInventory = inventory inventory.Owner, inventory.Manager = pChar, WeaponManager
              inventory.List = WeaponManager:GetAllInventoryWeaponList( false);
              inventory.Until = nowInventory + 1.11
            end
            local uWeaponList = inventory.List
            if not uWeaponList or not slua.isValid(uWeaponList) then
              return
            end
            local count = uWeaponList:Num();
            if count <= 0 then
              return
            end
            _G.OwenWeaponWatchState = _G.OwenWeaponWatchState or setmetatable( {}, { __mode = 'k' })
            local index = (_G.OwenWeaponWatchCursor or 0) % count;
            _G.OwenWeaponWatchCursor = index + 1
            local wep = uWeaponList:Get(index)
            if not slua.isValid(wep) then
              return
            end
            if wep.GetOwnerPawn and not _G.OwenCosmeticAttachments.SameNative(wep:GetOwnerPawn(), pChar) then
              if _G.OwenCosmeticAttachments then
                _G.OwenCosmeticAttachments.Clear(wep)
              end
              return
            end
            local now = _G.RealNow();
            local state = _G.OwenWeaponWatchState[wep]
            local base = wep:GetItemDefineID().TypeSpecificID
            local target = F.findTargetSkinForWeaponRes(base) or base
            local syn = F.getSynMasterSkinID(wep)
            local request = _G.OwenWeaponVisualRequests and _G.OwenWeaponVisualRequests[wep]
            local changed = not state or state.Target ~= target or state.Syn ~= syn or state.Base ~= base
            local pending = request and request.Pending and now >= (request.NextCheck or 0)
            if changed or pending then
              local ok = pcall(F.applySkinToWeapon, wep)
              if ok then
                state = state or {};
                _G.OwenWeaponWatchState[wep] = state state.Target, state.Syn, state.Base = target, F.getSynMasterSkinID(wep), base
              end
            else
              local V = _G.OwenCosmeticAttachments
              if V then
                pcall(V.Apply, wep, target, wep.WeaponAvatarComponent)
              end
            end
          end, - 1, 0.37)
          if handle ~= false then
            _G.SmartWeaponWatcherActive = true;
            _G.SmartWeaponWatcherHandle = handle
          end
        end
      end)
    end
    if isVisualMatched then
      local V = _G.OwenCosmeticAttachments
      if V then
        pcall(V.Apply, curWeapon, targetSkin, curWeapon.WeaponAvatarComponent)
      end
      _weaponApplied = true
      return true
    end
    F.buildSkinMappings()
    local okSyn = F.applySkinToWeapon(curWeapon)
    if F.getSynMasterSkinID(curWeapon) == targetSkin then
      _weaponApplied = true
    end
    return okSyn or _weaponApplied
  end
  local _matchTimer = nil
  local _matchTimerOwner = nil
  local _bootstrapPending = nil
  local _weaponApplyPending = nil
  local _matchWearDone = false
  function F.startMatchWatcher(char)
    if F.skinOff() or not F.isInRealMatch() then
      return
    end
    if _matchTimer or PERF.matchActive then
      return
    end
    if not char or not slua.isValid(char) or type(char.AddGameTimer) ~= "function" then
      return
    end
    _matchTimerOwner = char
    PERF.matchActive = true
    local skipWear = PERF.wearDoneThisMatch
    _matchWearDone = skipWear
    _avatarItemsRegistered = false
    _weaponDiagDone = false
    _weaponApplied = false
    _lastWeaponResID = 0
    local elapsed = 0
    local timerOK, timerHandle = pcall(char.AddGameTimer, char, MATCH_TICK_SEC, true, function()
      if not F.isInRealMatch() then
        F.stopMatchWatcher();
        return
      end
      elapsed = elapsed + MATCH_TICK_SEC
      local cur = F.getLocalChar()
      if not cur or not slua.isValid(cur) or cur ~= char then
        if _matchTimer and slua.isValid(char) and char.RemoveGameTimer then
          pcall(char.RemoveGameTimer, char, _matchTimer)
        end
        _matchTimer = nil;
        _matchTimerOwner = nil;
        PERF.matchActive = false
        return
      end
      if F.skinOff() then
        if _matchTimer and cur.RemoveGameTimer then
          pcall(function()
            char:RemoveGameTimer(_matchTimer)
          end)
        end
        _matchTimer = nil;
        _matchTimerOwner = nil
        PERF.matchActive = false
        return
      end
      if not _matchWearDone then
        _matchWearDone = F.matchApplyAllSlots(cur)
      end
      local extraOK, extraReady = pcall(F.applyMatchExtraCosmetics, cur)
      local hatReady = F.matchApplyHat(cur)
      local faceReady = F.matchApplyFaceWear(cur)
      if not _weaponApplied then
        F.matchApplyWeaponSkin(cur)
      end
      if F.isCharacterAirborne(cur) then
        F.applyAirborneSlots(cur, true)
      end
      if (_matchWearDone and hatReady and faceReady and _weaponApplied and extraOK and extraReady) or elapsed >= MATCH_MAX_SEC then
        if _matchWearDone then
          PERF.wearDoneThisMatch = true
        end
        if _matchTimer and cur.RemoveGameTimer then
          pcall(function()
            char:RemoveGameTimer(_matchTimer)
          end)
        end
        _matchTimer = nil;
        _matchTimerOwner = nil
        PERF.matchActive = false
      end
    end)
    if timerOK and timerHandle ~= nil and timerHandle ~= false then
      _matchTimer = timerHandle
    else
      _matchTimer = nil;
      _matchTimerOwner = nil;
      PERF.matchActive = false
    end
  end
  function F.rememberSelectedAppearance(kind)
    local ok, ad = pcall(require, 'client.logic.data.AvatarData')
    if not ok or not ad then
      return
    end
    local getter = kind == 1 and ad.GetHeadID or kind == 2 and ad.GetHairID
    if type(getter) ~= 'function' then
      return
    end
    local got, id = pcall(getter);
    id = got and tonumber(id)
    if not id or id <= 0 then
      return
    end
    F.SelectedAppearance = F.SelectedAppearance or {} F.SelectedAppearance[kind] = id
  end
  function F.applySelectedAppearance(char)
    if F.skinOff() or not F.isInRealMatch() or char ~= F.getLocalChar() then
      return false
    end
    local selected = F.SelectedAppearance
    if not selected or not next(selected) then
      return true
    end
    local comp = F.getAvatarComp2(char)
    if not comp or not slua.isValid(comp) then
      return false
    end
    local enums = import('EAvatarSlotType')
    F.SelectedAppearanceApplied = F.SelectedAppearanceApplied or setmetatable( {}, { __mode = 'k' })
    local record = F.SelectedAppearanceApplied[comp] or {};
    F.SelectedAppearanceApplied[comp] = record
    local complete = true
    for kind, id in pairs(selected) do
      local slot = kind == 1 and enums.EAvatarSlotType_HeadEquipemtSlot or kind == 2 and enums.EAvatarSlotType_HairEquipemtSlot
      if slot then
        local current
        if type(comp.GetEquippedItemDefineID3) == 'function' then
          local ok, def = pcall(comp.GetEquippedItemDefineID3, comp, slot)
          if ok and def then
            current = tonumber(def.TypeSpecificID)
          end
        end
        if current == id then
          record[kind] = id
        elseif current ~= nil or record[kind] ~= id then
          if F.matchApplyWearItem(char, id, slot, kind == 1 and 'SelectedHead' or 'SelectedHair') then
            record[kind] = id
          else
            complete = false
          end
        end
      else
        complete = false
      end
    end
    return complete
  end
  function F.installLocalAppearance()
    local ok, A = pcall(require, 'client.slua.logic.wardrobe.logic_wardrobe_appearance')
    if not ok or not A or type(A.GenerateAvatarData) ~= 'function' or type(A.PutAvatar) ~= 'function' then
      return
    end
    if A._OwenLocalAppearanceInstalled then
      return
    end
    A._OwenLocalAppearanceInstalled = true
    local function enabled()
      return not F.skinOff() and _G.OwenNeonLobbySceneAllowed() and _G.OwenLicenseValidated == true
    end
    local function supported(kind)
      return kind == 1 or kind == 2
    end
    local function compatible(data)
      local ad = require('client.logic.data.AvatarData')
      local sex = tonumber(data.Gender)
      return not sex or sex == 0 or sex == tonumber(ad.GetGameGender())
    end
    local generate, put = A.GenerateAvatarData, A.PutAvatar
    A.GenerateAvatarData = function(self, ...)
      local data = generate(self, ...)
      if enabled() and data and supported(tonumber(data.AvatarType)) and compatible(data) then
        data.Owned = true;
        data.RemainTime = 0
      end
      return data
    end
    A.PutAvatar = function(self, id, kind, bPutOn)
      kind = tonumber(kind)
      if not enabled() or not supported(kind) then
        return put(self, id, kind, bPutOn)
      end
      local data = self:GetAvatarDataById(id)
      if bPutOn == false or not data or tonumber(data.AvatarType) ~= kind or not compatible(data) then
        return false
      end
      if kind == 1 and ( not tonumber(data.ItemId) or tonumber(data.ItemId) <= 0) then
        return false
      end
      if kind == 2 and ( not tonumber(data.Hair) or tonumber(data.Hair) <= 0) then
        return false
      end
      local manager = require('client.logic.avatar.logic_team_avatar_manager')
      if not manager.GetMainAvatar() then
        return false
      end
      self.AppearanceMap = self.AppearanceMap or self:GetUserDataMap()
      self.TryAvatarMap = self.TryAvatarMap or {} self:RestoreToOrigin()
      self:ModifyAvatar(kind, data, false)
      F.rememberSelectedAppearance(kind)
      return true
    end
  end
  function F.repairLobbySelectedInstances(entity)
    if not F.lobbyWorkAllowed() or not entity or not entity.bInit then
      return false
    end
    local todo = {};
    local seen = {}
    local cache = F.cache()
    for _, slot in ipairs(PERSIST_SLOTS) do
      local selected = (slot[1] ~= 'outfit' and slot[1] ~= 'tshirt') or F.selectedLobbyClothesSlot() == slot[1]
      local res = tonumber(PERSIST.configSlots and PERSIST.configSlots[slot[1]]) or tonumber(cache[slot[2]])
      local ins = res and tonumber(R.resToIns[res])
      if selected and not F.isMatchOnlyCosmeticSlot(slot[1]) and ins and not seen[ins] and R.syntheticIns[ins] == res and not F.getSyntheticItem(ins, res) then
        seen[ins] = true;
        todo[ # todo + 1] = { res, ins }
      end
    end
    local repaired = false
    for _, item in ipairs(todo) do
      local ok, added = pcall(F.injectOne, entity, item[1], item[2])
      if ok and added and F.getSyntheticItem(item[2], item[1]) then
        repaired = true
      end
    end
    if repaired then
      F.applyPersistSlotsToCache()
      F.invalidateLobbyResolved()
      LOBBY.reapplyDone = false;
      _G.AddOutfitLobbyRestored = false
    end
    return repaired
  end
  function F.resumeLobbyInjection(now)
    if F.skinOff() or not _G.OwenNeonLobbySceneAllowed() then
      return false
    end
    now = now or _G.RealNow()
    if now < (F._LobbyInjectNext or 0) then
      return false
    end
    F._LobbyInjectNext = now + 3
    local entity = F.getEntity()
    local state = F.NeonInjectState
    if not entity then
      return false
    end
    if state and state.Entity == entity and state.Done then
      return F.repairLobbySelectedInstances(entity)
    end
    local ok, result = pcall(F.injectAll, entity)
    F.LobbyInjectError = not ok and tostring(result) or nil
    return ok and result == true
  end
  function F.onModSkinChanged(enabled)
    if not enabled and F.restoreMetroEquipmentOverrides then
      F.restoreMetroEquipmentOverrides()
    end
    if not enabled then
      F.LocalSkinSelections = {};
      F.PendingWear = {};
