      for _, name in ipairs( { 'SmartWeaponWatcherHandle', 'AddOutfitVehTickerId' }) do
        local handle = _G[name];
        if handle ~= nil then
          pcall(ticker.RemoveTimer, handle)
        end;
        _G[name] = nil
      end
    end
    _G.SmartWeaponWatcherActive = false;
    _G.OwenWeaponWatchState = nil;
    _G.OwenWeaponWatchInventory = nil
