  function F.repairAfterStaleWearReply(request, key)
    F.StaleWearRepairs = F.StaleWearRepairs or {}
    local pending = F.StaleWearRepairs[key] ~= nil
    F.StaleWearRepairs[key] = request
    if pending then
      return
    end
    F.later(0, function()
      local request = F.StaleWearRepairs[key]
      F.StaleWearRepairs[key] = nil
      if not request or not F.lobbyWorkAllowed() or F.getEntity() ~= request.Entity then
        return
      end
      local current = F.localWearRequestFor(request.ResID)
      if current ~= request or not F.isResourcesReady(request.ResID) then
        return
      end
      pcall(F.tryLocalWearByIns, request.InsID)
    end)
  end
  function F.hookPutOnRsp()
    pcall(function()
      local wl = require("client.slua.logic.wardrobe.logic_wardrobe_new")
      if wl._OwenSkinPutOnRspWrapped == wl.on_puton_rsp then
        return
      end
      local o = wl.on_puton_rsp
      if type(o) ~= "function" then
        return
      end
      local function pack( ...)
        return { n = select('#', ...), ... }
      end
      wl.on_puton_rsp = function(self, res, item, olditem, index, extra)
        local results = pack(o(self, res, item, olditem, index, extra))
        if not F.lobbyWorkAllowed() then
          return (table.unpack or unpack)(results, 1, results.n)
        end
        local cached, cacheError = pcall(function()
          if NetErrorCode_NONE == nil or res ~= NetErrorCode_NONE then
            return
          end
          if not item or not item.instid then
            return
          end
          local resID = tonumber(item.res_id)
          local insID = tonumber(item.instid)
          if not resID or not insID then
            return
          end
          local request, key = F.localWearRequestFor(resID)
          if request and request.Entity == F.getEntity() and request.ResID ~= resID then
            F.repairAfterStaleWearReply(request, key)
            return
          end
          local c = F.cfg(resID)
          local st = F.subType(c)
          if st == OUTFIT_SUB then
            F.saveEquip(resID, insID)
          elseif st == HAT_SUB or FACE_SUBS[st] or BODY_SUBS[st] or HELMET_SUBS[st] or st == PARACHUTE_SUB or F.isGlideRes(resID) or st == GLOVES_SUB then
            F.saveEquip(resID, insID)
          elseif F.isParachuteRes(resID) or F.isGlideRes(resID) then
            F.saveEquip(resID, insID)
          elseif HEAD_SUBS[st] then
            F.saveEquip(resID, insID)
          elseif GUN_SUB[st] then
            local wid = F.weaponIdFromSkin(resID)
            if wid then
              F.cacheWeaponSkinFromIns(wid, insID)
            end
          elseif st == MELEE_ID then
            F.cacheWeaponSkinFromIns(MELEE_ID, insID)
          elseif F.isInjectedIns(insID) then
            F.saveEquip(resID, insID)
          end
        end)
        if cached then
          _G.OwenSkinCacheError = nil
        else
          _G.OwenSkinCacheError = tostring(cacheError):sub(1, 256)
        end
        return (table.unpack or unpack)(results, 1, results.n)
      end
      wl._OwenSkinPutOnRspWrapped = wl.on_puton_rsp
    end)
  end
  function F.restoreLobbyClothingAfterWeapon()
    if F.skinOff() or not _G.OwenNeonLobbySceneAllowed() then
      return
    end
    if F._WeaponClothingRestoring then
      return
    end
    F._WeaponClothingGeneration = (F._WeaponClothingGeneration or 0) + 1
    local generation = F._WeaponClothingGeneration
    local entity = F.getEntity()
    local function restore()
      if generation ~= F._WeaponClothingGeneration or F._WeaponClothingRestoring then
        return
      end
      if F.skinOff() or not _G.OwenNeonLobbySceneAllowed() or F.getEntity() ~= entity then
        return
      end
      F._WeaponClothingRestoring = true
      local ok, err = pcall(function()
        F.applyPersistSlotsToCache()
        F.invalidateLobbyResolved()
        local cache = F.cache()
        for _, slot in ipairs( {
{ 'outfitIns', 'putOnOutfit' },
{ 'hatIns', 'putOnHat' },
{ 'maskIns', 'putOnRoleWear' },
{ 'glassIns', 'putOnRoleWear' },
{ 'tshirtIns', 'putOnRoleWear' },
{ 'pantsIns', 'putOnRoleWear' },
{ 'shoesIns', 'putOnRoleWear' },
{ 'glovesIns', 'putOnGloves' }
        }) do
          local ins = cache[slot[1]]
          if ins and F.isInjectedIns(ins) and type(F[slot[2]]) == 'function' then
            F[slot[2]](ins)
          end
        end
      end)
      F._WeaponClothingRestoring = false
      F.WeaponClothingRestoreError = not ok and tostring(err) or nil
    end
    local loaded, ticker = pcall(require, 'common.time_ticker')
    if loaded and ticker and type(ticker.AddTimerOnce) == 'function' then
      pcall(ticker.AddTimerOnce, 0.25, restore)
      pcall(ticker.AddTimerOnce, 1.0, restore)
    end
  end
  function F.hookWeaponPreviewClothingRestore(gun)
    if type(gun) ~= 'table' or type(gun.PutOnGunAvatar) ~= 'function' then
      return false
    end
    if gun._OwenClothingRestoreWrapper == gun.PutOnGunAvatar then
      return true
    end
    local original = gun.PutOnGunAvatar
    local function pack( ...)
      return { n = select('#', ...), ... }
    end
    gun.PutOnGunAvatar = function( ...)
      local result = pack(original( ...))
      if not F._WeaponClothingRestoring then
        pcall(F.restoreLobbyClothingAfterWeapon)
      end
      return (table.unpack or unpack)(result, 1, result.n)
    end
    gun._OwenClothingRestoreWrapper = gun.PutOnGunAvatar
    return true
  end
  function F.metroLobbyWeaponInfo(uid, info)
    if not OwenNeonAuthorized() or F.skinOff() or F.isInRealMatch() then
      return info
    end
    local mine = DataMgr and DataMgr.roleData and DataMgr.roleData.uid
    if not mine or tostring(uid) ~= tostring(mine) or type(info) ~= 'table' then
      return info
    end
    local physical = tonumber(info.itemID) or 0
    if physical <= 0 then
      return info
    end
    local base = F.resolveWeaponTypeID(physical)
    pcall(function()
      local row = CDataTable.GetTableData('XMWeaponIDMap', physical)
      if row and tonumber(row.WeaponID) then
        base = tonumber(row.WeaponID)
      end
    end)
    local skin = tonumber(F.getMatchWeaponSkin(base))
    if not skin or skin <= 0 or skin == tonumber(info.skinID) then
      return info
    end
    if F.isResourcesReady and not F.isResourcesReady(skin) then
      return info
    end
    local copy = {};
    for k, v in pairs(info) do
      copy[k] = v
    end
    copy.skinID = skin
    return copy
  end
  function F.tickMetroLobbyWeapon()
    local modules = package and package.loaded
    local mgr = modules and modules['client.slua.logic.TxMission.logic_xmission_avatar_mgr']
    if type(mgr) ~= 'table' or type(mgr.EquipWeaponBySlotID) ~= 'function' then
      return
    end
    local hook = F.MetroLobbyWeaponHook
    if not hook or hook.Manager ~= mgr or mgr.EquipWeaponBySlotID ~= hook.Wrapped then
      local original = mgr.EquipWeaponBySlotID
      local wrapped = function(uid, info, ...)
        local current = _G.AddOutfit
        local value = info
        if current and current.metroLobbyWeaponInfo then
          local ok, result = pcall(current.metroLobbyWeaponInfo, uid, info)
          if ok then
            value = result
          end
        end
        return original(uid, value, ...)
      end
      mgr.EquipWeaponBySlotID = wrapped
      hook = { Manager = mgr, Original = original, Wrapped = wrapped };
      F.MetroLobbyWeaponHook = hook
    end
    if not OwenNeonAuthorized() or F.skinOff() or F.isInRealMatch() then
      hook.Key = nil;
      return
    end
    local uid = DataMgr and DataMgr.roleData and DataMgr.roleData.uid
    local avatar = uid and mgr.avatars and mgr.avatars[tostring(uid)]
    if not avatar then
      hook.Key = nil;
      return
    end
    local team = modules['client.slua.logic.TxMission.logic_xmission_team']
    if type(team) ~= 'table' or type(team.GetEquipDataByUID) ~= 'function' or type(team.UpdateAvatar) ~= 'function' then
      return
    end
    local ok, equips = pcall(team.GetEquipDataByUID, tostring(uid))
    if not ok or type(equips) ~= 'table' then
      return
    end
    local parts = { tostring(avatar) }
    for slot, info in pairs(equips) do
      if type(info) == 'table' and tonumber(info.item_id) then
        local changed = F.metroLobbyWeaponInfo(uid, { itemID = info.item_id, skinID = info.weapon_skin })
        parts[ # parts + 1] = tostring(slot) .. ':' .. tostring(info.item_id) .. ':' .. tostring(changed.skinID)
      end
    end
    table.sort(parts)
    local key = table.concat(parts, '|')
    if hook.Key ~= key then
      local refreshed = pcall(team.UpdateAvatar, tostring(uid))
      if refreshed then
        hook.Key = key
      end
    end
  end
  function F.hookLobbyWeaponCache()
    if _G.AddOutfitLobbyWeaponCacheHooked then
      return
    end
    _G.AddOutfitLobbyWeaponCacheHooked = true pcall(function()
      local Arm = require("client.logic.armory.logic_armory")
      local oRsp = Arm.install_weapon_skin_rsp
      Arm.install_weapon_skin_rsp = function(client_data, errorCode, weapon_id, instanceID)
        oRsp(client_data, errorCode, weapon_id, instanceID)
        if not F.lobbyWorkAllowed() then
          return
        end
        if (errorCode == 0 or errorCode == NET_OK) and F.isWeaponSkinIns(instanceID) then
          F.cacheWeaponSkinFromIns(weapon_id, instanceID)
        end
      end
      local oH = Arm.HandleWeaponSkinChange
      Arm.HandleWeaponSkinChange = function(client_data, weapon_id, instanceID)
        oH(client_data, weapon_id, instanceID)
        if not F.lobbyWorkAllowed() then
          return
        end
        if F.isWeaponSkinIns(instanceID) then
          F.cacheWeaponSkinFromIns(weapon_id, instanceID)
        end
      end
    end)
    pcall(function()
      local wgl = require("client.slua.logic.wardrobe.logic_wardrobe_gun")
      F.hookWeaponPreviewClothingRestore(wgl)
      local o = wgl.on_put_on_weapon_wear_rsp
      wgl.on_put_on_weapon_wear_rsp = function(self, client_data, res, weapon_id, new_skin_id, extra_weapon_list)
        o(self, client_data, res, weapon_id, new_skin_id, extra_weapon_list)
        if not F.lobbyWorkAllowed() then
          return
        end
        if res == 0 or res == NET_OK then
          F.cacheWeaponSkinFromIns(weapon_id, new_skin_id)
        end
      end
    end)
    pcall(function()
      if not EventSystem or not EventSystem.registEvent then
        return
      end
      if EVENTTYPE_WARDROBE and EVENTID_WARDROBE_UPDATE_CURRENT_PUT_ON_GUN then
        EventSystem:registEvent(EVENTTYPE_WARDROBE, EVENTID_WARDROBE_UPDATE_CURRENT_PUT_ON_GUN, function(_, _, resOrFlag, weapon_id)
          if not F.lobbyWorkAllowed() then
            return
          end
          weapon_id = tonumber(weapon_id)
          if weapon_id and weapon_id > 0 then
            pcall(function()
              local wgl = require("client.slua.logic.wardrobe.logic_wardrobe_gun")
              local insID = tonumber(wgl:GetSkinIdByWeaponID(weapon_id)) or 0
              if insID > 0 then
                F.cacheWeaponSkinFromIns(weapon_id, insID)
              end
            end)
          elseif tonumber(resOrFlag) and tonumber(resOrFlag) > 100000 then
            pcall(function()
              local wid = F.weaponIdFromSkin(resOrFlag)
              if wid then
                local wd = require("client.slua.logic.wardrobe.wardrobe_data")
                local ins = wd.GetWardrobeInsIdByResId and wd:GetWardrobeInsIdByResId(resOrFlag)
                if ins and ins > 0 then
                  F.cacheWeaponSkinFromIns(wid, ins)
                end
              end
            end)
          end
        end)
      end
    end)
    pcall(function()
      local WRH = require("client.network.Protocol.WardRobeHandler")
      local oHeadReq = WRH.send_depot_set_head_show_req
      WRH.send_depot_set_head_show_req = function(insID)
        if not F.lobbyWorkAllowed() then
          return oHeadReq(insID)
        end
        insID = tonumber(insID) or 0
        if insID > 0 and F.isInjectedIns(insID) then
          local wd = require("client.slua.logic.wardrobe.wardrobe_data")
          local d = wd:GetHallDepotItemDataByInsID(insID)
          if d and d.resID then
            F.saveEquip(tonumber(d.resID), insID)
          end
          local fbd = require("client.slua.logic.wardrobe.fashionbag.fashionbag_data")
          fbd:SetHeadShow(insID)
          WRH.on_depot_set_head_show_rsp(NET_OK, insID)
          return
        end
        return oHeadReq(insID)
      end
      local oHead = WRH.on_depot_set_head_show_rsp
      WRH.on_depot_set_head_show_rsp = function(err_code, id)
        oHead(err_code, id)
        if not F.lobbyWorkAllowed() then
          return
        end
        if err_code ~= 0 and err_code ~= NET_OK then
          return
        end
        id = tonumber(id) or 0
        if id <= 0 then
          return
        end
        local wd = require("client.slua.logic.wardrobe.wardrobe_data")
        local d = wd:GetHallDepotItemDataByInsID(id)
        if d and d.resID then
          local st = tonumber(d.itemSubType or F.subType(F.cfg(d.resID)))
          if st == HAT_SUB or HELMET_SUBS[st] then
            F.saveEquip(tonumber(d.resID), id)
          end
        end
      end
    end)
  end
  function F.hookWardrobePutOnReq()
    pcall(function()
      local wl = require('client.slua.logic.wardrobe.logic_wardrobe_new')
      if wl._OwenSkinPutOnReqWrapped == wl.wardrobe_puton_req then
        return
      end
      local original = wl.wardrobe_puton_req
      if type(original) ~= 'function' then
        return
      end
      wl.wardrobe_puton_req = function(self, insID, extra, ...)
        if F.isSyntheticIns(insID) then
          return F.selectLocalSkin(insID)
        end
        pcall(F.cancelLocalSkinSelection, insID)
        return original(self, insID, extra, ...)
      end
      wl._OwenSkinPutOnReqWrapped = wl.wardrobe_puton_req
    end)
  end
  local _bootstrapNotified = false
  function F.bootstrapMatch(char)
    char = char or F.getLocalChar()
    if not char or not slua.isValid(char) then
      return false
    end
    if F.skinOff() then
      return false
    end
    if PERF.matchActive then
      return true
    end
    local now = _G.RealNow()
    if (now - PERF.lastBootstrapAt) < BOOTSTRAP_COOLDOWN then
      return false
    end
    PERF.lastBootstrapAt = now
    _G.OwenSkinBootstrappedPawn = char F.syncWeaponCacheFromLobby( true)
    F.applyPersistSlotsToCache()
    F.cleanArmoryPollution()
    F.syncGlobalWearSkins()
    pcall(F.hookMatchExtraCosmetics)
    pcall(F.applyMatchExtraCosmetics, char)
    pcall(F.airborneCosmeticTick, char)
    F.syncVehicleCacheFromDataMgr()
    F.syncVehicleSlotsToDataMgr()
    pcall(F.applyVehicleSkinsToPC, F.getPC())
    F.startVehicleSkinTicker()
    pcall(function()
      local v = F.getMatchVehicle()
      if slua.isValid(v) then
        F.autoApplyVehicleSkinOnEnter(v)
      end
    end)
    _weaponApplied = false
    _weaponDiagDone = false
    _matchApplied = false
    if not _bootstrapNotified then
      _bootstrapNotified = true
    end
    F.startMatchWatcher(char)
    return true
  end
  function F.hookMatchAvatar()
    pcall(function()
      local CAC = require("GameLua.Mod.Library.GamePlay.Avatar.Component.CharacterAvatarComponent")
      local o = CAC.OnAvatarAllMeshLoadedLua
      CAC.OnAvatarAllMeshLoadedLua = function(self, ...)
        local results
        if type(o) == "function" then
          results = table.pack(o(self, ...))
        end
        pcall(function()
          if F.skinOff() then
            return
          end
          if self.IsLobbyActor and self:IsLobbyActor() then
            return
          end
          local isSelf = self.IsSelf and self:IsSelf()
          if not isSelf then
            return
          end
          pcall(F.onMatchHeadwearMeshReady, self)
          if F.EquipmentSkinState then
            F.EquipmentSkinState.Next = 0
          end
          if PERF.wearDoneThisMatch or PERF.matchActive then
            return
          end
          local char = F.getLocalChar()
          if char and char.AddGameTimer and _bootstrapPending ~= char then
            _bootstrapPending = char
            local timerOK, timerHandle = pcall(char.AddGameTimer, char, 0.5, false, function()
              if _bootstrapPending ~= char then
                return
              end;
              _bootstrapPending = nil
              if slua.isValid(char) and F.getLocalChar() == char and not F.skinOff() then
                F.bootstrapMatch(char)
              end
            end)
            if not timerOK or timerHandle == nil or timerHandle == false then
              _bootstrapPending = nil
            end
          end
        end)
        if results then
          return table.unpack(results, 1, results.n)
        end
      end
    end)
    pcall(function()
      local WAC = require("GameLua.Mod.Library.GamePlay.Avatar.Component.WeaponAvatarComponent")
      local oLoad = WAC.OnWeaponAvatarLoadedLua
      WAC.OnWeaponAvatarLoadedLua = function(self, slotID, definedID, ...)
        local results
        if type(oLoad) == "function" then
          results = table.pack(oLoad(self, slotID, definedID, ...))
        end
        pcall(function()
          if F.skinOff() then
            return
          end
          if self.IsLobbyActor and self:IsLobbyActor() then
            return
          end
          local isSelf = self.IsSelf and self:IsSelf()
          if not isSelf then
            return
          end
          local char = F.getLocalChar()
          if not char then
            return
          end
          local now = _G.RealNow()
          if now < (_G.OwenWeaponMeshRecoveryNext or 0) then
            return
          end
          _G.OwenWeaponMeshRecoveryNext = now + 1
          _weaponApplied = false
          if not PERF.matchActive and _G.OwenSkinBootstrappedPawn ~= char then
            F.bootstrapMatch(char)
          elseif char.AddGameTimer and _weaponApplyPending ~= char then
            _weaponApplyPending = char
            local timerOK, timerHandle = pcall(char.AddGameTimer, char, 0.25, false, function()
              if _weaponApplyPending ~= char then
                return
              end;
              _weaponApplyPending = nil
              local c = F.getLocalChar()
              if c == char and slua.isValid(c) and not F.skinOff() then
                F.matchApplyWeaponSkin(c)
              end
            end)
            if not timerOK or timerHandle == nil or timerHandle == false then
              _weaponApplyPending = nil
            end
          end
        end)
        if results then
          return table.unpack(results, 1, results.n)
        end
      end
    end)
  end
