    local function enabled()
      local value = (_G.MWConfig or {}).ProfileCustomization
      return _G.OwenNeonLobbySceneAllowed() == true and _G.OwenLicenseValidated == true and (value == true or value == 1)
    end
    local function custom()
      _G.MWState = _G.MWState or {};
      _G.MWState.CustomTextData = _G.MWState.CustomTextData or {}
      return _G.MWState.CustomTextData
    end
    local function config(g, id)
      if not CDataTable then
        return nil
      end
      if CDataTable.GetTableData then
        for _, key in ipairs( { id, tostring(id) }) do
          local ok, row = pcall(CDataTable.GetTableData, g.Table, key)
          if ok and (type(row) == 'table' or type(row) == 'userdata') then
            return row
          end
        end
      end
      return g.NativeById and g.NativeById[id]
    end
    function P:Choices(g)
      local now = os.clock()
      if g.Choices and now < (g.ChoicesUntil or 0) then
        return g.Choices
      end
      local raw
      if CDataTable and CDataTable.GetTable then
        local ok, result = pcall(CDataTable.GetTable, g.Table);
        if ok then
          raw = result
        end
      end
      local byId = {}
      if raw then
        pcall(function()
          for key, row in pairs(raw) do
            if type(row) == 'table' or type(row) == 'userdata' then
              local id = tonumber(row.SkinID or row.ID or row.ItemID or row.PlanID)
              if not id and type(key) == 'string' then
                id = tonumber(key)
              end
              if id and id > 0 then
                byId[id] = row
              end
            end
          end
        end)
      end
      g.NativeById = byId
      local rows, seen = {}, {}
      for _, item in ipairs(g.Items) do
        if config(g, item[1]) then
          rows[ # rows + 1] = item;
          seen[item[1]] = true
        end
      end
      for id, row in pairs(byId) do
        if not seen[id] then
          rows[ # rows + 1] = { id, tostring(row.Name or row.ItemName or row.AliasName or (g.En .. ' ' .. id)) }
        end
      end
      table.sort(rows, function(a, b)
        return a[1] < b[1]
      end)
      g.Choices = rows;
      g.ChoicesUntil = now + (next(byId) and 30 or 2);
      return rows
    end
    local function module(key, common)
      local MM = require('client.module_framework.ModuleManager')
      local list = common and MM.CommonModuleConfig or MM.LobbyModuleConfig
      local token = list and list[key]
      return token and MM.GetModule(token)
    end
    local function event(name, ...)
      if EventSystem and EVENTTYPE_ROLEINFO and _G[name] then
        EventSystem:postEvent(EVENTTYPE_ROLEINFO, _G[name], ...)
      end
    end
    function P:RefreshLobbyIdentity()
      local d = DataMgr and DataMgr.roleData;
      if not d then
        return
      end
      pcall(function()
        local info = require('client.logic.roleinfo.logic_roleinfo')
        local basic = info.PersonalBasicInfo
        if basic then
          basic.role_avatar = d.headIconUrl;
          basic.role_avatar_frame = d.cur_avatar_box_id
        end
      end)
      local function post(kind, id, ...)
        if kind and id and EventSystem then
          pcall(EventSystem.postEvent, EventSystem, kind, id, ...)
        end
      end
      post(EVENTTYPE_ROLEINFO, EVENTID_ROLEINFO_UPDATE_HEAD_INFO, d.headIconUrl)
      post(EVENTTYPE_ROLEINFO, EVENTID_ROLEINFO_UPDATE_AVATAR_FRAME_INFO)
      post(EVENTTYPE_LOBBY, EVENTID_UPDATE_LOBBY_AVATAR)
      post(EVENTTYPE_LOBBY_SOCIAL, EVENTID_LOBBY_SOCIAL_UPDATE_HEAD_ICON)
      post(EVENTTYPE_ROLEINFO, EVENTID_ROLEINFO_UPDATE_AVATAR_PORTRAIT)
    end
    local function profile()
      local m = module('logic_profile')
      local hook = P.Native and P.Native.ProfileGetter
      if m and hook and hook.Object == m then
        return hook.Original(m, DataMgr.roleData.uid)
      end
      return m and m.GetLocalProfile and m:GetLocalProfile(DataMgr.roleData.uid)
    end
    local function state(g)
      local d = DataMgr and DataMgr.roleData
      if not d or not d.uid then
        return nil
      end
      local ok, cached = pcall(profile)
      local localProfile = ok and cached or {} localProfile = localProfile or {}
      if g.Key == 'Avatar' then
        if type(DataMgr.UpdateHeadIconUrl) ~= 'function' then
          return nil
        end
        return { Read = function()
          return d.headIconUrl
        end, Write = function(id)
          DataMgr.UpdateHeadIconUrl(tostring(id));
          localProfile.picUrl = tostring(id)
          event('EVENTID_ROLEINFO_UPDATE_USE_AVATAR');
          event('EVENTID_ROLEINFO_UPDATE_HEAD_INFO', tostring(id))
        end }
      elseif g.Key == 'AvatarFrame' then
        if type(DataMgr.UpdateAvatarBoxId) ~= 'function' then
          return nil
        end
        return { Read = function()
          return d.cur_avatar_box_id
        end, Write = function(id)
          DataMgr.UpdateAvatarBoxId(id);
          localProfile.cur_avatar_box_id = id
          local info = require('client.logic.roleinfo.logic_roleinfo')
          if info.PersonalBasicInfo then
            info.PersonalBasicInfo.role_avatar_frame = tonumber(id)
          end
          event('EVENTID_ROLEINFO_UPDATE_AVATAR_FRAME_INFO')
        end }
      elseif g.Key == 'Title' then
        if not d.alias then
          return nil
        end
        return {
          Read = function()
            return { id = d.alias.id, title = d.alias.title, nation = d.alias.nation, rank_id = d.alias.rank_id }
          end,
          Matches = function(id)
            return tonumber(d.alias.id) == id
          end,
          Write = function(id, row)
            if type(id) == 'table' then
              for key,
              value in pairs(id) do
                d.alias[key] = value
              end
            else
              d.alias.id = id;
              d.alias.title = row and row.AliasName or '';
              d.alias.nation = '';
              d.alias.rank_id = 0
            end
            localProfile.alias = localProfile.alias or {};
            for key,
            value in pairs(d.alias) do
              localProfile.alias[key] = value
            end
            local info = require('client.logic.roleinfo.logic_roleinfo')
            if info.PersonalBasicInfo then
              info.PersonalBasicInfo.role_aliasId = d.alias.id;
              info.PersonalBasicInfo.role_aliasTitle = d.alias.title
            end
            event('EVENTID_ROLEINFO_UPDATE_ALL_TITLE')
          end
        }
      elseif g.Key == 'NameTag' then
        if type(d.nameFrameData) ~= 'table' then
          return nil
        end
        local nm = require('client.slua.logic.person_space.logic_roleinfo_nameframe')
        return {
          Read = function()
            local old = {
              Used = nm.nUsedID,
              Rows = {}
            }
            for id,
            row in pairs(d.nameFrameData) do
              old.Rows[id] = row.is_used
            end
            return old
          end,
          Matches = function(id)
            return nm.nUsedID == id and tonumber(localProfile.brand_id) == id and d.nameFrameData[id] and d.nameFrameData[id].is_used == 1
          end,
          Write = function(id)
            if type(id) == 'table' then
              for key,
              row in pairs(d.nameFrameData) do
                if id.Rows[key] ~= nil then
                  row.is_used = id.Rows[key]
                elseif row._OwenProfileSynthetic then
                  d.nameFrameData[key] = nil
                end
              end
              nm.nUsedID = id.Used
            else
              DataMgr.ResetNameFrame()
              d.nameFrameData[id] = d.nameFrameData[id] or { id = id, expire_ts = 0, is_used = 0, _OwenProfileSynthetic = true }
              DataMgr.UseNameFrame(id);
              nm.nUsedID = id
            end
            localProfile.brand_id = nm.nUsedID event('EVENTID_ROLEINFO_USE_NAME_FRAME', nm.nUsedID)
          end
        }
      elseif g.Key == 'InfoCard' then
        local social = require('client.slua.logic.lobby.Left.logic_social_card')
        if not social.SocialCard then
          return nil
        end
        local function targets()
          local out = { social.SocialCard, social.MySocialCard, d.social_card, localProfile.social_card }
          return out
        end
        return { Read = function()
          return social.SocialCard.carte_frame_equip_id
        end, Matches = function(id)
          local t = targets()
          for i = 1, 4 do
            if t[i] and tonumber(t[i].carte_frame_equip_id) ~= id then
              return false
            end
          end
          return true
        end, Write = function(id)
          local t = targets()
          for i = 1, 4 do
            if t[i] then
              t[i].carte_frame_equip_id = id
            end
          end
          event('EVENTID_ROLEINFO_CARTE_FRAME_CHANGE')
        end }
      elseif g.Key == 'SocialPlayerCard' then
        local m = module('logic_social_card_bg')
        if not m or not m.on_notify_social_card_floor then
          return nil
        end
        return { Read = function()
          return m:GetCurrentSocialCardBGID()
        end, Write = function(id)
          m:on_notify_social_card_floor(id)
        end }
      elseif g.Key == 'InformationBackground' then
        local m = module('logic_roleInfo_background')
        if not m or not m.SetCurrentRoleInfoBGID or not ENUM_ITEM_SUBTYPE then
          return nil
        end
        return { Read = function()
          return d.social_card and d.social_card.social_info_bg and d.social_card.social_info_bg[ENUM_ITEM_SUBTYPE.RoleInfoBG]
        end, Write = function(id)
          m:SetCurrentRoleInfoBGID(id);
          event('EVENTID_ROLEINFO_BACKGROUND_UPDATE')
        end }
      elseif g.Key == 'MatchStartAnimation' then
        local m = module('logic_roleInfo_opening')
        if not m or not m.SetCurrentOpeningItemID then
          return nil
        end
        return {
          Read = function()
            return { Current = m:GetEquipedOpeningID(), Field = d.social_card and d.social_card.social_info_bg and ENUM_ITEM_SUBTYPE and d.social_card.social_info_bg[ENUM_ITEM_SUBTYPE.PersonalOpening] }
          end,
          Matches = function(id)
            return m:GetEquipedOpeningID() == id and d.social_card and d.social_card.social_info_bg and ENUM_ITEM_SUBTYPE and d.social_card.social_info_bg[ENUM_ITEM_SUBTYPE.PersonalOpening] == id
          end,
          Write = function(id)
            local restore = type(id) == 'table' m:SetCurrentOpeningItemID(restore and id.Current or id)
            if ENUM_ITEM_SUBTYPE and ENUM_ITEM_SUBTYPE.PersonalOpening then
              d.social_card = d.social_card or {};
              d.social_card.social_info_bg = d.social_card.social_info_bg or {}
              if restore then
                d.social_card.social_info_bg[ENUM_ITEM_SUBTYPE.PersonalOpening] = id.Field
              else
                d.social_card.social_info_bg[ENUM_ITEM_SUBTYPE.PersonalOpening] = id
              end
            end
            event('EVENTID_ROLEINFO_OPENING_UPDATE')
            if not restore and m.CheckAndDownloadOpeningBP then
              m:CheckAndDownloadOpeningBP(id)
            end
          end
        }
      elseif g.Key == 'CollectionNickname' then
        local m = module('NicknameColorManager', true)
        if not m or not m.SetUserData or not m.GetUserData then
          return nil
        end
        return {
          Read = function()
            return m:GetUserData(d.uid)
          end,
          Write = function(id)
            m.msg_recolor = m.msg_recolor or {};
            m.msg_recolor.use_color = id m:SetUserData(d.uid, id)
          end
        }
      else
        local key, field, ev
        if g.Key == 'NicknameEffect' then
          key = 'logic_roleInfo_nicknameframe';
          field = 'friend_nickname_skin';
          ev = 'EVENTID_ROLEINFO_NICKNAME_FRAME_UPDATE'
        elseif g.Key == 'ChatBubble' then
          key = 'logic_roleInfo_chatframe';
          field = 'chat_bubble';
          ev = 'EVENTID_ROLEINFO_CHAT_FRAME_UPDATE'
        elseif g.Key == 'InfoCardFrame' then
          key = 'logic_roleInfo_profileframe';
          field = 'profile_frame';
          ev = 'EVENTID_ROLEINFO_UPDATE_PROFILE_FRAME_INFO'
        elseif g.Key == 'SocialPlayerCardFrame' then
          key = 'logic_roleInfo_socialcardframe';
          field = 'social_card_frame';
          ev = 'EVENTID_ROLEINFO_UPDATE_SOCIALCARD_FRAME_INFO'
        end
        if not key then
          return nil
        end
        local m = module(key);
        if not m then
          return nil
        end
        return { Read = function()
          return d[field]
        end, Matches = (field == 'profile_frame' or field == 'social_card_frame') and function(id)
          return tonumber(d[field]) == id and tonumber(m.curEquipFrame) == id
        end or nil, Write = function(id)
          d[field] = id;
          localProfile[field] = id
          if field == 'profile_frame' or field == 'social_card_frame' then
            m.curEquipFrame = id
          elseif m.showDataList then
            for _, row in ipairs(m.showDataList) do
              if row.SubList then
                for _, sub in pairs(row.SubList) do
                  sub.bIsUse = sub.ID == id
                end
              else
                row.bIsUse = row.ID == id
              end
            end
          end
          event(ev)
        end }
      end
    end
    function P:Apply(g, id)
      if not enabled() then
        return false
      end
      local d = DataMgr and DataMgr.roleData;
      if not d or not d.uid then
        return false
      end
      if self.Uid ~= tostring(d.uid) or self.RoleData ~= d then
        self.Original = {};
        self.Applied = {};
        self.Uid = tostring(d.uid);
        self.RoleData = d
      end
      local row = config(g, id);
      if not row then
        return false
      end
      local item = CDataTable.GetTableData('Item', id)
      if item and _G.OwenSkinResourceReady and not _G.OwenSkinResourceReady(id) then
        self.DownloadAt = self.DownloadAt or {}
        if os.clock() >= (self.DownloadAt[id] or 0) then
          self.DownloadAt[id] = os.clock() + 10
          if _G.download_item then
            pcall(_G.download_item, id)
          end
        end
        return false
      end
      local s = state(g);
      if not s then
        return false
      end
      local key = g.Key
      if s.Matches and s.Matches(id) or ( not s.Matches and tonumber(s.Read()) == id) then
        return true
      end
      if not self.Original[key] then
        self.Original[key] = { Value = s.Read() }
      end
      self.Applied[key] = id s.Write(id, row)
      return true
    end
    function P:Restore(g)
      local old = self.Original[g.Key];
      if not old then
        return true
      end
      local s = state(g);
      if not s then
        return false
      end
      local current = self.Applied[g.Key]
      if not current or (s.Matches and s.Matches(current)) or ( not s.Matches and tonumber(s.Read()) == current) then
        s.Write(old.Value)
      end
      self.Original[g.Key] = nil;
      self.Applied[g.Key] = nil
      return true
    end
    function P:Tick()
      local lobby = GameStatus and GameStatus.IsInLobbyOrMainCity and GameStatus.IsInLobbyOrMainCity()
      if lobby ~= true and lobby ~= 1 then
        self.LastLobby = false;
        return
      end
      local now = os.clock()
      if self.InstallNative and now >= (self.NativeInstallNext or 0) then
        self.NativeInstallNext = now + 5;
        self:InstallNative()
      end
      local d = DataMgr and DataMgr.roleData;
      if not d or not d.uid then
        return
      end
      if self.Uid ~= tostring(d.uid) or self.RoleData ~= d then
        self.Original = {};
        self.Applied = {};
        self.Uid = tostring(d.uid);
        self.RoleData = d
      end
      self.LastLobby = true;
      self.Cursor = self.Cursor % # self.Groups + 1
      local g = self.Groups[self.Cursor];
      local id = tonumber(custom()['SkinProfile' .. g.Key .. 'ID'])
      local ok, result = pcall(function()
        if enabled() and id and id > 0 then
          return self:Apply(g, id)
        else
          return self:Restore(g)
        end
      end)
      self.Status = ok and (result and 'ready' or 'waiting_native_data') or 'native_error'
    end
    function P:Select(key, id)
      local g = self.ByKey[key];
      id = tonumber(id)
      if not g or not id or id < 0 or id % 1 ~= 0 or _G.OwenLicenseValidated ~= true then
        return false
      end
      if id > 0 and not config(g, id) then
        return false
      end
      custom()['SkinProfile' .. key .. 'ID'] = id
      _G.OwenSkinDirty = true
      local saved = false
      if _G.SaveModSettings then
        local ok, result = pcall(_G.SaveModSettings, false, 'skin');
        saved = ok and result ~= false
      end
      if not saved and _G.OwenScheduleSave then
        _G.OwenScheduleSave('skin')
      end
      local lobby = GameStatus and GameStatus.IsInLobbyOrMainCity and GameStatus.IsInLobbyOrMainCity()
      if lobby == true or lobby == 1 then
        pcall(function()
          if id == 0 then
            self:Restore(g)
          else
            self:Apply(g, id)
          end
        end)
      end
      return true
    end
