  local function AutoRestoreLobbySkin()
    local state = OwenLobbyRestoreState
    local outfit = _G.AddOutfit
    local cfg = _G.MWConfig or {}
    local enabled = cfg.ModSkin == true or cfg.ModSkin == 1
    local lobby = enabled and _G.OwenNeonLobbySceneAllowed and _G.OwenNeonLobbySceneAllowed() == true
    if not lobby or not outfit or (outfit.skinOff and outfit.skinOff()) or (outfit.isInRealMatch and outfit.isInRealMatch()) then
      state.WasLobby = false;
      state.Actor = nil;
      state.Model = nil;
      state.Comp = nil
      state.Attempts = 0;
      state.Confirmed = 0;
      state.NextAt = 0;
      state.FullApplied = false;
      state.RetryAt = nil
      state.Status = enabled and 'outside_lobby' or 'disabled'
      _G.AddOutfitLobbyRestored = false
      return
    end
    local now = os.time()
    if now < (state.NextAt or 0) then
      return
    end
    state.NextAt = now + 3
    if cfg.UnlockFPS then
      if not (_G.MWState and _G.MWState.GraphicsUnlocked) then
        pcall(InitializeGraphicsUnlock)
      end
      if _G.MWUltraHDEnsurePak then
        pcall(_G.MWUltraHDEnsurePak)
      end
    end
    local ok, actor, model, comp = pcall(outfit.getLobbyRestoreTarget)
    if not ok or not actor or not model or not comp then
      state.Actor = nil;
      state.Model = nil;
      state.Comp = nil;
      state.Confirmed = 0
      state.FullApplied = false;
      state.Status = 'model_pending'
      _G.AddOutfitLobbyRestored = false;
      return
    end
    if actor ~= state.Actor or model ~= state.Model or comp ~= state.Comp or not state.WasLobby then
      state.WasLobby = true;
      state.Actor = actor;
      state.Model = model;
      state.Comp = comp
      state.Attempts = 0;
      state.Confirmed = 0;
      state.FullApplied = false;
      state.NextAt = now + 2;
      state.RetryAt = nil
      state.Status = 'model_changed';
      _G.AddOutfitLobbyRestored = false
      if outfit.invalidateLobbyResolved then
        pcall(outfit.invalidateLobbyResolved)
      end
      local cached = _G.AddOutfitLobbyState
      if cached then
        cached.reapplyDone = false;
        cached.reapplyScheduled = false
      end
      return
    end
    local verified, confirmed, reason = pcall(outfit.confirmLobbyWear, actor, true)
    if verified and confirmed == true and state.FullApplied then
      state.Confirmed = (state.Confirmed or 0) + 1
      state.Status = state.Confirmed >= 2 and 'render_confirmed' or 'verifying_render'
      _G.AddOutfitLobbyRestored = state.Confirmed >= 2
      state.NextAt = now + (state.Confirmed >= 4 and 30 or state.Confirmed >= 2 and 10 or 3)
      return
    end
    state.Confirmed = 0;
    _G.AddOutfitLobbyRestored = false
    state.Status = verified and (reason or 'wear_missing') or 'verify_error'
    if now < (state.RetryAt or 0) then
      return
    end
    state.Attempts = (state.Attempts or 0) + 1
    state.RetryAt = now + (state.Attempts <= 6 and 3 or 15)
    state.NextAt = state.RetryAt
    local applied, result = pcall(function()
      outfit.applyPersistSlotsToCache()
      outfit.persistApplyLoaded()
      return outfit.reapplyLobbyEquipped()
    end)
    state.FullApplied = applied and result == true
    if state.FullApplied then
      state.Attempts = 0
    end
    if not applied then
      state.Status = 'repair_error'
    end
  end
